def _unrpyc_extraction_complete(target_dir):
    """R6 fix: gomulu unrpyc ayiklamasinin BUTUNLUK kontrolu.
    Kismi/bozuk temp klasorleri (decompiler/ kaynak .py dosyalari eksik, yalniz
    __pycache__/.pyc kalmis) unrpyc'yi import asamasinda ModuleNotFoundError
    ile dusurur ve hicbir .rpyc decompile edilemez. Bu durum tespit edilirse
    klasor silinip zip'ten yeniden ayiklanir."""
    try:
        required = (
            "unrpyc.py",
            "deobfuscate.py",
            os.path.join("decompiler", "__init__.py"),
            os.path.join("decompiler", "renpycompat.py"),
            os.path.join("decompiler", "magic.py"),
            os.path.join("decompiler", "translate.py"),
            os.path.join("decompiler", "util.py"),
        )
        return all(os.path.exists(os.path.join(target_dir, p)) for p in required)
    except Exception:
        return False


def get_unrpyc_path(log_callback=None):
    """
    unrpyc.py dosyasini bulur. Eger diskte yoksa gomulu zip arsivinden
    gecici klasore (tempfile) cikararak calistirir.
    Boylece program tek bir .py dosyasi olarak her yerde sorunsuz decompile yapabilir.
    """
    current_dir = os.path.dirname(os.path.abspath(__file__))
    local_unrpyc = os.path.join(current_dir, "unrpyc", "unrpyc.py")
    if os.path.exists(local_unrpyc):
        return local_unrpyc

    # Gomulu unrpyc'yi temp klasore cikar
    target_unrpyc_dir = os.path.join(tempfile.gettempdir(), "_renpy_unrpyc_embedded")
    target_script = os.path.join(target_unrpyc_dir, "unrpyc.py")
    if os.path.exists(target_script) and _unrpyc_extraction_complete(target_unrpyc_dir):
        return target_script

    try:
        # R6 fix: bozuk/kismi ayiklama bulunduysa temizle; eski davranis "varsa yeniden kullan"
        #Partial klasörde kalıcı import hatasına kilitleniyordu.
        if os.path.exists(target_script):
            if log_callback:
                log_callback("[!] Gomulu unrpyc klasoru eksik/bozuk — temiz yeniden ayiklaniyor...")
            shutil.rmtree(target_unrpyc_dir, ignore_errors=True)
        if log_callback:
            log_callback("[*] Gomulu unrpyc decompiler ayiklaniyor...")
        zip_data = base64.b64decode(UNRPYC_ZIP_B64)
        with zipfile.ZipFile(io.BytesIO(zip_data)) as zf:
            zf.extractall(target_unrpyc_dir)
        if not _unrpyc_extraction_complete(target_unrpyc_dir):
            if log_callback:
                log_callback("[X] Gomulu unrpyc ayiklandi ancak bilesenler eksik — decompile adimi atlanabilir.")
        return target_script
    except Exception as e:
        if log_callback:
            log_callback(f"[X] Gomulu unrpyc acilamadi: {e}")
        return None


ALLOWED_TL_LANGS = {"turkish", "turkce", "türkçe", "tr", "tur"}

def is_path_in_ignored_tl(path: str) -> bool:
    """
    Kullanici kurali: RWA veya AOC / Turkce yamalar haric tl/ klasorune dokunulmaz.
    Yalnizca 'turkish', 'turkce', 'türkçe', 'tr', 'tur' alt klasorleri taranabilir.
    F95 veya orijinal oyunlardaki diger diller (chinese, russian vb.) tamamen atlanir.
    """
    norm = os.path.normpath(path).lower()
    parts = norm.split(os.sep)
    if "tl" in parts:
        tl_idx = parts.index("tl")
        if tl_idx + 1 < len(parts):
            lang = parts[tl_idx + 1]
            if lang not in ALLOWED_TL_LANGS:
                return True
        else:
            return True
    return False

IGNORED_DIRS = {
    "renpy", "lib", "locales", "resources", ".userdata",
    "cache", "node_modules", ".git", "__pycache__", "python"
}

RPYC2_HEADER_STANDARD = b"RENPY RPC2"
RPYC2_HEADER_LAUREN = b"LAUREN RPC2"
XOR_KEY_RWAZONE = b"4\x12\xab\xcd\xef\x98vT!C\xba\xdc\xfe\x89gE"
PICKLE_MAGIC_RWAZONE = b"\xde\xad\xbe\xef"

def find_real_renpy_game_dir(start_path):
    """
    Kullanıcının seçtiği klasör içindeki gerçek Ren'Py oyun/script klasörünü bulur.
    Normal Ren'Py oyunlarını, Electron launcher'lı oyunları ve Türkçe yama paketlerini destekler.
    """
    start_path = os.path.abspath(start_path)
    if os.path.isfile(start_path):
        start_path = os.path.dirname(start_path)

    def has_renpy_scripts(folder):
        if not os.path.isdir(folder):
            return False
        try:
            files = os.listdir(folder)
            return any(f.endswith((".rpy", ".rpyc", ".rpa")) for f in files)
        except Exception:
            return False

    # 1. Öncelik: start_path/game/game (Electron / AOC Türkçe yama sarmalayıcıları)
    cand_nested = os.path.join(start_path, "game", "game")
    if has_renpy_scripts(cand_nested):
        return cand_nested

    # 2. Öncelik: start_path/game (Standart Ren'Py oyunları: Eternum vb.)
    cand_game = os.path.join(start_path, "game")
    if has_renpy_scripts(cand_game):
        return cand_game

    # 3. Öncelik: start_path'in kendisi (Kullanıcı doğrudan 'game' klasörünü seçtiyse)
    if has_renpy_scripts(start_path):
        return start_path

    # 4. Fallback: Güvenli arama (Asla renpy/ veya lib/ içine girmeden 'game' klasörünü bul)
    for root, dirs, files in os.walk(start_path):
        dirs[:] = [d for d in dirs if d.lower() not in IGNORED_DIRS]
        if os.path.basename(root).lower() == "game" and has_renpy_scripts(root):
            return root

    if os.path.isdir(cand_game):
        return cand_game
    return start_path


class RestrictedRPAUnpickler(pickle.Unpickler):
    """
    RPA indeks verilerini okumak icin guvenli ve kisitli Unpickler.
    Sadece temel ilkel veri yapilarina (dict, list, tuple, str, int, bytes vb.) izin verir.
    Zararli kod calistirma (arbitrary code execution) riskini kesin olarak onler.
    """
    SAFE_BUILTINS = {
        'bytearray', 'bytes', 'dict', 'list', 'set', 'frozenset',
        'str', 'int', 'float', 'bool', 'tuple', 'NoneType'
    }

    PY2_BUILTIN_MAP = {
        'unicode': str,
        'long': int,
        'NoneType': type(None)
    }

    def find_class(self, module, name):
        if module in ("builtins", "__builtin__"):
            if name in self.PY2_BUILTIN_MAP:
                return self.PY2_BUILTIN_MAP[name]
            if name in self.SAFE_BUILTINS:
                import builtins
                return getattr(builtins, name, None)
        raise pickle.UnpicklingError(f"RPA Guvenlik Engeli: '{module}.{name}' tipindeki nesnelerin yuklenmesine izin verilmiyor!")


