STUDIO_SIGNATURE = "Ren'Py Walkthrough Modder Studio - Hikâye Kontrol Merkezi"

def safe_zlib_decompress(data, max_decompressed_bytes=50 * 1024 * 1024, chunk_size=65536):
    """
    Güvenli zlib açma fonksiyonu.
    Decompression bomb ve aşırı bellek tüketimini önlemek için açılan verinin boyutunu
    kesin bir güvenli üst sınırla (varsayılan 50 MB) sınırlar ve taşma durumunda işlemi durdurur.
    """
    if not data or not isinstance(data, (bytes, bytearray)):
        return b""
    try:
        decompressor = zlib.decompressobj()
        decompressed = bytearray()
        view = memoryview(data)
        offset = 0
        total_len = len(view)
        while offset < total_len:
            end = min(offset + chunk_size, total_len)
            chunk = view[offset:end]
            offset = end
            max_remaining = max_decompressed_bytes - len(decompressed) + 1
            part = decompressor.decompress(chunk, max_remaining)
            decompressed.extend(part)
            if len(decompressed) > max_decompressed_bytes:
                raise ValueError(f"Decompression bomb engeli: Açılan veri maksimum güvenlik sınırını ({max_decompressed_bytes} byte) aştı!")

        trailing = decompressor.flush(max_decompressed_bytes - len(decompressed) + 1)
        decompressed.extend(trailing)
        if len(decompressed) > max_decompressed_bytes:
            raise ValueError(f"Decompression bomb engeli: Açılan veri maksimum güvenlik sınırını ({max_decompressed_bytes} byte) aştı!")

        return bytes(decompressed)
    except Exception as e:
        if isinstance(e, ValueError) and "Decompression bomb" in str(e):
            raise
        raise zlib.error(f"Zlib açma hatası: {e}")

def compute_file_sha256(file_path):
    """Dosyanın SHA-256 özetini ve bayt boyutunu güvenle hesaplar."""
    if not os.path.isfile(file_path):
        return None, 0
    h = hashlib.sha256()
    size = 0
    with open(file_path, 'rb') as f:
        while True:
            chunk = f.read(65536)
            if not chunk:
                break
            h.update(chunk)
            size += len(chunk)
    return h.hexdigest(), size

def is_file_owned_by_studio(file_path):
    """Dosyanın bu stüdyoya ait olup olmadığını özel imza başlığı ile kontrol eder."""
    if not os.path.isfile(file_path):
        return False
    try:
        with open(file_path, "r", encoding="utf-8", errors="ignore") as f:
            header = f.read(4096)
            return STUDIO_SIGNATURE in header
    except Exception:
        return False

def is_safe_subpath(path_to_check, base_dir):
    """
    Hedef yolun belirtilen temel dizin sınırları içinde kaldığını
    gerçek yollar (realpath), sembolik bağlantı çözümlemesi ve dizin sınırı
    kontrolü ile güvenle doğrular. startswith() açıklarına karşı tam korur.
    """
    try:
        if not path_to_check or not base_dir:
            return False
        real_base = os.path.realpath(os.path.abspath(base_dir))
        real_path = os.path.realpath(os.path.abspath(path_to_check))

        # Windows sürücü kontrolü
        if os.path.splitdrive(real_base)[0].upper() != os.path.splitdrive(real_path)[0].upper():
            return False

        common = os.path.commonpath([real_base, real_path])
        return os.path.normcase(common) == os.path.normcase(real_base)
    except Exception:
        return False

def is_safe_rpa_path(rel_path, target_game_dir):
    """
    RPA arşivi içindeki dosya yolunu güvenlik açısından doğrular.
    Kesinlikle REDDEDİLEN durumlar (otomatik temizlenmez, doğrudan reddedilir):
    - Null byte (\x00)
    - Mutlak yollar ('/' veya '\\' ile başlayanlar)
    - Windows sürücü yolları (C:, D: vb.)
    - '..' veya '.' yol parçaları (Path traversal)
    - Sembolik bağlantı (symlink) veya junction ile hedef klasör sınırını aşan yollar
    """
    if not isinstance(rel_path, str) or not rel_path.strip():
        return False, "Dosya yolu boş veya geçersiz tip"

    if "\x00" in rel_path:
        return False, "Null byte (\x00) içeriyor"

    norm = rel_path.replace("\\", "/")

    if norm.startswith("/"):
        return False, "Mutlak yol '/' ile başlayamaz"

    if re.match(r"^[a-zA-Z]:", norm):
        return False, "Windows sürücü yolu içeremez"

    parts = [p for p in norm.split("/") if p]
    if not parts:
        return False, "Geçersiz veya boş yol"

    for part in parts:
        if part == ".." or part == ".":
            return False, f"Path traversal bileşeni içeriyor: '{part}'"
        if any(c in part for c in '<>:"|?*'):
            return False, f"Geçersiz karakter içeren dosya/klasör adı: '{part}'"

    try:
        target_real = os.path.realpath(target_game_dir)
        combined = os.path.abspath(os.path.join(target_real, *parts))
        combined_real = os.path.realpath(combined)

        if os.path.exists(combined):
            if not is_safe_subpath(combined_real, target_real):
                return False, "Hedef gerçek yolu oyun klasörü dışında (symlink breakout)"
        else:
            curr = os.path.dirname(combined)
            while curr and not os.path.exists(curr):
                parent = os.path.dirname(curr)
                if parent == curr:
                    break
                curr = parent
            if curr and os.path.exists(curr):
                curr_real = os.path.realpath(curr)
                if not is_safe_subpath(curr_real, target_real):
                    return False, "Hedef üst klasör gerçek yolu oyun klasörü dışında (symlink breakout)"

        return True, combined
    except Exception as e:
        return False, f"Yol doğrulama hatası: {e}"

def safe_verified_restore_file(src_bak, dst_file, target_root, log_callback=None):
    """
    Yedek dosyasını hedef dosyaya SHA-256 ve boyut doğrulamalı atomik yöntemle geri yükler.
    Sembolik bağlantı ve hedef klasör dışına çıkışlar kesinlikle engellenir.
    Kaynak .wtbak dosyası SADECE hedef dosyanın yazıldığı ve özetinin eşleştiği doğrulandıktan sonra silinir.
    Geri yükleme başarısız olursa yedek KESİNLİKLE silinmez ve mevcut dosya korunur.
    """
    def _log(msg):
        if log_callback:
            try: log_callback(msg)
            except Exception: pass

    if not os.path.isfile(src_bak):
        return False

    try:
        target_real = os.path.realpath(target_root)
        src_real = os.path.realpath(src_bak)
        dst_real = os.path.realpath(dst_file)

        # Sembolik bağlantı / klasör dışına çıkış kontrolü (sağlam sınır doğrulaması)
        if not is_safe_subpath(src_real, target_real):
            _log(f"[!] Güvenlik engeli: Yedek dosya gerçek yolu oyun klasörü dışında ({src_bak}), atlandı.")
            return False

        parent_dst = os.path.dirname(dst_real)
        if not is_safe_subpath(parent_dst, target_real):
            _log(f"[!] Güvenlik engeli: Hedef dosya gerçek yolu oyun klasörü dışında ({dst_file}), atlandı.")
            return False

        # 1. Kaynak yedeğin SHA-256 özetini ve boyutunu al
        src_hash, src_size = compute_file_sha256(src_bak)
        if src_hash is None:
            return False

        # 2. Geçici dosyaya kopyala (.tmp_<uuid>)
        import uuid
        tmp_dst = dst_file + f".tmp_{uuid.uuid4().hex}"
        shutil.copy2(src_bak, tmp_dst)

        # 3. Geçici dosyanın özetini doğrula
        tmp_hash, tmp_size = compute_file_sha256(tmp_dst)
        if tmp_hash != src_hash or tmp_size != src_size:
            if os.path.exists(tmp_dst):
                try: os.remove(tmp_dst)
                except Exception: pass
            _log(f"[X] Geri yükleme bütünlük hatası: Geçici dosya özeti eşleşmedi ({dst_file}). Yedek korundu!")
            return False

        # 4. Mevcut hedef dosya varsa beklenmedik arızaya karşı anlık koruma kopyası al
        orig_safety_copy = None
        if os.path.exists(dst_file):
            orig_safety_copy = dst_file + f".pre_restore_{uuid.uuid4().hex}"
            try:
                shutil.copy2(dst_file, orig_safety_copy)
            except Exception:
                orig_safety_copy = None

        # 5. Atomik replace ile hedefe aktar
        try:
            os.replace(tmp_dst, dst_file)
        except Exception as e:
            if os.path.exists(tmp_dst):
                try: os.remove(tmp_dst)
                except Exception: pass
            if orig_safety_copy and os.path.exists(orig_safety_copy):
                try: os.remove(orig_safety_copy)
                except Exception: pass
            _log(f"[X] Geri yükleme yazma hatası ({dst_file}): {e}. Yedek korundu!")
            return False

        # 6. Hedef dosyanın özetini doğrula
        dst_hash, dst_size = compute_file_sha256(dst_file)
        if dst_hash != src_hash or dst_size != src_size:
            # Hedef doğrulanamadı, koruma kopyasını geri koy
            if orig_safety_copy and os.path.exists(orig_safety_copy):
                try: os.replace(orig_safety_copy, dst_file)
                except Exception: pass
            _log(f"[X] Geri yükleme bütünlük hatası: Hedef dosya özeti eşleşmedi ({dst_file}). Yedek ve orijinal dosya korundu!")
            return False

        # Başarılı: anlık koruma kopyasını temizle
        if orig_safety_copy and os.path.exists(orig_safety_copy):
            try: os.remove(orig_safety_copy)
            except Exception: pass

        # 7. SADECE doğrulama %100 başarılıysa kaynak .wtbak dosyasını sil
        try:
            os.remove(src_bak)
        except Exception:
            pass

        return True
    except Exception as e:
        _log(f"[X] Geri yükleme hatası ({os.path.basename(dst_file)}): {e}. Yedek korundu!")
        return False

def safe_write_with_backup(target_file, new_content, log_callback=None):
    """Hedef dosyayı değiştirmeden önce .wtbak yedeği oluşturur ve atomik replace ile yazar."""
    def _log(msg):
        if log_callback:
            try: log_callback(msg)
            except Exception: pass

    bak_path = target_file + ".wtbak"
    if os.path.exists(target_file) and not os.path.exists(bak_path):
        try:
            shutil.copy2(target_file, bak_path)
            bh, bs = compute_file_sha256(bak_path)
            oh, osz = compute_file_sha256(target_file)
            if bh != oh or bs != osz:
                if os.path.exists(bak_path):
                    try: os.remove(bak_path)
                    except Exception: pass
                _log(f"[X] Yedek doğrulanamadı: {bak_path}")
                return False
        except Exception as e:
            _log(f"[!] Yedekleme hatası ({target_file}): {e}")
            return False

    tmp_path = target_file + f".tmp_{uuid.uuid4().hex}"
    try:
        with open(tmp_path, "w", encoding="utf-8") as f:
            f.write(new_content)
        if not os.path.exists(tmp_path) or os.path.getsize(tmp_path) == 0:
            if os.path.exists(tmp_path):
                os.remove(tmp_path)
            return False
        # R5 Fix: atomik replace ONCESI yazilan icerik geri okunarak butunluk dogrulanir
        # (yedek dogrulanir ama son yazi dogrulanmiyordu).
        try:
            with open(tmp_path, "r", encoding="utf-8") as f:
                written_readback = f.read()
            if written_readback != new_content:
                if os.path.exists(tmp_path):
                    os.remove(tmp_path)
                _log(f"[X] Yazim bütünlük kontrolü başarısız ({target_file}). Dosya yazılmadı!")
                return False
        except Exception as rb_e:
            if os.path.exists(tmp_path):
                try: os.remove(tmp_path)
                except Exception: pass
            _log(f"[X] Yazım bütünlük kontrolü okumada hata ({target_file}): {rb_e}")
            return False
        os.replace(tmp_path, target_file)
        return True
    except Exception as e:
        _log(f"[X] Dosya yazma hatası ({target_file}): {e}")
        if os.path.exists(tmp_path):
            try: os.remove(tmp_path)
            except Exception: pass
        return False

WALKTHROUGH_TAGS_CODE = """# ==============================================================================
# Ren'Py Walkthrough Modder Studio - Evrensel Metin Etiketleri (Text Tags)
# Bu dosya '00_' oneki ile motor tarafindan en basta yuklenir ve
# seceneklerde kullanilan {wt_best}, {wt_worst}, {wt_hint} etiketlerinin
# Ren'Py tarafindan kesinlikle taninmasini ve hicbir zaman cokmemesini garanti eder.
# ==============================================================================

init -999 python:
    def _wt_extract_text(contents):
        try:
            return "".join(c[1] for c in contents if isinstance(c, tuple) and len(c) >= 2 and isinstance(c[1], str))
        except Exception:
            return ""

    def _wt_tag_best(tag, argument, contents):
        tag_type = getattr(renpy, "TEXT_TAG", 1)
        if getattr(persistent, "walkthrough_enabled", True):
            mode = getattr(persistent, "wt_mode", "full")
            if mode == "critical":
                raw_txt = _wt_extract_text(contents).lower()
                crit_kw = ("kurtar", "hayat", "rota", "olum", "ölüm", "bad", "tuzak", "son", "ending", "safe", "survival", "serbest")
                if not any(kw in raw_txt for kw in crit_kw):
                    return contents
            g_col = getattr(persistent, "wt_green_color", "#2ECC71")
            return [(tag_type, "color=" + str(g_col))] + contents + [(tag_type, "/color")]
        return contents

    def _wt_tag_worst(tag, argument, contents):
        tag_type = getattr(renpy, "TEXT_TAG", 1)
        if getattr(persistent, "walkthrough_enabled", True):
            mode = getattr(persistent, "wt_mode", "full")
            if mode == "critical":
                raw_txt = _wt_extract_text(contents).lower()
                crit_kw = ("olum", "ölüm", "death", "rota", "kapat", "tuzak", "bad_end", "lose", "zarar")
                if not any(kw in raw_txt for kw in crit_kw):
                    return contents
            r_col = getattr(persistent, "wt_red_color", "#EF4444")
            return [(tag_type, "color=" + str(r_col))] + contents + [(tag_type, "/color")]
        return contents

    def _wt_tag_hint(tag, argument, contents):
        tag_type = getattr(renpy, "TEXT_TAG", 1)
        if getattr(persistent, "walkthrough_enabled", True):
            if getattr(persistent, "wt_show_hints", True):
                raw_txt = _wt_extract_text(contents)
                f_char = getattr(persistent, "wt_focus_char", None)
                if f_char and str(f_char).lower() in raw_txt.lower():
                    txt_tag = getattr(renpy, "TEXT_TEXT", 0)
                    focus_prefix = [(tag_type, "color=#FDE047"), (tag_type, "b"), (txt_tag, u" [Odak: " + str(f_char) + u"] "), (tag_type, "/b"), (tag_type, "/color")]
                    return [(tag_type, "size=-4")] + focus_prefix + contents + [(tag_type, "/size")]
                return [(tag_type, "size=-4")] + contents + [(tag_type, "/size")]
        return []

    # Register custom text tags
    config.custom_text_tags["wt_best"] = _wt_tag_best
    config.custom_text_tags["wt_worst"] = _wt_tag_worst
    config.custom_text_tags["wt_hint"] = _wt_tag_hint
"""

def ensure_walkthrough_tags_installed(target_dir: str, log_callback=None):
    """
    Oyun klasorune '00_walkthrough_tags.rpy' dosyasini yazar.
    Bu dosya {wt_best}, {wt_worst}, {wt_hint} etiketlerini init -999 seviyesinde
    config.custom_text_tags sozrugune kaydeder ve oyunun cokmesini onler.
    """
    if not target_dir or not os.path.isdir(target_dir):
        return None
    tags_file = os.path.join(target_dir, "00_walkthrough_tags.rpy")
    try:
        if not os.path.exists(tags_file):
            with open(tags_file, "w", encoding="utf-8") as f:
                f.write(WALKTHROUGH_TAGS_CODE)
            if log_callback:
                try: log_callback(f"[*] Evrensel metin etiketleri kuruldu: {os.path.basename(tags_file)}")
                except Exception: pass
        else:
            with open(tags_file, "r", encoding="utf-8", errors="ignore") as f:
                cur_c = f.read()
            if "init -9999" in cur_c or "wt_hint" not in cur_c:
                with open(tags_file, "w", encoding="utf-8") as f:
                    f.write(WALKTHROUGH_TAGS_CODE)
                if log_callback:
                    try: log_callback(f"[*] Evrensel metin etiketleri guncellendi: {os.path.basename(tags_file)}")
                    except Exception: pass
        return tags_file
    except Exception as e:
        if log_callback:
            try: log_callback(f"[!] Metin etiketleri yazilamadi: {e}")
            except Exception: pass
        return None

def safe_rpa_pickle_loads(data):
    """Güvenli deserializasyon; yetkisiz nesneleri, aşırı büyük yükleri ve dosya sayısı anomalilerini kesinlikle reddeder."""
    # Maksimum 100 MB indeks boyutu sınırı (Memory exhaustion / Zip bomb / DoS önlemi)
    if len(data) > 100 * 1024 * 1024:
        raise ValueError("RPA indeks verisi izin verilen maksimum güvenlik boyutunu (100 MB) aşıyor!")
    res = RestrictedRPAUnpickler(io.BytesIO(data), encoding="latin1").load()
    if not isinstance(res, dict):
        raise pickle.UnpicklingError(f"RPA indeksi bir sözlük (dict) olmalıdır, alınan tip: {type(res).__name__}")
    if len(res) > 50000:
        raise ValueError(f"RPA indeksi izin verilen maksimum dosya sayısı sınırını (50000) aşıyor: {len(res)}")
    return res

def read_rpa_archive(rpa_path):
    """
    RPA arşivini okur ve dosya tablosunu (index) ve şifreleme anahtarını (key) döner.
    RPA-3.0, RPA-2.0, RPA-1.0 ve başlıksız formatları destekler.
    Güvenlik: Decompression bomb korumalı (safe_zlib_decompress), negatif/geçersiz ofset ve bozuk zlib verileri güvenle kontrol edilir.
    """
    if not os.path.isfile(rpa_path):
        return {}, 0

    try:
        file_size = os.path.getsize(rpa_path)
    except OSError:
        return {}, 0

    if file_size < 16:
        return {}, 0

    try:
        with open(rpa_path, 'rb') as f:
            header_line = f.readline()
            header = header_line.decode('latin1', errors='ignore')
            if header.startswith(('RPA-3.0', 'RPA-2.0')):
                tokens = header.split()
                if len(tokens) < 2:
                    return {}, 0
                try:
                    offset = int(tokens[1], 16)
                    key = int(tokens[2], 16) if len(tokens) > 2 else 0
                except (ValueError, IndexError):
                    return {}, 0

                if offset < 0 or offset >= file_size:
                    return {}, 0

                f.seek(offset)
                read_len = min(file_size - offset, 50 * 1024 * 1024)
                raw_compressed = f.read(read_len)
                try:
                    raw_index = safe_zlib_decompress(raw_compressed, max_decompressed_bytes=50 * 1024 * 1024)
                    index = safe_rpa_pickle_loads(raw_index)
                    return index, key
                except Exception:
                    return {}, 0

            elif header.startswith('RPA-1.0'):
                tokens = header.split()
                if len(tokens) < 2:
                    return {}, 0
                try:
                    offset = int(tokens[1], 16)
                except (ValueError, IndexError):
                    return {}, 0

                if offset < 0 or offset >= file_size:
                    return {}, 0

                f.seek(offset)
                read_len = min(file_size - offset, 50 * 1024 * 1024)
                try:
                    raw_index = safe_zlib_decompress(f.read(read_len), max_decompressed_bytes=50 * 1024 * 1024)
                    index = safe_rpa_pickle_loads(raw_index)
                    return index, 0
                except Exception:
                    return {}, 0

            else:
                f.seek(0)
                try:
                    read_len = min(file_size, 50 * 1024 * 1024)
                    raw_index = safe_zlib_decompress(f.read(read_len), max_decompressed_bytes=50 * 1024 * 1024)
                    index = safe_rpa_pickle_loads(raw_index)
                    return index, 0
                except Exception:
                    return {}, 0
    except Exception:
        return {}, 0

def extract_scripts_from_rpa(rpa_path, target_game_dir, log_callback=None):
    """
    RPA arşivi içindeki tüm script ve gerekli kaynak dosyalarını target_game_dir klasörüne çıkarır.
    Güvenlik kuralları:
    - Path traversal ve symlink kaçışlarını kesinlikle reddeder (is_safe_rpa_path).
    - Var olan kullanıcı dosyalarını korur (sessizce ezmez).
    - Chunk ofset, uzunluk ve dosya başına 100 MB sınırlarını doğrular.
    - Benzersiz geçici dosya (.tmp_<uuid>) ve SHA/boyut doğrulamalı atomik yazım yapar.
    - Bozuk kayıtlarda çökmeyip kaydı atlar ve açıklayıcı uyarı verir.
    """
    def _log(msg):
        if log_callback:
            try: log_callback(msg)
            except Exception: pass

    _log(f"[*] RPA Arşivi Açılıyor: {os.path.basename(rpa_path)}...")

    try:
        index, key = read_rpa_archive(rpa_path)
    except Exception as e:
        _log(f"[X] RPA arşivi okunamadı: {e}")
        return 0

    if not isinstance(index, dict) or not index:
        _log(f"[-] {os.path.basename(rpa_path)} içinde geçerli indeks tablosu bulunamadı.")
        return 0

    is_script_archive = "script" in os.path.basename(rpa_path).lower()
    script_keys = [
        k for k in index.keys()
        if isinstance(k, str) and (k.endswith(('.rpy', '.rpyc')) or (is_script_archive and k.endswith(('.ttf', '.otf', '.ttc', '.py'))))
    ]

    if not script_keys:
        _log(f"[-] {os.path.basename(rpa_path)} içinde script dosyası bulunamadı.")
        return 0

    try:
        file_size = os.path.getsize(rpa_path)
    except OSError:
        return 0

    extracted_count = 0
    MAX_FILE_BYTES = 100 * 1024 * 1024  # 100 MB üst sınır

    try:
        with open(rpa_path, 'rb') as f:
            for k in script_keys:
                is_safe, resolved_or_err = is_safe_rpa_path(k, target_game_dir)
                if not is_safe:
                    _log(f"[!] Güvenlik engeli: '{k}' geçersiz veya güvensiz dosya yolu ({resolved_or_err}), atlandı.")
                    continue

                out_path = resolved_or_err

                # Var olan dosyayı koru: kullanıcının üzerinde çalıştığı dosyayı sessizce ezme!
                if os.path.exists(out_path):
                    _log(f"[*] Var olan dosya korundu (ezilmedi): {k}")
                    continue

                chunks = index.get(k)
                if not isinstance(chunks, (list, tuple)):
                    continue

                content = b''
                valid_chunks = True
                total_file_bytes = 0

                for chunk in chunks:
                    if not isinstance(chunk, (list, tuple)) or len(chunk) < 2:
                        valid_chunks = False
                        break
                    if len(chunk) == 2:
                        c_off, c_len = chunk[0], chunk[1]
                        prefix = b''
                    else:
                        c_off, c_len, prefix = chunk[0], chunk[1], chunk[2]
                        if not isinstance(prefix, (bytes, bytearray)):
                            prefix = b''

                    if not isinstance(c_off, int) or not isinstance(c_len, int):
                        valid_chunks = False
                        break

                    c_off = c_off ^ key if key else c_off
                    c_len = c_len ^ key if key else c_len

                    if c_off < 0 or c_len < 0 or c_off + c_len > file_size:
                        valid_chunks = False
                        break

                    total_file_bytes += len(prefix) + c_len
                    if total_file_bytes > MAX_FILE_BYTES:
                        _log(f"[!] Güvenlik engeli: '{k}' maksimum dosya boyutu sınırını (100 MB) aştı, atlandı.")
                        valid_chunks = False
                        break

                    f.seek(c_off)
                    chunk_data = f.read(c_len)
                    if len(chunk_data) != c_len:
                        valid_chunks = False
                        break
                    content += prefix + chunk_data

                if not valid_chunks:
                    _log(f"[!] Uyarı: '{k}' bozuk veya sınırları aşan chunk verisi içeriyor, atlandı.")
                    continue

                if k.endswith('.rpy'):
                    try:
                        rpy_text = content.decode('utf-8')
                        repaired = False
                        if "init 700 init 700 init phone register:" in rpy_text:
                            rpy_text = rpy_text.replace("init 700 init 700 init phone register:", "init 700 init phone register:")
                            repaired = True
                        if '\n.add_positional' in rpy_text:
                            rpy_text = rpy_text.replace('\n.add_positional', '\n        .add_positional')
                            repaired = True
                        if '\n.add_property' in rpy_text:
                            rpy_text = rpy_text.replace('\n.add_property', '\n        .add_property')
                            repaired = True
                        if repaired:
                            content = rpy_text.encode('utf-8')
                    except Exception:
                        pass

                os.makedirs(os.path.dirname(out_path), exist_ok=True)
                tmp_out = out_path + f".tmp_{uuid.uuid4().hex}"
                try:
                    with open(tmp_out, 'wb') as out_f:
                        out_f.write(content)
                    if os.path.exists(tmp_out) and os.path.getsize(tmp_out) == len(content):
                        os.replace(tmp_out, out_path)
                        extracted_count += 1
                    else:
                        if os.path.exists(tmp_out):
                            os.remove(tmp_out)
                except Exception as e:
                    _log(f"[!] Dosya yazma hatası ({k}): {e}")
                    if os.path.exists(tmp_out):
                        try: os.remove(tmp_out)
                        except Exception: pass

    except Exception as e:
        _log(f"[X] Arşiv çıkarma sırasında hata: {e}")
        return extracted_count

    if is_script_archive and extracted_count > 0:
        try:
            bak_path = rpa_path + ".bak"
            if not os.path.exists(bak_path):
                os.rename(rpa_path, bak_path)
        except Exception:
            pass

    _log(f"[+] {os.path.basename(rpa_path)} içinden {extracted_count} adet script dosyası başarıyla dışa aktarıldı!")
    return extracted_count

def unpack_all_rpas_in_dir(game_dir, log_callback=None):
    """
    Belirtilen dizindeki (ve 'game' alt klasöründeki) tüm .rpa arşivlerini tarar
    ve içlerindeki scriptleri çıkarır. Asla renpy/ veya lib/ klasörlerine girmez.
    """
    target = find_real_renpy_game_dir(game_dir)

    rpa_files = []
    for root, dirs, files in os.walk(target):
        dirs[:] = [d for d in dirs if d.lower() not in IGNORED_DIRS]
        norm_parts = os.path.normpath(root).lower().split(os.sep)
        if "tl" in norm_parts:
            tl_idx = norm_parts.index("tl")
            if tl_idx == len(norm_parts) - 1:
                dirs[:] = [d for d in dirs if d.lower() in ALLOWED_TL_LANGS]
            else:
                lang = norm_parts[tl_idx + 1]
                if lang not in ALLOWED_TL_LANGS:
                    dirs[:] = []
                    continue
        for f in files:
            if f.endswith('.rpa'):
                rpa_files.append(os.path.join(root, f))

    if not rpa_files:
        return 0

    total_extracted = 0
    for rpa in rpa_files:
        cnt = extract_scripts_from_rpa(rpa, target, log_callback=log_callback)
        total_extracted += cnt

    return total_extracted

def detect_obfuscation_key_from_engine(game_dir):
    """
    Oyun motorunun renpy/ dizininden varsa özel anahtarları (AOC veya RWAZONE) tespit eder.
    """
    candidates = [
        os.path.join(game_dir, "renpy"),
        os.path.join(game_dir, "..", "renpy"),
        os.path.join(find_real_renpy_game_dir(game_dir), "..", "renpy"),
    ]
    for c in candidates:
        c = os.path.abspath(c)
        if os.path.exists(c) and os.path.isdir(c):
            # 1. script.py kaynak dosyasını kontrol et
            spy = os.path.join(c, "script.py")
            if os.path.exists(spy):
                try:
                    with open(spy, "r", encoding="utf-8", errors="ignore") as f:
                        txt = f.read()
                        if "XOR_KEY" in txt or "PICKLE_MAGIC" in txt:
                            return ("rwazone", (XOR_KEY_RWAZONE, PICKLE_MAGIC_RWAZONE))
                        if "_ROT_KEY" in txt or "LAUREN" in txt:
                            return ("aoc", 113)
                except Exception:
                    pass

            # 2. .pyc dosyalarında bytecode veya sabit ara
            for root, dirs, files in os.walk(c):
                for f in files:
                    if f.startswith("script") and f.endswith(".pyc"):
                        fpath = os.path.join(root, f)
                        try:
                            with open(fpath, "rb") as fp:
                                raw = fp.read()
                                if XOR_KEY_RWAZONE in raw or b"PICKLE_MAGIC" in raw:
                                    return ("rwazone", (XOR_KEY_RWAZONE, PICKLE_MAGIC_RWAZONE))
                                if b"_ROT_KEY" in raw or b"LAUREN" in raw:
                                    return ("aoc", 113)
                        except Exception:
                            pass
    return None

def is_game_obfuscated(game_dir):
    """
    Oyun motorunun veya .rpyc dosyalarının özel şifreli (AOC LAUREN RPC2 veya RWAZONE XOR) olup olmadığını tespit eder.
    """
    info = detect_obfuscation_key_from_engine(game_dir)
    if info is not None:
        return True, info

    target = find_real_renpy_game_dir(game_dir)
    for root, dirs, files in os.walk(target):
        dirs[:] = [d for d in dirs if d.lower() not in IGNORED_DIRS]
        for f in files:
            if f.endswith(".rpyc"):
                try:
                    with open(os.path.join(root, f), "rb") as fp:
                        hdr = fp.read(11)
                        if hdr == RPYC2_HEADER_LAUREN:
                            return True, ("aoc", 113)
                        elif hdr == RPYC2_HEADER_STANDARD:
                            fp.seek(len(RPYC2_HEADER_STANDARD))
                            slot, start, length = struct.unpack("III", fp.read(12))
                            if slot == 1 and length > 0:
                                fp.seek(start)
                                test_bytes = fp.read(length)
                                try:
                                    zlib.decompress(test_bytes)
                                except Exception:
                                    try:
                                        kl = len(XOR_KEY_RWAZONE)
                                        dec = bytes(b ^ XOR_KEY_RWAZONE[i % kl] for i, b in enumerate(test_bytes))
                                        if zlib.decompress(dec).startswith(PICKLE_MAGIC_RWAZONE):
                                            return True, ("rwazone", (XOR_KEY_RWAZONE, PICKLE_MAGIC_RWAZONE))
                                    except Exception:
                                        pass
                except Exception:
                    pass
    return False, None

def unlock_custom_renpy_engine(game_dir, log_callback=None):
    """
    Özel şifreli motorlarda (.rpy derleyicisi devredışı bırakılan veya XOR koruması olan)
    motoru standart ve açık uyumlu hale getirir.
    Böylece oyun hem .rpy kaynak kodlarını hem de özel .rpyc dosyalarını sorunsuz çalıştırır.
    """
    is_obf, obf_info = is_game_obfuscated(game_dir)
    if not is_obf:
        return False

    obf_type = obf_info[0] if isinstance(obf_info, tuple) else "aoc"

    candidates = [
        os.path.join(game_dir, "renpy"),
        os.path.join(game_dir, "..", "renpy"),
        os.path.join(find_real_renpy_game_dir(game_dir), "..", "renpy"),
    ]
    renpy_dir = None
    for c in candidates:
        c = os.path.abspath(c)
        if os.path.exists(c) and os.path.isdir(c):
            renpy_dir = c
            break

    if not renpy_dir:
        return False

    dest_script_py = os.path.join(renpy_dir, "script.py")

    if obf_type == "aoc":
        needs_copy = True
        if os.path.exists(dest_script_py):
            try:
                with open(dest_script_py, "r", encoding="utf-8", errors="ignore") as f:
                    content = f.read()
                    if "RPYC2_HEADER_STANDARD" in content and "self.initcode.extend" in content:
                        needs_copy = False
            except Exception:
                needs_copy = True

        if needs_copy:
            try:
                unlocked_code = safe_zlib_decompress(base64.b64decode(AOC_UNLOCKED_SCRIPT_PY_B64)).decode("utf-8")
                if not safe_write_with_backup(dest_script_py, unlocked_code, log_callback=log_callback):
                    return False
            except Exception as e:
                if log_callback:
                    log_callback(f"[X] AOC script.py yazılamadı: {e}")
                return False
            if log_callback:
                try:
                    log_callback("[⚡] AOC şifreli Ren'Py motoru tespit edildi ve motor kilidi açıldı (script.py eklendi).")
                except Exception:
                    pass
        return True

    elif obf_type == "rwazone":
        if os.path.exists(dest_script_py):
            try:
                with open(dest_script_py, "r", encoding="utf-8", errors="ignore") as f:
                    content = f.read()

                patched = False
                # 1. read_rpyc_data
                old_read = "        data = f.read(length)\n\n        data = xor_transform(data, XOR_KEY)\n        return zlib.decompress(data)"
                new_read = "        data = f.read(length)\n        try:\n            return zlib.decompress(data)\n        except Exception:\n            pass\n        try:\n            data = xor_transform(data, XOR_KEY)\n            return zlib.decompress(data)\n        except Exception:\n            return None"
                if old_read in content:
                    content = content.replace(old_read, new_read)
                    patched = True

                # 2. load_file
                old_load = "                            if bindata:\n                                if bindata.startswith(PICKLE_MAGIC):\n                                    bindata = bindata[len(PICKLE_MAGIC):]\n                                    data, stmts = loads(bindata)\n                                    break\n                                else:\n                                    # Fallback for old/unprotected files if needed, \n                                    # or just fail if we want strict enforcement.\n                                    # For now, we enforce protection.\n                                    pass"
                new_load = "                            if bindata:\n                                if bindata.startswith(PICKLE_MAGIC):\n                                    bindata = bindata[len(PICKLE_MAGIC):]\n                                try:\n                                    data, stmts = loads(bindata)\n                                    break\n                                except Exception:\n                                    pass"
                if old_load in content:
                    content = content.replace(old_load, new_load)
                    patched = True

                # 3. suppress key mismatch
                old_key = "        elif self.key != data['key']:\n            raise Exception(fn + \" does not share a key with at least one .rpyc file. To fix, delete all .rpyc files, or rerun Ren'Py with the --lock option.\")"
                new_key = "        elif self.key != data.get('key'):\n            pass"
                if old_key in content:
                    content = content.replace(old_key, new_key)
                    patched = True

                if patched:
                    safe_write_with_backup(dest_script_py, content, log_callback=log_callback)

                # 4. RWAZONE main.py bak rename engelle
                dest_main_py = os.path.join(renpy_dir, "main.py")
                if os.path.exists(dest_main_py):
                    try:
                        with open(dest_main_py, "r", encoding="utf-8", errors="ignore") as mf:
                            m_content = mf.read()
                        bad_pat = 'if not os.path.isfile(os.path.join(dn, fn + ".rpy")) and not os.path.isfile(os.path.join(dn, fn + "_ren.py")):'
                        if bad_pat in m_content:
                            m_content = m_content.replace(bad_pat, 'if False and not os.path.isfile(os.path.join(dn, fn + ".rpy")) and not os.path.isfile(os.path.join(dn, fn + "_ren.py")):')
                            safe_write_with_backup(dest_main_py, m_content, log_callback=log_callback)
                            patched = True
                    except Exception:
                        pass

                # 5. renpy/common ve sistem klasorlerinde .rpyc.bak dosyalarini kurtar
                common_dir = os.path.join(renpy_dir, "common")
                if os.path.exists(common_dir):
                    for cf in os.listdir(common_dir):
                        if cf.endswith(".rpyc.bak"):
                            c_src = os.path.join(common_dir, cf)
                            c_dst = os.path.join(common_dir, cf[:-4])
                            if os.path.exists(c_dst):
                                try:
                                    os.remove(c_dst)
                                except Exception:
                                    pass
                            try:
                                os.rename(c_src, c_dst)
                            except Exception:
                                pass

                if patched:
                    # pycache temizle
                    pycache = os.path.join(renpy_dir, "__pycache__")
                    if os.path.exists(pycache):
                        for pf in os.listdir(pycache):
                            if pf.startswith("script."):
                                try:
                                    os.remove(os.path.join(pycache, pf))
                                except Exception:
                                    pass

                    # Oyunun kendi python ortamı varsa derlet
                    game_py_candidates = [
                        os.path.join(game_dir, "..", "lib", "py3-windows-x86_64", "python.exe"),
                        os.path.join(game_dir, "lib", "py3-windows-x86_64", "python.exe"),
                        os.path.join(find_real_renpy_game_dir(game_dir), "..", "lib", "py3-windows-x86_64", "python.exe"),
                    ]
                    for gpy in game_py_candidates:
                        if os.path.exists(gpy):
                            try:
                                subprocess.run([gpy, "-m", "py_compile", dest_script_py], capture_output=True, timeout=10)
                                break
                            except Exception:
                                pass

                    if log_callback:
                        try:
                            log_callback("[⚡] RWAZONE korumalı Ren'Py motoru tespit edildi ve motor kilidi açıldı.")
                        except Exception:
                            pass
                else:
                    # R5 Fix: hicbir yama uygulanamazsa sessiz dernmek yerine nedeni raporla
                    if log_callback:
                        try:
                            log_callback("[!] RWAZONE motoru bulundu ancak beklenen yama imzaları bulunamadı; kilitleme desenleri farklı olabilir.")
                        except Exception:
                            pass
            except Exception as exc:
                # R5 Fix: sessiz swallow yerine raporla (milestone ve hata ayıklama şansı)
                if log_callback:
                    try:
                        log_callback(f"[!] RWAZONE motor kilidi acilirken hata: {exc}")
                    except Exception:
                        pass
        return True

    return False

_rpyc_base32_tables = None


def _decode_rpyc_base32(data):
    """Decode large canonical Base32 blocks with paired-symbol lookups.

    Keep the stdlib path for small/noncanonical data, including its exact errors.
    This only packs already validated symbols; it never loads a pickle.
    """
    if not isinstance(data, bytes) or len(data) < 4096:
        return base64.b32decode(data)
    trimmed = data.rstrip(b'=')
    padding = len(data) - len(trimmed)
    if len(data) % 8 or padding not in (0, 1, 3, 4, 6):
        return base64.b32decode(data)
    global _rpyc_base32_tables
    if _rpyc_base32_tables is None:
        from array import array
        alphabet = b'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
        validate = bytes(alphabet.find(bytes([symbol])) & 255 for symbol in range(256))
        pairs = array('H', [0]) * 65536
        # Validated trailing '=' packs as zero, avoiding a full padded copy.
        for left, a in enumerate(alphabet + b'='):
            for right, b in enumerate(alphabet + b'='):
                pairs[(a << 8) | b] = ((left & 31) << 5) | (right & 31)
        _rpyc_base32_tables = validate, pairs
    validate, pairs = _rpyc_base32_tables
    if b'\xff' in trimmed.translate(validate):
        return base64.b32decode(data)
    decoded = bytearray()
    for a, b, c, d in struct.iter_unpack('>HHHH', data):
        value = (pairs[a] << 30) | (pairs[b] << 20) | (pairs[c] << 10) | pairs[d]
        decoded.extend(value.to_bytes(5, 'big'))
    if padding:
        del decoded[-((padding * 5 + 7) // 8):]
    return bytes(decoded)


def _convert_reverse_base32_rpyc(file_path, max_bytes=50 * 1024 * 1024):
    """Decode the offset-91 codec without unpickling or modifying the input."""
    try:
        with open(file_path, 'rb') as source:
            # Ordinary RPC2 / LAUREN / XOR inputs must not be read in full merely
            # to discover that they do not use the offset-91 codec.
            header = source.read(46)
            if (not header.startswith(RPYC2_HEADER_STANDARD) or len(header) < 46 or
                    struct.unpack_from('<II', header, 10) != (1, 137)):
                return None
            source.seek(0)
            data = source.read(max_bytes + 1)
        if len(data) > max_bytes or not data.startswith(RPYC2_HEADER_STANDARD):
            return None
        slots = []
        pos = len(RPYC2_HEADER_STANDARD)
        for expected in (1, 2, 0):
            slot, start, length = struct.unpack_from('<III', data, pos)
            pos += 12
            if slot != expected:
                return None
            if not slot:
                if start or length:
                    return None
                break
            slots.append((slot, start - 91, length))
        cursor = pos
        payloads = []
        remaining = max_bytes
        for slot, start, length in slots:
            if start != cursor or length <= 0 or start + length > len(data):
                return None
            decoder = zlib.decompressobj()
            encoded = decoder.decompress(data[start:start + length][::-1], remaining + 1)
            if len(encoded) > remaining or not decoder.eof or decoder.unused_data or decoder.unconsumed_tail:
                return None
            remaining -= len(encoded)
            raw = _decode_rpyc_base32(encoded)
            if not raw.startswith(b'\x80\x02') or not raw.endswith(b'.'):
                return None
            payloads.append((slot, zlib.compress(raw)))
            cursor += length
        # Engine appends a digest after the slot data; it is not executable data.
        out = bytearray(RPYC2_HEADER_STANDARD)
        offset = pos
        for slot, payload in payloads:
            out.extend(struct.pack('<III', slot, offset, len(payload)))
            offset += len(payload)
        out.extend(struct.pack('<III', 0, 0, 0))
        for _, payload in payloads:
            out.extend(payload)
        return bytes(out)
    except (OSError, ValueError, struct.error, zlib.error):
        return None


def convert_custom_obfuscated_rpyc(file_path, rot_key=113, xor_key=XOR_KEY_RWAZONE, pickle_magic=PICKLE_MAGIC_RWAZONE):
    """
    Özel şifrelenmiş veya başlığı değiştirilmiş .rpyc dosyalarını
    (örn: Adult Oyun Çeviri LAUREN RPC2 veya RWAZONE XOR)
    standart Ren'Py RPC2 formatına dönüştürür.
    Böylece unrpyc tarafından sorunsuz decompile edilebilir.
    """
    converted = _convert_reverse_base32_rpyc(file_path)
    if converted is not None:
        return converted
    try:
        with open(file_path, "rb") as f:
            header_data = f.read(1024)

        is_lauren = header_data.startswith(RPYC2_HEADER_LAUREN)
        is_rwazone = False

        if not is_lauren and header_data.startswith(RPYC2_HEADER_STANDARD):
            pos = len(RPYC2_HEADER_STANDARD)
            slot, start, length = struct.unpack("III", header_data[pos:pos+12])
            if slot == 1 and length > 0:
                with open(file_path, "rb") as f:
                    f.seek(start)
                    test_bytes = f.read(length)
                try:
                    zlib.decompress(test_bytes)
                except Exception:
                    try:
                        kl = len(xor_key)
                        dec = bytes(b ^ xor_key[i % kl] for i, b in enumerate(test_bytes))
                        dec_uncomp = zlib.decompress(dec)
                        if dec_uncomp.startswith(pickle_magic):
                            is_rwazone = True
                    except Exception:
                        pass

        if not is_lauren and not is_rwazone:
            return None

        matched_header = RPYC2_HEADER_LAUREN if is_lauren else RPYC2_HEADER_STANDARD
        decrypt_table = bytes((i - rot_key) % 256 for i in range(256))

        with open(file_path, "rb") as f:
            header_data = f.read(1024)
            pos = len(matched_header)
            slots = []
            while pos + 12 <= len(header_data):
                slot, start, length = struct.unpack("III", header_data[pos:pos+12])
                if slot == 0:
                    break
                slots.append((slot, start, length))
                pos += 12

            if not slots:
                return None

            slot_data_map = {}
            kl = len(xor_key)
            for slot, start, length in slots:
                f.seek(start)
                data = f.read(length)
                if is_lauren:
                    dec = data[::-1].translate(decrypt_table)
                elif is_rwazone:
                    try:
                        dec = zlib.decompress(data)
                    except Exception:
                        raw_zlib = bytes(b ^ xor_key[i % kl] for i, b in enumerate(data))
                        dec = zlib.decompress(raw_zlib)
                    if dec.startswith(pickle_magic):
                        dec = dec[len(pickle_magic):]

                comp = zlib.compress(dec)
                slot_data_map[slot] = comp

            out = bytearray(RPYC2_HEADER_STANDARD)
            current_offset = 1024
            header_slots_bytes = bytearray()
            payloads = bytearray()
            for slot in sorted(slot_data_map.keys()):
                p = slot_data_map[slot]
                header_slots_bytes.extend(struct.pack("III", slot, current_offset, len(p)))
                payloads.extend(p)
                current_offset += len(p)
            header_slots_bytes.extend(struct.pack("III", 0, 0, 0))
            out.extend(header_slots_bytes)
            if len(out) < 1024:
                out.extend(b'\x00' * (1024 - len(out)))
            out.extend(payloads)
            return bytes(out)
    except Exception:
        return None

def _rpyc_decompile_batches(paths, prefix, max_files=128, max_command_chars=24000):
    """Amortize worker-pool startup without exceeding Windows command limits."""
    batch = []
    for path in paths:
        candidate = batch + [path]
        command = subprocess.list2cmdline(list(prefix) + candidate)
        units = len(command.encode('utf-16-le', errors='surrogatepass')) // 2
        if batch and (len(candidate) > max_files or units > max_command_chars):
            yield batch
            batch = [path]
        else:
            batch = candidate
    if batch:
        yield batch


def _publish_decompiled_source(temporary, destination):
    """Publish without replacing a source that appeared during decompilation."""
    try:
        if os.name == 'nt':
            # Unlike replace(), Windows rename() refuses an existing target.
            os.rename(temporary, destination)
        else:
            # Same-directory hard links give atomic exclusive creation on POSIX.
            os.link(temporary, destination)
            os.unlink(temporary)
        return True
    except FileExistsError:
        return False


def decompile_all_rpyc_in_dir(game_dir, log_callback=None):
    """
    Belirtilen dizindeki tum .rpyc derlenmis dosyalari .rpy kaynak kodlarina donusturur.
    Guvenlik kurallari:
    - Var olan .rpy dosyalarini korur (ezmez veya silmez).
    - Decompile ciktisini dogrular, basarisiz olursa orijinal dosyalari korur.
    - Gecici dosyalari guvenle temizler.
    - Donus kodlarini ve zaman asimlarini denetler.
    """
    def _log(msg):
        if log_callback:
            try: log_callback(msg)
            except Exception: pass

    target = find_real_renpy_game_dir(game_dir)
    rpyc_to_decompile = []
    skipped_existing = 0
    for root, dirs, files in os.walk(target):
        dirs[:] = [d for d in dirs if d.lower() not in IGNORED_DIRS]
        for f in files:
            if f.endswith('.rpyc') and not f.endswith('.wtbak') and not f.endswith('.bak'):
                rpy_counterpart = os.path.join(root, f[:-1])
                ren_py_counterpart = os.path.join(root, f[:-5] + "_ren.py")
                if os.path.exists(ren_py_counterpart) or os.path.exists(rpy_counterpart):
                    skipped_existing += 1
                    continue
                rpyc_to_decompile.append(os.path.join(root, f))

    if skipped_existing > 0:
        _log(f"[*] {skipped_existing} adet mevcut .rpy kaynak dosyasi korundu (ezilmedi).")

    if not rpyc_to_decompile:
        return 0

    unrpyc_path = get_unrpyc_path(log_callback=log_callback)
    if not unrpyc_path or not os.path.exists(unrpyc_path):
        _log("[!] unrpyc decompiler bulunamadi, decompile atlaniyor.")
        return 0

    _log(f"[*] {len(rpyc_to_decompile)} adet derlenmis .rpyc dosyasi decompile ediliyor...")

    unlock_custom_renpy_engine(game_dir, log_callback=log_callback)
    sanitize_inline_python_recursion(game_dir)

    obfuscated_map = {}
    standard_batch = []
    total_decompiled = 0

    for rpyc_file in rpyc_to_decompile:
        expected_rpy = rpyc_file[:-1]
        custom_bytes = convert_custom_obfuscated_rpyc(rpyc_file)
        if custom_bytes is not None:
            import uuid
            tmp_std = rpyc_file + f".tmp_{uuid.uuid4().hex}_std.rpyc"
            try:
                with open(tmp_std, "xb") as tf:
                    tf.write(custom_bytes)
                obfuscated_map[tmp_std] = expected_rpy
            except Exception as e:
                _log(f"[X] {os.path.basename(rpyc_file)} standartlastirma hatasi: {e}")
        else:
            standard_batch.append(rpyc_file)

    if obfuscated_map:
        _log(f"[+] {len(obfuscated_map)} adet ozel korumali .rpyc dosyasi standart formata donusturuldu, toplu decompile basliyor...")

    prefix = [sys.executable, unrpyc_path]
    obf_keys = list(obfuscated_map.keys())
    for batch in _rpyc_decompile_batches(obf_keys, prefix):
        cmd = prefix + batch
        timeout = 180 * max(1, (len(batch) + 49) // 50)
        try:
            res = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
            if res.returncode != 0 and res.stderr:
                _log(f"[!] unrpyc bildirimi: {res.stderr.strip()[:200]}")
        except subprocess.TimeoutExpired:
            _log(f"[X] Toplu decompile zaman asimina ugradi ({timeout}s)")
        except Exception as e:
            _log(f"[X] Toplu decompile hatasi: {e}")

        for tmp_std in batch:
            try:
                exp_rpy = obfuscated_map[tmp_std]
                tmp_rpy = tmp_std[:-1]
                if os.path.exists(tmp_rpy) and os.path.getsize(tmp_rpy) > 0:
                    if _publish_decompiled_source(tmp_rpy, exp_rpy):
                        total_decompiled += 1
                    else:
                        # It may have appeared while workers were running.
                        # Never overwrite a concurrent user source with our temp.
                        os.remove(tmp_rpy)
                        _log(f"[*] Islem sirasinda olusan kaynak korundu: {os.path.basename(exp_rpy)}")
                elif os.path.exists(tmp_rpy):
                    os.remove(tmp_rpy)
            except OSError as exc:
                _log(f"[X] Decompile ciktisi aktarilamadi ({os.path.basename(tmp_std)}): {exc}")
            finally:
                if os.path.exists(tmp_std[:-1]):
                    try: os.remove(tmp_std[:-1])
                    except Exception: pass
                if os.path.exists(tmp_std):
                    try: os.remove(tmp_std)
                    except Exception: pass

    for batch in _rpyc_decompile_batches(standard_batch, prefix):
        cmd = prefix + batch
        timeout = 120 * max(1, (len(batch) + 49) // 50)
        try:
            res = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
            if res.returncode != 0 and res.stderr:
                _log(f"[!] unrpyc bildirimi: {res.stderr.strip()[:200]}")
        except subprocess.TimeoutExpired:
            _log(f"[X] Standart decompile zaman asimina ugradi ({timeout}s)")
        except Exception as e:
            _log(f"[X] Decompile islemi sirasinda hata: {e}")

        for f in batch:
            exp_rpy = f[:-1]
            if os.path.exists(exp_rpy) and os.path.getsize(exp_rpy) > 0:
                total_decompiled += 1
            else:
                try:
                    cmd_retry = [sys.executable, unrpyc_path, "--try-harder", f]
                    subprocess.run(cmd_retry, capture_output=True, text=True, timeout=60)
                    if os.path.exists(exp_rpy) and os.path.getsize(exp_rpy) > 0:
                        total_decompiled += 1
                except Exception:
                    pass

    if total_decompiled > 0:
        _log(f"[+] Toplam {total_decompiled} adet script dosyasi .rpy kaynak koduna donusturuldu!")
    else:
        _log(f"[i] Yeni decompile edilecek dosya kalmadi veya dosyalar zaten mevcuttu.")

    auto_repair_decompiled_scripts(game_dir, log_callback=log_callback)
    sanitize_inline_python_recursion(game_dir)

    return total_decompiled


def auto_repair_decompiled_scripts(game_dir, log_callback=None):
    """
    unrpyc veya ucuncu parti modullerden kaynaklanan soz dizimi ve ayrastirma hatalarini otomatik onarir:
    1. python / python early bloklarinda satir basi girintisiz kalan '.add_...' metot zincirleri
    2. Bagimsiz 'init ... phone register:' gibi mukerrer veya hatali init deyimleri
    3. Dosya sonunda fonksiyon/etiket disi kalan ve sozdizimi bozan sahipsiz 'return' deyimleri
    4. Gecici veya bozuk test dosyalari (zz_test*.rpy*)
    """
    def _log(msg):
        if log_callback:
            try: log_callback(msg)
            except Exception: pass

    target = find_real_renpy_game_dir(game_dir)

    # 0. Gecici veya yetim test dosyalarini temizle
    for root, dirs, files in os.walk(target):
        for f in files:
            if f.startswith("zz_test") and (f.endswith(".rpy") or f.endswith(".rpyc") or f.endswith(".flag")):
                try:
                    os.remove(os.path.join(root, f))
                    _log(f"[*] Gecici test dosyasi temizlendi: {f}")
                except Exception:
                    pass

    repaired_count = 0
    for root, dirs, files in os.walk(target):
        dirs[:] = [d for d in dirs if d.lower() not in IGNORED_DIRS]
        for f in files:
            if not f.endswith(".rpy") or f.endswith(".wtbak") or f.endswith(".bak"):
                continue
            fpath = os.path.join(root, f)
            try:
                with open(fpath, "r", encoding="utf-8", errors="ignore") as fp:
                    file_text = fp.read()

                changed = False

                # A. Mukerrer veya hatali init phone register onarimi
                if "phone register:" in file_text:
                    new_t = re.sub(r'init\s+\d+\s+(?:init\s+\d+\s+)*(?:init\s+)?phone\s+register:', 'init phone register:', file_text)
                    new_t = re.sub(r'init\s+700\s+phone\s+register:', 'init phone register:', new_t)
                    if new_t != file_text:
                        file_text = new_t
                        changed = True

                # B. python / python early bloklarinda girintisiz kalan .add_ zincirleri
                if "\n.add_" in file_text:
                    file_text = re.sub(r'\n\.add_', '\n        .add_', file_text)
                    changed = True

                # C. unrpyc tarafindan dosya sonuna eklenen ve dosya duzeyinde sozdizim hatasi ureten sahipsiz return
                if re.search(r'\nreturn\s*\n\s*#\s*Decompiled by unrpyc', file_text):
                    file_text = re.sub(r'\nreturn(\s*\n\s*#\s*Decompiled by unrpyc)', r'\n# return\1', file_text)
                    changed = True

                if changed:
                    with open(fpath, "w", encoding="utf-8") as fp:
                        fp.write(file_text)
                    rpyc = fpath + "c"
                    if os.path.exists(rpyc):
                        try: os.remove(rpyc)
                        except Exception: pass
                    repaired_count += 1
            except Exception as e:
                _log(f"[!] Otomatik script onarim hatasi ({f}): {e}")

    if repaired_count > 0:
        _log(f"[+] {repaired_count} adet script dosyasindaki decompile/sozdizimi hatalari otomatik onarildi!")
    return repaired_count


def sanitize_inline_python_recursion(game_dir):
    """
    Third-party Inline-Python kutuphanesindeki global ORIGINAL_FILTER lambda recursion bug'ini temizler.
    """
    target = find_real_renpy_game_dir(game_dir)
    for root, dirs, files in os.walk(target):
        for f in files:
            if f.endswith('.rpy'):
                fpath = os.path.join(root, f)
                try:
                    with open(fpath, 'r', encoding='utf-8', errors='ignore') as fp:
                        content = fp.read()
                    if 'ORIGINAL_FILTER = config.say_menu_text_filter' in content and 'lambda s: ORIGINAL_FILTER(' in content:
                        patched = content.replace(
                            'ORIGINAL_FILTER = config.say_menu_text_filter\n        config.say_menu_text_filter = lambda s: ORIGINAL_FILTER(add_conditional_tags(s))',
                            '_orig_cond_filter = config.say_menu_text_filter\n        config.say_menu_text_filter = lambda s, _f=_orig_cond_filter: _f(add_conditional_tags(s)) if _f else add_conditional_tags(s)'
                        ).replace(
                            'ORIGINAL_FILTER = config.say_menu_text_filter\n        config.say_menu_text_filter = lambda s: ORIGINAL_FILTER(parse_general_expression(s))',
                            '_orig_expr_filter = config.say_menu_text_filter\n        config.say_menu_text_filter = lambda s, _f=_orig_expr_filter: _f(parse_general_expression(s)) if _f else parse_general_expression(s)'
                        )
                        if patched != content:
                            with open(fpath, 'w', encoding='utf-8') as fp:
                                fp.write(patched)
                            rpyc = fpath + 'c'
                            if os.path.exists(rpyc):
                                try: os.remove(rpyc)
                                except Exception: pass
                except Exception:
                    pass


def unblock_directory(folder):
    """
    Windows SmartScreen ve Zone.Identifier kilitlerini PowerShell ve alternatif veri akışı (ADS) ile kaldırır.
    """
    try:
        subprocess.run(
            ["powershell", "-NoProfile", "-Command", f'Get-ChildItem -Path "{folder}" -Recurse -File -ErrorAction SilentlyContinue | Unblock-File -ErrorAction SilentlyContinue'],
            capture_output=True,
            timeout=10
        )
    except Exception:
        pass
    try:
        if os.name == "nt":
            for root, _, files in os.walk(folder):
                for f in files:
                    fp = os.path.join(root, f) + ":Zone.Identifier"
                    if os.path.exists(fp):
                        try:
                            os.remove(fp)
                        except Exception:
                            pass
    except Exception:
        pass

def is_virtual_turbo_container(target_path):
    """
    Hedef klasorun veya calistirilabilir dosyanin Turbo Studio (Spoon / RWAZONE)
    sanallastirma kapsulu olup olmadigini tespit eder.
    """
    target_path = os.path.abspath(target_path)
    if os.path.isfile(target_path):
        folder = os.path.dirname(target_path)
        files = [os.path.basename(target_path)]
    else:
        folder = target_path
        try:
            files = os.listdir(folder)
        except Exception:
            return False, None

    has_rwa = any(f.lower().endswith(".rwa") for f in files)
    exe_files = [f for f in files if f.lower().endswith(".exe")]

    turbo_exe = None
    for ef in exe_files:
        ep = os.path.join(folder, ef)
        try:
            with open(ep, "rb") as f:
                head = f.read(15 * 1024 * 1024)
                if b">xvmi" in head or b"xvmi" in head or b"xlayer" in head:
                    turbo_exe = ep
                    break
        except Exception:
            pass

    if has_rwa or turbo_exe:
        return True, {
            "has_rwa": has_rwa,
            "turbo_exe": turbo_exe,
            "folder": folder
        }
    return False, None

def find_game_sandbox_folder(sandbox_base, preferred_name="", running_pid=None):
    """
    Turbo Studio'nun %LOCALAPPDATA% altindaki sanal diskinde oyunun gercek
    klasorunu bulur (@APPDATA@ veya @DESKTOP@ altinda).
    """
    roaming_base = os.path.join(sandbox_base, "roaming", "modified")
    if not os.path.exists(roaming_base):
        return None

    # 1. Calisan surecten dogrudan tespit et
    if running_pid:
        try:
            import psutil
            p = psutil.Process(running_pid)
            children = p.children(recursive=True)
            for c in children:
                for arg in c.cmdline():
                    arg_lower = arg.lower()
                    if arg_lower.endswith(".exe") and "turbo" not in arg_lower and "spoon" not in arg_lower:
                        rel_path = None
                        if "appdata\\roaming\\" in arg_lower:
                            idx = arg_lower.find("appdata\\roaming\\")
                            rel_path = os.path.join("@APPDATA@", arg[idx+len("appdata\\roaming\\"):])
                        elif "desktop\\" in arg_lower:
                            idx = arg_lower.find("desktop\\")
                            rel_path = os.path.join("@DESKTOP@", arg[idx+len("desktop\\"):])

                        if rel_path:
                            candidate_game_root = os.path.dirname(os.path.join(roaming_base, rel_path))
                            if os.path.exists(candidate_game_root):
                                return candidate_game_root
        except Exception:
            pass

    # 2. Disk taramasi ile tespit et (@APPDATA@ ve @DESKTOP@)
    candidates = []
    for sub in ["@APPDATA@", "@DESKTOP@"]:
        sub_dir = os.path.join(roaming_base, sub)
        if os.path.exists(sub_dir):
            for d in os.listdir(sub_dir):
                dp = os.path.join(sub_dir, d)
                if os.path.isdir(dp):
                    try:
                        subfiles = os.listdir(dp)
                        has_py = any(f.endswith(".py") or f in ["renpy", "lib", "game"] or d.endswith(("-pc", "-pc-lin")) for f in subfiles)
                        if has_py:
                            candidates.append((os.path.getmtime(dp), dp, d))
                    except Exception:
                        pass

    if not candidates:
        return None

    if preferred_name:
        p_clean = preferred_name.lower().replace("rwazone-", "").replace("rwazone_", "").replace("-", "").replace("_", "").replace(" ", "")
        for _, path, name in candidates:
            n_clean = name.lower().replace("-", "").replace("_", "").replace(" ", "")
            common_chars = 0
            for i in range(min(len(p_clean), len(n_clean))):
                if p_clean[i] == n_clean[i]:
                    common_chars += 1
                else:
                    break
            if common_chars >= 4 or p_clean in n_clean or n_clean in p_clean:
                return path
        return None

    candidates.sort(key=lambda x: x[0], reverse=True)
    return candidates[0][1]

def run_process_silently_with_window_hider(cmd, cwd, max_timeout=180, wait_for_file=None, poll_callback=None):
    """
    Kapsul / Oyun baslatma islemlerini 100% gorunmez, sessiz (headless) ve arka planda calistirir.
    - SDL_AUDIODRIVER=dummy ve RENPY_SOUND=0 ile tum oyun seslerini tamamen keser.
    - STARTUPINFO SW_HIDE ve CREATE_NO_WINDOW ile surecin pencere acmasini engeller.
    - Win32 API ile arka plan izleme dongusu calistirarak, olusan alt pencereleri (Turbo VM, splash, launcher)
      ekran disina iter (-32000, -32000) ve aninda gizler.
    - Islem bittiginde veya hedef dosya olustugunda tum alt islemleri aninda sonlandirir.
    """
    env = os.environ.copy()
    env["SDL_AUDIODRIVER"] = "dummy"
    env["RENPY_SOUND"] = "0"

    startupinfo = subprocess.STARTUPINFO()
    startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
    startupinfo.wShowWindow = 0  # SW_HIDE

    creationflags = 0x08000000  # CREATE_NO_WINDOW

    try:
        proc = subprocess.Popen(
            cmd,
            cwd=cwd,
            env=env,
            startupinfo=startupinfo,
            creationflags=creationflags
        )
    except Exception as e:
        return False, str(e)

    stop_event = threading.Event()

    def _window_hider():
        user32 = ctypes.windll.user32
        WNDENUMPROC = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)

        def enum_cb(hwnd, lparam):
            try:
                pid = ctypes.c_ulong()
                user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
                if pid.value in pids:
                    user32.ShowWindow(hwnd, 0)
                    user32.SetWindowPos(hwnd, 0, -32000, -32000, 0, 0, 0x0001 | 0x0004 | 0x0010)
            except Exception:
                pass
            return True

        cb = WNDENUMPROC(enum_cb)

        while not stop_event.is_set():
            pids = {proc.pid}
            try:
                p = psutil.Process(proc.pid)
                for c in p.children(recursive=True):
                    pids.add(c.pid)
            except Exception:
                pass

            try:
                user32.EnumWindows(cb, 0)
            except Exception:
                pass

            time.sleep(0.02)

    hider_thread = threading.Thread(target=_window_hider, daemon=True)
    hider_thread.start()

    start_time = time.time()
    success = False

    try:
        while time.time() - start_time < max_timeout:
            if wait_for_file and os.path.exists(wait_for_file):
                success = True
                time.sleep(0.5)
                break

            if poll_callback:
                try:
                    if poll_callback(proc.pid):
                        success = True
                        break
                except Exception:
                    pass

            if proc.poll() is not None:
                success = True
                break

            time.sleep(0.3)
    finally:
        stop_event.set()
        try:
            p = psutil.Process(proc.pid)
            for c in p.children(recursive=True):
                try:
                    c.kill()
                except Exception:
                    pass
            p.kill()
        except Exception:
            pass

    return success, None


def clean_site_artifacts(game_dir, log_callback=None, auto_delete=False):
    """
    RWAZONE, Adult Oyun Ceviri (AOC) ve diger repack sitelerinin launcher,
    presplash acilis ekrani, kisayol, reklam ve baslik artiklarini tespit eder.
    GÜVENLİK KURALI: Varsayılan olarak dosya silmez veya değiştirmez, sadece raporlar (auto_delete=False).
    auto_delete=True açıkça onaylandığında, silinen/değiştirilen her dosya için önce doğrulanmış .wtbak yedeği alır;
    yedek doğrulanamazsa silme işlemini DURDURUR.
    """
    def _log(msg):
        if log_callback:
            try: log_callback(msg)
            except Exception: pass

    if not os.path.isdir(game_dir):
        return None

    # 1. Gercek oyun adini bul (ana .py dosyasindan)
    py_files = [f for f in os.listdir(game_dir) if f.endswith(".py") and not f.startswith("zz_") and f.lower() != "setup.py"]
    official_game_name = None
    if py_files:
        official_game_name = os.path.splitext(py_files[0])[0]

    if not official_game_name:
        folder_base = os.path.basename(game_dir)
        clean_fb = folder_base
        for g in ["RWAZONE-", "RWAZONE_", "RWAZONE", "Adult Oyun Ceviri", "Adult Oyun Çeviri", "AOC", "_Unlocked"]:
            clean_fb = clean_fb.replace(g, "").strip(" -_")
        official_game_name = clean_fb or "Launch"

    clean_native_exe_name = official_game_name + ".exe"

    def _safe_remove(file_path, desc):
        if not auto_delete:
            _log(f"[*] {desc} tespit edildi (raporlandı, silinmedi): {os.path.basename(file_path)}")
            return False
        bak_p = file_path + ".wtbak"
        try:
            shutil.copy2(file_path, bak_p)
            bh, bs = compute_file_sha256(bak_p)
            oh, osz = compute_file_sha256(file_path)
            if bh != oh or bs != osz:
                if os.path.exists(bak_p):
                    try: os.remove(bak_p)
                    except Exception: pass
                _log(f"[X] Yedek doğrulanamadı, silme durduruldu: {file_path}")
                return False
            os.remove(file_path)
            _log(f"[*] {desc} güvenle yedeklenip silindi: {os.path.basename(file_path)}")
            return True
        except Exception as e:
            _log(f"[!] Dosya silme hatası ({file_path}): {e}")
            return False

    # 2. Site launcher'larini ve sanal konteyner exe'lerini incele
    for f in list(os.listdir(game_dir)):
        fpath = os.path.join(game_dir, f)
        fl = f.lower()

        # URL kisayollari (.url)
        if fl.endswith(".url"):
            _safe_remove(fpath, "Site bağlantısı")
            continue

        # Reklam / site metin ve bat dosyalari
        if any(site in fl for site in ["rwazone", "adultoyun", "adult oyun", "aoc", "bizi takip"]):
            if fl.endswith((".txt", ".bat", ".lnk", ".url", ".html", ".htm")):
                _safe_remove(fpath, "Site artık dosyası")
                continue

        # Executable dosyalari incele
        if fl.endswith(".exe") and not fl.startswith("zz_"):
            is_site_exe = any(site in fl for site in ["rwazone", "adult oyun", "adultoyun", "aoc"])
            is_virtual = False
            try:
                with open(fpath, "rb") as nef:
                    head = nef.read(1024 * 1024)
                    if b">xvmi" in head or b"xvmi" in head or b"xlayer" in head or b"spoon" in head:
                        is_virtual = True
            except Exception:
                pass

            if is_site_exe or is_virtual:
                if fl != clean_native_exe_name.lower():
                    _safe_remove(fpath, "Site launcher / sanal başlatıcı")

    # 3. Game klasoru icindeki presplash launcher gorsellerini ve site adlarini incele
    real_game_dir = find_real_renpy_game_dir(game_dir)
    if real_game_dir and os.path.isdir(real_game_dir):
        # A) Presplash acilis reklami/launcher gorselleri
        for presplash_f in list(os.listdir(real_game_dir)):
            pfl = presplash_f.lower()
            if (pfl.startswith("presplash_background") or pfl.startswith("presplash_foreground") or pfl.startswith("presplash")) and any(s in pfl for s in ["rwazone", "adultoyun", "aoc", "repack"]):
                ps_path = os.path.join(real_game_dir, presplash_f)
                _safe_remove(ps_path, "Site açılış yükleme ekranı")

        # B) Site adli scriptleri incele
        for sf in list(os.listdir(real_game_dir)):
            sfl = sf.lower()
            if any(site in sfl for site in ["rwazone", "adultoyun", "aoc"]) and sfl.endswith(".rpy"):
                if not auto_delete:
                    _log(f"[*] Site adlı script tespit edildi (raporlandı, değiştirilmedi): {sf}")
                else:
                    clean_sf = sf
                    for s in ["rwazone", "RWAZONE", "adultoyun", "AdultOyun", "aoc", "AOC"]:
                        clean_sf = clean_sf.replace(s, "turkish")
                    old_p = os.path.join(real_game_dir, sf)
                    new_p = os.path.join(real_game_dir, clean_sf)
                    try:
                        shutil.copy2(old_p, old_p + ".wtbak")
                        if os.path.exists(new_p):
                            os.remove(new_p)
                        os.rename(old_p, new_p)
                        if os.path.exists(old_p + "c"):
                            os.remove(old_p + "c")
                        _log(f"[*] Script güvenle yedeklenip yeniden adlandırıldı: {sf} -> {clean_sf}")
                    except Exception as e:
                        _log(f"[!] Script yeniden adlandırma hatası: {e}")

        # C) options.rpy ve tl/*/options.rpy icindeki site basliklarini incele
        for root, dirs, files in os.walk(real_game_dir):
            for f in files:
                if f.lower() == "options.rpy":
                    opt_p = os.path.join(root, f)
                    try:
                        with open(opt_p, "r", encoding="utf-8", errors="ignore") as opf:
                            opt_content = opf.read()
                        
                        modified = False
                        new_content = opt_content
                        site_patterns = [
                            ("RWAZONE ", ""),
                            ("RWAZONE_", ""),
                            (" - Adult Oyun Ceviri", ""),
                            (" - Adult Oyun Çeviri", ""),
                            (" - AdultOyunCeviri", ""),
                            (" - AOC", ""),
                            (" AOC", ""),
                            (" [RWAZONE]", ""),
                            (" [AOC]", "")
                        ]
                        for spat, srep in site_patterns:
                            if spat in new_content:
                                new_content = new_content.replace(spat, srep)
                                modified = True
                        
                        if modified:
                            if not auto_delete:
                                _log(f"[*] options.rpy içinde site başlığı tespit edildi (raporlandı, değiştirilmedi): {f}")
                            else:
                                safe_write_with_backup(opt_p, new_content, log_callback=log_callback)
                                _log("[*] options.rpy site başlıkları temizlendi.")
                    except Exception:
                        pass

    # 4. Temiz yerel baslaticiyi derle / garantile
    clean_exe_path = os.path.join(game_dir, clean_native_exe_name)
    if not os.path.exists(clean_exe_path):
        build_native_launcher(game_dir, exe_name=clean_native_exe_name, log_callback=log_callback)
    else:
        try:
            with open(clean_exe_path, "rb") as ef:
                head = ef.read(1024 * 1024)
                if b">xvmi" in head or b"xvmi" in head or b"xlayer" in head:
                    build_native_launcher(game_dir, exe_name=clean_native_exe_name, log_callback=log_callback)
        except Exception:
            pass

    return clean_native_exe_name

def unpack_virtual_turbo_container(target_path, output_dir=None, log_callback=None, allow_container_exec=False):
    """
    EVRENSEL TURBO STUDIO / RWAZONE OTOMATIK KIRICI & DISA AKTARICI:
    Paketli/sanallastirilmis (.rwa veya tek parca sanal exe) oyunlari tespit eder,
    SmartScreen kilitlerini acar, sanal bellek katmanindan tum oyun dosyalarini diske aktarir.
    GÜVENLİK KURALI: allow_container_exec=True olmadan KESİNLİKLE hiçbir .exe çalıştırılmaz!
    """
    def _log(msg):
        if log_callback:
            try: log_callback(msg)
            except Exception: pass

    if not allow_container_exec:
        _log("[!] GÜVENLİK ENGELİ: Sanallaştırılmış Turbo Studio kapsülünü çalıştırma izni (allow_container_exec) verilmedi.")
        _log("[!] Güvenliğiniz için harici .exe dosyaları açık kullanıcı onayı olmadan çalıştırılmaz. Kapsül atlandı.")
        return None
    """
    EVRENSEL TURBO STUDIO / RWAZONE OTOMATIK KIRICI & DISA AKTARICI:
    Paketli/sanallastirilmis (.rwa veya tek parca sanal exe) oyunlari tespit eder,
    SmartScreen kilitlerini acar, sanal bellek katmanindan tum oyun dosyalarini diske aktarir,
    yerel calistiriciyi yerlestirir ve motor kilidini acar.
    Tum islemler %100 gorunmez, sessiz (headless) arka planda calisir.
    Ren'Py 7 (Python 2.7) ve Ren'Py 8 (Python 3.x) ile %100 uyumludur.
    """
    is_v, info = is_virtual_turbo_container(target_path)
    if not is_v:
        return None

    folder = info["folder"]
    launcher_exe = info.get("turbo_exe")
    if not launcher_exe:
        for f in os.listdir(folder):
            if f.lower().endswith(".exe"):
                launcher_exe = os.path.join(folder, f)
                break
    if not launcher_exe:
        return None

    def _log(msg):
        if log_callback:
            try:
                log_callback(msg)
            except Exception:
                pass

    _log("[*] Sanallastirilmis Turbo Studio kapsulu tespit edildi: " + os.path.basename(launcher_exe))

    # 1. Dosya kilitlerini kaldir
    unblock_directory(folder)

    # 2. Sandbox klasorunu bul veya olustur
    localapp = os.environ.get("LOCALAPPDATA", "")
    sandbox_base = os.path.join(localapp, "Turbo.net", "Sandbox", "1.0.0.0")

    # Kisaca calistirip sandbox'i baslat (100% SESSİZ VE GÖRÜNMEZ)
    _log("[*] Sanal dosya sistemi baslatiliyor (Sessiz ve arka planda)...")

    folder_name = os.path.basename(folder)
    exe_name_base = os.path.splitext(os.path.basename(launcher_exe))[0]

    child_target_path = None
    def _check_sandbox(pid):
        nonlocal child_target_path
        child_target_path = find_game_sandbox_folder(sandbox_base, preferred_name=exe_name_base, running_pid=pid)
        return child_target_path is not None

    run_process_silently_with_window_hider(
        [launcher_exe],
        folder,
        max_timeout=8,
        poll_callback=_check_sandbox
    )

    # 3. Sandbox icindeki oyun klasorunu bul
    sb_game_dir = child_target_path
    if not sb_game_dir:
        sb_game_dir = find_game_sandbox_folder(sandbox_base, preferred_name=exe_name_base)
    if not sb_game_dir:
        sb_game_dir = find_game_sandbox_folder(sandbox_base, preferred_name=folder_name)

    if not sb_game_dir:
        _log("[X] Sandbox icinde sanal oyun klasoru tespit edilemedi!")
        return None

    target_game_dir = os.path.join(sb_game_dir, "game")
    os.makedirs(target_game_dir, exist_ok=True)

    # 4. Hedef disk klasorunu akilli belirle (Site isimlerinden arindirilmis)
    if not output_dir:
        base_parent = os.path.dirname(folder)
        generic_names = {"yeni klasor", "yeni klasör", "new folder", "desktop", "downloads", "masaustu", "masaüstü"}

        clean_name = folder_name
        for garbage in ["Adult Oyun Ceviri", "Adult Oyun Çeviri", "AdultOyunCeviri", "AOC", "RWAZONE-", "RWAZONE_", "RWAZONE", "RWA-", "RWA_"]:
            clean_name = clean_name.replace(garbage, "").strip(" -_")

        if not clean_name or clean_name.lower() in generic_names:
            clean_name = exe_name_base
            for garbage in ["Adult Oyun Ceviri", "Adult Oyun Çeviri", "AdultOyunCeviri", "AOC", "RWAZONE-", "RWAZONE_", "RWAZONE", "RWA-", "RWA_"]:
                clean_name = clean_name.replace(garbage, "").strip(" -_")

        if not clean_name:
            clean_name = "Unlocked_Game"

        output_dir = os.path.join(base_parent, clean_name)
        if os.path.abspath(output_dir) == os.path.abspath(folder):
            output_dir = output_dir + "_Unlocked"

    os.makedirs(output_dir, exist_ok=True)
    _log("[+] Dışa aktarma hedef klasörü: " + output_dir)

    # 5. Dumper scriptini sandbox'a enjekte et (Tamamen sessiz, hizli copyfile ve completion flag ile)
    dumper_script = os.path.join(target_game_dir, "zz_autodumper.rpy")
    flag_file = os.path.join(output_dir, "zz_dump_complete.flag")
    if os.path.exists(flag_file):
        try: os.remove(flag_file)
        except Exception: pass

    script_lines = [
        "init -9999999 python:",
        "    import os",
        "    import shutil",
        "    import sys",
        "    try:",
        "        import renpy",
        "        renpy.config.sound = False",
        "        renpy.config.music = False",
        "        renpy.config.has_sound = False",
        "        renpy.config.has_music = False",
        "        renpy.config.has_voice = False",
        "        renpy.config.presplash = None",
        "        renpy.config.presplash_image = None",
        "    except Exception:",
        "        pass",
        "",
        "    dest_dir = r'" + output_dir + "'",
        "    base = renpy.config.basedir",
        "",
        "    def _safe_mkdirs(d):",
        "        if not os.path.exists(d):",
        "            try:",
        "                os.makedirs(d)",
        "            except Exception:",
        "                pass",
        "",
        "    _safe_mkdirs(dest_dir)",
        "",
        "    def _fast_copy(src, dst):",
        "        try:",
        "            with open(src, 'rb') as fsrc:",
        "                with open(dst, 'wb') as fdst:",
        "                    while True:",
        "                        buf = fsrc.read(16 * 1024 * 1024)",
        "                        if not buf: break",
        "                        fdst.write(buf)",
        "        except Exception:",
        "            try: shutil.copyfile(src, dst)",
        "            except Exception: pass",
        "",
        "    for root, dirs, files in os.walk(base):",
        "        rel = os.path.relpath(root, base)",
        "        out_root = os.path.join(dest_dir, rel)",
        "        _safe_mkdirs(out_root)",
        "        for f in files:",
        "            if f.startswith('zz_autodumper'):",
        "                continue",
        "            src_path = os.path.join(root, f)",
        "            dst_path = os.path.join(out_root, f)",
        "            if not os.path.exists(dst_path) or os.path.getsize(dst_path) != os.path.getsize(src_path):",
        "                _fast_copy(src_path, dst_path)",
        "",
        "    try:",
        "        flag_p = os.path.join(dest_dir, 'zz_dump_complete.flag')",
        "        with open(flag_p, 'w') as fp:",
        "            fp.write('OK')",
        "    except Exception:",
        "        pass",
        "",
        "    try:",
        "        renpy.quit()",
        "    except Exception:",
        "        pass",
        "    try:",
        "        sys.exit(0)",
        "    except Exception:",
        "        pass",
        "    import os",
        "    os._exit(0)",
        ""
    ]
    with open(dumper_script, "w", encoding="utf-8") as f:
        f.write("\n".join(script_lines))

    # 6. Dumper'i calistir ve disari aktar (100% SESSİZ VE GÖRÜNMEZ)
    _log("[*] Sanal dosya sisteminden disk disina kopyalama basliyor (Sessiz ve arka planda)...")

    run_process_silently_with_window_hider(
        [launcher_exe],
        folder,
        max_timeout=240,
        wait_for_file=flag_file
    )

    if os.path.exists(flag_file):
        try: os.remove(flag_file)
        except Exception: pass

    # 7. Sandbox'i temizle
    for f in os.listdir(target_game_dir):
        if f.startswith("zz_autodumper"):
            try:
                os.remove(os.path.join(target_game_dir, f))
            except Exception:
                pass

    # Eger sandbox diskinde lib veya renpy klasorleri varsa ve dest_dir'de eksikse tamamla
    for eng_dir in ["lib", "renpy"]:
        sb_eng = os.path.join(sb_game_dir, eng_dir)
        dst_eng = os.path.join(output_dir, eng_dir)
        if os.path.exists(sb_eng) and (not os.path.exists(dst_eng) or len(os.listdir(dst_eng)) == 0):
            try:
                shutil.copytree(sb_eng, dst_eng, dirs_exist_ok=True)
            except Exception:
                pass

    # 8. Site launcher artiklarini temizle ve saf yerel Windows baslaticisini (.exe) hazirla
    clean_site_artifacts(output_dir, log_callback=log_callback)

    # 9. Motor kilidini otomatik ac
    try:
        unlock_custom_renpy_engine(output_dir, log_callback=log_callback)
    except Exception:
        pass

    _log("[✓] Oyun sanal kapsülden başarıyla çıkarıldı ve motor kilidi açıldı: " + output_dir)
    return output_dir


def build_native_launcher(game_root_dir, exe_name=None, log_callback=None):
    """
    Saf yerel (native) Windows Ren'Py baslaticisi (.exe) derler.
    Turbo Virtual Machine kilitlerini, site launcher bagimliliklarini ve 0x00E00 hatalarini onler.
    """
    def _log(msg):
        if log_callback:
            try: log_callback(msg)
            except Exception: pass

    if not exe_name:
        py_files = [f for f in os.listdir(game_root_dir) if f.endswith(".py") and not f.startswith("zz_") and f.lower() != "setup.py"]
        if py_files:
            exe_name = os.path.splitext(py_files[0])[0] + ".exe"
        else:
            exe_name = "Launch.exe"

    cs_code = r"""using System;
using System.Diagnostics;
using System.IO;

class Program {
    [STAThread]
    static void Main(string[] args) {
        string baseDir = AppDomain.CurrentDomain.BaseDirectory;

        string[] pyCandidates = new string[] {
            Path.Combine(baseDir, "lib", "py3-windows-x86_64", "pythonw.exe"),
            Path.Combine(baseDir, "lib", "py3-windows-x86_64", "python.exe"),
            Path.Combine(baseDir, "lib", "py3-windows-i686", "pythonw.exe"),
            Path.Combine(baseDir, "lib", "py3-windows-i686", "python.exe"),
            Path.Combine(baseDir, "lib", "windows-x86_64", "pythonw.exe"),
            Path.Combine(baseDir, "lib", "windows-x86_64", "python.exe"),
            Path.Combine(baseDir, "lib", "windows-i686", "pythonw.exe"),
            Path.Combine(baseDir, "lib", "windows-i686", "python.exe")
        };

        string pythonExe = null;
        foreach (string py in pyCandidates) {
            if (File.Exists(py)) {
                pythonExe = py;
                break;
            }
        }

        if (pythonExe == null) return;

        string scriptPy = null;
        string[] files = Directory.GetFiles(baseDir, "*.py");
        foreach (string f in files) {
            string name = Path.GetFileName(f);
            if (!name.StartsWith("zz_") && !name.Equals("setup.py", StringComparison.OrdinalIgnoreCase)) {
                scriptPy = f;
                break;
            }
        }

        if (scriptPy == null) return;

        ProcessStartInfo psi = new ProcessStartInfo();
        psi.FileName = pythonExe;
        psi.Arguments = "\"" + scriptPy + "\"";
        if (args != null && args.Length > 0) {
            // R5 Fix: bosluk/tirnak iceren argümanlar güvenli sekilde ayrı ayrı tırnaklanır
            psi.Arguments += " \"" + string.Join("\" \"", args) + "\"";
        }
        psi.WorkingDirectory = baseDir;
        psi.UseShellExecute = false;
        psi.CreateNoWindow = true;

        try {
            Process.Start(psi);
        } catch {}
    }
}
"""
    out_exe = os.path.join(game_root_dir, exe_name)
    cs_path = os.path.join(game_root_dir, "temp_launcher.cs")
    with open(cs_path, "w", encoding="utf-8") as f:
        f.write(cs_code)

    windir = os.environ.get("WINDIR", r"C:\Windows")
    csc_candidates = [
        os.path.join(windir, "Microsoft.NET", "Framework64", "v4.0.30319", "csc.exe"),
        os.path.join(windir, "Microsoft.NET", "Framework", "v4.0.30319", "csc.exe")
    ]
    csc_path = None
    for c in csc_candidates:
        if os.path.exists(c):
            csc_path = c
            break

    if not csc_path:
        _log("[!] csc.exe derleyicisi bulunamadi, baslatici derlenemedi.")
        return False

    cmd = [csc_path, "/target:winexe", "/optimize+", f"/out:{out_exe}", cs_path]
    res = subprocess.run(cmd, capture_output=True, encoding="utf-8", errors="ignore")

    if os.path.exists(cs_path):
        try:
            os.remove(cs_path)
        except Exception:
            pass

    if res.returncode == 0:
        _log(f"[+] Saf yerel baslatici basariyla derlendi: {exe_name}")
        return True
    else:
        _log(f"[!] Baslatici derleme hatasi: {res.stdout}")
        return False

# ======================================================================================
# BÖLÜM 2 & 3: SEÇİM ANALİZ MOTORU & HİKÂYE KONTROL MERKEZİ ŞABLONU
# ======================================================================================

def sanitize_renpy_system_folders(game_dir, log_callback=None, auto_delete=False):
    """
    Ren'Py motor klasörlerini (renpy/, renpy/common/) tarar ve 
    unrpyc veya eski modlardan kalan çakışan .rpy dosyalarını tespit eder.
    Ren'Py 8'in 'conflict, and can't exist in the same game' hatasını önler.
    GÜVENLİK KURALI: Varsayılan olarak silmez, raporlar (auto_delete=False).
    auto_delete=True verilmişse, silmeden önce doğrulanmış .wtbak yedeği alır;
    yedek doğrulanamazsa dosya silme işlemini derhal DURDURUR.
    """
    def _log(msg):
        if log_callback:
            try: log_callback(msg)
            except Exception: pass

    reported_count = 0
    cleaned_count = 0
    for root, dirs, files in os.walk(game_dir):
        if os.path.basename(root).lower() == "common" and "renpy" in os.path.normpath(root).lower().split(os.sep):
            for f in files:
                if f.endswith(".rpy"):
                    full_p = os.path.join(root, f)
                    ren_py_p = full_p[:-4] + "_ren.py"
                    rpyc_p = full_p + "c"
                    if os.path.exists(ren_py_p) or os.path.exists(rpyc_p):
                        reported_count += 1
                        if not auto_delete:
                            _log(f"[*] Çakışan sistem dosyası tespit edildi (raporlandı, silinmedi): {os.path.basename(full_p)}")
                        else:
                            bak_p = full_p + ".wtbak"
                            backup_ok = False
                            try:
                                shutil.copy2(full_p, bak_p)
                                bh, bs = compute_file_sha256(bak_p)
                                oh, osz = compute_file_sha256(full_p)
                                if bh == oh and bs == osz and bs > 0:
                                    backup_ok = True
                            except Exception as e:
                                _log(f"[X] Yedekleme başarısız ({os.path.basename(full_p)}): {e}. Dosya silme DURDURULDU!")
                                backup_ok = False

                            if not backup_ok:
                                if os.path.exists(bak_p):
                                    try: os.remove(bak_p)
                                    except Exception: pass
                                _log(f"[!] GÜVENLİK ENGELİ: Yedek doğrulanamadığı için sistem dosyası silinmedi: {full_p}")
                                continue

                            try:
                                os.remove(full_p)
                                cleaned_count += 1
                                _log(f"[✔] Çakışan sistem dosyası güvenle yedeklenip temizlendi: {os.path.basename(full_p)}")
                            except Exception as e:
                                _log(f"[!] Dosya silinemedi: {e}")

    if not auto_delete and reported_count > 0:
        _log(f"[i] Toplam {reported_count} adet potansiyel çakışan sistem dosyası raporlandı (dosyalara dokunulmadı).")
    return cleaned_count if auto_delete else reported_count

