                if clean_lookup:
                    trans = _wt_translate_clean(clean_lookup, lang)
                    if trans and trans != clean_lookup:
                        lead = inner[:len(inner) - len(inner.lstrip())]
                        trail = inner[len(inner.rstrip()):]
