            m3 = _wt_hint_only_regex.match(text)
            if m3:
                pre, inner, hint, post = m3.groups()
                hint = hint or ""
                clean_lookup = re.sub(r'\s*\([^)]*[+-][^)]*\)', '', inner).strip()
