    def wt_get_filtered_variables(query, limit=35):
        if not query or len(str(query).strip()) < 1:
            return []
        q = str(query).lower().strip()
        results = []
        try:
            store_dict = getattr(renpy.store, "__dict__", {})
            for k in sorted(store_dict.keys(), key=lambda x: str(x).lower()):
                if not isinstance(k, str) or k.startswith("_") or k.startswith("wt_"):
                    continue
                v = store_dict[k]
                if q in k.lower():
                    if isinstance(v, bool):
                        results.append((k, "bool", v))
                    elif isinstance(v, (int, float)) and not isinstance(v, bool):
                        results.append((k, "num", v))

                # 1. Seviye Sozluk (dict) Destegi (orn: points['sarah'])
                if isinstance(v, dict) and not k.startswith(("config", "gui", "renpy", "style", "preferences")):
                    for sub_k, sub_v in sorted(v.items(), key=lambda x: str(x[0]).lower()):
                        dict_expr = k + "['" + str(sub_k) + "']"
                        if q in k.lower() or q in str(sub_k).lower():
                            if isinstance(sub_v, bool):
                                results.append((dict_expr, "bool", sub_v))
                            elif isinstance(sub_v, (int, float)) and not isinstance(sub_v, bool):
                                results.append((dict_expr, "num", sub_v))
                        if len(results) >= limit:
                            break

                if len(results) >= limit:
                    break
        except Exception:
            pass
        return results

    def wt_toggle_bool_var(var_name):
        try:
            var_str = str(var_name)
            if "[" in var_str and var_str.endswith("]"):
                parts = var_str.split("[", 1)
                d_name = parts[0]
                raw_k = parts[1].rstrip("]")
                k_name = raw_k.strip("'\"")
                d = getattr(renpy.store, d_name, None)
                if isinstance(d, dict):
                    target_k = k_name if k_name in d else (int(k_name) if k_name.isdigit() and int(k_name) in d else None)
                    if target_k is not None:
                        d[target_k] = not bool(d[target_k])
                        renpy.restart_interaction()
                        return
            cur = getattr(renpy.store, var_str, False)
            setattr(renpy.store, var_str, not cur)
            renpy.restart_interaction()
        except Exception:
            pass

    def wt_modify_num_var(var_name, delta):
        try:
            var_str = str(var_name)
            if "[" in var_str and var_str.endswith("]"):
                parts = var_str.split("[", 1)
                d_name = parts[0]
                raw_k = parts[1].rstrip("]")
                k_name = raw_k.strip("'\"")
                d = getattr(renpy.store, d_name, None)
                if isinstance(d, dict):
                    target_k = k_name if k_name in d else (int(k_name) if k_name.isdigit() and int(k_name) in d else None)
                    if target_k is not None:
                        cur = d[target_k]
                        if isinstance(cur, float):
                            d[target_k] = round(cur + float(delta), 2)
                        else:
                            d[target_k] = int(cur) + int(delta)
                        renpy.restart_interaction()
                        return
            cur = getattr(renpy.store, var_str, 0)
            if isinstance(cur, float):
                new_v = round(cur + float(delta), 2)
            else:
                new_v = int(cur) + int(delta)
            setattr(renpy.store, var_str, new_v)
            renpy.restart_interaction()
        except Exception:
            pass


