class BothRouteCandidate:
    """Birbirini dışlayan iki rota, kıyafet veya etkinlik seçim çiftini temsil eder."""
    def __init__(self, menu, choice_a, choice_b, char_a="", char_b="", branch_a="", branch_b="", reason="", choices=None, bridge_kind="both"):
        self.menu = menu
        self.choice_a = choice_a
        self.choice_b = choice_b
        self.char_a = char_a
        self.char_b = char_b
        self.branch_a = branch_a
        self.branch_b = branch_b
        self.reason = reason
        self.choices = choices or [choice_a, choice_b]
        self.bridge_kind = bridge_kind
        self.file_path = menu.file_path
        self.line_num = menu.line_num
        self.file_basename = os.path.basename(menu.file_path)
        clean_name = re.sub(r'[^a-zA-Z0-9_]', '_', os.path.splitext(self.file_basename)[0])
        self.candidate_id = f"{clean_name}_m{menu.line_num + 1}"


