# R3: Soz dizimsel pasif eylemler ve gercek oncul olumsuzlama kaliplari
RE_PASSIVE_ACTIONS = re.compile(
    r'\b(?:leave|ignore|walk\s+away|wait|pass|rest|sleep|walk\s+out|skip|do\s+nothing|'
    r'ayril|terk\s*et|gormezden\s*gel|bekle|gec|dinlen|uyu|pas\s*gec|hicbir\s*sey\s*yapma)\b',
    re.IGNORECASE
)

RE_DIRECT_NEGATION_PREFIX = re.compile(
    r'\b(?:don\'?t|do\s+not|never|refuse\s+to|stop|won\'?t|will\s+not|can\'?t|cannot|asla|sakin|istemiyorum)\b',
    re.IGNORECASE
)

RE_TURKISH_NEG_VERB = re.compile(
    r'\b(?:terk\s*etme|bırakma|birakma|gitme|ayrılma|ayrilma|uyuma|bekleme|geçme|gecme)\b',
    re.IGNORECASE
)

def analyze_passive_skip_intent(text: str) -> tuple:
    """
    R3: Kelime yerine niyet ve soz dizimsel baglam kontrolu:
    - 'Don\'t leave her alone' -> Negation prefix 'Don\'t' passive action 'leave'den once -> PASIF DEGIL!
    - 'Leave me alone' -> Passive action 'leave', 'me' olumsuzluk degildir -> PASIF ATLAMADIR!
    - 'Help me find her', 'Tell me the truth', 'No problem' -> Pasif eylem yok -> PASIF DEGIL!
    """
    if not text:
        return False, ""
    
    t_clean = text.strip()
    t_lower = t_clean.lower()
    
    # 1. Turkce olumsuz fiil kontrolu
    if RE_TURKISH_NEG_VERB.search(t_lower):
        return False, "Turkce olumsuz fiil (pasif atlama reddedildi)"

    # 2. Pasif eylemleri bul
    m_acts = list(RE_PASSIVE_ACTIONS.finditer(t_lower))
    if not m_acts:
        return False, ""

    for m in m_acts:
        start_idx = m.start()
        # Eylemden onceki cumle parcasini incele
        clause_start = max(0, t_lower.rfind(',', 0, start_idx), t_lower.rfind('.', 0, start_idx), t_lower.rfind(';', 0, start_idx))
        preceding = t_lower[clause_start:start_idx].strip()
        
        # Eger pasif fiilden once bagli bir olumsuzluk on-eki varsa olumsuzdur
        if RE_DIRECT_NEGATION_PREFIX.search(preceding):
            continue
        else:
            return True, f"Pasif icerik atlama: '{m.group(0)}'"

    return False, "Olumsuzlanmis pasif eylem"


RE_ENGINE_TERMINATE = re.compile(
    r'(?:\$\s*)?renpy\.(?:quit|full_restart|utter_restart)\s*\(',
    re.IGNORECASE
)


def _source_python_statements(line):
    """Parse executable Python, not quoted Ren'Py dialogue or comments."""
    code = str(line).strip()
    if code.startswith('$'):
        code = code[1:].strip()
    try:
        return ast.parse(code).body
    except (SyntaxError, ValueError):
        return ()


def _is_renpy_dialogue(line):
    text = str(line).strip()
    if re.match(r'^(?:\$|if\b|elif\b|else\b|jump\b|call\b|label\b|scene\b|show\b|hide\b|menu\b|python\b|default\b|define\b|init\b|while\b|return\b|pause\b|with\b|stop\b|play\b|queue\b|nvl\b|window\b|voice\b|image\b|transform\b|screen\b|style\b)', text):
        return False
    return bool(re.match(r'^(?:[A-Za-z_][A-Za-z0-9_.]*(?:\s+[A-Za-z_][A-Za-z0-9_]*)*\s+)?(?:[rRfF])?["\']', text, re.DOTALL))


def _analysis_code_lines(lines):
    """Line-aligned executable view; never modify the original source buffer."""
    executable = ['\n'] * len(lines)
    for indent, text, number in cs_logical_lines(lines):
        if not _is_renpy_dialogue(text):
            executable[number] = ' ' * indent + text + '\n'
    return executable


def _is_engine_termination(line):
    if 'renpy.' not in str(line):
        return False
    for node in _source_python_statements(line):
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Call):
            fn = node.value.func
            if (isinstance(fn, ast.Attribute) and isinstance(fn.value, ast.Name)
                    and fn.value.id == 'renpy' and fn.attr in ('quit', 'full_restart', 'utter_restart')):
                return True
    return False


def _is_player_death_assignment(line):
    if '=' not in str(line):
        return False
    for node in _source_python_statements(line):
        if not isinstance(node, ast.Assign) or not isinstance(node.value, ast.Constant) or node.value.value is not True:
            continue
        for target in node.targets:
            name = target.id if isinstance(target, ast.Name) else ''
            if name and (name.lower() in PLAYER_DEATH_VARS or RE_PLAYER_DEATH_VAR_PATTERN.search(name.lower())):
                return True
    return False


class BranchPath:
    """H6b & H7: Karar agaci dali ve kosullu etki kapsullemesi."""
    def __init__(self, condition_str="", is_negated=False):
        self.condition_str = condition_str
        self.is_negated = is_negated
        self.score_delta = 0.0
        self.deltas_positive = []
        self.deltas_negative = []
        self.is_death = False
        self.is_survival = False
