def is_system_ui_screen(fpath: str = "", screen_name: str = "") -> bool:
    """Sistem, arayuz, ayar veya ceviri ekranlarini story secim menulerinden kesin olarak ayristirir."""
    if screen_name:
        scr_lower = screen_name.strip().lower()
        if scr_lower in SYSTEM_SCREEN_NAMES:
            return True
        if scr_lower.startswith(("_", "gallery", "mainmenu")):
            return True
    if fpath:
        fname = os.path.basename(fpath).lower()
        if fname in SYSTEM_UI_FILENAMES:
            return True
        norm_p = os.path.normpath(fpath).lower().split(os.sep)
        if any(folder in norm_p for folder in SYSTEM_UI_FOLDERS):
            if not any(st in norm_p for st in ("chapters", "scenes", "story")):
                return True
    return False

def find_renpy_command(game_dir: str, renpy_executable: str = None) -> list:
    """R9 & Z3: Proje icin calistirilabilir Ren'Py komutunu (exe veya python + script) tespit eder."""
    if renpy_executable and os.path.exists(renpy_executable):
        return [renpy_executable]

    for c in ["renpy.exe", "renpy.sh", "renpy"]:
        found = shutil.which(c)
        if found:
            return [found]

    candidates_dirs = [game_dir]
    parent = os.path.dirname(game_dir)
    if parent and os.path.isdir(parent):
        candidates_dirs.append(parent)
        grandparent = os.path.dirname(parent)
        if grandparent and os.path.isdir(grandparent):
            candidates_dirs.append(grandparent)

    for d in candidates_dirs:
        for c in ["renpy.exe", "renpy.sh"]:
            p_c = os.path.join(d, c)
            if os.path.exists(p_c):
                return [p_c]

        # Oyun adiyla adlandirilmis exe (orn. Between-Humanity.exe)
        try:
            for f in os.listdir(d):
                if f.lower().endswith(".exe") and not f.lower().startswith("uninstall") and not f.lower().startswith("python"):
                    exe_path = os.path.join(d, f)
                    py_counterpart = os.path.join(d, f[:-4] + ".py")
                    if os.path.exists(py_counterpart):
                        return [exe_path]
        except Exception:
            pass

        # lib/ altindaki python.exe + oyun_adi.py
        lib_dir = os.path.join(d, "lib")
        if os.path.isdir(lib_dir):
            py_exes = []
            for root, _, files in os.walk(lib_dir):
                for f in files:
                    if f.lower() in ("python.exe", "pythonw.exe", "python"):
                        py_exes.append(os.path.join(root, f))
            if py_exes:
                chosen_py = py_exes[0]
                # R5 Fix: os.listdir sırası dosya sistemine bağlıdır; yanlış script/interpreter
                # eşleşmesini önlemek için tespit deterministik öncele sıraya göre yapılır.
                py_candidates = sorted(f for f in os.listdir(d) if f.lower().endswith('.py') and f.lower() != 'setup.py')
                script_py = None
                for preferred in ("renpy.py", "main.py", "launcher.py"):
                    if preferred in py_candidates:
                        script_py = preferred
                        break
                if script_py is None and py_candidates:
                    script_py = py_candidates[0]
                if script_py:
                    return [chosen_py, os.path.join(d, script_py)]

    return []

def run_renpy_lint(game_dir: str, renpy_executable: str = None, timeout: int = 180) -> tuple:
    """R9 & Z3: Proje icin Ren'Py lint (renpy lint) calistirarak resmi dogrulama saglar."""
    cmd = find_renpy_command(game_dir, renpy_executable)
    if not cmd:
        return False, "Ren'Py calistirilabilir dosyasi bulunamadi (lint atlandi).", False

    root_dir = game_dir
    if os.path.basename(os.path.normpath(game_dir)).lower() == "game":
        root_dir = os.path.dirname(os.path.normpath(game_dir))

    full_cmd = list(cmd) + [root_dir, "lint"]
    try:
        import subprocess
        res = subprocess.run(full_cmd, capture_output=True, text=True, timeout=timeout)
        return (res.returncode == 0), (res.stdout + "\n" + res.stderr), False
    except subprocess.TimeoutExpired:
        return False, f"Ren'Py lint zaman asimina ugradi ({timeout}s).", True
    except Exception as e:
        return False, f"Lint calistirma hatasi: {e}", False

def compile_renpy_game(game_dir: str, renpy_executable: str = None, timeout: int = 120, log_callback=None) -> bool:
    """Modlama sonrasinda .rpyc bytecode'larini temiz ve eksiksiz derler (suffix _1 cakismasini ve acilis donmasini onler)."""
    cmd = find_renpy_command(game_dir, renpy_executable)
    if not cmd:
        return False

    root_dir = game_dir
    if os.path.basename(os.path.normpath(game_dir)).lower() == "game":
        root_dir = os.path.dirname(os.path.normpath(game_dir))

    full_cmd = list(cmd) + [root_dir, "compile", "--keep-orphan-rpyc"]
    try:
        import subprocess
        if log_callback:
            log_callback("[*] Ren'Py bytecode (.rpyc) toplu derlemesi baslatiliyor...")
        res = subprocess.run(full_cmd, capture_output=True, text=True, timeout=timeout)
        if res.returncode == 0:
            if log_callback:
                log_callback("[✓] Ren'Py bytecode (.rpyc) basariyla derlendi; ceviri kimlikleri korundu.")
            return True
        else:
            if log_callback:
                log_callback(f"[!] Bytecode derleme tamamlanamadi (kod: {res.returncode})")
            return False
    except Exception as e:
        if log_callback:
            log_callback(f"[!] Bytecode derleme hatasi: {e}")
        return False



# ==========================================================================
# ContractSim (gömülü): sınırlı Ren'Py alt kümesi yürütücüsü
# ==========================================================================
# -*- coding: utf-8 -*-
# ==========================================================================
# ContractSim - Doğruluk sözleşmesinin gerçek yürütmeyle denetimi
#
# Amaç: Bir menü seçeneğinin "güvenli mi / kaçınılmaz ölüm mü / gerçekten
# bir koşulu açıyor mu / rakiplerden kesin üstün mü" sorularını, betiği
# (Ren'Py alt kümesi) soyut olarak YÜRÜTEREK yanıtlamak. Emin olunamayan her
# durumda sınırlar (alt/üst) geniş tutulur; böylece renk verilmez (sağlamlık).
# ==========================================================================
import ast as _cs_ast
import re as _cs_re
import os as _cs_os
import sys as _cs_sys

CS_INF = float("inf")


class _CSUnk(object):
    __slots__ = ()

    def __repr__(self):
        return "CS_UNK"


CS_UNK = _CSUnk()


class CSSimAbort(Exception):
    pass


CS_DEATH_TEXT = _cs_re.compile(
    r"\b(game\s*over|you\s*(?:died|perished|were\s*killed|bled\s*out|drowned|are\s*dead|have\s*died)|"
    r"bad\s*end(?:ing)?|killed\s*instantly|fell\s*to\s*(?:your\s*)?death|lost\s*your\s*life|"
    r"öldün|oldun|kötü\s*son|kotu\s*son|can\s*verdin)\b", _cs_re.IGNORECASE)
CS_DEATH_LABEL = _cs_re.compile(r"(^|_)(bad_?end|game_?over|dead|death|died|you_?died)(_|$)", _cs_re.IGNORECASE)

_CS_NOOP_CALLS = (
    "renpy.notify", "renpy.pause", "renpy.restart_interaction", "renpy.music.", "renpy.sound.",
    "renpy.show", "renpy.hide", "renpy.scene", "renpy.transition", "renpy.block_rollback",
    "renpy.checkpoint", "renpy.fix_rollback", "renpy.save_persistent", "renpy.free_memory",
    "renpy.show_screen", "renpy.hide_screen", "renpy.say", "renpy.with_statement", "print",
)


def _cs_noop_call(fn):
    return any(fn.startswith(name) if name.endswith('.') else fn == name
               for name in _CS_NOOP_CALLS)


def _cs_api_write(name):
    return (name in ('print', 'renpy', 'store', 'Character', '_', 'store.print', 'store.renpy', 'builtins.print', '__builtins__.print')
            or name.startswith(('renpy.', 'store.', 'Character.', '_.')))


def _cs_state_name(name):
    for prefix in ('renpy.store.', 'store.'):
        if name.startswith(prefix):
            return name[len(prefix):]
    return name


def _cs_plain_character(node):
    # Only the native cosmetic declaration, without callbacks/conditions/custom
    # expressions. Rebinding Character/_ is separately excluded from proofs.
    if not (isinstance(node, _cs_ast.Call) and isinstance(node.func, _cs_ast.Name)
            and node.func.id == 'Character' and len(node.args) <= 1):
        return False
    values = list(node.args)
    for keyword in node.keywords:
        if keyword.arg not in ('color', 'who_color', 'what_color'):
            return False
        values.append(keyword.value)
    for value in values:
        if (isinstance(value, _cs_ast.Call) and isinstance(value.func, _cs_ast.Name)
                and value.func.id == '_' and len(value.args) == 1 and not value.keywords):
            value = value.args[0]
        if not isinstance(value, _cs_ast.Constant) or not (isinstance(value.value, str) or value.value is None):
            return False
    return True

_CS_NOOP_KEYWORDS = ("show ", "hide ", "scene ", "play ", "stop ", "queue ", "pause", "with ", "window ",
                  "nvl ", "voice ", "centered ", "extend ", "image ", "transform ", "camera ", "pass")
_CS_TOP_SKIP = ("init", "screen ", "transform ", "style ", "translate ", "image ", "layeredimage ", "camera ",
             "python", "label ")
_CS_SCREEN_COND_PREFIX = ("if ", "elif ", "showif ", "while ", "action", "sensitive", "selected", "$", "python")
_CS_TOKEN = _cs_re.compile(r"[A-Za-z_][A-Za-z0-9_.]*")


# ---------------------------------------------------------------- ayrıştırma
def _cs_scan(txt):
    """Yorumları atar; açık string ve parantez derinliğini döndürür."""
    out = []
    i, n = 0, len(txt)
    in_str = None
    triple = False
    depth = 0
    while i < n:
        ch = txt[i]
        if in_str:
            if ch == "\\" and i + 1 < n:
                out.append(ch); out.append(txt[i + 1]); i += 2; continue
            if triple:
                if txt.startswith(in_str * 3, i):
                    out.append(in_str * 3); i += 3; in_str = None; triple = False; continue
            elif ch == in_str:
                in_str = None
            out.append(ch); i += 1; continue
        if ch == "#":
            while i < n and txt[i] != "\n":
                i += 1
            continue
        if ch in "\"'":
            if txt.startswith(ch * 3, i):
                in_str = ch; triple = True; out.append(ch * 3); i += 3; continue
            in_str = ch; triple = False; out.append(ch); i += 1; continue
        if ch in "([{":
            depth += 1
        elif ch in ")]}":
            depth -= 1
        out.append(ch); i += 1
    return "".join(out), (in_str is not None), depth


def cs_logical_lines(raw):
    out = []
    i, n = 0, len(raw)
    while i < n:
        start = i
        txt = raw[i].rstrip("\r\n")
        while True:
            code, in_str, depth = _cs_scan(txt)
            if (in_str or depth > 0) and i + 1 < n and (i - start) < 60:
                i += 1
                txt = txt + "\n" + raw[i].rstrip("\r\n")
                continue
            break
        i += 1
        first = raw[start].rstrip("\r\n")
        lead = first[:len(first) - len(first.lstrip())].replace("\t", "    ")
        code = code.strip()
        if not code:
            continue
        out.append((len(lead), code, start))
    return out


def _cs_dotted(node):
    parts = []
    while isinstance(node, _cs_ast.Attribute):
        parts.append(node.attr)
        node = node.value
    if isinstance(node, _cs_ast.Name):
        parts.append(node.id)
        return ".".join(reversed(parts))
    return None


def _cs_parse_expr(src):
    try:
        return _cs_ast.parse(src.strip(), mode="eval").body
    except Exception:
        return None


def _cs_expr_names(node):
    names = set()
    for n in _cs_ast.walk(node):
        if isinstance(n, _cs_ast.Name):
            names.add(n.id)
        elif isinstance(n, _cs_ast.Attribute):
            d = _cs_dotted(n)
            if d:
                names.add(_cs_state_name(d))
    return names


def _cs_split_choice(t):
    """'"metin" [if kosul]:' -> (metin, kosul|None) ya da None."""
    if not t.endswith(":") or t[0] not in "\"'":
        return None
    q = t[0]
    i, n = 1, len(t)
    while i < n:
        if t[i] == "\\":
            i += 2; continue
        if t[i] == q:
            break
        i += 1
    if i >= n:
        return None
    text = t[1:i]
    rest = t[i + 1:-1].strip()
    cond = None
    m = _cs_re.search(r"(?:^|\s)if\s+(.+)$", rest)
    if m:
        cond = m.group(1).strip()
    return text, cond


class CSProgram(object):
    def __init__(self, death_text=CS_DEATH_TEXT):
        self.blocks = []
        self.block_label = []
        self.block_parent = []
        self.labels = {}
        self.label_files = {}
        self.next_label = {}
        self.defaults = {}
        self.consts = {}
        self.ext_tokens = set()
        self.consumed = set()
        self.menus = {}       # (path, line) -> dict
        self.menu_loc = {}    # (path, line) -> (bid, idx)
        self.death_text = death_text
        self.parse_errors = 0
        self._analysis = None
        self._context_entry = None
        self.context_unsupported = False
        self.context_reasons = set()

    # ---- yardımcılar
    def new_block(self, label, parent):
        self.blocks.append([])
        self.block_label.append(label)
        self.block_parent.append(parent)
        return len(self.blocks) - 1

    def is_death_label(self, name):
        return bool(CS_DEATH_LABEL.search(name or ""))

    def _tokens(self, src):
        for t in _CS_TOKEN.findall(src):
            t = _cs_state_name(t)
            self.ext_tokens.add(t)
            if "." in t:
                self.ext_tokens.add(t.split(".")[0])

    # ---- dosya ekleme
    def add_file(self, path, raw_lines):
        self._analysis = None
        self._context_entry = None
        L = cs_logical_lines(raw_lines)
        n = len(L)
        i = 0
        file_labels = []
        while i < n:
            ind, t, ln = L[i]
            j = i + 1
            while j < n and L[j][0] > ind:
                j += 1
            if t.startswith("label ") and t.endswith(":"):
                m = _cs_re.match(r"label\s+([A-Za-z_][\w.]*)", t)
                if m:
                    name = m.group(1)
                    if name in self.labels:
                        self.context_unsupported = True
                        self.context_reasons.add('duplicate_label')
                    if t[m.end():].strip() != ':':
                        self.context_unsupported = True  # Label parameters are not modelled.
                        self.context_reasons.add('label_parameters')
                    bid = self.new_block(name, None)
                    self.labels[name] = bid
                    self.label_files[name] = path
                    file_labels.append(name)
                    if t[m.end():].strip() != ':':
                        self.blocks[bid].append(('unknown',))
                    self._parse_stmts(L, i + 1, j, bid, name, path)
                else:
                    self.context_unsupported = True
                    self.context_reasons.add('label_syntax')
            elif t.startswith(("default ", "define ")):
                self._parse_default(t)
            else:
                # init / screen / python vb. : yalnız dış okuma izleri
                self._collect_ext(t, L[i + 1:j], screen=t.startswith("screen "))
            i = j
        for a, b in zip(file_labels, file_labels[1:]):
            self.next_label[a] = b

    def prepare_analysis(self):
        """Conservative interprocedural liveness; values/approvals are not cached.

        Call returns are supplemented by the actual continuation in CSSolver.
        Assignment dependencies include intermediate RHS variables, not just the
        variables spelled directly in conditions.
        """
        if self._analysis is not None:
            return self._analysis
        successors, predecessors, reads, writes, dependencies = {}, {}, {}, {}, {}
        for bid, block in enumerate(self.blocks):
            for idx in range(len(block) + 1):
                point = (bid, idx)
                used, defined, edges = set(), set(), set()
                after = (bid, idx + 1)
                if idx == len(block):
                    parent = self.block_parent[bid]
                    nxt = self.next_label.get(self.block_label[bid])
                    if parent is not None:
                        edges.add(parent)
                    elif nxt in self.labels:
                        edges.add((self.labels[nxt], 0))
                else:
                    stmt = block[idx]
                    kind = stmt[0]
                    if kind == 'assign':
                        target, op, node = stmt[1:]
                        if _cs_api_write(target):
                            self.context_unsupported = True
                            self.context_reasons.add('api_rebinding')
                        used |= _cs_expr_names(node) if node is not None else set()
                        if op != '=':
                            used.add(target)
                        defined.add(target)
                        dependencies.setdefault(target, set()).update(used)
                        edges.add(after)
                    elif kind == 'if':
                        for node, child, _ in stmt[1]:
                            used |= _cs_expr_names(node) if node is not None else set()
                            edges.add((child, 0))
                        edges.add((stmt[2], 0) if stmt[2] is not None else after)
                    elif kind == 'menu':
                        edges.add(after)  # Every conditional item may be hidden.
                        for _, node, child, _, _ in stmt[2]:
                            used |= _cs_expr_names(node) if node is not None else set()
                            edges.add((child, 0))
                    elif kind in ('jump', 'call'):
                        if stmt[1] in self.labels:
                            edges.add((self.labels[stmt[1]], 0))
                        if kind == 'call':
                            edges.add(after)
                    elif kind == 'call_args':
                        call = stmt[1]
                        for node in list(call.args) + [kw.value for kw in call.keywords]:
                            used |= _cs_expr_names(node)
                        edges.add(after)
                    elif kind not in ('quit', 'return', 'ctrl_unknown'):
                        edges.add(after)
                successors[point] = edges
                reads[point], writes[point] = used, defined
                self.consumed.update(used)
                for edge in edges:
                    predecessors.setdefault(edge, set()).add(point)
        live = {point: set(names) for point, names in reads.items()}
        queue = collections.deque(live)
        queued = set(live)
        while queue:
            point = queue.popleft()
            queued.discard(point)
            needed = set(reads[point])
            for edge in successors[point]:
                needed.update(live.get(edge, ()))
            needed.difference_update(writes[point] - reads[point])
            if needed != live[point]:
                live[point] = needed
                for pred in predecessors.get(point, ()):
                    if pred not in queued:
                        queue.append(pred)
                        queued.add(pred)
        self._analysis = {'live': {p: frozenset(v) for p, v in live.items()},
                          'dependencies': dependencies, 'closures': {}}
        return self._analysis

    def dependency_closure(self, names):
        analysis = self.prepare_analysis()
        key = frozenset(names)
        cached = analysis['closures'].get(key)
        if cached is not None:
            return cached
        found, pending = set(key), list(key)
        while pending:
            for name in analysis['dependencies'].get(pending.pop(), ()):
                if name not in found:
                    found.add(name)
                    pending.append(name)
        result = frozenset(found)
        analysis['closures'][key] = result
        return result

    def initial_state(self):
        self.prepare_analysis()
        initial = dict(self.consts)
        initial.update({k: v for k, v in self.defaults.items() if k in self.consumed})
        for name in list(initial):
            if name.startswith('persistent.') or name in self.ext_tokens or name.split('.')[0] in self.ext_tokens:
                initial.pop(name)
        return initial

    def _parse_default(self, t):
        m = _cs_re.match(r"(?:default|define)\s+(?:-?\d+\s+)?([A-Za-z_][\w.]*)\s*=\s*(.+)$", t)
        if not m:
            return
        name, expr = m.group(1), m.group(2)
        if name.startswith(('store.', 'renpy.store.')):
            self.context_unsupported = True
            self.context_reasons.add('default_namespace')
        if _cs_api_write(name):
            self.context_unsupported = True
            self.context_reasons.add('api_rebinding')
        try:
            val = _cs_ast.literal_eval(expr.strip())
        except Exception:
            node = _cs_parse_expr(expr)
            if _cs_expr_effect(node, {}) and not _cs_plain_character(node):
                self.context_unsupported = True
                self.context_reasons.add('initializer_effect')
            return
        if isinstance(val, (int, float, bool, str)) or val is None:
            if t.startswith("default"):
                self.defaults[name] = val
            else:
                self.consts[name] = val

    def _collect_ext(self, head, children, screen=False):
        if head.startswith(("init", "python")) or "python" in head.split(":")[0]:
            # Function bodies are declarations, not executed startup paths.
            # Other arbitrary initialization is outside this entry-state model.
            if 'python' in head and children:
                base = children[0][0]
                code = '\n'.join(' ' * (ind - base) + text for ind, text, _ in children)
                try:
                    declarations = _cs_ast.parse(code).body
                    safe_declarations = all(isinstance(n, (_cs_ast.FunctionDef, _cs_ast.AsyncFunctionDef))
                        and n.name not in ('print', 'renpy', 'store', 'Character', '_')
                        and not n.decorator_list and not n.args.defaults and not any(n.args.kw_defaults)
                        and n.returns is None and all(a.annotation is None for a in
                            list(n.args.posonlyargs) + list(n.args.args) + list(n.args.kwonlyargs)
                            + ([n.args.vararg] if n.args.vararg else [])
                            + ([n.args.kwarg] if n.args.kwarg else []))
                        for n in declarations)
                except (SyntaxError, ValueError):
                    safe_declarations = False
                if not safe_declarations:
                    self.context_unsupported = True
                    self.context_reasons.add('initialization')
            elif children:
                self.context_unsupported = True
                self.context_reasons.add('initialization')
            self._tokens(head)
            for (_, t, _l) in children:
                self._tokens(t)
            return
        if screen:
            for (_, t, _l) in children:
                if t.startswith(_CS_SCREEN_COND_PREFIX):
                    self._tokens(t)
            return
        # diğer üst düzey bloklar (transform/style...): iz yok

    # ---- ifade/deyim ayrıştırma
    def _cond(self, src):
        node = _cs_parse_expr(src)
        if node is None:
            self._tokens(src)
            return None
        self.consumed |= _cs_expr_names(node)
        return node

    def _parse_stmts(self, L, i, j, cur, label, path):
        blocks = self.blocks
        while i < j:
            ind, t, ln = L[i]
            k = i + 1
            while k < j and L[k][0] > ind:
                k += 1
            idx = len(blocks[cur])
            parent = (cur, idx + 1)
            try:
                if t.startswith("menu") and t.endswith(":") and _cs_re.match(r"menu\b[^\"']*:$", t):
                    if not _cs_re.fullmatch(r'menu(?:\s+[A-Za-z_]\w*)?:', t):
                        self.context_unsupported = True
                        self.context_reasons.add('menu_arguments')
                        blocks[cur].append(('unknown',))
                        parent = (cur, len(blocks[cur]) + 1)
                    self._parse_menu(L, i, k, cur, label, path, ln, parent)
                    i = k
                    continue
                if t.startswith("if ") and t.endswith(":"):
                    branches = []
                    else_bid = None
                    cond_node = self._cond(t[3:-1])
                    bid = self.new_block(label, parent)
                    self._parse_stmts(L, i + 1, k, bid, label, path)
                    branches.append((cond_node, bid, ln))
                    i = k
                    while i < j and L[i][0] == ind:
                        ind2, t2, ln2 = L[i]
                        k2 = i + 1
                        while k2 < j and L[k2][0] > ind:
                            k2 += 1
                        if t2.startswith("elif ") and t2.endswith(":"):
                            cn = self._cond(t2[5:-1])
                            b2 = self.new_block(label, parent)
                            self._parse_stmts(L, i + 1, k2, b2, label, path)
                            branches.append((cn, b2, ln2))
                            i = k2
                            continue
                        if t2 == "else:":
                            else_bid = self.new_block(label, parent)
                            self._parse_stmts(L, i + 1, k2, else_bid, label, path)
                            i = k2
                        break
                    blocks[cur].append(("if", branches, else_bid))
                    continue
                if t.startswith("while ") and t.endswith(":"):
                    self._tokens(t)
                    for (_, tt, _l) in L[i + 1:k]:
                        self._tokens(tt)
                    blocks[cur].append(("unknown",))
                    i = k
                    continue
                if t.startswith("python") and t.endswith(":"):
                    if t != 'python:':
                        self.context_unsupported = True
                        self.context_reasons.add('python_namespace')
                        blocks[cur].append(('unknown',))
                    self._parse_python_block(L, i, k, cur)
                    i = k
                    continue
                if t.startswith("$"):
                    self._parse_py(t[1:].strip(), cur)
                    i = k
                    continue
                if t.startswith("jump "):
                    rest = t[5:].strip()
                    if rest.startswith("expression"):
                        blocks[cur].append(("ctrl_unknown",))
                    else:
                        blocks[cur].append(("jump", rest.split()[0]))
                    i = k
                    continue
                if t.startswith("call "):
                    rest = t[5:].strip()
                    if rest.startswith("screen") or rest.startswith("expression"):
                        blocks[cur].append(("ctrl_unknown",))
                    else:
                        nm = _cs_re.match(r"([A-Za-z_][\w.]*)", rest)
                        if nm and not _cs_re.fullmatch(r'(?:\s+from\s+[A-Za-z_][\w.]*)?', rest[nm.end():]):
                            self.context_unsupported = True
                            self.context_reasons.add('call_arguments')
                            blocks[cur].append(('ctrl_unknown',))
                        else:
                            blocks[cur].append(("call", nm.group(1)) if nm else ("ctrl_unknown",))
                    i = k
                    continue
                if t == "return" or t.startswith("return "):
                    if t != 'return':
                        self.context_unsupported = True
                        self.context_reasons.add('return_expression')
                        blocks[cur].append(('unknown',))
                    blocks[cur].append(("return",))
                    i = k
                    continue
                if t[0] in "\"'" or _cs_re.match(r"^[A-Za-z_][\w.]*(?:\s+[A-Za-z_]\w*)*\s+[\"'rRfF]", t):
                    blocks[cur].append(("say", t))
                    i = k
                    continue
                if t.startswith(_CS_NOOP_KEYWORDS):
                    literal_pause = _cs_re.fullmatch(r'pause\s*\(?\s*(?:\d+(?:\.\d*)?|\.\d+)\s*\)?', t)
                    if ('(' in t or ' expression ' in t) and not literal_pause:
                        self.context_unsupported = True
                        self.context_reasons.add('display_expression')
                        blocks[cur].append(('unknown',))
                    else:
                        blocks[cur].append(("noop",))
                    i = k
                    continue
                # tanınmayan deyim: durum bozulur, kontrol akışı da bilinmeyebilir
                self._tokens(t)
                blocks[cur].append(("unknown",))
            except Exception:
                self.parse_errors += 1
                blocks[cur].append(("unknown",))
            i = k

    def _parse_menu(self, L, i, k, cur, label, path, ln, parent):
        choices = []
        children = L[i + 1:k]
        if not children:
            self.blocks[cur].append(("noop",))
            return
        cbase = children[0][0]
        if any(ind == cbase and text.startswith('set ') for ind, text, _ in children):
            self.context_unsupported = True
            self.context_reasons.add('menu_set')
            self.blocks[cur].append(('unknown',))
            parent = (cur, len(self.blocks[cur]) + 1)
        a = i + 1
        while a < k:
            ind, t, cln = L[a]
            b = a + 1
            while b < k and L[b][0] > ind:
                b += 1
            if ind == cbase:
                sc = _cs_split_choice(t)
                if sc is not None:
                    text, cond_src = sc
                    cnode = None
                    cond_ok = True
                    if cond_src:
                        cnode = self._cond(cond_src)
                        cond_ok = cnode is not None
                    bid = self.new_block(label, parent)
                    self._parse_stmts(L, a + 1, b, bid, label, path)
                    choices.append((cln, cnode, bid, text, cond_ok))
            a = b
        mid = (path, ln)
        idx = len(self.blocks[cur])
        self.menus[mid] = {"choices": choices, "bid": cur, "idx": idx}
        self.menu_loc[mid] = (cur, idx)
        self.blocks[cur].append(("menu", mid, choices))

    def _parse_python_block(self, L, i, k, cur):
        kids = L[i + 1:k]
        if not kids:
            self.blocks[cur].append(("noop",))
            return
        base = kids[0][0]
        code = "\n".join(" " * (ind - base) + t for (ind, t, _l) in kids)
        self._parse_py(code, cur, block=True)

    def _parse_py(self, code, cur, block=False):
        blocks = self.blocks
        try:
            tree = _cs_ast.parse(code)
        except Exception:
            self._tokens(code)
            blocks[cur].append(("unknown",))
            return
        for node in tree.body:
            if isinstance(node, _cs_ast.Assign):
                ok = True
                names = []
                for tg in node.targets:
                    d = _cs_dotted(tg) if isinstance(tg, (_cs_ast.Name, _cs_ast.Attribute)) else None
                    if d is None:
                        ok = False
                        break
                    names.append(_cs_state_name(d))
                if not ok:
                    self._tokens(code); blocks[cur].append(("unknown",)); continue
                for d in names:
                    blocks[cur].append(("assign", d, "=", node.value))
            elif isinstance(node, _cs_ast.AugAssign):
                d = _cs_dotted(node.target) if isinstance(node.target, (_cs_ast.Name, _cs_ast.Attribute)) else None
                if d is not None:
                    d = _cs_state_name(d)
                op = {_cs_ast.Add: "+", _cs_ast.Sub: "-", _cs_ast.Mult: "*", _cs_ast.FloorDiv: "//",
                      _cs_ast.Mod: "%"}.get(type(node.op))
                if d is None or op is None:
                    self._tokens(code); blocks[cur].append(("unknown",)); continue
                blocks[cur].append(("assign", d, op, node.value))
            elif isinstance(node, _cs_ast.Expr) and isinstance(node.value, _cs_ast.Call):
                # Python evaluates arguments before even a recognized control or
                # presentation call. Preserve those expressions for effect checks.
                blocks[cur].append(("call_args", node.value))
                fn = _cs_dotted(node.value.func) or ""
                arg0 = node.value.args[0] if node.value.args else None
                lit = arg0.value if isinstance(arg0, _cs_ast.Constant) and isinstance(arg0.value, str) else None
                if fn == "renpy.jump" and lit:
                    blocks[cur].append(("jump", lit))
                elif fn == "renpy.call" and lit:
                    blocks[cur].append(("call", lit))
                elif fn in ("renpy.quit", "renpy.full_restart"):
                    blocks[cur].append(("quit",))
                elif fn in ("renpy.jump", "renpy.call", "renpy.call_in_new_context", "renpy.call_screen",
                            "renpy.run", "renpy.display_menu", "renpy.invoke_in_new_context"):
                    blocks[cur].append(("ctrl_unknown",))
                elif _cs_noop_call(fn):
                    blocks[cur].append(("noop",))
                else:
                    self._tokens(code)
                    blocks[cur].append(("unknown",))
            elif isinstance(node, _cs_ast.Pass):
                blocks[cur].append(("noop",))
            else:
                self._tokens(code)
                blocks[cur].append(("unknown",))


# ---------------------------------------------------------------- değerlendirme
_CS_TAINT = "\0t"


def _cs_expr_effect(node, st):
    """May this evaluated expression run unmodelled Python? Never execute it.

    Missing scalar values alone are not effects. Unknown guards require checking
    both possible continuations; known short circuits skip unreachable calls.
    """
    if node is None:
        return True
    t = type(node)
    if t in (_cs_ast.Constant, _cs_ast.Name):
        return False
    if t is _cs_ast.BoolOp:
        for operand in node.values:
            if _cs_expr_effect(operand, st):
                return True
            truth = _cs_truth(cs_ev(operand, st))
            if (isinstance(node.op, _cs_ast.And) and truth is False or
                    isinstance(node.op, _cs_ast.Or) and truth is True):
                break
        return False
    if t is _cs_ast.IfExp:
        if _cs_expr_effect(node.test, st):
            return True
        truth = _cs_truth(cs_ev(node.test, st))
        return (truth is not False and _cs_expr_effect(node.body, st) or
                truth is not True and _cs_expr_effect(node.orelse, st))
    if t is _cs_ast.Compare:
        if _cs_expr_effect(node.left, st):
            return True
        left = cs_ev(node.left, st)
        for op, operand in zip(node.ops, node.comparators):
            if _cs_expr_effect(operand, st):
                return True
            right = cs_ev(operand, st)
            if left is not CS_UNK and right is not CS_UNK:
                if _cs_truth(_cs_cmp(op, left, right)) is False:
                    break
            left = right
        return False
    if t is _cs_ast.Call:
        if not _cs_noop_call(_cs_dotted(node.func) or ''):
            return True
        return any(_cs_expr_effect(arg, st) for arg in node.args) or any(
            _cs_expr_effect(kw.value, st) for kw in node.keywords)
    if t is _cs_ast.NamedExpr:
        return True  # A write hidden inside an expression is not modelled.
    return any(_cs_expr_effect(child, st) for child in _cs_ast.iter_child_nodes(node))


def _cs_cmp(op, a, b):
    try:
        if isinstance(op, _cs_ast.Eq): return a == b
        if isinstance(op, _cs_ast.NotEq): return a != b
        if isinstance(op, _cs_ast.Lt): return a < b
        if isinstance(op, _cs_ast.LtE): return a <= b
        if isinstance(op, _cs_ast.Gt): return a > b
        if isinstance(op, _cs_ast.GtE): return a >= b
        if isinstance(op, _cs_ast.Is): return a is b
        if isinstance(op, _cs_ast.IsNot): return a is not b
        if isinstance(op, _cs_ast.In): return a in b
        if isinstance(op, _cs_ast.NotIn): return a not in b
    except Exception:
        return CS_UNK
    return CS_UNK


def cs_ev(node, st):
    if node is None:
        return CS_UNK
    t = type(node)
    if t is _cs_ast.Constant:
        return node.value
    if t is _cs_ast.Name or t is _cs_ast.Attribute:
        if st.get(_CS_TAINT):
            return CS_UNK
        name = node.id if t is _cs_ast.Name else _cs_dotted(node)
        if name is not None:
            name = _cs_state_name(name)
        if name is None:
            return CS_UNK
        return st.get(name, CS_UNK)
    if t is _cs_ast.UnaryOp:
        v = cs_ev(node.operand, st)
        if v is CS_UNK:
            return CS_UNK
        try:
            if isinstance(node.op, _cs_ast.Not): return not v
            if isinstance(node.op, _cs_ast.USub): return -v
            if isinstance(node.op, _cs_ast.UAdd): return +v
        except Exception:
            return CS_UNK
        return CS_UNK
    if t is _cs_ast.BoolOp:
        if not node.values or not isinstance(node.op, (_cs_ast.And, _cs_ast.Or)):
            return CS_UNK
        for operand in node.values[:-1]:
            value = cs_ev(operand, st)
            truth = _cs_truth(value)
            if truth is CS_UNK:
                # The unknown operand might itself be returned. A later known
                # value cannot prove the exact Python result or its safety.
                return CS_UNK
            if isinstance(node.op, _cs_ast.And) and not truth:
                return value
            if isinstance(node.op, _cs_ast.Or) and truth:
                return value
        return cs_ev(node.values[-1], st)
    if t is _cs_ast.Compare:
        cur = cs_ev(node.left, st)
        unk = False
        for op, comp in zip(node.ops, node.comparators):
            if isinstance(comp, (_cs_ast.List, _cs_ast.Tuple, _cs_ast.Set)):
                elts = [cs_ev(e, st) for e in comp.elts]
                r = CS_UNK if any(e is CS_UNK for e in elts) else tuple(elts)
            else:
                r = cs_ev(comp, st)
            if cur is CS_UNK or r is CS_UNK:
                unk = True
            else:
                res = _cs_cmp(op, cur, r)
                if res is CS_UNK:
                    unk = True
                elif not res:
                    return False
            cur = r
        return CS_UNK if unk else True
    if t is _cs_ast.BinOp:
        a, b = cs_ev(node.left, st), cs_ev(node.right, st)
        if a is CS_UNK or b is CS_UNK:
            return CS_UNK
        try:
            if isinstance(node.op, _cs_ast.Add): return a + b
            if isinstance(node.op, _cs_ast.Sub): return a - b
            if isinstance(node.op, _cs_ast.Mult): return a * b
            if isinstance(node.op, _cs_ast.FloorDiv): return a // b
            if isinstance(node.op, _cs_ast.Mod): return a % b
        except Exception:
            return CS_UNK
        return CS_UNK
    if t is _cs_ast.IfExp:
        c = cs_ev(node.test, st)
        if c is CS_UNK:
            return CS_UNK
        return cs_ev(node.body if c else node.orelse, st)
    return CS_UNK


def _cs_truth(v):
    if v is CS_UNK:
        return CS_UNK
    try:
        return bool(v)
    except Exception:
        return CS_UNK


# ---------------------------------------------------------------- çözücü
CS_DEAD = (False, False, 0.0, 0.0, False)


def _cs_scalar_key(value):
    if value is CS_UNK:
        return ('unknown',)
    if type(value) is float:
        return ('float', value.hex())
    return (type(value).__name__, value)


class CSSolver(object):
    def __init__(self, prog, mode="global", max_steps=300000, max_depth=2500, project_state=True):
        self.prog = prog
        self.analysis = prog.prepare_analysis()
        self.project_state = project_state
        self._needed_cache = {}
        self.mode = mode
        self.max_steps = max_steps
        self.max_depth = max_depth
        self.steps = 0
        self.memo = {}
        self.inprog = set()
        self.obs = {}
        self.aborted = False
        self.obs_cap = 400
        self.memo_hits = 0

    # tail: betik / çağıran bilinmeyen sonu
    def _tail(self):
        if self.mode == "global":
            return (True, True, 0.0, 0.0, False)
        # Local analysis has not seen the caller: return is not proof that the
        # complete continuation is safe.
        return (False, True, 0.0, CS_INF, True)

    @staticmethod
    def _skey(st):
        return tuple(sorted((k, _cs_scalar_key(v)) for k, v in st.items()))

    def relevant_state(self, bid, idx, state, cont):
        if not self.project_state:
            return dict(state)
        if state.get(_CS_TAINT):
            return {_CS_TAINT: True}
        key = (bid, idx, cont)
        needed = self._needed_cache.get(key)
        if needed is None:
            names = set(self.analysis['live'].get((bid, idx), ()))
            # The callee may assign an RHS dependency to a value read by its
            # caller. Preserve that dependency even before the return executes.
            for cb, ci, _ in cont:
                names.update(self.analysis['live'].get((cb, ci), ()))
            needed = self.prog.dependency_closure(names) | {_CS_TAINT}
            self._needed_cache[key] = needed
        return {name: value for name, value in state.items() if name in needed}

    @staticmethod
    def _fin(v, glo, ghi, unres=False):
        return (v[0], v[1], v[2] + glo, v[3] + ghi, v[4] or unres)

    @staticmethod
    def _strip(cont):
        while cont and cont[0][2] == 0:
            cont = cont[1:]
        return cont

    def _ret(self, cont):
        cont = self._strip(cont)
        if cont and cont[0][2] == 1:
            b, i, _ = cont[0]
            return b, i, cont[1:]
        return None

    def solve(self, bid, idx, state, cont, depth):
        state = self.relevant_state(bid, idx, state, cont)
        key = (bid, idx, self._skey(state), cont)
        v = self.memo.get(key)
        if v is not None:
            self.memo_hits += 1
            return v
        if key in self.inprog:
            # A cycle has not proved a terminating safe continuation.
            return (False, True, 0.0, CS_INF, True)
        if depth > self.max_depth:
            raise CSSimAbort("depth")
        self.inprog.add(key)
        try:
            v = self._run(bid, idx, state, cont, depth)
        finally:
            self.inprog.discard(key)
        self.memo[key] = v
        return v

    def _assign(self, st, s):
        var, op, node = s[1], s[2], s[3]
        prog = self.prog
        ext = var in prog.ext_tokens
        if _cs_api_write(var):
            st[_CS_TAINT] = True
            prog.context_unsupported = True
            prog.context_reasons.add('api_rebinding')
        if _cs_expr_effect(node, st):
            st[_CS_TAINT] = True
        if var not in prog.consumed:
            return ext
        val = cs_ev(node, st)
        if op != "=":
            cur = st.get(var, CS_UNK)
            if st.get(_CS_TAINT) or cur is CS_UNK or val is CS_UNK:
                val = CS_UNK
            else:
                try:
                    if op == "+": val = cur + val
                    elif op == "-": val = cur - val
                    elif op == "*": val = cur * val
                    elif op == "//": val = cur // val
                    elif op == "%": val = cur % val
                except Exception:
                    val = CS_UNK
        if val is CS_UNK:
            st[var] = CS_UNK
        elif isinstance(val, (int, float, bool, str)) or val is None:
            st[var] = val
        else:
            st[var] = CS_UNK
        return ext

    def _run(self, bid, idx, state, cont, depth):
        prog = self.prog
        st = dict(state)
        glo = ghi = 0.0
        unres = bool(st.get(_CS_TAINT))

        def finish(v, lo, hi, unresolved=False):
            if st.get(_CS_TAINT):
                return (False, True, 0.0, CS_INF, True)
            return self._fin(v, lo, hi, unresolved)

        while True:
            self.steps += 1
            if self.steps > self.max_steps:
                raise CSSimAbort("steps")
            block = prog.blocks[bid]
            if idx >= len(block):
                if cont and cont[0][2] == 0:
                    bid, idx, _ = cont[0]
                    cont = cont[1:]
                    continue
                nxt = prog.next_label.get(prog.block_label[bid])
                if nxt is not None:
                    bid, idx = prog.labels[nxt], 0
                    continue
                r = self._ret(cont)
                if r is None:
                    return finish(self._tail(), glo, ghi, unres)
                bid, idx, cont = r
                continue
            s = block[idx]
            k = s[0]
            if k == "say":
                # Narrative wording is not an executable death event.
                idx += 1
            elif k == "assign":
                if self._assign(st, s):
                    ghi += CS_INF
                    unres = True
                idx += 1
            elif k == "noop":
                idx += 1
            elif k == "call_args":
                call = s[1]
                if any(_cs_expr_effect(arg, st) for arg in call.args) or any(
                        _cs_expr_effect(kw.value, st) for kw in call.keywords):
                    st[_CS_TAINT] = True
                    unres = True
                idx += 1
            elif k == "unknown":
                st[_CS_TAINT] = True
                unres = True
                idx += 1
            elif k == "ctrl_unknown":
                return finish((False, True, 0.0, CS_INF, True), glo, ghi, True)
            elif k == "quit":
                return finish(CS_DEAD, glo, ghi, unres)
            elif k == "return":
                r = self._ret(cont)
                if r is None:
                    return finish(self._tail(), glo, ghi, unres)
                bid, idx, cont = r
            elif k == "jump" or k == "call":
                name = s[1]
                if name not in prog.labels:
                    return finish((False, True, 0.0, CS_INF, True), glo, ghi, True)
                if k == "call":
                    cont = ((bid, idx + 1, 1),) + cont
                else:
                    cont = self._strip(cont)
                bid, idx = prog.labels[name], 0
            elif k == "if":
                branches, else_bid = s[1], s[2]
                alts = []          # (next_bid, add_lo, add_hi)
                taken = False
                for (cnode, bb, _ln) in branches:
                    if _cs_expr_effect(cnode, st):
                        st[_CS_TAINT] = True
                        unres = True
                    v = _cs_truth(cs_ev(cnode, st))
                    if v is False:
                        continue
                    if v is True:
                        alts.append((bb, 0.0, 0.0))
                        taken = True
                        break
                    alts.append((bb, 0.0, 0.0))
                if not taken:
                    alts.append((else_bid, 0.0, 0.0))
                after = (bid, idx + 1, 0)
                if len(alts) == 1:
                    nb, alo, ahi = alts[0]
                    glo += alo
                    ghi += ahi
                    if nb is None:
                        idx += 1
                    else:
                        cont = (after,) + cont
                        bid, idx = nb, 0
                else:
                    vals = []
                    for (nb, alo, ahi) in alts:
                        if nb is None:
                            v2 = self.solve(bid, idx + 1, dict(st), cont, depth + 1)
                        else:
                            v2 = self.solve(nb, 0, dict(st), (after,) + cont, depth + 1)
                        vals.append((v2[0], v2[1], v2[2] + alo, v2[3] + ahi, True))
                    j = (all(v[0] for v in vals), any(v[1] for v in vals),
                         min(v[2] for v in vals), max(v[3] for v in vals), True)
                    return finish(j, glo, ghi, True)
            elif k == "menu":
                return finish(self._menu(s, bid, idx, st, cont, depth, glo, ghi, unres), 0, 0)
            else:
                st[_CS_TAINT] = True
                unres = True
                idx += 1

    def _menu(self, s, bid, idx, st, cont, depth, glo, ghi, unres):
        mid, choices = s[1], s[2]
        after = ((bid, idx + 1, 0),) + cont
        vals = {}
        sure = {}
        # Visibility expressions run before selection, not inside their option.
        if any(not ok or node is not None and _cs_expr_effect(node, st)
               for _, node, _, _, ok in choices):
            st[_CS_TAINT] = True
            unres = True
        for ci, (cln, cnode, cbid, ctext, cond_ok) in enumerate(choices):
            if cnode is not None or not cond_ok:
                cv = _cs_truth(cs_ev(cnode, st)) if cond_ok else CS_UNK
                if cv is False:
                    continue
                sure[ci] = (cv is True)
            else:
                sure[ci] = True
            vals[ci] = self.solve(cbid, 0, dict(st), after, depth + 1)
        if not vals:
            # Native Ren'Py falls through when no menu item is available.
            return self._fin(self.solve(bid, idx + 1, dict(st), cont, depth + 1),
                             glo, ghi, unres)
        visits = self.obs.setdefault(mid, [])
        if len(visits) < self.obs_cap:
            visits.append({"vals": dict(vals), "sure": dict(sure), "state": dict(st), "cont": after})
        sure_safe = [v for c, v in vals.items() if sure[c] and v[0]]
        safe_lo = bool(sure_safe)
        safe_hi = any(v[1] for v in vals.values())
        if safe_lo:
            g_lo = max(v[2] for v in sure_safe)
        else:
            sv = [v[2] for c, v in vals.items() if sure[c]]
            g_lo = max(sv) if sv else 0.0
        hi_pool = [v[3] for v in vals.values() if v[1]] or [v[3] for v in vals.values()]
        g_hi = max(hi_pool)
        un = any(v[4] for v in vals.values()) or any(not x for x in sure.values())
        if not any(sure.values()):
            # UNKNOWN guards also permit the all-hidden case. Ignoring it could
            # turn a possibly safe fall-through into an inevitable-death claim.
            empty = self.solve(bid, idx + 1, dict(st), cont, depth + 1)
            safe_lo = safe_lo and empty[0]
            safe_hi = safe_hi or empty[1]
            g_lo, g_hi = min(g_lo, empty[2]), max(g_hi, empty[3])
            un = True
        return self._fin((safe_lo, safe_hi, g_lo, g_hi, un), glo, ghi, unres or un)

    # ---- giriş noktaları
    def run_global(self, entry="start"):
        prog = self.prog
        if entry not in prog.labels:
            self.aborted = True
            return False
        st0 = prog.initial_state()
        old = _cs_sys.getrecursionlimit()
        _cs_sys.setrecursionlimit(max(old, 20000))
        try:
            self.solve(prog.labels[entry], 0, st0, (), 0)
        except (CSSimAbort, RecursionError):
            self.aborted = True
            self.obs = {}
        finally:
            _cs_sys.setrecursionlimit(old)
        return not self.aborted

    def local_cont(self, bid, idx):
        frames = []
        b = bid
        i = idx
        while self.prog.block_parent[b] is not None:
            pb, pi = self.prog.block_parent[b]
            frames.append((pb, pi, 0))
            b = pb
        return tuple(frames)


class CSIncoming(object):
    """Forward, call-stack-aware fixed point of possible menu-entry states.

    At each program point/context, differing scalar values join to UNKNOWN.
    This overapproximates *all* earlier player choices, never samples a path.
    Opaque Python/control flow prevents certification of entry coverage.
    """
    def __init__(self, prog, max_steps=300000, max_depth=2500, entry='start'):
        self.prog = prog
        self.max_steps, self.max_depth, self.entry = max_steps, max_depth, entry
        self.transfer = CSSolver(prog)
        self.states = {}
        self.steps = 0
        self.complete = False
        self.aborted = False
        self.opaque = False
        self.reason = 'not_started'
        self._queue = collections.deque()
        self._queued = set()

    def _enqueue(self, bid, idx, state, cont):
        if len(cont) > self.max_depth:
            self.aborted = True
            self.reason = 'context_depth'
            return
        key = (bid, idx, cont)
        projected = self.transfer.relevant_state(bid, idx, state, cont)
        projected = {k: v for k, v in projected.items() if v is not CS_UNK}
        previous = self.states.get(key)
        if previous is not None:
            # Absence denotes UNKNOWN, not zero/False or an unreachable point.
            joined = {k: v for k, v in previous.items()
                      if k in projected and _cs_scalar_key(v) == _cs_scalar_key(projected[k])}
            if previous.get(_CS_TAINT) or projected.get(_CS_TAINT):
                joined[_CS_TAINT] = True
            if CSSolver._skey(joined) == CSSolver._skey(previous):
                return
            projected = joined
        self.states[key] = projected
        if key not in self._queued:
            self._queue.append(key)
            self._queued.add(key)

    def _opaque(self):
        # An arbitrary call may jump/re-enter any menu with another state. A
        # completed static prefix is therefore not universal entry coverage.
        self.opaque = True

    def _step(self, bid, idx, state, cont):
        block = self.prog.blocks[bid]
        st = dict(state)
        if idx >= len(block):
            if cont and cont[0][2] == 0:
                b, i, _ = cont[0]
                self._enqueue(b, i, st, cont[1:])
                return
            nxt = self.prog.next_label.get(self.prog.block_label[bid])
            if nxt is not None:
                self._enqueue(self.prog.labels[nxt], 0, st, cont)
                return
            returned = self.transfer._ret(cont)
            if returned is not None:
                b, i, rest = returned
                self._enqueue(b, i, st, rest)
            return
        stmt = block[idx]
        kind = stmt[0]
        if kind == 'assign':
            self.transfer._assign(st, stmt)
            if st.get(_CS_TAINT):
                self._opaque()
                return
        elif kind == 'call_args':
            call = stmt[1]
            if any(_cs_expr_effect(n, st) for n in call.args) or any(
                    _cs_expr_effect(kw.value, st) for kw in call.keywords):
                self._opaque()
                return
        elif kind in ('say', 'noop'):
            pass
        elif kind in ('unknown', 'ctrl_unknown'):
            self._opaque()
            return
        elif kind == 'quit':
            return
        elif kind == 'return':
            returned = self.transfer._ret(cont)
            if returned is not None:
                b, i, rest = returned
                self._enqueue(b, i, st, rest)
            return
        elif kind in ('jump', 'call'):
            target = self.prog.labels.get(stmt[1])
            if target is None:
                self._opaque()
                return
            frames = (((bid, idx + 1, 1),) + cont if kind == 'call'
                      else self.transfer._strip(cont))
            self._enqueue(target, 0, st, frames)
            return
        elif kind == 'if':
            after = ((bid, idx + 1, 0),) + cont
            for node, child, _ in stmt[1]:
                if _cs_expr_effect(node, st):
                    self._opaque()
                    return
                truth = _cs_truth(cs_ev(node, st))
                if truth is not False:
                    self._enqueue(child, 0, st, after)
                if truth is True:
                    return
            if stmt[2] is not None:
                self._enqueue(stmt[2], 0, st, after)
            else:
                self._enqueue(bid, idx + 1, st, cont)
            return
        elif kind == 'menu':
            choices = stmt[2]
            if any(not ok or node is not None and _cs_expr_effect(node, st)
                   for _, node, _, _, ok in choices):
                self._opaque()
                return
            after = ((bid, idx + 1, 0),) + cont
            sure_available = False
            for _, node, child, _, _ in choices:
                truth = _cs_truth(cs_ev(node, st)) if node is not None else True
                if truth is not False:
                    self._enqueue(child, 0, st, after)
                if truth is True:
                    sure_available = True
            if not sure_available:
                self._enqueue(bid, idx + 1, st, cont)
            return
        else:
            self._opaque()
            return
        self._enqueue(bid, idx + 1, st, cont)

    def run(self):
        if self.entry not in self.prog.labels:
            self.reason = 'missing_entry'
            self.aborted = True
            return False
        initial = self.prog.initial_state()
        self._enqueue(self.prog.labels[self.entry], 0, initial, ())
        while self._queue and not self.aborted:
            if self.steps >= self.max_steps:
                self.aborted = True
                self.reason = 'context_steps'
                break
            key = self._queue.popleft()
            self._queued.discard(key)
            self.steps += 1
            bid, idx, cont = key
            self._step(bid, idx, self.states[key], cont)
        if not self.aborted:
            self.reason = ('unmodelled_effect' if self.opaque else
                           'unsupported_context:' + ','.join(sorted(self.prog.context_reasons)) if self.prog.context_unsupported else
                           'parse_errors' if self.prog.parse_errors else 'complete')
        self.complete = self.reason == 'complete'
        return self.complete

    def contexts(self, mid):
        point = self.prog.menu_loc.get(mid)
        if point is None:
            return []
        return [{'state': dict(st), 'cont': cont} for (bid, idx, cont), st in self.states.items()
                if (bid, idx) == point]

    def coverage(self):
        return {'complete': self.complete, 'reason': self.reason, 'steps': self.steps,
                'state_points': len(self.states), 'opaque_effect': self.opaque,
                'merge': 'scalar_equality_else_unknown', 'sampled': False}


def _cs_context_session(prog, max_steps=300000, max_depth=2500):
    key = (max_steps, max_depth)
    cached = prog._context_entry
    if cached is None or cached['key'] != key:
        incoming = CSIncoming(prog, max_steps=max_steps, max_depth=max_depth)
        incoming.run()
        cached = {'key': key, 'incoming': incoming, 'solver': CSSolver(
            prog, max_steps=max_steps, max_depth=max_depth), 'menus': {}}
        prog._context_entry = cached
    return cached


def cs_run_contextual(prog, mid, max_steps=300000, max_depth=2500):
    """Evaluate a menu only after complete, overapproximated incoming coverage.

    The continuation solver is shared across menus, with the same total budget.
    Incomplete entry/continuation results never become global proof.
    """
    cached = _cs_context_session(prog, max_steps, max_depth)
    if mid in cached['menus']:
        return cached['menus'][mid]
    incoming, solver = cached['incoming'], cached['solver']
    coverage = incoming.coverage()
    result = {'complete': False, 'visits': [], 'coverage': coverage}
    contexts = incoming.contexts(mid)
    if not incoming.complete or not contexts or len(contexts) >= solver.obs_cap or solver.aborted:
        result['reason'] = (coverage['reason'] if not incoming.complete else
                            'unreachable' if not contexts else 'context_or_continuation_limit')
        cached['menus'][mid] = result
        return result
    bid, idx = prog.menu_loc[mid]
    visits = []
    old_limit = _cs_sys.getrecursionlimit()
    _cs_sys.setrecursionlimit(max(old_limit, 20000))
    previous_obs = solver.obs
    try:
        for context in contexts:
            solver.obs = {}
            st, cont = dict(context['state']), context['cont']
            solver._menu(prog.blocks[bid][idx], bid, idx, st, cont, 0, 0., 0., False)
            observed = solver.obs.get(mid, [])
            expected_cont = ((bid, idx + 1, 0),) + cont
            matches = [v for v in observed if v['cont'] == expected_cont]
            if not matches and not observed and all(node is not None and ok and
                    _cs_truth(cs_ev(node, st)) is False for _, node, _, _, ok in prog.blocks[bid][idx][2]):
                visits.append({'vals': {}, 'sure': {}, 'state': dict(st), 'cont': expected_cont})
                continue
            if not matches or len(observed) >= solver.obs_cap:
                raise CSSimAbort('context_observation_limit')
            visits.append(matches[-1])
    except (CSSimAbort, RecursionError) as error:
        solver.aborted = True
        result['reason'] = 'continuation_incomplete:' + type(error).__name__
    else:
        result.update(complete=True, visits=visits, reason='complete')
    finally:
        solver.obs = previous_obs
        _cs_sys.setrecursionlimit(old_limit)
    result['coverage'] = dict(coverage, complete=result['complete'], contexts=len(contexts),
                              continuation_steps=solver.steps)
    cached['menus'][mid] = result
    return result


def cs_run_local(prog, mid, max_steps=3000):
    loc = prog.menu_loc.get(mid)
    if loc is None:
        return None
    sv = CSSolver(prog, mode="local", max_steps=max_steps, max_depth=200)
    bid, idx = loc
    st0 = dict(prog.consts)
    old = _cs_sys.getrecursionlimit()
    _cs_sys.setrecursionlimit(max(old, 5000))
    try:
        sv.solve(bid, idx, st0, sv.local_cont(bid, idx), 0)
    except (CSSimAbort, RecursionError):
        return None
    finally:
        _cs_sys.setrecursionlimit(old)
    return sv.obs.get(mid)


# ---------------------------------------------------------------- sınıflandırma
def cs_classify_visit(visit):
    """Bir menü ziyareti için {ci: 'GREEN'|'RED'|'NONE'} ve veto kümesi."""
    vals, sure = visit["vals"], visit["sure"]
    cis = list(vals)
    if len(cis) < 2:
        return dict((c, "NONE") for c in cis), set(cis)     # tek erişilebilir seçenek: karar yok
    dead = set(c for c in cis if not vals[c][1])
    out = dict((c, "NONE") for c in cis)
    veto = set()
    safe_certain = [c for c in cis if sure[c] and vals[c][0]]
    for c in dead:
        if any(o != c for o in safe_certain):
            out[c] = "RED"
    for b in cis:
        if not vals[b][0] or not sure[b]:
            veto.add(b)
            continue
        rivals = [o for o in cis if o != b and o not in dead]
        if any(vals[b][3] <= vals[o][2] for o in rivals):
            veto.add(b)
    for b in safe_certain:
        if b in veto:
            continue
        rivals = [o for o in cis if o != b and o not in dead]
        if not rivals and not (dead - {b}):
            continue
        if all(vals[b][2] > vals[o][3] for o in rivals):
            out[b] = "GREEN"
    greens = [c for c in cis if out[c] == "GREEN"]
    if len(greens) > 1:
        for c in greens:
            out[c] = "NONE"
    return out, veto


def cs_aggregate(visits, n_choices):
    """Tüm ziyaretlerde ortak (evrensel) kararlar."""
    info = {}
    if not visits:
        return info
    classes = [cs_classify_visit(v) for v in visits]
    for ci in range(n_choices):
        present = [(c, v) for (c, vz), v in zip(classes, visits) if ci in v["vals"]]
        # present: (classification-pair, visit) değil; basitleştir
        outs = []
        vetos = []
        safes = []
        unresolved = []
        for (out, veto), v in zip(classes, visits):
            if ci in out:
                outs.append(out[ci])
                vetos.append(ci in veto)
                safes.append(bool(v["sure"][ci] and v["vals"][ci][0]))
                unresolved.append(bool(v["vals"][ci][4] or not v["sure"][ci]))
        full = len(outs) == len(visits)
        info[ci] = {
            "green": bool(outs) and full and all(o == "GREEN" for o in outs),
            "red": bool(outs) and full and all(o == "RED" for o in outs),
            "veto_green": any(vetos),
            "safe_certain": bool(outs) and full and all(safes),
            "unresolved": not full or any(unresolved),
            "visits": len(outs),
        }
    return info


# ==========================================================================
# SÖZLEŞME ENTEGRASYONU: evaluate_choices sonucunu ContractSim ile denetler.
#  - Simülasyon bilgisi varsa: kanıtlı yeşil/kırmızı verir, kanıtlanamayanı iptal eder.
#  - Simülasyon bilgisi yoksa: kesin renk verilmez; sezgisel kanıt raporda kalır.
# ==========================================================================
_CS_FATAL_TOKENS = ("OLUM", "ÖLÜM", "KOTU SON", "KÖTÜ SON", "ROTA", "HAYAT", "DEATH", "BAD END")


def _cs_norm(p):
    try:
        return os.path.normpath(os.path.abspath(str(p)))
    except Exception:
        return str(p)


def _cs_get(analyzer):
    files = [_cs_norm(p) for p in (getattr(analyzer, "rpy_files", None) or [])]
    sig = []
    for p in files:
        try:
            stt = os.stat(p)
            sig.append((p, stt.st_mtime_ns, stt.st_size))
        except OSError:
            sig.append((p, 0, 0))
    key = tuple(sig)
    ent = getattr(analyzer, "_cs_entry", None)
    if ent is not None and ent[0] == key:
        return ent[1], ent[2]
    prog = CSProgram()
    for p in files:
        try:
            with open(p, "r", encoding="utf-8", errors="replace") as fh:
                raw = fh.read().splitlines(True)
        except OSError:
            continue
        try:
            prog.add_file(p, raw)
        except Exception:
            prog.parse_errors += 1
    solver = CSSolver(prog)
    try:
        solver.run_global()
    except Exception:
        solver.aborted = True
        solver.obs = {}
    try:
        analyzer._cs_entry = (key, prog, solver)
    except Exception:
        pass
    return prog, solver


def _cs_menu_info(menu):
    analyzer = getattr(menu, "analyzer", None)
    if analyzer is None or getattr(menu, "is_screen", False):
        return None
    prog, solver = _cs_get(analyzer)
    mid = (_cs_norm(getattr(menu, "file_path", "")), getattr(menu, "line_num", -1))
    entry = prog.menus.get(mid)
    if entry is None:
        return None
    ch_lines = [c[0] for c in entry["choices"]]
    idx_map = {}
    for ch in menu.choices:
        ln = getattr(ch, "line_num", None)
        if ln in ch_lines:
            idx_map[ch] = ch_lines.index(ln)
    if len(idx_map) != len(menu.choices) or len(set(idx_map.values())) != len(idx_map):
        return None
    mode = "global"
    origin = 'global_solver'
    coverage = {'complete': not solver.aborted, 'reason': 'global_solver', 'sampled': False}
    visits = None if solver.aborted else solver.obs.get(mid)
    if visits and len(visits) >= solver.obs_cap:
        mode = "local"
        visits = None
    if visits:
        coverage = _cs_context_session(prog)['incoming'].coverage()
        if not coverage['complete']:
            mode, origin = 'partial', 'partial_global_solver'
    if not visits:
        contextual = cs_run_contextual(prog, mid)
        coverage = contextual['coverage']
        if contextual['complete']:
            visits = contextual['visits']
            mode, origin = 'global', 'incoming_contexts'
    if not visits:
        mode = "local"
        origin = 'local_fallback'
        try:
            visits = cs_run_local(prog, mid)
        except Exception:
            visits = None
    menu.context_coverage = dict(coverage, origin=origin)
    if not visits:
        return None
    info = cs_aggregate(visits, len(entry["choices"]))
    return {"idx": idx_map, "info": info, "mode": mode, "visits": visits,
            "prog": prog, "mid": mid, "entry": entry, 'origin': origin,
            'coverage': coverage}


def _cs_diagnostics(analyzer):
    entry = getattr(analyzer, '_cs_entry', None)
    if entry is None:
        return {'available': False}
    _, prog, solver = entry
    session = prog._context_entry
    return {'available': True, 'global_completed': not solver.aborted,
            'global_steps': solver.steps, 'global_step_limit': solver.max_steps,
            'depth_limit': solver.max_depth, 'observed_menus': len(solver.obs),
            'parsed_menus': len(prog.menus), 'memo_entries': len(solver.memo),
            'memo_hits': solver.memo_hits, 'relevant_state_projection': solver.project_state,
            'incoming_coverage': session['incoming'].coverage() if session else {'complete': False, 'reason': 'not_requested'},
            'contextual_continuation_steps': session['solver'].steps if session else 0}


def _cs_has_fatal_evidence(ch):
    if (getattr(ch, "is_death", False) or getattr(ch, "is_downstream_death", False)
            or getattr(ch, "future_death_risk", False) or getattr(ch, "is_route_lock", False)):
        return True
    try:
        for d in list(getattr(ch, "deltas_negative", []) or []) + list(getattr(ch, "downstream_neg", []) or []):
            name = str(d[0]).upper() if isinstance(d, (tuple, list)) and d else str(d).upper()
            if any(tok in name for tok in _CS_FATAL_TOKENS):
                return True
    except Exception:
        pass
    return False


def _cs_enabled(menu):
    an = getattr(menu, "analyzer", None)
    opts = getattr(an, "options", None) or {}
    try:
        return bool(opts.get("contract_enforcement", True))
    except Exception:
        return True


def _cs_bridge_ok(menu, bridge):
    """Fail closed; detection and writing must use the same source scene plan."""
    try:
        bridge['scene_plan'] = build_both_scene_plan(
            getattr(menu, 'analyzer', None), menu, list(bridge.get('subset') or []))
        return True
    except (BothPlanError, OSError, ValueError, RecursionError):
        return False


def _cs_set(ch, new, rule, reason):
    d = Decision(new)
    try:
        ch.verdict = d
        ch.decision_rule = rule
        ch.decision_reason = reason
        ch.decision_verified = new in ('GREEN', 'RED') and rule in (
            'CS_SIM_UNIQUE_BEST', 'CS_SIM_INEVITABLE_DEATH')
        if new == 'NONE' and rule in ('CS_SIM_UNRESOLVED', 'CS_SIM_UNAVAILABLE'):
            reasons = getattr(ch, 'uncertainty_reasons', None)
            if isinstance(reasons, list) and reason not in reasons:
                reasons.append(reason)
        chain = getattr(ch, "evidence_chain", None)
        if isinstance(chain, list):
            chain.append("ContractSim: " + reason)
    except Exception:
        pass
    return d


def _cs_enforce(menu, result, bridge):
    """Karar sözleşmesi (S1-S4): sonuçları yürütmeyle doğrula; ihlalleri düşür."""
    if bridge or not _cs_enabled(menu):
        return result
    final = dict(result)
    info = None
    try:
        info = _cs_menu_info(menu)
    except Exception:
        info = None
    certain = info is not None and info["mode"] == "global"
    for ch in menu.choices:
        old = str(final.get(ch, "NONE"))
        new = old
        rule = None
        reason = None
        fatal = _cs_has_fatal_evidence(ch)
        if info is None and new != "NONE":
            new, rule, reason = "NONE", "CS_SIM_UNAVAILABLE", "Yürütme doğrulanamadı; sezgisel öneri kesin renk olarak gösterilmedi."
        if old == "RED" and not fatal:
            new, rule, reason = "NONE", "CS_RED_NEEDS_FATAL", "Salt puan kaybı kırmızı değildir (kaçınılmaz zarar kanıtı yok)."
        if old == "GREEN" and fatal:
            new, rule, reason = "NONE", "CS_GREEN_FATAL", "Ölüm/rota kapanışı kanıtı olan seçenek yeşil olamaz."
        if info is not None:
            ci = info["idx"].get(ch)
            inf = info["info"].get(ci) if ci is not None else None
            if inf is None and new != "NONE":
                new, rule, reason = "NONE", "CS_SIM_UNAVAILABLE", "Seçenek için yürütme sonucu bulunamadı; kesin renk verilmedi."
            if inf:
                if inf["red"] and certain:
                    new, rule, reason = "RED", "CS_SIM_INEVITABLE_DEATH", "Yürütme: tüm devamlarda ölüm, güvenli alternatif var."
                elif inf["green"] and certain:
                    new, rule, reason = "GREEN", "CS_SIM_UNIQUE_BEST", "Yürütme: güvenli alternatif; rakip devamların ölüm/sonlanma riski doğrulandı."
                else:
                    if new != "NONE":
                        unresolved = inf.get('unresolved', False) or not certain
                        new, rule, reason = "NONE", ('CS_SIM_UNRESOLVED' if unresolved else 'CS_SIM_NOT_PROVEN'), "Giriş kapsamı, güvenli alternatif veya kesin üstünlük doğrulanamadı; sezgisel renk korunmadı."
        if info is not None and certain:
            _ci = info["idx"].get(ch)
            _inf = info["info"].get(_ci) if _ci is not None else None
            if _inf is not None and _inf.get("visits", 1) == 0 and new != "NONE":
                new, rule, reason = "NONE", "CS_SIM_UNAVAILABLE", "Yürütme: seçenek koşulu hiçbir durumda sağlanmıyor (erişilemez)."
        if new != old or (rule is not None and new != "NONE"):
            final[ch] = _cs_set(ch, new, rule, reason)    # karar aynı kalsa bile gerekçe yürütmeden gelir
    greens = [c for c in menu.choices if str(final.get(c, "NONE")) == "GREEN"]
    if len(greens) > 1:
        sure = []
        if info is not None and certain:
            sure = [c for c in greens if info["info"].get(info["idx"].get(c), {}).get("green")]
        keep = sure[0] if len(sure) == 1 else None
        for c in greens:
            if c is not keep:
                final[c] = _cs_set(c, "NONE", "CS_SINGLE_GREEN", "Bir menüde en fazla bir yeşil: kesin tek üstün kanıtlanamadı.")
    return final


class RenpyChoice:
    def __init__(self, file_path, line_num, indent, quote, text, condition, raw_line):
        self.file_path = file_path
        self.line_num = line_num
        self.indent = indent
        self.quote = quote
        self.text = text
        self.clean_text = text
        self.raw_line = raw_line
        self.block_lines = []
        self.menu = None

        self.is_inquiry = False
        self.is_inquiry_exit = False
        self.dialogue_line_count = 0

        # H6c: Secenek kosulunun ayristirilmasi ("Flirt" if charm > 5:)
        self.condition_raw = condition or ""
        cond_clean = condition.strip() if condition else ""
        if cond_clean.startswith("if "):
            cond_clean = cond_clean[3:].strip()
        elif " if " in cond_clean:
            cond_clean = cond_clean.split(" if ", 1)[1].strip()
        self.condition = cond_clean
        self.condition_parsed = RenpyASTAnalyzer.parse_expr(cond_clean) if cond_clean else None

        # Hedefler (H1, H2)
        self.jump_target = None
        self.call_target = None
        self.dynamic_jump_unresolved = None
        self.assigned_flags = {}

        # Skorlar ve sonuclar
        self.score = 0.0
        self.deltas_positive = []
        self.deltas_negative = []
        self.is_death = False
        self.is_survival = False
        self.is_enemy_defeat = False
        self.is_route_lock = False
        self.route_locked_name = ""
        self.death_reason = "OLUM"

        # Downstream lookahead (H4)
        self.downstream_score = 0.0
        self.downstream_pos = []
        self.downstream_neg = []
        self.is_downstream_death = False
        self.is_downstream_survival = False
        self.is_gateway = False
        self.is_conflicting_branches = False
        self.effective_score = 0.0
        self.is_truncated = False

        # Ozel nitelikler
        self.is_active_exploration = False
        self.is_passive_skip = False
        self.is_purchase_or_item = False
        self.is_harem_or_romance = False
        self.is_monogamy_lock = False
        self.currency_score_gain = 0.0
        self.is_bribe_trap = False
        self.is_multi_route_breaker = False
        self.broken_routes = []
        self.is_combat_action = False
        self.is_combat_success = False
        self.is_combat_failure = False
        self.is_creampie = False

        # Gelecek etkiler ve esikler (H6a)
        self.future_consequence_score = 0.0
        self.future_life_saver = False
        self.future_route_unlocker = False
        self.future_scene_unlocker = False
        self.future_death_risk = False
        self.unlocked_thresholds = []

        # R8: Coklu Kategori Skorlari (Multi-category scoring)
        self.category_scores = {
            "romance": 0.0,
            "combat": 0.0,
            "survival": 0.0,
            "items": 0.0,
            "exploration": 0.0,
            "gallery": 0.0
        }
        # R5 Fix: dynamic_jump_unresolved yukarida (satir ~8792) zaten None olarak atandi;
        # buradaki ikinci (kopya) atama kaldirildi.
        self.downstream_truncated = False

        # Karar agaci ve dallar (H6b, H7, R7)
        self.branch_paths = []
        self.conditional_branches = []
        self.nested_menus = []
        self.parent_choice = None
        self.has_contingent_inner = False
        self.contingent_inner_max = 0.0
        self.contingent_inner_choices = []
        self.inner_min_score = 0.0
        self.inner_potential_score = 0.0
        self.is_unreachable_stat_only = False
        self.threshold_uncertain = False
        self.dynamic_func_unresolved = False
        self.dynamic_calls_unresolved = []


        # Kanit duzeyi ve guven skoru (H8, Katman 4)
        self.evidence_level = "AMBIGUOUS" # CODE_VERIFIED, STRONG_HEURISTIC, AMBIGUOUS, CONFLICTING
        self.confidence_score = 0.0 # 0.0 - 1.0
        self.evidence_details = []
        self.evidence_chain = []
        # G3 & G5: Karar kuralı, belirsizlik nedenleri ve AST çözümleme hataları
        self.decision_rule = "RULE_DEFAULT_NEUTRAL"
        self.decision_reason = ""
        self.confidence = 0.0
        self.bridge_info = {}
        self.uncertainty_reasons = []
        self.unresolved_ast_expressions = []


class RenpyMenu:
    def __init__(self, file_path, line_num, indent, is_screen=False, screen_name="", menu_name=None, menu_args=None):
        self.file_path = file_path
        self.line_num = line_num
        self.indent = indent
        self.end_line_num = line_num
        self.parent_choice = None
        self.enclosing_label = None
        self.is_looping_hub = False
        self.is_harem_game = False
        self.is_screen = is_screen
        self.screen_name = screen_name
        self.menu_name = menu_name
        self.menu_args = menu_args
        self.set_statement = None
        self.with_statement = None
        self.caption = None
        self.choices = []

    def _collect_evidence(self, player_profile="ALL_CONTENT", is_harem_game=None, goal=None, highlight_negative=True):
        """
        R8 & G4: COK KATEGORILI VE PROFIL TABANLI KANITA DAYALI KARAR MOTORU:
        - Romantizm (+3) ile Savas (+10) tek eksende birbirini ezmez.
        - ALL_CONTENT profilinde her aktif kategorinin en iyi secenegi BEST olur.
        - ROMANCE_ONLY, SURVIVAL_ONLY, COMPLETIONIST, CRITICAL_CHOICES_ONLY veya CHARACTER:<name>
          profillerinde secilen kategori veya karakter onceliklendirilir.
        - Esit en iyi seceneklerin hepsi BEST (yesil) olarak isaretlenir (H10a).
        - R4: Gelecekte olum riski olan secenekler WORST olarak isaretlenir.
        - G5: Karar kurallari (RULE_*), kanit duzeyleri ve belirsizlik nedenleri kaydedilir.
        """
        if not self.choices:
            return {}

        # Rule 1: Kod bloklarinda degisken ($), puan (+=, -=), envanter, olum veya ozel sahne (scene cg_) farki YOKSA:
        # Menudeki secenekler siradan bir sohbet menusudur; hicbir secenegi Yesil veya Kirmizi BOYAMA (tamami notr/beyaz kalir).
        def _choice_has_concrete_code_impact(c):
            # Her turlu kod degiskeni, puan veya envanter degisimi somut kod etkisidir
            if c.deltas_positive or c.deltas_negative:
                return True
            if any(l.strip().startswith("$") for l in getattr(c, "block_lines", [])):
                return True
            if c.is_death or c.is_downstream_death or getattr(c, "future_death_risk", False):
                return True
            if c.is_route_lock or getattr(c, "route_locked_name", None) or getattr(c, "is_bribe_trap", False) or getattr(c, "is_multi_route_breaker", False) or getattr(c, "is_monogamy_lock", False):
                return True
            if getattr(c, "is_combat_action", False) or getattr(c, "is_combat_failure", False) or getattr(c, "is_combat_success", False) or c.is_enemy_defeat:
                return True
            if c.is_purchase_or_item or c.is_creampie or bool(c.unlocked_thresholds) or c.future_life_saver:
                return True
            if getattr(c, "downstream_pos", []) or getattr(c, "downstream_neg", []):
                return True
            if any(re.search(r'\b(?:scene|show)\s+(?:cg|event|hscene|anim|special|movie|gallery)_', l, re.IGNORECASE) or re.search(r'\bscene\s+cg\b', l, re.IGNORECASE) for l in getattr(c, "block_lines", [])):
                return True
            if c.jump_target:
                if c.jump_target in getattr(self, "free_roam_labels", set()) or RE_ROAM_LABELS.search(c.jump_target.lower()):
                    return True
                if c.jump_target in getattr(self, "day_skip_labels", set()) or RE_DAY_SKIP_LABELS.search(c.jump_target.lower()):
                    return True
            return False

        menu_has_code_impact = any(_choice_has_concrete_code_impact(c) for c in self.choices)
        if not menu_has_code_impact:
            # Yalnizca kod duzeyinde tamamen bos / pass olan secenekler goreli ustunluge girebilir
            has_literal_pass = any(
                len(getattr(c, "block_lines", [])) > 0 and all(l.strip() in ("pass", "") or l.strip().startswith("#") for l in getattr(c, "block_lines", []))
                for c in self.choices
            )
            has_pass_skip = has_literal_pass
            has_content_opener = any(
                any(l.strip() and not l.strip().startswith(("#", "$", "jump", "call", "pass", "return")) for l in getattr(c, "block_lines", [])) or
                bool(c.jump_target) or bool(c.call_target)
                for c in self.choices
            )
            if not (STUDIO_CONFIG.get("enable_relative_dominance", True) and has_pass_skip and has_content_opener):
                pure_dec = {}
                for c in self.choices:
                    pure_dec[c] = 'NEUTRAL'
                    c.decision_rule = "RULE_PURE_DIALOGUE_NEUTRAL"
                return pure_dec

        # 0. Diyalog Menusu (Inquiry Hub) tespiti ve koruma kalkani
        inquiry_choices = [c for c in self.choices if getattr(c, "is_inquiry", False)]
        exit_choices = [c for c in self.choices if getattr(c, "is_inquiry_exit", False)]
        loops_to_self = any(
            c.jump_target and hasattr(self, "enclosing_label") and self.enclosing_label and c.jump_target == self.enclosing_label
            for c in self.choices
        )
        is_inquiry_hub = (
            len(inquiry_choices) >= 2 or
            (len(inquiry_choices) >= 1 and len(exit_choices) >= 1) or
            getattr(self, "is_looping_hub", False) or
            loops_to_self
        )

        if is_inquiry_hub:
            for c in self.choices:
                if getattr(c, "is_inquiry", False) or getattr(c, "is_inquiry_exit", False) or (c.jump_target and hasattr(self, "enclosing_label") and c.jump_target == self.enclosing_label):
                    if getattr(c, "is_passive_skip", False):
                        c.is_passive_skip = False
                        if any(d[0] == "ICERIK ATLAR" for d in c.deltas_negative):
                            c.score += 20.0
                            c.deltas_negative = [d for d in c.deltas_negative if d[0] != "ICERIK ATLAR"]

        w_direct = STUDIO_CONFIG["weight_direct_score"]
        w_down = STUDIO_CONFIG["weight_downstream_score"]
        w_future = STUDIO_CONFIG["weight_future_consequence"]

        for c in self.choices:
            if getattr(c, "downstream_pos", None) and any(str(d[0]).startswith("ROTA:") for d in c.deltas_positive):
                for d in list(c.deltas_positive):
                    if str(d[0]).startswith("ROTA:"):
                        r_char = str(d[0]).replace("ROTA:", "").strip().lower()
                        if any((r_char in str(pos_d[0]).lower() or r_char in clean_var_to_name(str(pos_d[0])).lower()) for pos_d in c.downstream_pos):
                            c.deltas_positive.remove(d)
                            c.score -= d[1]
                            c.category_scores["romance"] = max(0.0, c.category_scores.get("romance", 0.0) - d[1])

        # Kodla dogrulanmis puan onceligi: Eger menude gercek puan veren secenek(ler) varsa,
        # sadece metin tahminine veya genel boolean bayraklarina dayanan secenekler gercek kod puaninin onune gecemez.
        has_code_points_in_menu = any(any(is_real_point_metric(d[0]) and d[1] > 0 for d in (ch.deltas_positive + getattr(ch, "downstream_pos", []))) for ch in self.choices)
        if has_code_points_in_menu:
            for c in self.choices:
                has_own_code_pts = any(is_real_point_metric(d[0]) and d[1] > 0 for d in (c.deltas_positive + getattr(c, "downstream_pos", [])))
                if not has_own_code_pts and not c.is_survival and not c.is_death:
                    for d in list(c.deltas_positive):
                        if str(d[0]).startswith("ROTA:"):
                            c.deltas_positive.remove(d)
                            c.score = max(0.0, c.score - d[1])
                            c.category_scores["romance"] = max(0.0, c.category_scores.get("romance", 0.0) - d[1])
                    # Eger secenek yalnizca jenerik boolean bayragi atiyorsa, gercek karakter puani olan menude sahte galeri ile puan calamaz
                    if not c.is_purchase_or_item and c.category_scores.get("gallery", 0.0) > 0:
                        c.category_scores["gallery"] = 0.0
                        c.score = max(0.0, c.score - 20.0)

        # Profil carpani (G4: Genisletilmis Oyuncu Profilleri & Odak Karakter)
        target_char = None
        if goal:
            target_char = str(goal).strip().lower()
        elif player_profile.startswith(("CHARACTER:", "char:", "CHARACTER_ONLY:")):
            target_char = player_profile.split(":", 1)[1].strip().lower()
        elif getattr(self, "focus_char", None):
            target_char = str(self.focus_char).lower().strip()

        for c in self.choices:
            base_score = c.score
            if target_char:
                char_pts = sum(val for var, val in c.deltas_positive if target_char in var.lower())
                other_rom = sum(val for var, val in c.deltas_positive if is_true_route_variable(var) and target_char not in var.lower())
                base_score += char_pts * 5.0
                if other_rom > 0 and char_pts <= 0 and not c.is_survival and not c.is_death:
                    base_score = 0.0
                if getattr(c, "route_locked_name", "") and target_char in c.route_locked_name.lower():
                    base_score -= 50.0
            elif player_profile == "ROMANCE_ONLY":
                base_score += c.category_scores.get("romance", 0.0) * 2.0
            elif player_profile == "SURVIVAL_ONLY":
                base_score += (c.category_scores.get("survival", 0.0) + c.category_scores.get("combat", 0.0)) * 2.0
                if c.is_death or c.is_downstream_death: base_score -= 100.0
            elif player_profile == "DIK_ONLY":
                dik_pts = sum(val for var, val in c.deltas_positive if var.lower() == "dik" or "dik" in var.lower())
                chick_pts = sum(val for var, val in c.deltas_positive if var.lower() == "chick" or "chick" in var.lower())
                base_score += dik_pts * 10.0
                if chick_pts > 0 and dik_pts <= 0:
                    base_score = 0.0
            elif player_profile == "CHICK_ONLY":
                chick_pts = sum(val for var, val in c.deltas_positive if var.lower() == "chick" or "chick" in var.lower())
                dik_pts = sum(val for var, val in c.deltas_positive if var.lower() == "dik" or "dik" in var.lower())
                base_score += chick_pts * 10.0
                if dik_pts > 0 and chick_pts <= 0:
                    base_score = 0.0
            elif player_profile == "COMPLETIONIST":
                base_score += (c.category_scores.get("gallery", 0.0) + c.category_scores.get("items", 0.0)) * 2.0
            elif player_profile == "CRITICAL_CHOICES_ONLY":
                is_crit = (
                    c.is_death or c.is_downstream_death or getattr(c, "future_death_risk", False) or
                    c.is_survival or c.is_downstream_survival or c.future_life_saver or
                    getattr(c, "is_combat_action", False) or c.is_combat_failure or
                    c.is_route_lock or getattr(c, "is_critical_route", False) or
                    any("persistent" in var.lower() for var, _ in c.deltas_positive)
                )
                if not is_crit:
                    base_score = 0.0

            c.effective_score = (base_score * w_direct) + (c.downstream_score * w_down) + (c.future_consequence_score * w_future)

        # H8: Kanit Duzeyi (evidence_level) ve Guven Skoru (confidence_score)
        for c in self.choices:
            has_real_points = any(d[1] != 0 for d in (c.deltas_positive + c.deltas_negative))
            has_code_downstream = c.downstream_score != 0 or len(c.downstream_pos) > 0 or len(c.downstream_neg) > 0
            has_code_death = c.is_death or c.is_downstream_death or getattr(c, "future_death_risk", False)
            has_code_surv = c.is_survival or c.is_downstream_survival
            has_thresh = bool(c.unlocked_thresholds)
            has_code_action = (
                has_real_points or has_code_downstream or has_code_death or
                has_code_surv or c.is_route_lock or c.is_purchase_or_item or
                c.future_life_saver or has_thresh or c.is_combat_action or c.is_creampie or
                c.is_enemy_defeat or any("Kodla dogrulandi" in str(d) for d in c.evidence_details)
            )

            real_neg_deltas = [d for d in c.deltas_negative if not str(d[0]).startswith("ROTA KAPANIR")]
            is_conflicting = (
                getattr(c, "is_conflicting_branches", False) or
                (len(c.deltas_positive) > 0 and len(real_neg_deltas) > 0 and not c.is_purchase_or_item and not getattr(c, "is_bribe_trap", False) and not getattr(c, "is_multi_route_breaker", False)) or
                (c.score > 0 and getattr(c, "future_death_risk", False)) or
                (c.downstream_score > 0 and c.is_downstream_death)
            )

            has_heuristic = any("Guclu tahmin" in str(d) for d in c.evidence_details) or getattr(c, "is_active_exploration", False)

            if is_conflicting:
                c.evidence_level = "CONFLICTING"
                c.confidence_score = 0.35
                if "Çelişkili etki veya gelecekte ölüm riski" not in c.uncertainty_reasons:
                    c.uncertainty_reasons.append("Çelişkili etki veya gelecekte ölüm riski")
            elif has_code_action:
                c.evidence_level = "CODE_VERIFIED"
                c.confidence_score = 0.95 if has_code_downstream or has_thresh else 0.90
            elif has_heuristic:
                c.evidence_level = "STRONG_HEURISTIC"
                c.confidence_score = 0.65
            else:
                c.evidence_level = "AMBIGUOUS"
                c.confidence_score = 0.20
                if "Yetersiz kod kanıtı veya belirsiz dallanma" not in c.uncertainty_reasons:
                    c.uncertainty_reasons.append("Yetersiz kod kanıtı veya belirsiz dallanma")
            if getattr(c, "downstream_truncated", False):
                c.evidence_level = "AMBIGUOUS"
                c.confidence_score = min(c.confidence_score, 0.20)
                if "Aşağı-akış analizi bütçe sınırında kesildi" not in c.uncertainty_reasons:
                    c.uncertainty_reasons.append("Aşağı-akış analizi bütçe sınırında kesildi")

        eff_scores = [c.effective_score for c in self.choices]
        max_eff = max(eff_scores) if eff_scores else 0.0
        min_eff = min(eff_scores) if eff_scores else 0.0

        decisions = {}
        has_combat = any(getattr(ch, "is_combat_action", False) or ch.is_enemy_defeat for ch in self.choices)

        # R8: Kategori bazli en yuksek skorlar
        category_max = {}
        for cat in ("romance", "combat", "survival", "items", "exploration", "gallery"):
            c_vals = [c.category_scores.get(cat, 0.0) for c in self.choices]
            category_max[cat] = max(c_vals) if c_vals else 0.0

        for c in self.choices:
            c.evidence_chain.clear()
            c.decision_rule = "RULE_DEFAULT_NEUTRAL"

            # 1. Olum / Kotu Son (H5a & R4: Gercek oyuncu olumu veya gelecekte olum riski)
            if c.is_death or c.is_downstream_death or getattr(c, "future_death_risk", False):
                has_char_point = any(d[1] > 0 for d in c.deltas_positive)
                has_hard_kill = c.is_death and any(_is_engine_termination(l) for l in getattr(c, "block_lines", []))
                if (has_char_point or c.score > 0) and not has_hard_kill and not getattr(c, "future_death_risk", False):
                    pass
                else:
                    decisions[c] = 'WORST'
                    c.decision_rule = "RULE_LETHAL_DEATH"
                    c.evidence_chain.append("Kesin oyuncu olumu / motor sonlandirma / gelecek olum riski")
                    continue

            # 2. Gelecekte Hayat Kurtaran Secim
            if c.future_life_saver:
                decisions[c] = 'BEST'
                c.decision_rule = "RULE_LIFE_SAVER"
                c.evidence_chain.append("Gelecekte hayat kurtaran secim")
                continue

            # 2b. Hedef Karakter Rotasi Kilidi (Karakter Profilinde hedef kizin rotasini kapatan secim WORST yapilir)
            if target_char and getattr(c, "route_locked_name", "") and target_char in c.route_locked_name.lower():
                decisions[c] = 'WORST'
                c.decision_rule = "RULE_TARGET_ROUTE_LOCKED"
                c.evidence_chain.append(f"Hedef karakter rotasini kapatir ({c.route_locked_name})")
                continue

            # 3. Rota Kilidi: Yalnizca o secenek hicbir karakter rotasi veya puan kazanmiyorsa kesin WORST yapilir
            if c.is_route_lock and not any(str(d[0]).startswith("ROTA:") for d in c.deltas_positive) and c.score <= 0:
                decisions[c] = 'WORST'
                c.decision_rule = "RULE_ROUTE_LOCK"
                c.evidence_chain.append(f"Karakter rotasini kapatir ({c.route_locked_name})")
                continue

            # 3b. Harem Oyununda Tekli Secenek Kilidi (Haremde tekli secenek kotudur)
            is_harem_mode = is_harem_game if is_harem_game is not None else (getattr(self, "is_harem_game", False) or getattr(c.menu, "is_harem_game", False))
            if is_harem_mode and getattr(c, "is_monogamy_lock", False):
                decisions[c] = 'WORST'
                c.decision_rule = "RULE_HAREM_MONOGAMY_PENALTY"
                c.evidence_chain.append("Harem oyununda tum kizlarla olmayi engelleyen tekli secenek (Cezali)")
                continue

            # 3c. Requirement 3: Rüşvet / İhanet Tuzağı
            if getattr(c, "is_bribe_trap", False):
                decisions[c] = 'WORST'
                c.decision_rule = "RULE_BRIBE_TRAP"
                c.evidence_chain.append("Para karşılığı karakter ilişkisini bozan veya tehlike açan İhanet/Rüşvet Tuzağı")
                continue

            # 3d. Requirement 4: AST Çoklu Rota Kırıcı Koruması
            if getattr(c, "is_multi_route_breaker", False):
                if is_harem_mode:
                    decisions[c] = 'WORST'
                    c.decision_rule = "RULE_MULTI_ROUTE_BREAKER"
                    c.evidence_chain.append(f"Harem oyununda diğer kızların rotalarını kapatan tekli rota kilidi ({', '.join(getattr(c, 'broken_routes', []))})")
                    continue
                elif target_char and any(target_char in br.lower() for br in getattr(c, "broken_routes", [])):
                    decisions[c] = 'WORST'
                    c.decision_rule = "RULE_TARGET_ROUTE_LOCKED"
                    c.evidence_chain.append(f"Hedef karakter rotasını kapatan tekli rota seçimi ({target_char})")
                    continue

            # 4. Creampie
            if c.is_creampie:
                decisions[c] = 'BEST'
                c.decision_rule = "RULE_CREAMPIE"
                c.evidence_chain.append("Iceriye bosalma (Creampie)")
                continue

            # 5. Dovus / QTE mini-oyunu (Profil ROMANCE_ONLY ise otomatik ezmeyi engelle)
            if has_combat and (c.is_combat_action or c.is_enemy_defeat) and player_profile != "ROMANCE_ONLY":
                other_failed = any(getattr(o, "is_combat_failure", False) for o in self.choices if o != c)
                is_win = c.is_combat_success or c.is_enemy_defeat or (not c.is_combat_failure and other_failed)
                if is_win:
                    decisions[c] = 'BEST'
                    c.decision_rule = "RULE_COMBAT_VICTORY"
                    c.evidence_chain.append("Dovus / Dusman yenme basarisi")
                    continue
                elif c.is_combat_failure:
                    decisions[c] = 'WORST'
                    c.decision_rule = "RULE_COMBAT_FAILURE"
                    continue

            # 6. R8: Cok Kategorili Secim Degerlendirmesi (ALL_CONTENT & Profil Onceligi)
            is_cat_best = False
            menu_has_priority_content = any(
                ch.category_scores.get("survival", 0.0) > 0 or
                ch.category_scores.get("combat", 0.0) > 0 or
                ch.category_scores.get("romance", 0.0) > 0 or
                any(is_real_point_metric(d[0]) and d[1] > 0 for d in (ch.deltas_positive + getattr(ch, "downstream_pos", [])))
                for ch in self.choices
            )
            has_real_char_points = any(is_real_point_metric(d[0]) and d[1] > 0 for d in (c.deltas_positive + getattr(c, "downstream_pos", [])))

            if player_profile == "ALL_CONTENT":
                for cat in ("romance", "combat", "survival", "items", "exploration", "gallery"):
                    # 4: Kategori hiyerarsisi - survival, combat veya romance varken sadece items veya exploration olanlar elenir
                    if menu_has_priority_content and cat in ("items", "exploration"):
                        continue
                    cat_score = c.category_scores.get(cat, 0.0)
                    if cat_score > 0 and cat_score == category_max[cat]:
                        is_cat_best = True
                        c.evidence_chain.append(f"{cat.capitalize()} kategorisinde en iyi secim (+{cat_score:.1f})")

                # 4: Birden fazla secenek pozitif karakter puani veriyorsa (Sarah +1, Chloe +2), her ikisi de kendi rotasinda BEST
                if has_real_char_points and not c.is_death and not c.is_downstream_death:
                    is_cat_best = True
            elif player_profile == "ROMANCE_ONLY":
                rom_score = c.category_scores.get("romance", 0.0)
                if rom_score > 0 and rom_score == category_max.get("romance", 0.0):
                    is_cat_best = True
                    c.evidence_chain.append(f"Romantizm profilinde en iyi secim (+{rom_score:.1f})")
            elif player_profile == "SURVIVAL_ONLY":
                surv_score = c.category_scores.get("survival", 0.0) + c.category_scores.get("combat", 0.0)
                max_surv = max((ch.category_scores.get("survival", 0.0) + ch.category_scores.get("combat", 0.0) for ch in self.choices), default=0.0)
                if surv_score > 0 and surv_score == max_surv:
                    is_cat_best = True
                    c.evidence_chain.append(f"Hayatta kalma profilinde en iyi secim (+{surv_score:.1f})")

            # 7. Genel En Yuksek Puan (H10a) - Ozel profilde profil disi secenekler engellenir
            is_profile_eligible = True
            if player_profile == "ROMANCE_ONLY" and c.category_scores.get("romance", 0.0) <= 0:
                is_profile_eligible = False
            elif player_profile == "SURVIVAL_ONLY" and (c.category_scores.get("survival", 0.0) + c.category_scores.get("combat", 0.0)) <= 0:
                is_profile_eligible = False
            elif player_profile == "DIK_ONLY" and not any(var.lower() == "dik" or "dik" in var.lower() for var, _ in c.deltas_positive):
                is_profile_eligible = False
            elif player_profile == "CHICK_ONLY" and not any(var.lower() == "chick" or "chick" in var.lower() for var, _ in c.deltas_positive):
                is_profile_eligible = False
            # 4: Oncelik hiyerarsisi: Menude gercek karakter puani / romance / survival varsa items/exploration max_eff ile secilemez
            if menu_has_priority_content and not (
                c.category_scores.get("romance", 0.0) > 0 or
                c.category_scores.get("survival", 0.0) > 0 or
                c.category_scores.get("combat", 0.0) > 0 or
                has_real_char_points or c.is_survival
            ):
                is_profile_eligible = False

            if ((c.effective_score > 0 and c.effective_score == max_eff and is_profile_eligible) or is_cat_best):
                if getattr(c, "is_avoidance", False) or c.is_passive_skip:
                    decisions[c] = 'NEUTRAL'
                    c.decision_rule = "RULE_NEUTRAL_PASSIVE_SKIP"
                elif c.evidence_level in ("AMBIGUOUS", "CONFLICTING"):
                    decisions[c] = 'NEUTRAL'
                    c.decision_rule = "RULE_NEUTRAL_UNCERTAIN"
                elif getattr(c, "has_contingent_inner", False) and c.score == 0:
                    # P2: Garantili puani olmayan, yalnizca ic secime bagli potansiyeli olan dis secenek kesin BEST yapilamaz
                    decisions[c] = 'NEUTRAL'
                    c.decision_rule = "RULE_NEUTRAL_CONTINGENT"
                    c.evidence_chain.append("Ic secime bagli kosullu puan (garanti degil, notr tutuldu)")
                elif getattr(c, "threshold_satisfied_independent", False):
                    # Y4: Esik secimden bagimsiz zaten karsilaniyor -> kesin NEUTRAL
                    decisions[c] = 'NEUTRAL'
                    c.decision_rule = "RULE_NEUTRAL_INDEPENDENT_THRESHOLD"
                    c.evidence_chain.append("Esik secimden bagimsiz zaten karsilaniyor (notr tutuldu)")
                elif getattr(c, "is_unreachable_stat_only", False) and len(c.deltas_positive) <= 1:
                    # R6: Erisilemez esik degiskeni (notr tutuldu)
                    decisions[c] = 'NEUTRAL'
                    c.decision_rule = "RULE_NEUTRAL_UNREACHABLE_STAT"
                    c.evidence_chain.append("Erisilemez esik degiskeni (notr tutuldu)")
                else:
                    decisions[c] = 'BEST'
                    c.decision_rule = "RULE_HIGHEST_STAT_BEST" if not is_cat_best else "RULE_CATEGORY_BEST"
                    if not is_cat_best:
                        c.evidence_chain.append(f"En yuksek puan/kazanim (+{c.effective_score:.1f})")
                continue

            # 8. Cezali Secenek (Rule 3: Yalnizca gercek zarar/kayip iceren secenek WORST olabilir)
            if highlight_negative and c.effective_score < 0 and c.effective_score == min_eff and min_eff < max_eff:
                if c.evidence_level == "CODE_VERIFIED":
                    decisions[c] = 'WORST'
                    c.decision_rule = "RULE_PENALIZED_WORST"
                    c.evidence_chain.append(f"Zararli / cezali secenek ({c.effective_score:.1f})")
                else:
                    decisions[c] = 'NEUTRAL'
                    c.decision_rule = "RULE_NEUTRAL_UNCERTAIN"
                continue

            # Digerleri notr
            decisions[c] = 'NEUTRAL'
            c.decision_rule = "RULE_NEUTRAL_DEFAULT"

        # -------------------------------------------------------------------------
        # Requirement 6: Kardeş Seçeneklerde Birleşme Noktası ve CG/Diyalog Yoğunluğu
        # -------------------------------------------------------------------------
        is_pure_dialogue_menu = all(
            c.score <= 0 and len(c.deltas_positive) == 0 and not c.is_death and not c.is_route_lock and not getattr(c, "is_bribe_trap", False)
            for c in self.choices
        )
        if is_pure_dialogue_menu and len(self.choices) >= 2:
            def _has_cg(lines):
                return any(
                    re.search(r'\b(?:scene|show)\s+(?:cg|event|hscene|anim|special|movie|gallery)_', l, re.IGNORECASE) or
                    re.search(r'\bscene\s+cg\b', l, re.IGNORECASE)
                    for l in lines
                )
            def _count_dialogue(lines):
                return sum(
                    1 for l in lines
                    if l.strip() and not l.strip().startswith(("#", "$", "jump", "call", "pass", "return", "scene", "show", "play", "stop", "pause", "with"))
                )

            cg_flags = [_has_cg(getattr(c, "block_lines", [])) for c in self.choices]
            diag_counts = [_count_dialogue(getattr(c, "block_lines", [])) for c in self.choices]
            max_diag = max(diag_counts) if diag_counts else 0

            # 1. CG varlığı kontrolü
            if any(cg_flags) and not all(cg_flags):
                for idx, c in enumerate(self.choices):
                    if cg_flags[idx]:
                        decisions[c] = 'BEST'
                        c.evidence_level = "CODE_VERIFIED"
                        c.decision_rule = "RULE_SPECIAL_DIALOGUE_SCENE"
                        c.score += STUDIO_CONFIG.get("bonus_special_dialogue", 10.0)
                        c.category_scores["gallery"] += STUDIO_CONFIG.get("bonus_special_dialogue", 10.0)
                        if not any("+Özel Diyalog" in d[0] for d in c.deltas_positive):
                            c.deltas_positive.append(("[+Özel Diyalog / Sahne]", STUDIO_CONFIG.get("bonus_special_dialogue", 10.0)))
                        c.evidence_chain.append("Özel CG / Sahne görseli barındırır (Kardeş seçeneklere kıyasla üstün)")


        # Katman 6: Goreli Ustunluk (Relative Dominance)
        menu_has_code_deltas = any(bool(ch.deltas_positive) for ch in self.choices)
        if STUDIO_CONFIG.get("enable_relative_dominance", True) and not menu_has_code_deltas:
            has_best = any(decisions.get(c) == 'BEST' for c in self.choices)
            if not has_best and len(self.choices) == 2:
                content_openers = []
                passive_skippers = []
                for c in self.choices:
                    dialogue_lines = [
                        l for l in getattr(c, "block_lines", [])
                        if l.strip() and not l.strip().startswith(("#", "$", "jump", "call", "pass", "return"))
                    ]
                    is_day_skip = bool(c.jump_target and (
                        c.jump_target in getattr(self, "day_skip_labels", set()) or
                        RE_DAY_SKIP_LABELS.search(c.jump_target.lower())
                    ))
                    is_passive = (
                        (getattr(c, "is_passive_skip", False) or
                         getattr(c, "is_avoidance", False) or
                         is_day_skip or
                         (len(getattr(c, "block_lines", [])) > 0 and all(l.strip() in ("pass", "") or l.strip().startswith("#") for l in getattr(c, "block_lines", []))) or
                         bool(RE_PASSIVE_ACTIONS.search(c.clean_text))) and
                        not (bool(c.jump_target) and not is_day_skip) and
                        not bool(c.call_target)
                    )
                    has_story_content = (
                        len(dialogue_lines) > 0 or
                        getattr(c, "is_active_exploration", False) or
                        (bool(c.jump_target) and not is_day_skip) or
                        bool(c.call_target) or
                        len(getattr(c, "block_lines", [])) > 1
                    )
                    is_unreachable = (
                        getattr(c, "is_unreachable_stat_only", False) or
                        getattr(c, "threshold_satisfied_independent", False) or
                        c.decision_rule in ("RULE_NEUTRAL_UNREACHABLE_STAT", "RULE_NEUTRAL_INDEPENDENT_THRESHOLD")
                    )
                    is_bad = (
                        c.is_death or c.is_downstream_death or getattr(c, "future_death_risk", False) or
                        c.is_route_lock or getattr(c, "is_combat_failure", False) or
                        getattr(c, "is_avoidance", False) or
                        c.effective_score < 0 or decisions.get(c) == 'WORST' or
                        getattr(c, "is_conflicting_branches", False) or
                        (len(c.deltas_positive) > 0 and len(c.deltas_negative) > 0) or
                        c.evidence_level == "CONFLICTING" or
                        getattr(c, "dynamic_jump_unresolved", None) is not None or
                        getattr(c, "dynamic_func_unresolved", False)
                    )

                    if has_story_content and not is_passive and not is_unreachable and not is_bad:
                        content_openers.append(c)
                    elif is_passive or is_bad or decisions.get(c) == 'WORST':
                        passive_skippers.append(c)

                if content_openers and passive_skippers and len(content_openers) < len(self.choices):
                    for co in content_openers:
                        decisions[co] = 'BEST'
                        co.decision_rule = "RULE_RELATIVE_DOMINANCE"
                        co.evidence_level = "CODE_VERIFIED"
                        co.confidence_score = 0.85
                        co.evidence_chain.append("Göreli üstünlük: Diğer seçenek pasif/atlama iken içerik/diyalog açar")

        # H8 Gatekeeper Filtresi: AMBIGUOUS ve CONFLICTING asla boyanmaz, WORST yalniz CODE_VERIFIED
        for c in self.choices:
            v = decisions.get(c, 'NEUTRAL')
            if v == 'BEST' and c.evidence_level in ('AMBIGUOUS', 'CONFLICTING') and c.decision_rule != "RULE_SPECIAL_DIALOGUE_SCENE":
                decisions[c] = 'NEUTRAL'
                c.decision_rule = "RULE_NEUTRAL_UNCERTAIN"
            elif v == 'WORST' and c.evidence_level != 'CODE_VERIFIED' and not getattr(c, "is_bribe_trap", False) and c.decision_rule not in ("RULE_BRIBE_TRAP", "RULE_HAREM_MONOGAMY_PENALTY", "RULE_MULTI_ROUTE_BREAKER", "RULE_TARGET_ROUTE_LOCKED"):
                decisions[c] = 'NEUTRAL'
                c.decision_rule = "RULE_NEUTRAL_UNCERTAIN"

        # Rule 3: Bir seçenek SADECE gerçek bir kayıp/zarar içeriyorsa Kırmızı ({wt_worst}) olabilir:
        # - Oyuncu ölümü / Bad End (is_death, future_death_risk)
        # - Net karakter sevgisi veya stat kaybı (-=)
        # - Karakter rotasını False yapma / kapatma
        # - Serbest dolaşımı (Free Roam) veya özel sahneyi atlayıp gün sonuna geçme (jump next_day vb.)
        # Eğer Seçenek A +1 veriyor, Seçenek B 0 veriyorsa: Seçenek B ASLA Kırmızı olamaz (NEUTRAL kalır).
        # Eğer Seçenek A +1 Sarah, Seçenek B +1 Chloe veriyorsa (veya biri +DIK diğeri +CHICK): ikisi de Kırmızı OLMAZ.
        # R5 Fix: bu kuralları gerçekleştiren _is_real_damage_or_loss yerel fonksiyonu hiçbir
        # yerden çağrılmadığı için (ölü kod) kaldırıldı; kural davranışı _finalize içindedir.

        return decisions

    def _finalize(self, decisions, bridge=None, player_profile="ALL_CONTENT", goal=None, heuristic_decisions=None):
        project_ctx = getattr(self, "project_ctx", None)
        analyzer = getattr(self, "analyzer", None)
        consumed_set = None
        is_dynamic = False
        if project_ctx and "consumed_vars" in project_ctx:
            cv = project_ctx["consumed_vars"]
            if isinstance(cv, tuple): consumed_set, is_dynamic = cv
            else: consumed_set = set(cv)
        elif analyzer and hasattr(analyzer, "get_all_consumed_variables"):
            consumed_set, is_dynamic = analyzer.get_all_consumed_variables()

        target_char = None
        if goal:
            target_char = str(goal).strip().lower()
        elif player_profile.startswith(("CHARACTER:", "char:", "CHARACTER_ONLY:")):
            target_char = player_profile.split(":", 1)[1].strip().lower()
        elif getattr(self, "focus_char", None):
            target_char = str(self.focus_char).lower().strip()

        def _is_unconsumed(c):
            if consumed_set is not None and len(consumed_set) > 0 and not is_dynamic:
                all_v = [d[0] for d in (c.deltas_positive + getattr(c, "downstream_pos", []))]
                if all_v and not any(counts_as_gain(v, 1.0, consumed_set, is_dynamic) for v in all_v):
                    return True
            return False

        def _is_unreachable_or_independent(c):
            # Y3 fix: downstream_truncated burada YER ALMAZ. Taramanin butce
            # sinirinda kesilmesi "erişilemez" değil "kanıt kısmi" demektir;
            # aksi halde belirgin ölüm/kazanç dalları dahil herkes NONE'a düşer.
            # Kesilme yine _collect_evidence içinde uncertainty_reasons ile not edilir.
            return (
                getattr(c, "threshold_satisfied_independent", False) or
                getattr(c, "is_unreachable_stat_only", False) or
                c.decision_rule in ("RULE_NEUTRAL_UNREACHABLE_STAT", "RULE_NEUTRAL_INDEPENDENT_THRESHOLD")
            )

        final_decisions = {}
        for c in self.choices:
            dec_val = decisions.get(c, Decision("NONE"))
            if bridge:
                # Both köprüsü uygulandıysa orijinal seçenekler NONE (kırmızı değil)
                dec_val = Decision("NONE")
                c.verdict = dec_val
                c.decision_rule = "RULE_BRIDGE_ORIGINAL_NEUTRAL"
                c.decision_reason = f"Köprü oluşturuldu ({bridge.get('label', 'Mod: Both')}); orijinal seçenek nötr kaldı."
                c.confidence = 0.9
                c.bridge_info = bridge
                final_decisions[c] = dec_val
                continue

            # Eğer bağımsız veya erişilemez eşikse ASLA yeşil olamaz
            if _is_unreachable_or_independent(c):
                dec_val = Decision("NONE")
            elif _is_unconsumed(c):
                # Tüketilmeyen değişken (Senaryo 1 & 2)
                dec_val = Decision("NONE")
            elif target_char:
                # Hedef karakter modu: sadece hedefe kazanç sağlayan seçenek kazanır
                # R6 Faz 2.7: alias grafiği — 'love_L'/'luna_points' benzeri takma adlar
                # ayni karakter grubuada toplandigindan puan toplama eksik kalmaz.
                _alias_grp = {}
                try:
                    _alias_grp = getattr(analyzer, "alias_group", {}) or {}
                except Exception:
                    _alias_grp = {}

                def _var_hits_target(var_name):
                    for _v_name in ({clean_var_to_name(str(var_name)).lower(), clean_identifier(str(var_name)).lower()} |
                                    {str(x).lower() for x in _alias_grp.get(clean_identifier(str(var_name)).lower(), set())} |
                                    {clean_var_to_name(str(x)).lower() for x in _alias_grp.get(clean_identifier(str(var_name)).lower(), set())}):
                        if _v_name and target_char in _v_name:
                            return True
                    return False

                char_pts = sum(val for var, val in (c.deltas_positive + getattr(c, "downstream_pos", [])) if _var_hits_target(var))
                if char_pts > 0 and not (c.is_death or getattr(c, "future_death_risk", False) or c.is_route_lock):
                    dec_val = Decision("GREEN")
                else:
                    dec_val = Decision("NONE")
            elif dec_val == "GREEN":
                pass
            elif heuristic_decisions and heuristic_decisions.get(c) == "BEST":
                # Sezgisel / Kanıt analizinde BEST olarak belirlenmişse ve zarar/kilit yoksa
                if not (c.is_death or getattr(c, "future_death_risk", False) or c.is_route_lock or getattr(c, "is_conflicting_branches", False)):
                    dec_val = Decision("GREEN")
            elif heuristic_decisions and heuristic_decisions.get(c) == "WORST":
                # Sezgisel / Kanıt analizinde WORST olarak belirlenmişse ve somut kayıp varsa
                has_loss = (
                    c.is_death or c.is_downstream_death or getattr(c, "future_death_risk", False) or
                    c.is_route_lock or getattr(c, "route_locked_name", None) or
                    getattr(c, "is_combat_failure", False) or
                    any(d[1] < 0 and not str(d[0]).startswith("ROTA KAPANIR") and d[0] not in ("PASIF / UZAK DURMA", "ICERIK ATLAR") for d in c.deltas_negative)
                )
                if has_loss:
                    dec_val = Decision("RED")

            # Rule 3: Bir seçenek SADECE gerçek bir kayıp/zarar içeriyorsa Kırmızı olabilir
            if dec_val == "RED" or dec_val == "WORST":
                has_loss = (
                    c.is_death or c.is_downstream_death or getattr(c, "future_death_risk", False) or
                    c.is_route_lock or getattr(c, "route_locked_name", None) or
                    getattr(c, "is_combat_failure", False) or
                    any(d[1] < 0 and not str(d[0]).startswith("ROTA KAPANIR") and d[0] not in ("PASIF / UZAK DURMA", "ICERIK ATLAR") for d in c.deltas_negative)
                )
                if not has_loss:
                    dec_val = Decision("NONE")

            c.verdict = dec_val
            c.decision_rule = getattr(c, "decision_rule", "RULE_PROVABLY_SUPERIOR" if dec_val == "GREEN" else ("RULE_PROVABLY_HARMFUL" if dec_val == "RED" else "RULE_NEUTRAL"))
            c.decision_reason = c.decision_rule + (" - " + " | ".join(dict.fromkeys(c.evidence_chain)) if c.evidence_chain else "")
            c.confidence = getattr(c, "confidence_score", 1.0 if dec_val in ("GREEN", "RED") else 0.5)
            c.bridge_info = bridge if bridge else {}
            final_decisions[c] = dec_val

        if bridge:
            final_decisions["__BOTH__"] = Decision("GREEN")

        return final_decisions

    def evaluate_choices(self, highlight_negative=True, player_profile="ALL_CONTENT", is_harem_game=None, goal=None):
        """
        Doğruluk Sözleşmesi ve Yola Duyarlı Karar Motoru:
        1) Kanıt toplama (_collect_evidence)
        2) Yola duyarlı özet oluşturma (build_summary)
        3) Sözleşmeye uygun karar (decide / decide_with_bridge)
        4) Geriye uyumlu sonuç yazma (_finalize)
        """
        if not self.choices:
            return {}

        # R6 Faz 1.2: ayni parametrelerle tekrar cagriliyorsa yeniden hesaplama yok (decision cache).
        # patch_file, analiz turunden sonra ayni menuler icin karar ureticini tekrar calistirmak
        # yerine bu cache'i okuyarak ~2x hiz kazanir.
        _an = getattr(self, "analyzer", None)
        _ck = (
            getattr(_an, "_analysis_revision", 0),
            bool(highlight_negative),
            str(player_profile),
            None if is_harem_game is None else bool(is_harem_game),
            str(goal) if goal else None,
        )
        _cached = getattr(self, "_evt_decision_cache", None)
        if _cached is not None:
            try:
                if _cached[0] == _ck:
                    return dict(_cached[1])
            except Exception:
                pass

        # 1) Mevcut sezgisel/kanit toplama aynen çalışsın ama KARAR VERMESİN
        heuristic_decisions = self._collect_evidence(player_profile, is_harem_game, goal, highlight_negative)

        # 2) Gerçek karar: her seçenek için yola duyarlı özet + sözleşmeye uygun karar
        project_ctx = getattr(self, "project_ctx", None)
        analyzer = getattr(self, "analyzer", None)
        summaries = {c: build_summary(c, analyzer, project_ctx) for c in self.choices}
        decisions, bridge = decide_with_bridge(self, summaries, goal, analyzer)
        if bridge:
            try:
                if not _cs_bridge_ok(self, bridge):
                    decisions = decide(summaries, goal)
                    bridge = None
            except Exception:
                decisions = decide(summaries, goal)
                bridge = None

        # Seçim etkisini yalnızca aynı label/çağrı/hedef akışındaki koşullara bağla.
        for choice in self.choices:
            append_causal_evidence(choice, analyzer)

        # 3) Sonuçları geriye uyumlu alanlara yaz
        result = self._finalize(decisions, bridge, player_profile, goal, heuristic_decisions)
        try:
            result = _cs_enforce(self, result, bridge)
        except Exception:
            pass

        # R6 Faz 3.11: karar-gereklendirme kaydi (raporlama icin seffaflik)
        try:
            _dlog = getattr(analyzer, "decision_log", None)
            if _dlog is not None:
                _dlog.append({
                    "file": getattr(self, "file_path", ""),
                    "line": int(getattr(self, "line_num", -1)) + 1,
                    "choices": [
                        {
                            "text": str(getattr(c, "text", "")),
                            "verdict": str(v) if isinstance(v, str) else str(getattr(v, "value", v)),
                            "rule": str(getattr(c, "decision_rule", "")),
                            "confidence": float(getattr(c, "confidence", 0.0) or 0.0),
                            "reasons": [str(x) for x in list(getattr(c, "evidence_chain", []))[:12]],
                        }
                        for c, v in result.items() if not isinstance(c, str)
                    ],
                })
        except Exception:
            pass

        try:
            self._evt_decision_cache = (_ck, dict(result))
        except Exception:
            pass
        return result

class RenpyWalkthroughAnalyzer:
    def __init__(self, game_dir, options=None, log_callback=None):
        self._cached_consumed_vars = None
        self.game_dir = game_dir
        self.target_dir = find_real_renpy_game_dir(game_dir)
        self.log_callback = log_callback
        default_options = {
            "green_color": "#2ECC71",
            "red_color": "#EF4444",
            "highlight_negative": True,
            "show_hints": True,
            "hint_style": "name_and_number",
            "remove_rpyc": True,
            "auto_backup": True,
            "deep_jump_scan": True,
            "enable_cheat_menu": True,
            "contract_enforcement": True,
            "skip_rpa": False,
            "allow_container_exec": False,
            "read_only": False,
            "player_profile": "ALL_CONTENT",
            "max_downstream_depth": STUDIO_CONFIG["max_downstream_depth"],
            "max_downstream_lines": STUDIO_CONFIG["max_downstream_lines"],
            "verify_with_renpy_lint": STUDIO_CONFIG.get("verify_with_renpy_lint", False),
            "renpy_lint_timeout": STUDIO_CONFIG.get("renpy_lint_timeout", 180),
            "renpy_executable": STUDIO_CONFIG.get("renpy_executable", None)
        }
        self.options = default_options.copy()
        if options:
            self.options.update(options)
            if "highlight_negatives" in options and "highlight_negative" not in options:
                self.options["highlight_negative"] = options["highlight_negatives"]
            if "deep_jump_analysis" in options and "deep_jump_scan" not in options:
                self.options["deep_jump_scan"] = options["deep_jump_analysis"]
            if "clear_rpyc" in options and "remove_rpyc" not in options:
                self.options["remove_rpyc"] = options["clear_rpyc"]
            if "cheat_menu" in options and "enable_cheat_menu" not in options:
                self.options["enable_cheat_menu"] = options["cheat_menu"]

        self.is_harem_game = False
        self.labels = {}
        self.initial_vars = {}
        self.var_thresholds = {}
        self.global_flag_impact = {}
        self.global_function_summaries = {}
        self.global_instance_class_map = {}
        self.global_condition_impact_map = collections.defaultdict(list)
        self.all_stat_deltas = []
        self.median_delta = 1.0
        self.iqr_delta = 0.0
        self.variables_lifecycle = {}
        self.free_roam_labels = set()
        self.day_skip_labels = set()
        self.file_cache = {}
        self.file_cache_meta = {}
        self.rpy_files = []
        self.rpyc_files = []
        self.rpa_files = []
        self.downstream_memo = {}
        self.file_encoding_info = {}
        self.baseline_lint_output = ""
        self.baseline_lint_issues = []
        self.last_rolled_back_files = []
        self.last_rollback_reasons = {}
        self.var_absolute_assignments = {}
        self.baseline_unattributed_errors = []
        self.cfg = None
        self.ast_parse_errors = []
        self.menus = []
        self.unresolved_targets = []
        self.truncated_scans = []
        self.conflicting_branches = []
        self.max_var_additions = {}
        self.skipped_menus = []
        self.compound_thresholds = []
        self.var_has_dynamic_addition = {}
        self.var_dynamic_reasons = {}
        self.point_functions = {}
        self.unreachable_thresholds = []
        self.uncertain_thresholds = []
        self.last_lint_output = ""
        self._in_batch_patch = False
        # R6 Faz 1-3: yeni analitik durum alanlari
        self.project_ctx = None              # {"consumed_vars": (set, is_dynamic)} — karar motoruna proje genelini baglar
        self.label_scan_memo = {}            # (label, stop_labels) -> tarama ozeti; durumsuz yan cagrilar icin genellenmis memo
        self.cfg_unreachable_labels = set()  # CFG'e gore hicbir yoldan erisilemeyen etiketler
        self.cfg_points_of_no_return = set() # geri donulemez secim/kilit noktalari (bilgi amacli raporlandirilir)
        self.cfg_mutually_exclusive = []     # birbirini dislayan rota ciftleri (both-kandidate maskesi)
        self.menu_lookup = {}                # (abspath, menu_line) -> RenpyMenu; Graph Solver v0.5 icin
        self.all_menus = []                  # tam analizde toplanan tum menuler (alias/CFG/rapor turlari)
        self.alias_group = {}                # anonimlestirilmis degisken -> ayni karakterin grup adlari
        self.runtime_observations = {}       # runtime probe geri besleme haritasi
        self.decision_log = []               # karar-gereklendirme kaydi (Rapor/GUI panel icin)

        # Regex Tanimlari
        # P1: Tam Ren'Py menu baslik soz dizimi (istege bagli ad, istege bagli arguman parantezi, colon ve yorum)
        self.re_menu = re.compile(r'^\s*menu(?:\s+([a-zA-Z0-9_]+))?(?:\s*\((.*?)\))?\s*:(?:\s*#.*)?\r?$')
        self.re_py_assign_init = re.compile(r'^\s*\$\s*([a-zA-Z0-9_.]+)\s*=\s*(.+?)\s*(?:#.*)?$')
        self.re_choice = re.compile(r'^(\s*)(["\'])(.+?)\2(\s*(?:\([^\)]*\))?\s*(?:if\s+.*?)?)\s*:(?:\s*#.*)?\r?$')
        self.re_label = re.compile(r'^\s*label\s+([a-zA-Z0-9_]+)(?:\s*\([^\)]*\))?\s*:(?:\s*#.*|\s*)$')
        self.re_jump = re.compile(r'^\s*jump\s+([a-zA-Z0-9_]+)', re.IGNORECASE)
        self.re_call = re.compile(r'^\s*call\s+([a-zA-Z0-9_]+)', re.IGNORECASE)
        self.re_renpy_jump = re.compile(r'(?:\$\s*|\b)renpy\.jump\s*\(\s*([\'"])(.+?)\1\s*\)', re.IGNORECASE)
        self.re_renpy_call = re.compile(r'(?:\$\s*|\b)renpy\.call\s*\(\s*([\'"])(.+?)\1\s*\)', re.IGNORECASE)
        self.re_renpy_jump_any = re.compile(r'(?:\$\s*|\b)renpy\.jump\s*\(\s*([^\)]+)\s*\)', re.IGNORECASE)
        self.re_renpy_call_any = re.compile(r'(?:\$\s*|\b)renpy\.call\s*\(\s*([^\)]+)\s*\)', re.IGNORECASE)
        self.re_jump_expr = re.compile(r'^\s*jump\s+expression\s+(.+)', re.IGNORECASE)
        self.re_call_expr = re.compile(r'^\s*call\s+expression\s+(.+)', re.IGNORECASE)

        self.re_aug_assign = re.compile(
            r'(?:\$\s*)?([a-zA-Z0-9_.\[\]\'\"]+)\s*(\+=|\-=)\s*([0-9]+(?:\.[0-9]+)?)'
        )
        self.re_self_assign = re.compile(
            r'(?:\$\s*)?([a-zA-Z0-9_.\[\]\'\"]+)\s*=\s*\1\s*([\+\-])\s*([0-9]+(?:\.[0-9]+)?)'
        )
        self.re_bool_assign = re.compile(
            r'(?:\$\s*)?([a-zA-Z0-9_.\[\]\'\"]+)\s*=\s*(True|False)', re.IGNORECASE
        )
        self.re_default = re.compile(
            r'^\s*default\s+([a-zA-Z0-9_.]+)\s*=\s*(.+?)\s*(?:#.*)?$', re.IGNORECASE
        )
        self.re_define = re.compile(
            r'^\s*define\s+([a-zA-Z0-9_.]+)\s*=\s*(.+?)\s*(?:#.*)?$', re.IGNORECASE
        )
        self.re_screen = re.compile(
            r'^\s*screen\s+([a-zA-Z0-9_]+)(?:\s*\([^\)]*\))?\s*:(?:\s*#.*)?$', re.IGNORECASE
        )
        # N2: Ceviri sarmalayicili (_(), _p()), kwargs'li ve liste action'li screen butonlari
        self.re_textbutton = re.compile(
            r'textbutton\s+'
            r'(?:(_[p_]?)\s*\(\s*)?'
            r'([\'"])(.*?)\2'
            r'(?:\s*\))?'
            r'(?:\s+[^:]*?)?'
            r'\s+action\s+'
            r'(.+)',
            re.IGNORECASE
        )

        self.re_func_point = re.compile(
            r'(?:add|gain|give|inc|mod|change|set)_(?:point|points|love|aff|affection|rel|relation|trust|like|stat|pts)'
            r'\s*\(\s*(?:[\'"]([a-zA-Z0-9_]+)[\'"]\s*,\s*([+-]?[0-9]+(?:\.[0-9]+)?)|([+-]?[0-9]+(?:\.[0-9]+)?)\s*,\s*[\'"]([a-zA-Z0-9_]+)[\'"])',
            re.IGNORECASE
        )
        self.re_rel_func = re.compile(
            r'(?:update|change|mod|modify|set|add)_relationship\s*\(\s*[\'"]([a-zA-Z0-9_]+)[\'"]\s*,\s*(?:[a-zA-Z0-9_]+\s*=\s*)?([+-]?[0-9]+(?:\.[0-9]+)?)',
            re.IGNORECASE
        )
        self.re_method_points = re.compile(
            r'([a-zA-Z0-9_]+)\.(?:add|gain|give|inc|change)_(?:point|points|love|aff|affection|rel|trust|stat)'
            r'\s*\(\s*([+-]?[0-9]+(?:\.[0-9]+)?)',
            re.IGNORECASE
        )
        self.re_notify = re.compile(r'renpy\.notify\s*\(\s*[\'"]([^"\']+)[\'"]\s*\)', re.IGNORECASE)
        self.re_rejection = re.compile(
            r'(?:reject|rejected|dump|dumped|friendzone|friendzoned|broke_up|breakup|refuse|refused|failed_date|failed_romance|hates_mc|dislike)',
            re.IGNORECASE
        )

    def _find_files(self, target):
        self.rpy_files = []
        self.rpyc_files = []
        self.rpa_files = []
        for root, dirs, files in os.walk(target):
            dirs[:] = [d for d in dirs if d.lower() not in IGNORED_DIRS]
            norm_parts = os.path.normpath(root).lower().split(os.sep)
            if "tl" in norm_parts:
                tl_idx = norm_parts.index("tl")
                if tl_idx == len(norm_parts) - 1:
                    dirs[:] = [d for d in dirs if d.lower() in ALLOWED_TL_LANGS]
                else:
                    lang = norm_parts[tl_idx + 1]
                    if lang not in ALLOWED_TL_LANGS:
                        continue
            for f in files:
                f_lower = f.lower()
                full_p = os.path.join(root, f)
                if f_lower.endswith('.rpy'):
                    self.rpy_files.append(full_p)
                elif f_lower.endswith('.rpyc'):
                    self.rpyc_files.append(full_p)
                elif f_lower.endswith('.rpa'):
                    self.rpa_files.append(full_p)

    def discover_game_characters(self, log_callback=None):
        count = 0
        re_char_def = re.compile(r'^\s*define\s+([a-zA-Z0-9_]+)\s*=\s*Character\s*\(\s*["\']([^"\']+)["\']', re.IGNORECASE)
        ignore_names = {"narrator", "centered", "extend", "nvl", "slow", "fast", "gui", "config", "flash", "thought", "mc", "player", "hero"}
        # M1 fix: Python yerlesikleri / fonksiyon parametre adlari karakter sanilmasin.
        # (Gercek vaka: 'min_aff += min_val' satiri 'min' adinda hayali karakter uretiyordu)
        builtin_names = {
            "min", "max", "len", "sum", "abs", "int", "str", "float", "bool", "list", "dict",
            "set", "tuple", "round", "any", "all", "sorted", "print", "range", "zip", "map",
            "filter", "type", "next", "iter", "id", "hash", "repr", "format", "input", "open",
            "super", "object", "self", "cls", "person", "true", "false", "none", "renpy",
            "persistent", "store", "random", "time", "temp", "val", "value", "index", "item",
            "fine", "new", "old", "best", "good", "bad", "last", "first", "cur", "current",
            "obj", "target", "char", "character", "data", "info", "result", "res", "tmp"
        }
        # M1 fix: nesne tabanli stat kullanimi keşfi (lucy.Affection, bot.Lust gibi).
        # Birçok oyun (Between Humanity, vb.) karakterleri düz store sayısı değil
        # nesne özniteliği olarak tutar; bu tarama onları haritaya ekler.
        re_obj_stat = re.compile(
            r'\b([a-zA-Z_][a-zA-Z0-9_]*)\s*\.\s*(?:MCAffection|Affection|Love|Lust|Trust|Points|Relation)\b'
        )
        re_stat_gain = re.compile(r'(?:\$\s*)?([a-zA-Z0-9_]+)_(?:love|aff|points|romance|like|trust)\s*\+=', re.IGNORECASE)
        obj_stat_words = ('Affection', 'Love', 'Lust', 'Trust', 'Points', 'Relation')

        for fpath in self.rpy_files:
            lines = self.get_file_lines(fpath)
            for l in lines:
                m = re_char_def.match(l)
                if m:
                    var_k = m.group(1).lower()
                    char_n = m.group(2).strip()
                    if var_k in builtin_names or char_n.lower() in builtin_names:
                        continue
                    if var_k not in ignore_names and len(char_n) >= 2 and char_n.lower() not in ignore_names:
                        if var_k not in DYNAMIC_CHARACTERS:
                            DYNAMIC_CHARACTERS[var_k] = char_n
                            count += 1
                        clean_k = re.sub(r'[^a-zA-Z]', '', var_k)
                        if clean_k and clean_k not in DYNAMIC_CHARACTERS:
                            DYNAMIC_CHARACTERS[clean_k] = char_n

        for fpath in self.rpy_files:
            lines = self.get_file_lines(fpath)
            for l in lines:
                # Necessary literal substrings only; preserve the original regex
                # and all three passes (explicit Character definitions win).
                if '_' not in l or '+=' not in l:
                    continue
                m = re_stat_gain.search(l)
                if m:
                    k = m.group(1)
                    if k.lower() in builtin_names:
                        continue
                    if k.lower() not in ignore_names and k.lower() not in DYNAMIC_CHARACTERS:
                        DYNAMIC_CHARACTERS[k.lower()] = k.capitalize()
                        count += 1

        # M1 fix: nesne-özniteliği karakter keşfi (3. tur)
        for fpath in self.rpy_files:
            lines = self.get_file_lines(fpath)
            for l in lines:
                if '.' not in l or not any(word in l for word in obj_stat_words):
                    continue
                m = re_obj_stat.search(l)
                if m:
                    k = m.group(1)
                    k_low = k.lower()
                    if k_low in ignore_names or k_low in builtin_names or len(k) < 2:
                        continue
                    if k_low not in DYNAMIC_CHARACTERS:
                        DYNAMIC_CHARACTERS[k_low] = k.capitalize()
                        count += 1

        if log_callback and count > 0:
            log_callback(f"[+] Oyunda {len(DYNAMIC_CHARACTERS)} farkli karakter ve stat dinamik olarak haritalandi.")

    def detect_harem_game(self, log_callback=None):
        """
        HAREM OYUNU OTOMATIK TESPIT MOTORU:
        Oyundaki karakter sayisini, romantizm degiskenlerini, oyun adini ve senaryo kaliplarini analiz ederek
        oyunun bir Harem (polyamory / multi-romance) oyunu olup olmadigini deterministik olarak tespit eder.
        """
        def _log(msg):
            if log_callback:
                try: log_callback(msg)
                except Exception: pass

        game_dir_full = os.path.abspath(self.game_dir).lower()
        dir_name = os.path.basename(os.path.abspath(self.game_dir)).lower()
        parent_dir_name = os.path.basename(os.path.dirname(os.path.abspath(self.game_dir))).lower()
        known_harem_titles = (
            "eternum", "being a dik", "beingadik", "once in a lifetime", "onceinaLifetime",
            "lust academy", "lustacademy", "summertime saga", "harem hotel", "haremhotel",
            "freshwomen", "milfy city", "college kings", "westview", "ripples",
            "acting lessons", "shut up and dance", "shutupanddance", "intertwined"
        )
        if any(t in dir_name or t in parent_dir_name or t in game_dir_full for t in known_harem_titles):
            self.is_harem_game = True
            _log(f"[+] HAREM OYUNU TESPITI: Oyun yolu veya klasoru '{dir_name}' taninan Harem oyunlari listesinde bulundu.")
            return True

        for fpath in self.rpy_files:
            fname = os.path.basename(fpath).lower()
            if fname in ("options.rpy", "gui.rpy", "script.rpy"):
                lines = self.get_file_lines(fpath)
                for l in lines[:120]:
                    l_low = l.lower()
                    if "config.name" in l_low or "config.window_title" in l_low:
                        if any(t in l_low for t in known_harem_titles) or "harem" in l_low:
                            self.is_harem_game = True
                            _log(f"[+] HAREM OYUNU TESPITI: config.name iceriginde Harem basligi tespit edildi.")
                            return True

        romance_chars_found = set()
        for k in KNOWN_CHARACTERS:
            for fpath in self.rpy_files[:30]:
                for l in self.get_file_lines(fpath)[:200]:
                    if f"{k}_" in l.lower() or f"{k}." in l.lower() or f"'{k}'" in l.lower() or f'"{k}"' in l.lower():
                        romance_chars_found.add(k)
                        break

        if len(romance_chars_found) >= 3:
            self.is_harem_game = True
            _log(f"[+] HAREM OYUNU TESPITI: Projede {len(romance_chars_found)} farkli kadin karakter romantizm/etkinlik degiskeni tespit edildi.")
            return True

        self.is_harem_game = False
        return False

    
    def get_all_consumed_variables(self):
        if hasattr(self, "_cached_consumed_vars") and self._cached_consumed_vars is not None:
            return self._cached_consumed_vars
        all_reads = set()
        is_dyn = False
        for fpath in getattr(self, "rpy_files", []):
            lines = self.get_file_lines(fpath)
            reads, dyn = consumed_vars_from_code(lines)
            all_reads.update(reads)
            if dyn:
                is_dyn = True
        self._cached_consumed_vars = (all_reads, is_dyn)
        return self._cached_consumed_vars

    def scan_files(self, auto_extract=False, log_callback=None):
        target = find_real_renpy_game_dir(self.game_dir)
        self.target_dir = target
        self.file_cache.clear()
        try: self.file_cache_meta = {}
        except Exception: pass

        # Salt okunur mod koruması: read_only=True ise auto_extract kesinlikle devre dışıdır
        if self.options.get("read_only", False):
            auto_extract = False

        if auto_extract:
            is_v, _ = is_virtual_turbo_container(self.game_dir)
            if is_v:
                allow_exec = self.options.get("allow_container_exec", False)
                if allow_exec:
                    unpacked = unpack_virtual_turbo_container(self.game_dir, log_callback=log_callback, allow_container_exec=True)
                    if unpacked:
                        self.game_dir = unpacked
                        target = find_real_renpy_game_dir(self.game_dir)
                        self.target_dir = target
                else:
                    if log_callback:
                        log_callback("[!] GÜVENLİK ENGELİ: Sanallaştırılmış Turbo Studio kapsülünü çalıştırma izni verilmedi (allow_container_exec=False). Kapsül çalıştırılmadı.")

            clean_site_artifacts(self.game_dir, log_callback=log_callback, auto_delete=False)
            sanitize_renpy_system_folders(self.game_dir, log_callback=log_callback, auto_delete=False)
            unlock_custom_renpy_engine(self.game_dir, log_callback=log_callback)
            auto_repair_decompiled_scripts(self.game_dir, log_callback=log_callback)

        self._find_files(target)

        if auto_extract and len(self.rpy_files) == 0:
            if not self.options.get("skip_rpa", False) and len(self.rpa_files) > 0:
                unpack_all_rpas_in_dir(self.game_dir, log_callback=log_callback)
                decompile_all_rpyc_in_dir(self.game_dir, log_callback=log_callback)
                self._find_files(target)
            elif len(self.rpyc_files) > 0:
                decompile_all_rpyc_in_dir(self.game_dir, log_callback=log_callback)
                self._find_files(target)
        elif auto_extract and len(self.rpyc_files) > 0:
            # R6 fix (kismi decompile kalintisi): .rpy kaynaklari mevcut ama bazi
            # .rpyc'lerin .rpy karsiligi yok (onceki islem yari kesilmisse).
            # Eski davranis bu siralamayi hic decompile etmiyordu; simdi sadece
            # eksikler icin decompile_all_rpyc_in_dir cagrilir (mevcutlar korunur).
            missing_rpy = [rp for rp in self.rpyc_files if not os.path.exists(rp[:-1])]
            if missing_rpy:
                if log_callback:
                    log_callback(f"[*] {len(missing_rpy)} adet .rpyc dosyasinin .rpy karsiligi yok — kalan decompile ediliyor...")
                decompile_all_rpyc_in_dir(self.game_dir, log_callback=log_callback)
                self._find_files(target)

        self.discover_game_characters(log_callback=log_callback)
        self.index_labels(log_callback=log_callback)
        self.detect_harem_game(log_callback=log_callback)
        return len(self.rpy_files), len(self.rpyc_files), len(self.rpa_files)

    def get_file_lines(self, fpath):
        if fpath not in self.file_cache:
            enc, nl, has_bom = detect_file_encoding(fpath)
            self.file_encoding_info[fpath] = (enc, nl, has_bom)
            try:
                with open(fpath, "r", encoding=enc, errors="surrogateescape") as f:
                    self.file_cache[fpath] = f.readlines()
                try: self._cache_file_meta(fpath)
                except Exception: pass
            except Exception as e:
                if self.log_callback:
                    self.log_callback(f"[!] HATA: Dosya okunamadi ({fpath}): {e}")
                self.file_cache[fpath] = []
        else:
            # R6 Faz 1.4: disaridan degisen dosyada bayat cache kullanma (mtime+size)
            try:
                if self._cache_file_meta(fpath, refresh=False):
                    enc, nl, has_bom = self.file_encoding_info.get(fpath) or detect_file_encoding(fpath)
                    self.file_encoding_info[fpath] = (enc, nl, has_bom)
                    with open(fpath, "r", encoding=enc, errors="surrogateescape") as f:
                        self.file_cache[fpath] = f.readlines()
                    try: self._cache_file_meta(fpath)
                    except Exception: pass
            except Exception:
                pass
        return self.file_cache[fpath]

    def _cache_file_meta(self, fpath, refresh=True):
        """R6 Faz 1.4: Dosyanin (mtime_ns, size) imzasini kaydeder; refresh=True yazarken,
        refresh=False mevcut imza ile karsilastirir ve degisti True döndurur."""
        st = os.stat(fpath)
        sig = (st.st_mtime_ns, st.st_size)
        meta = getattr(self, "file_cache_meta", None)
        if meta is None:
            meta = self.file_cache_meta = {}
        old = meta.get(fpath)
        if refresh or old is None:
            meta[fpath] = sig
            return False if (refresh and old is not None and old == sig) else (old is not None and old != sig)
        return old != sig

    def index_labels(self, log_callback=None):
        self.labels.clear()
        self.initial_vars.clear()
        self.var_thresholds.clear()

        re_thresh = re.compile(r'([a-zA-Z0-9_]+)\s*(>=|>|==|<=|<)\s*([0-9]+(?:\.[0-9]+)?)')
        re_py_start = re.compile(r'^\s*(?:init(?:\s+-\d+)?\s+)?python(?:\s+in\s+[a-zA-Z0-9_]+)?\s*:(?:\s*#.*)?$')

        for fpath in self.rpy_files:
            lines = self.get_file_lines(fpath)
            in_py_block = False
            py_block_indent = 0
            in_triple = None

            for idx, line in enumerate(lines):
                curr_indent = len(line) - len(line.lstrip())
                line_clean = line.strip()

                if in_py_block:
                    if line_clean and curr_indent <= py_block_indent and not line_clean.startswith("#") and in_triple is None:
                        in_py_block = False

                if not in_py_block and re_py_start.match(line):
                    in_py_block = True
                    py_block_indent = curr_indent

                if in_triple:
                    pos = line.find(in_triple)
                    if pos != -1:
                        in_triple = None
                elif '"""' in line or "'''" in line:
                    i = 0
                    while i < len(line):
                        if in_triple:
                            if line[i:i+3] == in_triple:
                                in_triple = None
                                i += 3
                                continue
                            i += 1
                        else:
                            if line[i:i+3] in ('"""', "'''"):
                                in_triple = line[i:i+3]
                                i += 3
                                continue
                            i += 1

                if in_py_block or in_triple:
                    continue

                m = self.re_label.match(line)
                if m:
                    lbl = m.group(1)
                    self.labels[lbl] = (fpath, idx)

                m_def = self.re_default.match(line) or self.re_define.match(line)
                if m_def:
                    var_name = normalize_var_name(m_def.group(1))
                    val_str = m_def.group(2).strip()
                    try:
                        val = float(val_str)
                    except ValueError:
                        if val_str.lower() == 'true': val = True
                        elif val_str.lower() == 'false': val = False
                        else: val = val_str.strip('"\'')
                    self.initial_vars[var_name] = val
                elif curr_indent == 0:
                    m_init = self.re_py_assign_init.match(line)
                    if m_init:
                        var_name = normalize_var_name(m_init.group(1))
                        if var_name not in self.initial_vars:
                            val_str = m_init.group(2).strip()
                            try:
                                val = float(val_str)
                                self.initial_vars[var_name] = val
                            except ValueError:
                                if val_str.lower() in ('true', 'false'):
                                    self.initial_vars[var_name] = (val_str.lower() == 'true')
                                elif (val_str.startswith('"') and val_str.endswith('"')) or (val_str.startswith("'") and val_str.endswith("'")):
                                    self.initial_vars[var_name] = val_str[1:-1]

                if re.match(r'^\s*(?:if|elif)\s+', line):
                    for m_th in re_thresh.finditer(line):
                        v_name = m_th.group(1)
                        if len(v_name) < 2 or v_name.lower() in ("i", "j", "k", "x", "y", "z", "n", "d", "c", "t", "s", "p", "idx", "temp", "tmp"):
                            continue
                        op = m_th.group(2)
                        th_val = float(m_th.group(3))
                        if v_name not in self.var_thresholds:
                            self.var_thresholds[v_name] = []
                        self.var_thresholds[v_name].append((op, th_val, fpath, idx))

        # Katman 1: Proje genelindeki tum python bloklarini ve .py dosyalarini AST ile on-tara (Pass 1)
        self.index_interprocedural_functions()

        # Q3: Python fonksiyonlarini indeksle
        self.index_python_functions()

        # Q1, R6, Z1 & Z2: Oyun genelindeki tum degisken artislarini topla ve dinamik/sabit ayrir
        self.max_var_additions.clear()
        self.var_absolute_assignments.clear()
        self.var_has_dynamic_addition.clear()
        self.var_dynamic_reasons.clear()
        for fp in self.rpy_files:
            flines = self.get_file_lines(fp)
            in_py_block = False
            py_block_indent = 0
            in_triple = None
            # Y1 fix: 'idx' burada tanimli degildi; Pass-1'den kalan bayat deger
            # kullaniliyor ve var_absolute_assignments kayitlari yanlis satir
            # numarasi tasiyordu (find_absolute_assignment filtresini bozuyor).
            for idx, fl in enumerate(flines):
                curr_indent = len(fl) - len(fl.lstrip())
                if in_py_block:
                    if fl.strip() and curr_indent <= py_block_indent and not fl.strip().startswith('#'):
                        in_py_block = False
                if not in_py_block and re_py_start.match(fl):
                    in_py_block = True
                    py_block_indent = curr_indent

                if in_triple:
                    pos = fl.find(in_triple)
                    if pos != -1:
                        in_triple = None
                elif '"""' in fl or "'''" in fl:
                    i = 0
                    while i < len(fl):
                        if in_triple:
                            if fl[i:i+3] == in_triple:
                                in_triple = None
                                i += 3
                                continue
                            i += 1
                        else:
                            if fl[i:i+3] in ('"""', "'''"):
                                in_triple = fl[i:i+3]
                                i += 3
                                continue
                            i += 1

                if in_py_block or in_triple:
                    continue

                fl_strip = fl.strip()
                if not fl_strip or fl_strip.startswith('#'):
                    continue
                if not in_py_block and not fl_strip.startswith('$') and not fl_strip.startswith(('default ', 'define ')):
                    continue
                if '=' not in fl_strip and '(' not in fl_strip:
                    continue

                ast_info = RenpyASTAnalyzer.get_assignment_info(fl)
                if ast_info["is_assign"]:
                    raw_target = ast_info["target"]
                    if raw_target:
                        v = normalize_var_name(raw_target)
                        val = ast_info["value"]
                        vtype = ast_info["val_type"]
                        op = ast_info["op"]
                        if op == "=" and vtype == "number" and isinstance(val, (int, float)):
                            if v not in self.var_absolute_assignments:
                                self.var_absolute_assignments[v] = []
                            fl_s = fl.strip()
                            is_cond = fl_s.startswith("if ") or (" if " in fl_s)
                            self.var_absolute_assignments[v].append({
                                "file": fp, "line": idx, "val": float(val),
                                "is_conditional": is_cond, "cond": fl_s if is_cond else ""
                            })
                        if op in ("+=", "+"):
                            if vtype == "number" and isinstance(val, (int, float)):
                                f_val_num = float(val)
                                self.max_var_additions[v] = self.max_var_additions.get(v, 0.0) + f_val_num
                                self.all_stat_deltas.append(abs(f_val_num))
                            else:
                                self.var_has_dynamic_addition[v] = True
                                self.var_dynamic_reasons[v] = f"Dinamik atama ({op} {val})"
                        elif op in ("*=", "formula") or vtype == "dynamic":
                            self.var_has_dynamic_addition[v] = True
                            self.var_dynamic_reasons[v] = f"Dinamik islem ({op} {val})"
                elif ast_info["is_call"]:
                    # Z1: Fonksiyon / metot cagrilarini analiz et
                    func_name = ast_info["call_func"]
                    if func_name and not self.is_irrelevant_call(func_name):
                        func_norm = normalize_var_name(func_name)
                        # Point function mi?
                        if func_norm in self.point_functions or func_name in self.point_functions:
                            fdata = self.point_functions.get(func_norm) or self.point_functions.get(func_name)
                            call_args = ast_info["call_args"]
                            for eff in fdata.get("effects", []):
                                if eff.get("type") == "param_val":
                                    p_idx = eff.get("param_idx", 0)
                                    target_var = eff.get("target")
                                    if p_idx < len(call_args) and isinstance(call_args[p_idx], (int, float)):
                                        c_val = float(call_args[p_idx])
                                        self.max_var_additions[target_var] = self.max_var_additions.get(target_var, 0.0) + c_val
                                    else:
                                        self.var_has_dynamic_addition[target_var] = True
                                        self.var_dynamic_reasons[target_var] = f"Dinamik fonksiyon argumani ({func_name})"
                                elif eff.get("type") == "constant":
                                    target_var = eff.get("target")
                                    c_val = eff.get("val", 0.0)
                                    self.max_var_additions[target_var] = self.max_var_additions.get(target_var, 0.0) + c_val
                        else:
                            # Tanimsiz veya harici fonksiyon/obje metodu cagrisi (Z1)
                            for v in self.var_thresholds:
                                affects, rule = self.check_call_affects_variable(func_name, fl, v)
                                if affects:
                                    self.var_has_dynamic_addition[v] = True
                                    self.var_dynamic_reasons[v] = f"Cozulemeyen cagri ({rule}): {func_name}"
                else:
                    m_aug = re.search(r'(?:\$\s*)?([a-zA-Z0-9_.[\]\'"]+)\s*(\+=)\s*(.+)', fl)
                    if m_aug:
                        v = normalize_var_name(m_aug.group(1).strip())
                        rhs = m_aug.group(3).split('#')[0].strip()
                        m_num = re.match(r'^[0-9]+(?:\.[0-9]+)?$', rhs)
                        if m_num:
                            self.max_var_additions[v] = self.max_var_additions.get(v, 0.0) + float(m_num.group(0))
                        else:
                            self.var_has_dynamic_addition[v] = True
                            self.var_dynamic_reasons[v] = f"Dinamik regex artisi ({rhs})"

        if self.all_stat_deltas:
            sorted_deltas = sorted(self.all_stat_deltas)
            import statistics
            self.median_delta = statistics.median(sorted_deltas)
            n_d = len(sorted_deltas)
            q1 = sorted_deltas[n_d // 4]
            q3 = sorted_deltas[(3 * n_d) // 4]
            self.iqr_delta = q3 - q1
        else:
            self.median_delta = 1.0
            self.iqr_delta = 0.0

        self.index_story_universe(log_callback=log_callback)

    def index_story_universe(self, log_callback=None):
        """R4 & Katman 2: Karar ağaçlarını ve GLOBAL_CONDITION_IMPACT_MAP haritasını oluşturur."""
        self.global_flag_impact.clear()
        self.global_condition_impact_map.clear()
        GLOBAL_CONDITION_IMPACT_MAP.clear()
        self.free_roam_labels.clear()
        self.day_skip_labels.clear()

        re_py_start = re.compile(r'^\s*(?:init(?:\s+-\d+)?\s+)?python(?:\s+in\s+[a-zA-Z0-9_]+)?\s*:(?:\s*#.*)?$')
        re_inv_item = re.compile(r'["\']([a-zA-Z0-9_]+)["\']\s+in\s+inventory', re.IGNORECASE)
        re_if_line = re.compile(r'^\s*if\s+(.*?)\s*:', re.IGNORECASE)
        re_elif_line = re.compile(r'^\s*elif\s+(.*?)\s*:', re.IGNORECASE)
        re_else_line = re.compile(r'^\s*else\s*:', re.IGNORECASE)

        for fpath in self.rpy_files:
            lines = _analysis_code_lines(self.get_file_lines(fpath))
            idx = 0
            in_py_block = False
            py_block_indent = 0
            while idx < len(lines):
                line = lines[idx]
                curr_indent = len(line) - len(line.lstrip())
                line_clean = line.strip()
                if in_py_block and line_clean and curr_indent <= py_block_indent and not line_clean.startswith("#"):
                    in_py_block = False
                if not in_py_block and re_py_start.match(line):
                    in_py_block = True
                    py_block_indent = curr_indent
                if in_py_block:
                    idx += 1
                    continue

                m_lbl = self.re_label.match(line)
                if m_lbl:
                    lbl_raw = m_lbl.group(1)
                    lbl_lower = lbl_raw.lower()
                    if RE_ROAM_LABELS.search(lbl_lower):
                        self.free_roam_labels.add(lbl_raw)
                    if RE_DAY_SKIP_LABELS.search(lbl_lower):
                        self.day_skip_labels.add(lbl_raw)
                    idx += 1
                    continue

                m_if = re_if_line.match(line)
                if not m_if:
                    idx += 1
                    continue

                # R4: Tum karar agaci zincirini (if ... elif ... else) birlestir
                base_indent = len(line) - len(line.lstrip())
                branches = []
                curr_type = "if"
                curr_cond = m_if.group(1).strip()
                curr_lines = []

                j = idx + 1
                while j < len(lines):
                    sub_l = lines[j]
                    sub_str = sub_l.strip()
                    if not sub_str or sub_str.startswith("#"):
                        curr_lines.append(sub_l)
                        j += 1
                        continue
                    sub_indent = len(sub_l) - len(sub_l.lstrip())
                    if sub_indent == base_indent:
                        m_elif = re_elif_line.match(sub_l)
                        m_else = re_else_line.match(sub_l)
                        if m_elif:
                            branches.append((curr_type, curr_cond, curr_lines))
                            curr_type = "elif"
                            curr_cond = m_elif.group(1).strip()
                            curr_lines = []
                            j += 1
                            continue
                        elif m_else:
                            branches.append((curr_type, curr_cond, curr_lines))
                            curr_type = "else"
                            curr_cond = ""
                            curr_lines = []
                            j += 1
                            continue
                        else:
                            break
                    elif sub_indent < base_indent:
                        break
                    else:
                        curr_lines.append(sub_l)
                        j += 1

                branches.append((curr_type, curr_cond, curr_lines))
                # Dış dalı indeksledikten sonra gövdesini de satır satır tara;
                # iç içe if/elif zincirleri ayrı koşul haritasına eklenmelidir.
                idx += 1

                # Karar agacinin sonucunu degerlendir
                else_branches = [b for b in branches if b[0] == "else"]
                else_has_death = False
                if else_branches:
                    _, _, e_lines = else_branches[0]
                    else_has_death = any(_is_engine_termination(l) or _is_player_death_assignment(l) for l in e_lines)

                all_prior_vars = set()
                prior_conditions = []

                for b_type, b_cond, b_lines in branches:
                    if b_type == "if":
                        effective_cond = b_cond
                        prior_conditions = [b_cond] if b_cond else []
                    elif b_type == "elif":
                        neg_prior = " and ".join(f"not ({c})" for c in prior_conditions)
                        effective_cond = f"{neg_prior} and ({b_cond})" if neg_prior else b_cond
                        prior_conditions.append(b_cond)
                    else:
                        effective_cond = " and ".join(f"not ({c})" for c in prior_conditions)

                    b_vars = set()
                    if effective_cond:
                        for m_item in re_inv_item.finditer(effective_cond):
                            b_vars.add(m_item.group(1).lower())
                        cond_vars, _ = condition_variable_names(effective_cond)
                        b_vars.update(cond_vars)

                    all_prior_vars.update(b_vars)

                    b_has_surv = False  # Survival wording alone is not proof.
                    b_has_death = any(_is_engine_termination(l) or _is_player_death_assignment(l) for l in b_lines)
                    b_has_scenes = any(re.match(r'^\s*(?:scene|show)\s+(?:cg\b|cg_|event_|hscene_|anim_|special_|movie_|gallery_)', l, re.IGNORECASE) for l in b_lines)

                    b_temp_ch = RenpyChoice("", 0, "", "", "", "", "")
                    self.inspect_code_lines(b_lines, b_temp_ch)
                    branch_pts_delta = b_temp_ch.score
                    b_real_pos = [(d[0], d[1]) for d in b_temp_ch.deltas_positive if is_real_point_metric(d[0]) or is_true_route_variable(d[0])]
                    b_real_neg = [(d[0], d[1]) for d in b_temp_ch.deltas_negative if is_real_point_metric(d[0]) or is_true_route_variable(d[0])]
                    b_has_pts = bool(b_real_pos) and not b_real_neg
                    # A bare jump is control flow, not proof of a romantic route.
                    b_has_route = any(str(d[0]).startswith('ROTA:') and d[1] > 0
                                      for d in b_temp_ch.deltas_positive) and not b_temp_ch.is_route_lock

                    b_net_score = 0.0
                    if b_has_death: b_net_score -= 100.0
                    if b_has_surv: b_net_score += 80.0
                    if b_has_route: b_net_score += 35.0
                    if b_has_scenes: b_net_score += 20.0
                    if branch_pts_delta < 0:
                        b_net_score += branch_pts_delta
                    elif b_has_pts:
                        b_net_score += 15.0

                    branch_vars = b_vars if effective_cond else all_prior_vars
                    for v in branch_vars:
                        if v not in self.global_flag_impact:
                            self.global_flag_impact[v] = {
                                "saves_life": False,
                                "prevents_death": False,
                                "enables_route": False,
                                "unlocks_scenes": False,
                                "true_unlocks_scenes": False,
                                "false_unlocks_scenes": False,
                                "true_enables_route": False,
                                "false_enables_route": False,
                                "true_saves_life": False,
                                "false_saves_life": False,
                                "positive_score": 0.0,
                                "test_count": 0,
                                "true_net_value": 0.0,
                                "false_net_value": 0.0
                            }
                        entry = self.global_flag_impact[v]
                        entry["test_count"] += 1

                        is_t_cond = evaluate_cond_for_var(effective_cond, v, True) if effective_cond else False
                        is_f_cond = evaluate_cond_for_var(effective_cond, v, False) if effective_cond else True

                        if effective_cond:
                            if is_t_cond:
                                entry["true_net_value"] = entry.get("true_net_value", 0.0) + b_net_score
                            if is_f_cond:
                                entry["false_net_value"] = entry.get("false_net_value", 0.0) + b_net_score
                        else:
                            entry["false_net_value"] = entry.get("false_net_value", 0.0) + b_net_score

                        # N5: Olumsuzlanmis kosullarda (if not has_rope: died)
                        # v=False iken kosul saglaniyor ve olum oluyorsa, v=True bu olumu onler -> HAYAT KURTARIR!
                        if b_has_death and effective_cond:
                            if is_f_cond and not is_t_cond:
                                entry["saves_life"] = True
                                entry["true_saves_life"] = True
                                entry["positive_score"] += 80.0
                            elif is_t_cond and not is_f_cond:
                                entry["false_saves_life"] = True

                        if b_has_surv:
                            entry["saves_life"] = True
                            if is_t_cond and not is_f_cond:
                                entry["true_saves_life"] = True
                            elif is_f_cond and not is_t_cond:
                                entry["false_saves_life"] = True
                            entry["positive_score"] += 80.0
                        if b_has_route:
                            if is_t_cond and not is_f_cond:
                                entry["true_enables_route"] = True
                                entry["enables_route"] = True
                            elif is_f_cond and not is_t_cond:
                                entry["false_enables_route"] = True
                            entry["positive_score"] += 35.0
                        if b_has_pts:
                            entry["positive_score"] += 15.0
                        if b_has_scenes:
                            if is_t_cond and not is_f_cond:
                                entry["true_unlocks_scenes"] = True
                                entry["unlocks_scenes"] = True
                            elif is_f_cond and not is_t_cond:
                                entry["false_unlocks_scenes"] = True
                            entry["positive_score"] += 15.0

                        # Katman 2 & Katman 5: GLOBAL_CONDITION_IMPACT_MAP esik ve tehlike kaydi (AST Compare Destegi)
                        cond_op = None
                        cond_th = None
                        try:
                            cond_tree = ast.parse(effective_cond.strip(), mode='eval')
                            for sub in ast.walk(cond_tree):
                                if isinstance(sub, ast.Compare):
                                    left_target = normalize_var_name(RenpyASTAnalyzer._resolve_target(sub.left)).lower()
                                    if left_target == v.lower():
                                        for op_node, comp in zip(sub.ops, sub.comparators):
                                            if isinstance(op_node, ast.GtE): cond_op = ">="
                                            elif isinstance(op_node, ast.Gt): cond_op = ">"
                                            elif isinstance(op_node, ast.LtE): cond_op = "<="
                                            elif isinstance(op_node, ast.Lt): cond_op = "<"
                                            elif isinstance(op_node, ast.Eq): cond_op = "=="
                                            elif isinstance(op_node, ast.NotEq): cond_op = "!="
                                            comp_val, _ = RenpyASTAnalyzer._resolve_value(comp)
                                            if comp_val is not None:
                                                cond_th = comp_val
                                            elif isinstance(comp, ast.Constant):
                                                cond_th = comp.value
                                            elif isinstance(comp, ast.Name):
                                                if comp.id == "True": cond_th = True
                                                elif comp.id == "False": cond_th = False
                                            break
                        except Exception:
                            pass

                        if cond_op is None or cond_th is None:
                            op_m = re.search(r'\b' + re.escape(v) + r'\s*(>=|<=|>|<|==|!=)\s*([0-9]+(?:\.[0-9]+)?|True|False)', effective_cond, re.IGNORECASE)
                            if op_m:
                                cond_op = op_m.group(1)
                                raw_v = op_m.group(2)
                                if raw_v.lower() == "true": cond_th = True
                                elif raw_v.lower() == "false": cond_th = False
                                else:
                                    try: cond_th = float(raw_v)
                                    except Exception: cond_th = None

                        # Bug 5: Dal içindeki gerçek karakter puanlarını çıkar
                        # Bug 5 & Fix 2: Dal icindeki puanlar aktarildi (b_real_pos, b_real_neg)

                        c_info = {
                            "file": fpath,
                            "line": idx,
                            "cond": effective_cond,
                            "var": v,
                            "op": cond_op,
                            "threshold": cond_th,
                            "has_death": b_has_death,
                            "has_surv": b_has_surv,
                            "has_route": b_has_route,
                            "has_scenes": b_has_scenes,
                            "has_pts": b_has_pts,
                            "is_else": (b_type == "else"),
                            "pos_deltas": list(b_real_pos),
                            "neg_deltas": list(b_real_neg)
                        }
                        self.global_condition_impact_map[v].append(c_info)
                        GLOBAL_CONDITION_IMPACT_MAP[v].append(c_info)

                # R4: Else dali olumle sonuclaniyorsa, bu dala dusmeyi engelleyen ONCEKI TUM bayraklar hayati kurtarir!
                if else_has_death:
                    for v in all_prior_vars:
                        if v not in self.global_flag_impact:
                            self.global_flag_impact[v] = {
                                "saves_life": False,
                                "prevents_death": False,
                                "enables_route": False,
                                "unlocks_scenes": False,
                                "positive_score": 0.0,
                                "test_count": 0,
                                "true_net_value": 0.0,
                                "false_net_value": 0.0
                            }
                        entry = self.global_flag_impact[v]
                        entry["saves_life"] = True
                        entry["positive_score"] += 80.0
                        entry["true_net_value"] = entry.get("true_net_value", 0.0) + 80.0
                        entry["false_net_value"] = entry.get("false_net_value", 0.0) - 80.0

        if log_callback:
            log_callback(f"[+] Derin Hikaye Haritasi: {len(self.global_flag_impact)} adet karar bayragi/esya, {len(self.free_roam_labels)} serbest dolasim hub'i indekslendi.")

    def is_variable_inverted(self, var_name):
        """
        Hedef Odakli Ters Polarite Cikarimi:
        Bir degisken ileride var <= esik ile odul veriyorsa veya var >= esik ile olum/ceza veriyorsa,
        o degiskenin ters polariteli (azalmasi iyi, artmasi kotu) oldugunu deterministik tespit eder.
        NOT: Gercek romantizm puanlari (*_points, *_love, *_aff) ve rota bayraklari ASLA tersine cevrilmez!
        """
        lower_v = str(var_name).lower().strip()
        # 1. Romantizm/sevgi puanları ve rota bayrakları KESİNLİKLE TERSİNE ÇEVRİLEMEZ
        if any(lower_v.endswith(suf) for suf in (
            "_points", "_point", "_pts", "_love", "_aff", "_affection",
            "_trust", "_favor", "_romance", "_like", "_liking", "_rel", "_relationship"
        )):
            return False
        if is_true_route_variable(lower_v):
            return False
        for char_k in KNOWN_CHARACTERS:
            if lower_v in (f"{char_k}points", f"{char_k}_points", f"{char_k}path", f"{char_k}_path", f"{char_k}love", f"{char_k}_love"):
                return False

        # 2. Belirlenmiş açık negatif metrikler daima terstir
        if any(neg in lower_v for neg in NEGATIVE_METRICS):
            return True
        consequences = getattr(self, "global_condition_impact_map", {}).get(lower_v, [])
        for c_inf in consequences:
            c_op = c_inf.get("op")
            has_reward = c_inf.get("has_surv") or c_inf.get("has_route") or c_inf.get("has_scenes") or c_inf.get("has_pts")
            has_penalty = c_inf.get("has_death")
            if c_op in ("<=", "<") and has_reward and not has_penalty:
                return True
            if c_op in (">=", ">") and has_penalty:
                return True
        return False

    def _record_unique(self, attr, item, keys):
        """R5: Global rapor kayıtlarını (uncertain/unreachable/unresolved/truncated/conflicting)
        yeniden analiz turlarında tekleştirir: aynı (keys) imzasına sahip kayıt zaten listede
        varsa yeni kayıt eklenmez (rapor şişmesi ve çift sayım önlemi)."""
        try:
            lst = getattr(self, attr)
            sig = tuple(repr(item.get(k)) for k in keys)
            for e in lst:
                try:
                    if tuple(repr(e.get(k)) for k in keys) == sig:
                        return
                except Exception:
                    pass
            lst.append(item)
        except Exception:
            pass

    def _is_dialogue_only_line(self, line):
        """R6 Faz 1.6: Satirin saf diyalog olup olmadigi ('luna "Hello!"' / '"Some text"').
        Kod gorunumlu satirlar ($ ..., if ..., jump, scene, vb.) daima False dondurur;
        boylece diyalog agirligi mekanizmasi kod tespitlerini etkilemez."""
        return _is_renpy_dialogue(line)

    def inspect_code_lines(self, lines, choice):
        """Kod satirlarini olum, rota kapatma, hayatta kalma, esya, serbest dolasim ve stat kazanimlari icin inceler."""
        # Share the logical-line lexer with ContractSim. Quoted/multiline
        # dialogue must not become Python/control evidence on a continuation line.
        lines = _analysis_code_lines(lines)
        boosted_chars = set()
        broken_chars = set()
        # 0. Soru / Bilgi menusu kontrolu
        is_inquiry = bool(RE_INQUIRY_CHOICE.search(choice.text))
        is_inquiry_exit = bool(RE_INQUIRY_EXIT.search(choice.text))
        choice.is_inquiry = is_inquiry
        choice.is_inquiry_exit = is_inquiry_exit

        # Choice wording can suggest a lock, but cannot establish one.
        if bool(RE_MONOGAMY_LOCK.search(choice.text)):
            choice.evidence_details.append("Guclu tahmin: Harem oyununda diger kizlari kilitleyen tekli secenek")

        # 0b. Secenek Metninde Karakter Romantizm/Etkinlik Tespiti (Rule 1: Salt metin puan uyduramaz)
        prec_spk = getattr(choice, "preceding_speaker", None)
        is_avoidance = bool(RE_AVOIDANCE_OR_REJECTION.search(choice.text))
        is_active_intervention = bool(RE_ACTIVE_INTERVENTION.search(choice.text))
        is_flirt_romance = bool(RE_FLIRT_OR_ROMANCE.search(choice.text))
        is_compassion = bool(RE_COMPASSION_OR_HELP.search(choice.text))

        # R3 & H10: Olumsuzlama tespiti (Don't leave her alone pasif/uzak durma degil aktif yardimdir)
        is_skip, skip_detail = analyze_passive_skip_intent(choice.text)
        if "reddedildi" in skip_detail or "Olumsuzlanmis" in skip_detail or "olumsuzlama" in skip_detail.lower():
            is_avoidance = False

        # Metadata olarak kaydet (tek basina puan veya secenek boyamasi yapamaz, yalnizca tie-breaker)
        choice.is_avoidance = is_avoidance
        choice.text_has_avoidance = is_avoidance
        choice.text_has_active = is_active_intervention or is_compassion
        choice.text_has_flirt = is_flirt_romance

        # Rota ret tespiti (salt metinle karakter reddetme - rota kilidi)
        if bool(RE_ROUTE_REJECTION.search(choice.text)):
            char_rej = extract_route_character("", choice.text, preceding_speaker=prec_spk)
            if char_rej:
                choice.evidence_details.append(f"Guclu tahmin: Secenek metni {char_rej} reddini ima ediyor; rota kapanisi dogrulanmadi")

        # 1. R3: Soz Dizimsel Pasif Atlama & Olumsuzlama Kontrolu
        if not getattr(choice, "is_avoidance", False):
            is_skip, skip_detail = analyze_passive_skip_intent(choice.text)
            if is_skip:
                choice.is_passive_skip = True
                choice.evidence_details.append(f"Guclu tahmin: {skip_detail}")
            else:
                choice.is_passive_skip = False
                if "reddedildi" in skip_detail or "Olumsuzlanmis" in skip_detail:
                    choice.is_active_exploration = True
                    choice.evidence_details.append("Kodla dogrulandi: Olumsuzlama tespiti (aktif yardim)")

        # Serbest dolasim metin tespiti (salt metin puani uydurmaz, sadece bayrak tutar)
        if bool(RE_ACTIVE_EXPLORATION.search(choice.text)) and not choice.is_passive_skip:
            choice.is_active_exploration = True

        # Dovus Hamlesi (Combat Mini-Game) Tespiti
        if bool(RE_COMBAT_ACTION.search(choice.text)):
            # Bug 6: Defend Victoria, Defend her, Block his number gibi sosyal hamleleri dövüşten muaf tut
            is_combat = True
            m_def = re.search(r'\b(?:defend|block|savun|engelle)\s+([a-zA-Z]+)', choice.text, re.IGNORECASE)
            if m_def:
                target_word = m_def.group(1).lower()
                if (target_word in KNOWN_CHARACTERS or
                    target_word in DYNAMIC_CHARACTERS or
                    target_word in PRONOUN_EXCLUSIONS or
                    target_word in ("his", "her", "him", "them", "number", "the", "a", "an")):
                    is_combat = False

            if is_combat:
                choice.is_combat_action = True
                choice.evidence_details.append("Guclu tahmin: Dovus hamlesi metni; basari/hasar sonucu yalniz koddan belirlenir")

        # 2. H6b & H7: Karar Agaci & Dallanma (if / elif / else) Analizi
        # Her if/elif/else zincirini kendi girinti seviyesinde tut; iç içe dallar
        # alt çağrıda tekrar incelenir. Böylece ayrı if blokları birbirine bağlanmaz.
        conditional_line_indices = set()
        i = 0
        while i < len(lines):
            head = lines[i].strip()
            if not head.startswith("if "):
                i += 1
                continue

            base_indent = len(lines[i]) - len(lines[i].lstrip())
            conditional_line_indices.add(i)
            branches = []
            current_type = "if"
            current_cond = head[3:].rstrip(":").strip()
            current_start = i + 1
            j = i + 1
            while j < len(lines):
                raw = lines[j]
                stripped = raw.strip()
                if not stripped or stripped.startswith("#"):
                    j += 1
                    continue
                indent = len(raw) - len(raw.lstrip())
                if indent < base_indent:
                    break
                if indent == base_indent:
                    if stripped.startswith("elif ") or stripped.startswith("else:") or stripped.startswith("else :"):
                        conditional_line_indices.add(j)
                        conditional_line_indices.update(range(current_start, j))
                        branches.append((current_type, current_cond, lines[current_start:j]))
                        if stripped.startswith("elif "):
                            current_type = "elif"
                            current_cond = stripped[5:].rstrip(":").strip()
                        else:
                            current_type = "else"
                            current_cond = ""
                        current_start = j + 1
                        j += 1
                        continue
                    break
                j += 1
            conditional_line_indices.update(range(current_start, j))
            branches.append((current_type, current_cond, lines[current_start:j]))

            prior_conds = []
            branch_results = []
            for branch_type, cond_expr, branch_lines in branches:
                if branch_type == "if":
                    branch = BranchPath(condition_str=cond_expr)
                    prior_conds = [cond_expr]
                elif branch_type == "elif":
                    neg_prior = " and ".join(f"not ({c})" for c in prior_conds)
                    branch = BranchPath(condition_str=f"{neg_prior} and ({cond_expr})")
                    prior_conds.append(cond_expr)
                else:
                    neg_all = " and ".join(f"not ({c})" for c in prior_conds)
                    branch = BranchPath(condition_str=neg_all, is_negated=True)

                sub_ch = RenpyChoice("", 0, "", "", "", "", "")
                self.inspect_code_lines(branch_lines, sub_ch)
                raw_d = sum(d[1] for d in sub_ch.deltas_positive) + sum(d[1] for d in sub_ch.deltas_negative)
                branch.score_delta = raw_d if (sub_ch.deltas_positive or sub_ch.deltas_negative) else sub_ch.score
                branch.deltas_positive = sub_ch.deltas_positive
                branch.deltas_negative = sub_ch.deltas_negative
                branch.is_death = sub_ch.is_death
                branch.is_survival = sub_ch.is_survival
                branch.jump_target = sub_ch.jump_target
                branch.call_target = sub_ch.call_target
                choice.branch_paths.append(branch)
                choice.conditional_branches.append(branch.to_dict())
                branch_results.append((branch, sub_ch))

            # Dallardaki kodu ana satır taramasında tekrar sayma. Alternatif
            # dalların etkileri ancak tüm yollar aynı sonucu veriyorsa kesindir.
            has_else = any(bt == "else" for bt, _, _ in branches)
            effects = []
            for branch, sub_ch in branch_results:
                effects.append((
                    tuple(sorted(sub_ch.deltas_positive)),
                    tuple(sorted(sub_ch.deltas_negative)),
                    bool(sub_ch.is_death), bool(sub_ch.is_survival),
                    sub_ch.jump_target, sub_ch.call_target,
                    tuple(sorted(sub_ch.category_scores.items())),
                    bool(sub_ch.is_route_lock), getattr(sub_ch, "route_locked_name", None),
                    tuple(sorted((k, repr(v)) for k, v in sub_ch.assigned_flags.items())),
                    bool(sub_ch.is_conflicting_branches),
                    round(float(sub_ch.score), 6),
                ))
            if not has_else:
                effects.append(((), (), False, False, None, None, 0.0))

            has_nested_conflict = any(sub_ch.is_conflicting_branches for _, sub_ch in branch_results)
            if not has_nested_conflict and effects and all(e == effects[0] for e in effects[1:]):
                common = branch_results[0][1]
                choice.score += common.score
                for category, value in common.category_scores.items():
                    choice.category_scores[category] += value
                for d in common.deltas_positive:
                    if d not in choice.deltas_positive:
                        choice.deltas_positive.append(d)
                for d in common.deltas_negative:
                    if d not in choice.deltas_negative:
                        choice.deltas_negative.append(d)
                if common.is_death:
                    choice.is_death = True
                if common.is_survival:
                    choice.is_survival = True
                if common.is_route_lock:
                    choice.is_route_lock = True
                    choice.route_locked_name = common.route_locked_name
                choice.assigned_flags.update(common.assigned_flags)
                if common.jump_target:
                    choice.jump_target = common.jump_target
                if common.call_target:
                    choice.call_target = common.call_target
            elif has_nested_conflict or len(set(effects)) > 1:
                choice.is_conflicting_branches = True
                msg = "Koşullu dallar farklı etkiler içeriyor; kesin hüküm verilmedi"
                if msg not in choice.uncertainty_reasons:
                    choice.uncertainty_reasons.append(msg)
            i = max(j, i + 1)

        # 3. Satir satir kod incelemesi ve R9 AST ayristirma
        for line_index, line in enumerate(lines):
            if line_index in conditional_line_indices:
                continue
            line_str = line.strip()
            if not line_str or line_str.startswith("#"):
                continue
            if line_str == "python:" or re.match(r'^python(?:\s+in\s+[a-zA-Z0-9_]+)?\s*:', line_str):
                continue

            if line_str.startswith(('play ', 'stop ', 'queue ', 'sound ')):
                continue

            # Olum ve motoru sonlandiran komutlar (H5a, R1, V3)
            if _is_engine_termination(line_str):
                choice.is_death = True
                choice.score += STUDIO_CONFIG["penalty_death"]
                choice.category_scores["survival"] += STUDIO_CONFIG["penalty_death"]
                choice.death_reason = "OLUM / MOTOR SONU"
                # R5 Fix: ölüm ekleme öncesi aynı (etiket, değer) çifti listeden tekrar günlanm
                if ("OLUM", STUDIO_CONFIG["penalty_death"]) not in choice.deltas_negative:
                    choice.deltas_negative.append(("OLUM", STUDIO_CONFIG["penalty_death"]))
                choice.evidence_details.append(f"Kodla dogrulandi: Motor sonlandirma ({line_str[:30]})")

            # Creampie sahnesi
            if RE_CREAMPIE_TEXT.search(line_str):
                choice.is_creampie = True
                choice.score += STUDIO_CONFIG["bonus_creampie"]
                choice.category_scores["gallery"] += STUDIO_CONFIG["bonus_creampie"]
                if ("CREAMPIE", STUDIO_CONFIG["bonus_creampie"]) not in choice.deltas_positive:
                    choice.deltas_positive.append(("CREAMPIE", STUDIO_CONFIG["bonus_creampie"]))
                choice.evidence_details.append("Kodla dogrulandi: Creampie metni")

            # H2 & M3: renpy.jump(...) ve renpy.call(...) (sabit string veya dinamik ifade)
            m_rjump_any = self.re_renpy_jump_any.match(line_str)
            if m_rjump_any and not choice.jump_target:
                arg = m_rjump_any.group(1).strip()
                if (arg.startswith('"') and arg.endswith('"')) or (arg.startswith("'") and arg.endswith("'")):
                    choice.jump_target = arg[1:-1]
                    choice.evidence_details.append(f"Kodla dogrulandi: renpy.jump({choice.jump_target})")
                else:
                    choice.dynamic_jump_unresolved = arg
                    choice.evidence_details.append(f"Dinamik hedef cozulemedi: renpy.jump({arg})")

            m_rcall_any = self.re_renpy_call_any.match(line_str)
            if m_rcall_any and not choice.call_target:
                arg = m_rcall_any.group(1).strip()
                if (arg.startswith('"') and arg.endswith('"')) or (arg.startswith("'") and arg.endswith("'")):
                    choice.call_target = arg[1:-1]
                    choice.evidence_details.append(f"Kodla dogrulandi: renpy.call({choice.call_target})")
                else:
                    choice.dynamic_jump_unresolved = arg
                    choice.evidence_details.append(f"Dinamik hedef cozulemedi: renpy.call({arg})")

            # H2 & V1: Dinamik jump expression ve call expression
            m_jexpr = self.re_jump_expr.search(line_str)
            if m_jexpr and not choice.jump_target:
                expr = m_jexpr.group(1).strip()
                choice.dynamic_jump_unresolved = expr
                choice.evidence_details.append(f"Dinamik hedef cozulemedi: jump expression {expr}")

            m_cexpr = self.re_call_expr.search(line_str)
            if m_cexpr and not choice.call_target:
                expr = m_cexpr.group(1).strip()
                choice.dynamic_jump_unresolved = expr
                choice.evidence_details.append(f"Dinamik hedef cozulemedi: call expression {expr}")

            # Call komutu tespiti (call anna_scene)
            m_call = self.re_call.search(line_str)
            if m_call and not choice.call_target and m_call.group(1).lower() != 'expression':
                choice.call_target = m_call.group(1)
                choice.evidence_details.append(f"Kodla dogrulandi: call {choice.call_target}")

            # Standart Jump
            m_jump = self.re_jump.search(line_str)
            if m_jump and not choice.jump_target and m_jump.group(1).lower() != 'expression':
                choice.jump_target = m_jump.group(1)
                jt_clean = choice.jump_target.lower()

                if RE_FATAL_LABELS.search(choice.jump_target):
                    choice.evidence_details.append(f"Guclu tahmin: Olum/son etiketi adi ({choice.jump_target}); govde sonucu ayrica incelenir")
                elif RE_SAFE_LABELS.search(choice.jump_target):
                    choice.evidence_details.append(f"Guclu tahmin: Guvenli/iyi son etiketi adi ({choice.jump_target}); govde sonucu ayrica incelenir")
                elif choice.jump_target in self.free_roam_labels or RE_ROAM_LABELS.search(jt_clean):
                    is_merge = False
                    if getattr(choice, "is_subscene", False):
                        is_merge = True
                    if hasattr(choice, "menu") and choice.menu:
                        merge_lbls = getattr(choice.menu, "merge_labels", set())
                        if choice.jump_target in merge_lbls:
                            is_merge = True
                        sib_jumps = [c.jump_target for c in choice.menu.choices if c != choice and c.jump_target]
                        if sib_jumps and all(sj == choice.jump_target for sj in sib_jumps):
                            is_merge = True
                    if not is_merge:
                        choice.is_active_exploration = True
                        choice.score += STUDIO_CONFIG["bonus_free_roam"]
                        choice.category_scores["exploration"] += STUDIO_CONFIG["bonus_free_roam"]
                        if not any("SERBEST DOLASIM" in d[0] for d in choice.deltas_positive):
                            choice.deltas_positive.append(("SERBEST DOLASIM", 25.0))

            # R9: Python AST ile atama, cagri ve islemlerin cozumu
            s_strip = line_str.strip()
            is_renpy_stmt = (
                s_strip.startswith(("jump ", "call ", "scene ", "show ", "play ", "stop ", "hide ", "pause", "with ", "label "))
                or s_strip in ("else:", "pass", "return")
                or s_strip.startswith("elif ")
                or s_strip.startswith("if ")
            )
            ast_info = None
            if not is_renpy_stmt and ("=" in s_strip or "(" in s_strip or s_strip.startswith("$") or s_strip.startswith("python:")):
                ast_info = RenpyASTAnalyzer.get_assignment_info(line_str)
                if not ast_info.get("is_ast_parsed", True):
                    err_msg = ast_info.get("parse_error") or "Bilinmeyen AST hatasi"
                    choice.unresolved_ast_expressions.append((line_str, err_msg))
                    self.ast_parse_errors.append({
                        "file": getattr(choice, "file_path", ""),
                        "line": getattr(choice, "line_num", 0) + 1,
                        "expr": line_str,
                        "error": err_msg
                    })
                    msg_ast = f"Ayrıştırılamayan AST ifadesi: {line_str}"
                    if msg_ast not in choice.evidence_details:
                        choice.evidence_details.append(msg_ast)
                    if msg_ast not in choice.uncertainty_reasons:
                        choice.uncertainty_reasons.append(msg_ast)
            if ast_info is None:
                ast_info = {
                    "is_assign": False,
                    "target": None,
                    "target_raw": None,
                    "op": "=",
                    "value": None,
                    "val_type": None,
                    "is_call": False,
                    "call_func": None,
                    "call_args": [],
                    "is_ast_parsed": True,
                    "parse_error": None
                }
            if ast_info["is_call"]:
                func_name = ast_info["call_func"]
                call_args = ast_info["call_args"]
                resolved = self.resolve_point_function_call(line_str, choice)
                if not resolved and ast_info.get("resolved_effects"):
                    # Katman 1: Interprocedural AST ile cozulen coklu fonksiyon etkileri (Multi-Effect Pipeline)
                    resolved = True
                    for eff in ast_info["resolved_effects"]:
                        t_var = eff["target"]
                        e_val = eff["value"]
                        e_op = eff["op"]
                        e_type = eff["val_type"]
                        choice.evidence_details.append(f"Fonksiyon AST analiziyle dogrulandi: {func_name} -> {t_var} ({e_op} {e_val})")
                        lower_tv = t_var.lower()
                        is_inv = any(neg in lower_tv for neg in NEGATIVE_METRICS)
                        is_curr = any(curr in lower_tv for curr in ("money", "cash", "gold", "coins", "credits", "silver", "tokens", "gems", "para", "altin"))
                        e_cat = "romance"
                        if any(k in lower_tv for k in ("zombie", "enemy", "boss", "combat", "fight", "saldiri")):
                            e_cat = "combat"
                        elif is_curr or "item" in lower_tv or "inv" in lower_tv:
                            e_cat = "items"
                        elif any(k in lower_tv for k in ("hp", "health", "life", "stamina", "surviv")):
                            e_cat = "survival"
                        elif any(k in lower_tv for k in ("galeri", "cg", "scene", "unlock", "ending")):
                            e_cat = "gallery"

                        if e_type == "bool":
                            choice.assigned_flags[t_var] = bool(e_val)
                        elif e_type == "number" and isinstance(e_val, (int, float)):
                            ef_val = float(e_val)
                            med = getattr(self, "median_delta", 1.0)
                            if STUDIO_CONFIG.get("enable_adaptive_normalization", True) and (med > 100.0 or ef_val > 150.0):
                                norm_ef = (ef_val / max(1.0, med)) * 5.0
                                norm_ef = max(-45.0, min(45.0, norm_ef))
                            else:
                                norm_ef = ef_val

                            if e_op in ("+=", "+"):
                                if is_inv:
                                    choice.score -= norm_ef
                                    choice.category_scores[e_cat] -= norm_ef
                                    choice.deltas_negative.append((f"+{t_var}", -ef_val))
                                else:
                                    choice.score += norm_ef
                                    choice.category_scores[e_cat] += norm_ef
                                    choice.deltas_positive.append((f"+{t_var}", ef_val))
                            elif e_op in ("-=", "-"):
                                if is_inv:
                                    choice.score += norm_ef
                                    choice.category_scores[e_cat] += norm_ef
                                    choice.deltas_positive.append((f"-{t_var}", ef_val))
                                else:
                                    choice.score -= norm_ef
                                    choice.category_scores[e_cat] -= norm_ef
                                    choice.deltas_negative.append((f"-{t_var}", -ef_val))
                            elif e_op == "=":
                                choice.score += norm_ef
                                choice.category_scores[e_cat] += norm_ef
                                choice.deltas_positive.append((f"{t_var} = {ef_val}", ef_val))

                            # Katman 5: Esik Yakinligi ve Dinamik Tehlike Tespiti
                            consequences = self.global_condition_impact_map.get(lower_tv, [])
                            for c_inf in consequences:
                                th_val = c_inf.get("threshold")
                                c_op = c_inf.get("op")
                                if th_val is not None and c_op in (">=", ">", "==") and e_op in ("+=", "+"):
                                    if c_inf.get("has_death"):
                                        hazard_pen = STUDIO_CONFIG.get("penalty_hazard", -40.0)
                                        choice.future_death_risk = True
                                        choice.score += hazard_pen
                                        choice.category_scores["survival"] += hazard_pen
                                        if not any("TEHLIKE" in d[0] for d in choice.deltas_negative):
                                            choice.deltas_negative.append((f"TEHLIKE: {t_var}", hazard_pen))
                                        choice.evidence_details.append(
                                            f"Dinamik tehlike tespiti: {t_var} (+{ef_val}) olum getiren esige ({c_inf['cond']}) yaklastiriyor."
                                        )
                                    elif (c_inf.get("has_surv") or c_inf.get("has_route")) and not c_inf.get("has_death"):
                                        prox_ratio = min(1.0, ef_val / max(1.0, th_val))
                                        prox_bonus = STUDIO_CONFIG.get("bonus_threshold_unlock", 15.0) * prox_ratio
                                        choice.score += prox_bonus
                                        choice.evidence_details.append(
                                            f"Esik yakinligi bonusu: {t_var} (+{ef_val}) hedef esige ({c_inf['cond']}) yaklastiriyor (+{prox_bonus:.1f})."
                                        )
                if not resolved:
                    lower_f = func_name.lower().strip() if func_name else ""
                    method_part = lower_f.split(".")[-1]
                    is_inv_container = any(k in lower_f for k in ("inventory", "items", "bag", "pack", "stash", "storage"))
                    is_item_method = (is_inv_container and method_part in ("append", "add", "remove", "pop", "extend")) or method_part in ("give_item", "add_item") or bool(RE_ITEM_GAIN.search(line_str)) or bool(RE_ITEM_OR_PURCHASE.search(line_str))
                    if is_item_method:
                        item_bonus = STUDIO_CONFIG.get("bonus_item_or_key", 25.0)
                        choice.score += item_bonus
                        choice.category_scores["items"] += item_bonus
                        m_arg = ast_info["call_args"][0] if ast_info.get("call_args") else "Item"
                        clean_item_name = str(m_arg).strip("'").strip('"') if m_arg else "Item"
                        if not any("ESYA" in d[0] for d in choice.deltas_positive):
                            choice.deltas_positive.append((f"ESYA: {clean_item_name.capitalize()}", item_bonus))
                        choice.evidence_details.append(f"Kodla dogrulandi: Envanter/Esya kazanimi ({func_name})")
                    elif not resolved and "." in lower_f:
                        parts = func_name.rsplit(".", 1)
                        obj_raw = parts[0].strip()
                        method_raw = parts[1].strip()
                        obj_lower = obj_raw.lower()
                        method_lower = method_raw.lower()
                        system_modules = ("renpy", "config", "persistent", "store", "gui", "audio", "preferences", "os", "sys", "random", "math", "time")
                        if obj_lower not in system_modules:
                            stat_keywords = ("affection", "love", "trust", "relationship", "rel", "points", "point", "stat", "stats", "romance", "affinity", "favor", "like", "friendship", "attraction", "lust", "submissiveness", "dominance", "corruption", "purity", "morality")
                            has_stat_kw = any(k in method_lower for k in stat_keywords)
                            is_decrease = any(k in method_lower for k in ("decrease", "sub", "dec", "down", "lower", "reduce", "lose", "minus", "loss", "drop"))
                            is_increase = any(k in method_lower for k in ("increase", "add", "gain", "give", "inc", "up", "raise", "boost", "plus"))
                            if has_stat_kw and (is_decrease or is_increase):
                                delta_val = 1.0
                                if ast_info.get("call_args"):
                                    try:
                                        delta_val = abs(float(ast_info["call_args"][0]))
                                    except Exception:
                                        delta_val = 1.0
                                if is_decrease:
                                    delta_val = -delta_val
                                char_name_clean = obj_raw[4:] if obj_lower.startswith("npc_") else obj_raw
                                if char_name_clean.lower().endswith(("_affection", "_love", "_points", "_rel", "_trust", "_stat", "_stats")):
                                    char_var = char_name_clean
                                else:
                                    char_var = f"{char_name_clean}_affection"
                                self.apply_variable_delta_to_choice(choice, char_var, "+=" if delta_val > 0 else "-=", abs(delta_val), f"Metot: {func_name}()")
                                choice.evidence_details.append(f"Kodla dogrulandi: OOP karakter stat degisimi ({func_name} -> {delta_val:+.1f})")
                                resolved = True
                    if not resolved and func_name and not self.is_irrelevant_call(func_name):
                        choice.dynamic_func_unresolved = True
                        if func_name not in choice.dynamic_calls_unresolved:
                            choice.dynamic_calls_unresolved.append(func_name)
                        for v in self.var_thresholds:
                            affects, rule = self.check_call_affects_variable(func_name, line_str, v)
                            if affects:
                                choice.threshold_uncertain = True
                                for op_th, th_val, _, _ in self.var_thresholds[v]:
                                    choice.unlocked_thresholds.append((
                                        f"{v} {op_th} {th_val}",
                                        f"Eşik belirsiz / Esik belirsiz: dinamik çağrı mevcut [Gereken: {th_val}]"
                                    ))
            elif ast_info["is_assign"]:
                # Fix 4: Coklu atama (Tuple) etkilerini secenege uygula
                if ast_info.get("resolved_effects"):
                    for eff in ast_info["resolved_effects"]:
                        eff_target = eff["target"]
                        eff_op = eff["op"]
                        eff_val = eff["value"]
                        eff_type = eff["val_type"]
                        if eff_type == "bool":
                            choice.assigned_flags[eff_target] = bool(eff_val)
                        elif eff_type == "number" and isinstance(eff_val, (int, float)):
                            self.apply_variable_delta_to_choice(choice, eff_target, eff_op, float(eff_val), "Coklu atama (Tuple)")
                    continue

                var_name = ast_info["target"]
                op = ast_info["op"]
                val = ast_info["value"]
                lower_v = var_name.lower()
                is_inverted = self.is_variable_inverted(var_name)
                is_currency = any(curr in lower_v for curr in ("money", "cash", "gold", "coins", "coin", "credits", "credit", "silver", "tokens", "token", "gems", "gem", "para", "altin", "eternum", "eternums", "shard", "shards", "currency", "dolar", "dollar", "dollars"))

                # Kategori belirleme (R8)
                cat = "romance"
                if any(k in lower_v for k in ("zombie", "enemy", "boss", "combat", "fight", "saldiri")):
                    cat = "combat"
                elif is_currency or "item" in lower_v or "inv" in lower_v:
                    cat = "items"
                elif any(k in lower_v for k in ("hp", "health", "life", "stamina", "surviv")):
                    cat = "survival"
                elif any(k in lower_v for k in ("galeri", "cg", "scene", "unlock", "ending")):
                    cat = "gallery"
                elif is_true_route_variable(var_name):
                    cat = "romance"

                if op == "=" and ast_info["val_type"] in ("bool", "str", "number"):
                    choice.assigned_flags[var_name] = val

                if ast_info["val_type"] == "bool":
                    val_bool = bool(val)
                    choice.assigned_flags[var_name] = val_bool
                    var_clean = var_name.split('.')[-1].lower()

                    if val_bool:
                        if var_name.startswith("persistent."):
                            choice.score += STUDIO_CONFIG["bonus_true_ending"]
                            choice.category_scores["gallery"] += STUDIO_CONFIG["bonus_true_ending"]
                            choice.deltas_positive.append((f"GALERI: {var_name}", STUDIO_CONFIG["bonus_true_ending"]))
                            choice.evidence_details.append(f"Kodla dogrulandi: Persistent galeri ({var_name})")
                        elif var_clean in ENEMY_DEATH_VARS or RE_ENEMY_DEATH_VAR_PATTERN.search(var_clean):
                            choice.is_enemy_defeat = True
                            choice.score += STUDIO_CONFIG["bonus_enemy_defeat"]
                            choice.category_scores["combat"] += STUDIO_CONFIG["bonus_enemy_defeat"]
                            choice.deltas_positive.append(("DUSMAN ELENDI", STUDIO_CONFIG["bonus_enemy_defeat"]))
                            choice.evidence_details.append(f"Kodla dogrulandi: Dusman elendi ({var_name})")
                        elif var_clean in PLAYER_DEATH_VARS or RE_PLAYER_DEATH_VAR_PATTERN.search(var_clean):
                            choice.death_reason = "OLUM"
                            if not choice.is_death:
                                choice.is_death = True
                                choice.score += STUDIO_CONFIG["penalty_death"]
                                choice.category_scores["survival"] += STUDIO_CONFIG["penalty_death"]
                                if not any("OLUM" in str(d[0]) for d in choice.deltas_negative):
                                    choice.deltas_negative.append(("OLUM", STUDIO_CONFIG["penalty_death"]))
                                ev_msg = f"Kodla dogrulandi: Oyuncu olumu ({var_name})"
                                if ev_msg not in choice.evidence_details:
                                    choice.evidence_details.append(ev_msg)
                        elif RE_CREAMPIE_VAR.search(var_clean):
                            choice.is_creampie = True
                            choice.score += STUDIO_CONFIG["bonus_creampie"]
                            choice.category_scores["gallery"] += STUDIO_CONFIG["bonus_creampie"]
                            if ("CREAMPIE", 25.0) not in choice.deltas_positive:
                                choice.deltas_positive.append(("CREAMPIE", 25.0))
                        elif RE_ITEM_OR_PURCHASE.search(var_clean) or RE_ITEM_OR_PURCHASE.search(lower_v):
                            choice.is_purchase_or_item = True
                            choice.score += STUDIO_CONFIG["bonus_item_purchase"]
                            choice.category_scores["items"] += STUDIO_CONFIG["bonus_item_purchase"]
                            item_lbl = clean_var_to_name(var_name) or "ESYA"
                            if not any("ESYA" in d[0] for d in choice.deltas_positive):
                                choice.deltas_positive.append((f"ESYA: {item_lbl}", STUDIO_CONFIG["bonus_item_purchase"]))
                            choice.evidence_details.append(f"Kodla dogrulandi: Esya / Hediye kazanimi ({var_name})")
                        elif any(r in lower_v for r in ("reject", "friendzone", "dump", "broke_up", "breakup", "dislike", "failed_date", "hates_mc", "route_lock", "route_locked", "locked_out")):
                            char_name = extract_route_character(var_name, choice.text)
                            if char_name:
                                broken_chars.add(char_name)
                            tag_name = f"ROTA KAPANIR: {char_name}" if char_name else "ROTA KAPANIR"
                            choice.deltas_negative.append((tag_name, -25.0))
                            choice.route_locked_name = char_name or "ROTA"
                            if char_name:
                                choice.deltas_positive = [d for d in choice.deltas_positive if d[0] != f"ROTA: {char_name}"]
                            if not any(str(d[0]).startswith("ROTA:") for d in choice.deltas_positive):
                                choice.is_route_lock = True
                                choice.score += STUDIO_CONFIG["penalty_route_lock"]
                                choice.category_scores["romance"] += STUDIO_CONFIG["penalty_route_lock"]
                        else:
                            if not lower_v.startswith(("quick_menu", "config", "renpy", "gui", "preferences", "persistent", "style", "window")):
                                if is_true_route_variable(var_name):
                                    char_name = extract_route_character(var_name, choice.text)
                                    if char_name:
                                        boosted_chars.add(char_name)
                                        choice.score += 5.0
                                        choice.category_scores["romance"] += 5.0
                                        choice.deltas_positive.append((f"ROTA: {char_name}", 5.0))
                                else:
                                    # Rule 1: Kodda degisken degistiginde iyi/kotu bilinmiyorsa ufak tie-breaker (+0.5 / -0.5)
                                    if getattr(choice, "text_has_flirt", False) or getattr(choice, "text_has_active", False):
                                        choice.score += 0.5
                                        choice.evidence_details.append(f"Metin tie-breaker (+0.5): {var_name}")
                                    elif getattr(choice, "text_has_avoidance", False):
                                        choice.score -= 0.5
                                        choice.evidence_details.append(f"Metin tie-breaker (-0.5): {var_name}")

                        # Katman 2: Ters Etki Haritası (Backward Consequence Indexing)
                        already_scored_future = False
                        if STUDIO_CONFIG.get("enable_global_dataflow", True):
                            consequences = self.global_condition_impact_map.get(lower_v, [])
                            for c_inf in consequences:
                                # Bug 5: True dalındaki gerçek karakter puanlarını doğrudan aktar
                                if not c_inf.get("is_else", False):
                                    for p_var, p_val in c_inf.get("pos_deltas", []):
                                        if not any(d[0] == p_var for d in choice.deltas_positive):
                                            self.apply_variable_delta_to_choice(choice, p_var, "+=", p_val, f"Gecikmeli etki: {var_name}=True")
                                    for n_var, n_val in c_inf.get("neg_deltas", []):
                                        if not any(d[0] == n_var for d in choice.deltas_negative):
                                            self.apply_variable_delta_to_choice(choice, n_var, "-=", abs(n_val), f"Gecikmeli etki: {var_name}=True")
                                c_cond = c_inf.get("cond", "")
                                if c_inf.get("is_else"):
                                    cond_true = False
                                    cond_false = True
                                else:
                                    cond_true = evaluate_cond_for_var(c_cond, var_name, True) if c_cond else True
                                    cond_false = evaluate_cond_for_var(c_cond, var_name, False) if c_cond else False
                                # N5: Olumsuzlanmis kosullarda (if not has_antidote: death) v=False olum yaratir,
                                # bu yuzden v=True bu olumu ONLER ve HAYAT KURTARIR!
                                if c_inf.get("has_death"):
                                    if cond_false and not cond_true:
                                        choice.future_life_saver = True
                                        choice.score += STUDIO_CONFIG["bonus_life_saver"]
                                        choice.category_scores["survival"] += STUDIO_CONFIG["bonus_life_saver"]
                                        if not any("HAYAT KURTARIR" in d[0] for d in choice.deltas_positive):
                                            choice.deltas_positive.append((f"HAYAT KURTARIR: {var_name}", STUDIO_CONFIG["bonus_life_saver"]))
                                        choice.future_impact_badge = "(İleride: [Hayat Kurtarır] Açar/Önler)"
                                        already_scored_future = True
                                    elif cond_true and not cond_false:
                                        choice.future_death_risk = True
                                        choice.score -= 80.0
                                        choice.category_scores["survival"] -= 80.0
                                        already_scored_future = True
                                elif cond_true and not cond_false:
                                    if c_inf.get("has_route"):
                                        choice.future_route_unlocker = True
                                        choice.score += STUDIO_CONFIG["bonus_route_unlocker"]
                                        choice.category_scores["romance"] += STUDIO_CONFIG["bonus_route_unlocker"]
                                        if not any("ROTA ACAR" in d[0] for d in choice.deltas_positive):
                                            choice.deltas_positive.append((f"ROTA ACAR: {var_name}", STUDIO_CONFIG["bonus_route_unlocker"]))
                                        choice.future_impact_badge = "(İleride: [Rota] Açar)"
                                        already_scored_future = True
                                    elif c_inf.get("has_scenes"):
                                        choice.future_scene_unlocker = True
                                        choice.score += STUDIO_CONFIG["bonus_gallery_unlock"]
                                        choice.category_scores["gallery"] += STUDIO_CONFIG["bonus_gallery_unlock"]
                                        if not any("GALERI" in d[0] for d in choice.deltas_positive):
                                            choice.deltas_positive.append((f"GALERI: {var_name}", STUDIO_CONFIG["bonus_gallery_unlock"]))
                                        choice.future_impact_badge = "(İleride: [Galeri] Açar)"
                                        already_scored_future = True
                                elif cond_false and not cond_true:
                                    if c_inf.get("has_scenes"):
                                        # v=True iken sahne engellenir / atlanir!
                                        choice.category_scores["gallery"] = max(0.0, choice.category_scores.get("gallery", 0.0) - 20.0)
                                        choice.score -= 20.0
                                        if not any("SAHNE ENGELLER" in d[0] for d in choice.deltas_negative):
                                            choice.deltas_negative.append((f"SAHNE ENGELLER: {var_name}", -20.0))
                                        already_scored_future = True

                        # Evrensel Ileriye Donuk Etki Haritasi (True) (Requirement 5: Gecikmeli Kelebek Etkisi)
                        # 3(b): global_condition_impact_map puan verdiyse ayni bayraga mukerrer puan ekleme
                        impact = self.global_flag_impact.get(lower_v)
                        if impact and not already_scored_future:
                            w_future = STUDIO_CONFIG.get("weight_future_consequence", 0.9)
                            if impact.get("true_saves_life") or (impact.get("saves_life") and not impact.get("false_saves_life")):
                                choice.future_life_saver = True
                                choice.future_consequence_score += 80.0
                                choice.score += 80.0
                                choice.category_scores["survival"] += 80.0
                                choice.deltas_positive.append((f"HAYAT KURTARIR: {var_name}", 80.0))
                                choice.future_impact_badge = "(İleride: [Hayat Kurtarır] Açar/Önler)"
                            elif impact.get("true_enables_route") or (impact.get("enables_route") and not impact.get("false_enables_route")):
                                choice.future_route_unlocker = True
                                choice.category_scores["romance"] += 35.0
                                choice.deltas_positive.append((f"ROTA ACAR: {var_name}", 35.0))
                            elif impact.get("true_unlocks_scenes") or (impact.get("unlocks_scenes") and not impact.get("false_unlocks_scenes")):
                                choice.future_scene_unlocker = True
                                choice.category_scores["gallery"] += 20.0
                                choice.deltas_positive.append((f"EKSTRA SAHNE: {var_name}", 20.0))
                            elif impact.get("false_unlocks_scenes") and not impact.get("true_unlocks_scenes"):
                                choice.category_scores["gallery"] = max(0.0, choice.category_scores.get("gallery", 0.0) - 20.0)
                                choice.score -= 20.0
                                if not any("SAHNE ENGELLER" in d[0] for d in choice.deltas_negative):
                                    choice.deltas_negative.append((f"SAHNE ENGELLER: {var_name}", -20.0))
                            elif impact.get("true_net_value", 0.0) != 0.0:
                                true_net = impact["true_net_value"]
                                future_val = true_net * w_future
                                # 3(c): Siradan kelebek etkisi puanini maksimum +3.0 ile sinirla
                                if future_val > 0:
                                    future_val = min(3.0, future_val)
                                choice.future_consequence_score += future_val
                                choice.score += future_val
                                if future_val > 0:
                                    if not any("GELECEKTE KAZANIM" in d[0] for d in choice.deltas_positive):
                                        choice.deltas_positive.append((f"GELECEKTE KAZANIM: {var_name}", future_val))
                                    choice.evidence_details.append(f"Kelebek etkisi: {var_name} ilerideki bloklarda net +{future_val:.1f} kazanım sağlar.")
                                elif future_val < 0:
                                    if not any("GELECEKTE KAYIP" in d[0] for d in choice.deltas_negative):
                                        choice.deltas_negative.append((f"GELECEKTE KAYIP: {var_name}", future_val))
                                    choice.evidence_details.append(f"Kelebek etkisi: {var_name} ilerideki bloklarda net {future_val:.1f} kayıp/tehlike yaratır.")
                    else:
                        # val_bool is False (R4 & Route Kill)
                        is_route_flag = is_true_route_variable(var_name) or any(lower_v.endswith(suf) for suf in ("path", "_path", "route", "_route"))
                        if is_route_flag:
                            c_off = extract_route_character(var_name, choice.text, preceding_speaker=getattr(choice, "preceding_speaker", None))
                            if c_off:
                                broken_chars.add(c_off)
                            tag_name = f"ROTA KAPANIR: {c_off}" if c_off else "ROTA KAPANIR"
                            choice.is_route_lock = True
                            choice.score += STUDIO_CONFIG["penalty_route_lock"]
                            choice.category_scores["romance"] += STUDIO_CONFIG["penalty_route_lock"]
                            if not any(tag_name in str(d[0]) for d in choice.deltas_negative):
                                choice.deltas_negative.append((tag_name, STUDIO_CONFIG["penalty_route_lock"]))
                            if c_off:
                                choice.deltas_positive = [d for d in choice.deltas_positive if d[0] != f"ROTA: {c_off}"]
                            choice.evidence_details.append(f"Kodla dogrulandi: Rota kapatan secenek ({var_name} = False)")

                        # Bug 5: False / else dalındaki gerçek karakter puanlarını doğrudan aktar
                        consequences = self.global_condition_impact_map.get(lower_v, [])
                        for c_inf in consequences:
                            if c_inf.get("is_else", False):
                                for p_var, p_val in c_inf.get("pos_deltas", []):
                                    if not any(d[0] == p_var for d in choice.deltas_positive):
                                        self.apply_variable_delta_to_choice(choice, p_var, "+=", p_val, f"Gecikmeli etki: {var_name}=False")
                                for n_var, n_val in c_inf.get("neg_deltas", []):
                                    if not any(d[0] == n_var for d in choice.deltas_negative):
                                        self.apply_variable_delta_to_choice(choice, n_var, "-=", abs(n_val), f"Gecikmeli etki: {var_name}=False")

                        impact = self.global_flag_impact.get(lower_v)
                        if impact:
                            w_future = STUDIO_CONFIG.get("weight_future_consequence", 0.9)
                            false_net = impact.get("false_net_value", 0.0)
                            if impact.get("saves_life") or false_net <= -80.0:
                                choice.future_death_risk = True
                                choice.future_consequence_score -= 80.0
                                choice.score -= 80.0
                                choice.category_scores["survival"] -= 80.0
                                choice.deltas_negative.append((f"GELECEKTE OLUM: {var_name}", -80.0))
                                choice.evidence_details.append(f"Kodla dogrulandi: Hayati bayrak False yapildi ({var_name} = False)")
                            elif false_net != 0.0:
                                # Rota kapatıldığında asla pozitif kelebek etkisi bonusu verilemez!
                                if is_route_flag and false_net > 0:
                                    false_net = 0.0
                                future_val = false_net * w_future
                                if future_val != 0.0:
                                    choice.future_consequence_score += future_val
                                    choice.score += future_val
                                    if future_val > 0:
                                        if not any("GELECEKTE KAZANIM" in d[0] for d in choice.deltas_positive):
                                            choice.deltas_positive.append((f"GELECEKTE KAZANIM: {var_name}=False", future_val))
                                        choice.evidence_details.append(f"Kelebek etkisi: {var_name}=False ilerideki bloklarda net +{future_val:.1f} kazanım sağlar.")
                                    elif future_val < 0:
                                        if not any("GELECEKTE KAYIP" in d[0] for d in choice.deltas_negative):
                                            choice.deltas_negative.append((f"GELECEKTE KAYIP: {var_name}=False", future_val))
                                        choice.evidence_details.append(f"Kelebek etkisi: {var_name}=False ilerideki bloklarda net {future_val:.1f} kayıp/tehlike yaratır.")
                    continue

                elif isinstance(val, (int, float)) and ast_info["val_type"] == "number" and op in ("+=", "+", "-=", "-"):
                    f_val = float(val)
                    # Katman 5: Uyarlanabilir Değişken Puanı Normalizasyonu
                    med = getattr(self, "median_delta", 1.0)
                    if STUDIO_CONFIG.get("enable_adaptive_normalization", True) and (med > 100.0 or f_val > 150.0):
                        scale_factor = max(1.0, med)
                        norm_f_val = (f_val / scale_factor) * 5.0
                        norm_f_val = max(-45.0, min(45.0, norm_f_val))
                    else:
                        norm_f_val = f_val

                    if op in ("+=", "+"):
                        c_pt_name = extract_route_character(var_name, choice.text)
                        if c_pt_name and is_real_point_metric(var_name):
                            if not is_inverted: boosted_chars.add(c_pt_name)
                            else: broken_chars.add(c_pt_name)

                        if is_currency:
                            # Requirement 3: Para/Ekonomi artışlarının toplam skora katkısını maksimum +3.0 ile sınırla
                            currency_gain = min(3.0, max(0.0, norm_f_val))
                            choice.score += currency_gain
                            choice.currency_score_gain = getattr(choice, "currency_score_gain", 0.0) + currency_gain
                            choice.category_scores["items"] += currency_gain
                            choice.deltas_positive.append((var_name, f_val))
                            choice.evidence_details.append(f"Kodla dogrulandi: Para/Ekonomi artisi ({var_name} +{f_val}, limitli katkı: +{currency_gain})")
                        elif is_inverted:
                            choice.score -= norm_f_val
                            choice.category_scores[cat] -= norm_f_val
                            choice.deltas_negative.append((f"+{var_name}", -f_val))
                            choice.evidence_details.append(f"Ters polarite: {var_name} artmasi tehlikeli esik/ceza icin NEGATIF (+{f_val})")
                        else:
                            choice.score += norm_f_val
                            choice.category_scores[cat] += norm_f_val
                            choice.deltas_positive.append((var_name, f_val))
                            choice.evidence_details.append(f"Kodla dogrulandi: {var_name} (+{f_val})")

                        # Katman 5: Esik Yakinligi ve Dinamik Tehlike Tespiti
                        consequences = self.global_condition_impact_map.get(lower_v, [])
                        for c_inf in consequences:
                            th_val = c_inf.get("threshold")
                            c_op = c_inf.get("op")
                            if th_val is not None and c_op in (">=", ">", "=="):
                                if c_inf.get("has_death"):
                                    hazard_pen = STUDIO_CONFIG.get("penalty_hazard", -40.0)
                                    choice.future_death_risk = True
                                    choice.score += hazard_pen
                                    choice.category_scores["survival"] += hazard_pen
                                    if not any("TEHLIKE" in d[0] for d in choice.deltas_negative):
                                        choice.deltas_negative.append((f"TEHLIKE: {var_name}", hazard_pen))
                                    choice.evidence_details.append(
                                        f"Dinamik tehlike tespiti: {var_name} (+{f_val}) olum getiren esige ({c_inf['cond']}) yaklastiriyor."
                                    )
                                elif (c_inf.get("has_surv") or c_inf.get("has_route")) and not c_inf.get("has_death"):
                                    prox_ratio = min(1.0, f_val / max(1.0, th_val))
                                    prox_bonus = STUDIO_CONFIG.get("bonus_threshold_unlock", 15.0) * prox_ratio
                                    choice.score += prox_bonus
                                    choice.evidence_details.append(
                                        f"Esik yakinligi bonusu: {var_name} (+{f_val}) hedef esige ({c_inf['cond']}) yaklastiriyor (+{prox_bonus:.1f})."
                                    )

                        # Q1, R6 & Y4: Kümülatif, erişilebilirlik ve mutlak atama eşik analizi
                        v_norm = normalize_var_name(var_name)
                        if v_norm in self.var_thresholds:
                            init_val = self.initial_vars.get(v_norm, 0.0)
                            if isinstance(init_val, (int, float)):
                                direct_val = init_val + f_val
                                has_dynamic = self.var_has_dynamic_addition.get(v_norm, False)
                                max_game_additions = self.max_var_additions.get(v_norm, f_val)
                                max_achievable = init_val + max_game_additions
                                for op_th, th_val, fpath_th, idx_th in self.var_thresholds[v_norm]:
                                    # Y4: Menü sonrası mutlak değer ataması ($ love = 50) kontrolü
                                    abs_assign = self.find_absolute_assignment(v_norm, choice, fpath_th, idx_th)
                                    if abs_assign is not None:
                                        if abs_assign["is_conditional"]:
                                            # Koşullu mutlak atama (if flag: love = 50)
                                            choice.threshold_uncertain = True
                                            choice.unlocked_thresholds.append((
                                                f"{v_norm} {op_th} {th_val}",
                                                f"Eşik belirsiz / Esik belirsiz: koşullu mutlak atama [Gereken: {th_val}]"
                                            ))
                                            choice.evidence_details.append(f"Koşullu mutlak atama: {v_norm} -> Eşik belirsiz")
                                            self._record_unique("uncertain_thresholds", {
                                                "file": choice.file_path, "line": choice.line_num + 1, "var": v_norm, "threshold": th_val
                                            }, ("file", "line", "var", "threshold"))
                                        else:
                                            abs_val = abs_assign["val"]
                                            is_met = False
                                            if op_th in ('>=', '>'):
                                                is_met = (abs_val >= th_val) if op_th == '>=' else (abs_val > th_val)
                                            elif op_th == '==':
                                                is_met = (abs_val == th_val)
                                            elif op_th in ('<=', '<'):
                                                is_met = (abs_val <= th_val) if op_th == '<=' else (abs_val < th_val)

                                            if is_met:
                                                # Eşik seçimden bağımsız zaten karşılanıyor! (love = 50, love = 10)
                                                choice.threshold_satisfied_independent = True
                                                choice.unlocked_thresholds.append((
                                                    f"{v_norm} {op_th} {th_val}",
                                                    f"(? Eşik seçimden bağımsız zaten karşılanıyor) [Mutlak: {abs_val:.1f}, Gereken: {th_val}]"
                                                ))
                                                choice.evidence_details.append(f"Eşik seçimden bağımsız zaten karşılanıyor: {v_norm} = {abs_val:.1f} (Gereken: {th_val})")
                                            else:
                                                # Eşik mutlak atama sonrası karşılanamıyor (love = 0)
                                                choice.is_unreachable_stat_only = True
                                                choice.unlocked_thresholds.append((
                                                    f"{v_norm} {op_th} {th_val}",
                                                    f"Katkı / Katki (+{f_val:.1f}) [Gereken: {th_val}] - Erişilemez / Erisilemez: eşiğe ulaşılamıyor [Mutlak: {abs_val:.1f}, Gereken: {th_val}]"
                                                ))
                                                choice.evidence_details.append(f"Erişilemez: eşiğe ulaşılamıyor [Mutlak: {abs_val:.1f}, Gereken: {th_val}]")
                                            self._record_unique("unreachable_thresholds", {
                                                "file": choice.file_path, "line": choice.line_num + 1, "var": v_norm, "threshold": th_val, "mutlak": abs_val
                                            }, ("file", "line", "var", "threshold"))
                                        continue

                                    if op_th in ('>=', '>'):
                                        if (direct_val >= th_val if op_th == '>=' else direct_val > th_val):
                                            choice.unlocked_thresholds.append((f"{v_norm} {op_th} {th_val}", "Eşik sağlandı; sonucu ayrıca doğrulanmalı (ödül kanıtı değil)"))
                                            choice.evidence_details.append(f"Eşik hesabı: {v_norm} {op_th} {th_val}; tek başına kazanç değildir")
                                        elif has_dynamic:
                                            choice.unlocked_thresholds.append((
                                                f"{v_norm} {op_th} {th_val}",
                                                f"Eşik belirsiz / Esik belirsiz: dinamik artış mevcut [Gereken: {th_val}]"
                                            ))
                                            choice.threshold_uncertain = True
                                            choice.evidence_details.append(f"Dinamik artis: Esik belirsiz ({v_norm} {op_th} {th_val})")
                                            self._record_unique("uncertain_thresholds", {
                                                "file": choice.file_path, "line": choice.line_num + 1, "var": v_norm, "threshold": th_val
                                            }, ("file", "line", "var", "threshold"))
                                        elif max_achievable >= th_val:
                                            choice.unlocked_thresholds.append((f"{v_norm} {op_th} {th_val}", f"Katkı / Katki (+{f_val:.1f}) [Gereken: {th_val}, bu secim {f_val:.1f} katki verir]"))
                                            choice.evidence_details.append(f"Kodla dogrulandi: Esik katkisi (Gerekli: {th_val}, Katki: +{f_val})")
                                        else:
                                            # R5 Fix: '>=' 100 durumu '>=' 10'a tamamen dahildi; tekil koşula indirildi
                                            if th_val >= 10 and max_achievable < th_val * 0.2:
                                                choice.unlocked_thresholds.append((f"{v_norm} {op_th} {th_val}", f"Katkı / Katki (+{f_val:.1f}) [Gereken: {th_val}, bu secim {f_val:.1f} katki verir] - Erişilemez / Erisilemez: eşiğe ulaşılamıyor [Gereken: {th_val}, Maks: {max_achievable:.1f}]"))
                                                choice.is_unreachable_stat_only = True
                                                self._record_unique("unreachable_thresholds", {
                                                    "file": choice.file_path, "line": choice.line_num + 1, "var": v_norm, "threshold": th_val, "max": max_achievable
                                                }, ("file", "line", "var", "threshold"))
                                            else:
                                                choice.unlocked_thresholds.append((f"{v_norm} {op_th} {th_val}", f"Katkı / Katki (+{f_val:.1f}) [Gereken: {th_val}, bu secim {f_val:.1f} katki verir]"))
                                                choice.evidence_details.append(f"Kodla dogrulandi: Esik katkisi (Gerekli: {th_val}, Katki: +{f_val})")

                    elif op in ("-=", "-"):
                        is_enemy_hp = (
                            any(k in lower_v for k in ("enemy", "boss", "zombie", "target", "foe", "rival", "opponent", "troy", "magnus", "maat", "azazel", "bandit", "beast", "monster", "villain", "thug", "dusman", "rakip")) or
                            (getattr(choice, "is_combat_action", False) and not lower_v.startswith(("mc", "player", "my_", "hero", "user")))
                        ) and any(k in lower_v for k in ("hp", "health", "life"))

                        if is_enemy_hp:
                            choice.is_enemy_defeat = True
                            choice.is_combat_success = True
                            choice.score += norm_f_val
                            choice.category_scores["combat"] += norm_f_val
                            choice.deltas_positive.append((f"DUSMAN HASAR ({var_name} -{f_val:.0f})", norm_f_val))
                            choice.evidence_details.append(f"Kodla dogrulandi: Dusmana hasar verildi ({var_name} -{f_val})")
                            continue

                        # Bug 4: Sandbox enerji / stamina / AP kaynak harcamaları deltas_negative içine ceza olarak girmez
                        is_energy_resource = any(k in lower_v for k in (
                            "energy", "stamina", "ap", "action_points", "mana", "mp", "fatigue", "hunger", "time", "enerji"
                        ))
                        if is_energy_resource:
                            choice.evidence_details.append(f"Kaynak harcaması: {var_name} (-{f_val})")
                            continue

                        if is_currency:
                            is_invest = (
                                choice.is_purchase_or_item or
                                choice.is_active_exploration or
                                len(choice.assigned_flags) > 0 or
                                choice.future_consequence_score > 0 or
                                any(RE_ITEM_OR_PURCHASE.search(l) for l in choice.block_lines) or
                                bool(RE_ITEM_OR_PURCHASE.search(choice.text)) or
                                bool(re.search(r'\b(?:buy|purchase|satın\s*al|take\s+the|al|sipariş|order|pendant|shovel|glasses|pistol)\b', choice.text, re.IGNORECASE))
                            )
                            if is_invest:
                                choice.is_purchase_or_item = True
                                if not any("SATIN ALMA" in d[0] for d in choice.deltas_positive):
                                    choice.score += STUDIO_CONFIG["bonus_item_purchase"]
                                    choice.category_scores["items"] += STUDIO_CONFIG["bonus_item_purchase"]
                                    choice.deltas_positive.append(("SATIN ALMA", STUDIO_CONFIG["bonus_item_purchase"]))
                                    choice.evidence_details.append(f"Kodla dogrulandi: Alisveris/Esya yatirimi ({var_name} -{f_val})")
                                continue
                        c_pt_name = extract_route_character(var_name, choice.text)
                        if c_pt_name and is_real_point_metric(var_name):
                            if not is_inverted: broken_chars.add(c_pt_name)
                            else: boosted_chars.add(c_pt_name)

                        if is_inverted:
                            choice.score += f_val
                            choice.category_scores[cat] += f_val
                            choice.deltas_positive.append((f"-{var_name}", f_val))
                            choice.evidence_details.append(f"Ters polarite: {var_name} azalmasi hedeflenen esik icin POZITIF (-{f_val})")
                        else:
                            choice.score -= f_val
                            choice.category_scores[cat] -= f_val
                            choice.deltas_negative.append((var_name, -f_val))
                    continue

                elif op in ("+=", "+", "*=", "formula"):
                    # Z2: Dinamik atama ve islemler (+= bonus, = x + bonus, = x * 2, = min(x + 5, 100))
                    v_norm = normalize_var_name(var_name)
                    choice.threshold_uncertain = True
                    choice.evidence_details.append(f"Dinamik islem: {var_name} ({line_str})")
                    if v_norm in self.var_thresholds:
                        for op_th, th_val, _, _ in self.var_thresholds[v_norm]:
                            choice.unlocked_thresholds.append((
                                f"{v_norm} {op_th} {th_val}",
                                f"Eşik belirsiz / Esik belirsiz: dinamik artış mevcut [Gereken: {th_val}]"
                            ))
                            self.uncertain_thresholds.append({
                                "file": choice.file_path, "line": choice.line_num + 1, "var": v_norm, "threshold": th_val
                            })
                    if is_real_point_metric(var_name) and not is_inverted:
                        choice.score += 1.0
                        choice.category_scores[cat] += 1.0
                        choice.deltas_positive.append((var_name, 1.0))
                    continue

            # renpy.notify bildirimi
            m_notify = self.re_notify.search(line_str)
            if m_notify:
                not_text = m_notify.group(1)
                m_val = re.search(r'([+-])\s*([0-9]+(?:\.[0-9]+)?)', not_text)
                if m_val:
                    sign = m_val.group(1)
                    val = float(m_val.group(2))
                    c_name = extract_route_character(not_text, choice.text)
                    target_label = c_name or "Puan"
                    if sign == "+":
                        choice.score += val
                        choice.category_scores["romance"] += val
                        choice.deltas_positive.append((target_label, val))
                    else:
                        choice.score -= val
                        choice.category_scores["romance"] -= val
                        choice.deltas_negative.append((target_label, -val))

        # 4. H1 & N3: Call Hedefini coz ve cagrilan label etkilerini tek yerde say
        if choice.call_target and choice.call_target in self.labels:
            target_fpath, line_idx = self.labels[choice.call_target]
            all_lines = self.get_file_lines(target_fpath)
            active_calls = getattr(self, '_inspect_active_calls', None)
            if active_calls is None:
                active_calls = self._inspect_active_calls = set()
            if choice.call_target in active_calls:
                c_score, c_pos, c_neg, c_death, c_surv, c_truncated = 0.0, [], [], False, False, True
            else:
                active_calls.add(choice.call_target)
                try:
                    c_score, c_pos, c_neg, c_death, c_surv, c_truncated = self.scan_downstream(choice.call_target, depth=1)
                finally:
                    active_calls.remove(choice.call_target)
            choice.score += c_score
            choice.downstream_pos.extend(c_pos)
            choice.downstream_neg.extend(c_neg)
            if c_death: choice.is_death = True
            if c_surv: choice.is_survival = True
            if c_truncated: choice.downstream_truncated = True
            # N3: Call hedefi puani choice.score icinde sayildigindan, downstream_score sifirlanir (cift sayim onlenir)
            choice.downstream_score = 0.0
            choice.evidence_details.append(f"Kodla dogrulandi: call {choice.call_target} zinciri cozumlendi ({format_point_val(c_score)})")

        # 5. Pasif secenek korumasi
        if len(choice.deltas_positive) > 0 or choice.score > 0 or choice.is_active_exploration:
            if choice.is_passive_skip:
                choice.is_passive_skip = False
                choice.deltas_negative = [d for d in choice.deltas_negative if d[0] != "ICERIK ATLAR"]

        # 5b. ROTA: tahmini deduplikasyonu (cift sayimi onle)
        for d in list(choice.deltas_positive):
            if d[0].startswith("ROTA:"):
                r_char = d[0].replace("ROTA:", "").strip().lower()
                has_concrete_pts = any(
                    (r_char in str(pos_d[0]).lower() or r_char in clean_var_to_name(str(pos_d[0])).lower())
                    for pos_d in choice.deltas_positive if not str(pos_d[0]).startswith("ROTA:")
                ) or any(
                    (r_char in str(ds[0]).lower() or r_char in clean_var_to_name(str(ds[0])).lower())
                    for ds in choice.downstream_pos
                )
                if has_concrete_pts:
                    choice.deltas_positive.remove(d)
                    choice.score -= d[1]
                    choice.category_scores["romance"] = max(0.0, choice.category_scores.get("romance", 0.0) - d[1])

        # -------------------------------------------------------------------------
        # Requirement 3: Rüşvet / İhanet Tuzağı Koruması (Bribe Trap Filter)
        # -------------------------------------------------------------------------
        has_money_gain = getattr(choice, "currency_score_gain", 0.0) > 0 or any(
            any(curr in str(d[0]).lower() for curr in ("money", "cash", "gold", "coins", "coin", "credits", "para", "altin", "dollar", "dollars"))
            for d in choice.deltas_positive
        )
        if has_money_gain:
            has_char_penalty = (
                len(broken_chars) > 0 or
                any(is_real_point_metric(d[0]) and d[1] < 0 for d in choice.deltas_negative) or
                any("ROTA KAPANIR" in str(d[0]) for d in choice.deltas_negative) or
                any(is_true_route_variable(k) and v is False for k, v in choice.assigned_flags.items())
            )
            has_danger = (
                choice.is_death or getattr(choice, "future_death_risk", False) or
                any("TEHLIKE" in str(d[0]) or "OLUM" in str(d[0]) for d in choice.deltas_negative)
            )
            if has_char_penalty or has_danger:
                choice.score -= getattr(choice, "currency_score_gain", 0.0)
                choice.currency_score_gain = 0.0
                bribe_penalty = STUDIO_CONFIG.get("penalty_bribe_trap", -60.0)
                choice.is_bribe_trap = True
                choice.evidence_level = "CODE_VERIFIED"
                choice.score += bribe_penalty
                choice.deltas_negative.append(("[⚠️ İhanet / Rüşvet Tuzağı]", bribe_penalty))
                choice.evidence_details.append("Rüşvet/İhanet Tuzağı: Para karşılığı karakter ilişkisi bozuluyor veya tehlike açılıyor!")

        # -------------------------------------------------------------------------
        # Requirement 4: AST Düzeyinde Çoklu Rota Kırıcı Tespiti (Harem / Multi-Route)
        # -------------------------------------------------------------------------
        other_broken = broken_chars - boosted_chars
        if boosted_chars and other_broken:
            choice.is_multi_route_breaker = True
            choice.broken_routes = sorted(list(other_broken))
            broken_desc = ", ".join(choice.broken_routes)
            tag = f"[⚠️ Tekli Rota Kilidi: Diğer Rotaları Kapatır ({broken_desc})]"
            choice.deltas_negative.append((tag, STUDIO_CONFIG.get("penalty_multi_route_breaker", -35.0)))
            choice.evidence_details.append(f"AST Rota Kırıcı: {', '.join(boosted_chars)} rotasını açarken {broken_desc} rotasını/puanını kapatıyor.")

    def _get_post_menu_matching_lines(self, post_lines, assigned_flags):
        matching_lines = []
        if not assigned_flags:
            return matching_lines

        in_matching_block = False
        block_indent = 0
        chain_indent = None
        chain_matched = False

        for l in post_lines:
            stripped = l.strip()
            if not stripped or stripped.startswith("#"):
                continue
            if self.re_menu.match(l) or self.re_label.match(l):
                break
            indent = len(l) - len(l.lstrip())

            if in_matching_block and indent <= block_indent:
                in_matching_block = False

            # if koşulu
            if stripped.startswith("if "):
                chain_indent = indent
                chain_matched = False
                in_matching_block = False
                cond = stripped[3:].split(":", 1)[0].strip()
                res = RenpyASTAnalyzer.evaluate_condition_ast(cond, assigned_flags)
                if res is None:
                    is_not = cond.startswith("not ")
                    v = cond[4:].strip() if is_not else cond.strip()
                    flag_val = assigned_flags.get(v)
                    if flag_val is not None:
                        res = (flag_val is True and not is_not) or (flag_val is False and is_not)

                if res is True:
                    in_matching_block = True
                    chain_matched = True
                    block_indent = indent
                continue

            # elif koşulu
            if stripped.startswith("elif ") and chain_indent is not None and indent == chain_indent:
                if chain_matched:
                    in_matching_block = False
                else:
                    cond = stripped[5:].split(":", 1)[0].strip()
                    res = RenpyASTAnalyzer.evaluate_condition_ast(cond, assigned_flags)
                    if res is None:
                        is_not = cond.startswith("not ")
                        v = cond[4:].strip() if is_not else cond.strip()
                        flag_val = assigned_flags.get(v)
                        if flag_val is not None:
                            res = (flag_val is True and not is_not) or (flag_val is False and is_not)

                    if res is True:
                        in_matching_block = True
                        chain_matched = True
                        block_indent = indent
                continue

            # else koşulu
            if (stripped.startswith("else:") or stripped.startswith("else :")) and chain_indent is not None and indent == chain_indent:
                if chain_matched:
                    in_matching_block = False
                else:
                    in_matching_block = True
                    chain_matched = True
                    block_indent = indent
                continue

            if in_matching_block:
                matching_lines.append(l)

        return matching_lines

    def _find_convergent_hop(self, fpath, menu_abs_line, visited=None):
        """R6 follow_menu_hops (Graph Solver v0.5): Verilen konumdaki menu, kardes seceneklerinin
        TUMU ayni TEK etikete `jump` yapiyor ise o etiketi dondurur (akis yakinsama → guvenli devam).
        Bileşik durumlarda (fallthrough, call, divergent efektler) None doner; boylece eski
        durdurma davranisi korunur."""
        try:
            m_obj = self.menu_lookup.get((os.path.abspath(fpath), menu_abs_line))
            if not m_obj:
                return None
            choices = [c for c in list(getattr(m_obj, "choices", [])) if c is not None]
            if not choices:
                return None
            jump_targets = set()
            for c in choices:
                jt = getattr(c, "jump_target", None)
                if not jt:
                    # fallthrough / call-only / pasif secenek var → yakinsama bilgisi yok
                    return None
                jump_targets.add(jt)
            if len(jump_targets) == 1:
                tgt = next(iter(jump_targets))
                if tgt in self.labels and tgt not in (visited or set()):
                    return tgt
        except Exception:
            pass
        return None

    def scan_downstream(self, jump_name, depth=0, visited=None, call_stack=None, branch_state_env=None, stop_labels=None, _hops_left=None):
        """
        H1, H4: ILERIYE DONUK GRAF GEZGINI:
        - Sabit derinlik ve satır kısıtları kaldırıldı (yapılandırılabilir STUDIO_CONFIG).
        - Döngüler visited kümesi ve memoization ile kesilir.
        - Limite takılırsa 'KESİLDİ' raporlanır.
        Not (R5): call_stack parametresi çağrı/Ren'Py call bağlamlarını takip etmek için
        imzada tutulsa da tarama sırasında hiç büyütülmez (yığın-modeli TAM DEĞİL).
        Geçerli model: visited kesimidir + memoization; call/return bağlamları modelde
        soyutlanmıştır, bu nedenle 'geri dönüş sonrası' akış öngörülemez (belirsiz notuyla işaretlenir).
        """
        # Rule 2 & Fix 1: Kardes seceneklerin ortak birlesme etiketine ulasildiginda taramayi EN BASTA DURDUR
        if stop_labels and jump_name in stop_labels:
            return 0.0, [], [], False, False, False

        # R6 Faz 1.5: CFG'e gore hicbir yoldan erisilemeyen etiketler taramaya girmez;
        # erisilemeyen daldan gelen yanlis "olum / icerik kaniti" boylece engellenir.
        try:
            if self.cfg_unreachable_labels and jump_name in self.cfg_unreachable_labels:
                return 0.0, [], [], False, False, False
        except Exception:
            pass

        cache_key = None
        # R6 follow_menu_hops: hop taramasi aktifken memo anahtari hop butcesini
        # kapsamadigindan bellek kapisi devre disi kalir (bayat ozet riski olmasin).
        _hops_cfg0 = self.options.get("follow_menu_hops", STUDIO_CONFIG.get("follow_menu_hops", 0))
        try:
            _hops_cfg0 = int(_hops_cfg0 or 0)
        except Exception:
            _hops_cfg0 = 0
        if not call_stack and not branch_state_env and not visited and depth == 0 and not stop_labels and _hops_cfg0 == 0:
            cache_key = jump_name
            if cache_key in getattr(self, "downstream_memo", {}):
                m_score, m_pos, m_neg, m_death, m_surv, m_truncated = self.downstream_memo[cache_key]
                return m_score, list(m_pos), list(m_neg), m_death, m_surv, m_truncated

        # R6 Faz 1.3: durumsuz yan cagrilar icin genellenmis memo (stop_labels dahil).
        # Ayni label'in ozeti farkli secimlerden defalarca yeniden taramak yerine bir kez uretilir
        # (O(choices x lines) -> O(labels)). branch_state_env'li cagrilar baglamsal oldugu icin
        # halen her seyde hesaplanir.
        _stk_frozen = frozenset(stop_labels) if stop_labels else frozenset()
        _memo_ctx_free = bool(not call_stack and branch_state_env is None and not visited and _stk_frozen and _hops_cfg0 == 0)
        if _memo_ctx_free:
            try:
                _m_entry = self.label_scan_memo.get((jump_name, _stk_frozen))
            except Exception:
                _m_entry = None
            if _m_entry is not None:
                m_score, m_pos, m_neg, m_death, m_surv, m_truncated = _m_entry
                return m_score, list(m_pos), list(m_neg), m_death, m_surv, m_truncated

        if visited is None:
            visited = set()
        if call_stack is None:
            call_stack = []

        max_depth = self.options.get("max_downstream_depth", STUDIO_CONFIG["max_downstream_depth"])
        max_lines = self.options.get("max_downstream_lines", STUDIO_CONFIG["max_downstream_lines"])

    # R6 follow_menu_hops: hop butcesi (opt-in; varsayilan 0 = eski davranis)
        try:
            _hops_left = int(_hops_left) if _hops_left is not None else _hops_cfg0
        except Exception:
            _hops_left = 0

        if depth > max_depth:
            return 0.0, [], [], False, False, True
        if not jump_name or jump_name in visited or jump_name not in self.labels:
            return 0.0, [], [], False, False, False



        visited.add(jump_name)
        target_fpath, line_idx = self.labels[jump_name]
        all_lines = self.get_file_lines(target_fpath)

        score = 0.0
        pos_deltas = []
        neg_deltas = []
        is_death = False
        is_survival = False
        is_truncated = False

        if depth == 0 and (jump_name in self.free_roam_labels or RE_ROAM_LABELS.search(jump_name.lower())):
            score += 25.0
            pos_deltas.append(("SERBEST DOLASIM", 25.0))

        if jump_name in self.day_skip_labels or RE_DAY_SKIP_LABELS.search(jump_name.lower()):
            score -= 20.0
            neg_deltas.append(("ICERIK ATLAR", -20.0))

        sub_lines = []
        scene_count = 0
        limit_count = 0
        _hop_deferred = None  # R6 follow_menu_hops: yakinsayan menu-hop hedefi

        # Katman 3: Yol Duyarlı Dal Budama (Path-Sensitive Pruning)
        skip_block_indent = None
        if_chain_satisfied = {}
        for rel_i, l in enumerate(all_lines[line_idx + 1:]):
            limit_count += 1
            if limit_count > max_lines:
                is_truncated = True
                break
            if self.re_label.match(l):
                break
            # Rule 2: Yeni bir menu: satiri gordugu anda lookahead taramasini KESIN OLARAK DURDUR.
            # R6 follow_menu_hops (opt-in): kardes seceneklerin TUMU ayni tek etikete atliyorsa
            # akis ortak noktaya yakinsar; bu durumda eskisi gibi kesi yok, tarama oradan
            # guvenle devam eder. Divergent menuler eski durdurm davranisini korur.
            if self.re_menu.match(l) or l.strip().startswith("menu:"):
                try:
                    if _hops_left > 0 and branch_state_env is None and not call_stack:
                        _hop_deferred = self._find_convergent_hop(
                            target_fpath, line_idx + 1 + rel_i, visited)
                except Exception:
                    _hop_deferred = None
                break

            curr_l_indent = len(l) - len(l.lstrip())
            line_str = l.strip()

            if skip_block_indent is not None:
                if line_str and curr_l_indent <= skip_block_indent:
                    skip_block_indent = None
                else:
                    continue

            # Unindent sirasinda daha derin zincir durumlari temizlenir
            keys_to_del = [k for k in if_chain_satisfied if k >= curr_l_indent]
            for k in keys_to_del:
                del if_chain_satisfied[k]

            if STUDIO_CONFIG.get("enable_path_sensitive_pruning", True) and branch_state_env:
                if line_str.startswith("if "):
                    cond_part = line_str[3:].split(":", 1)[0].strip()
                    res_cond = RenpyASTAnalyzer.evaluate_condition_ast(cond_part, branch_state_env)
                    if res_cond is True:
                        if_chain_satisfied[curr_l_indent] = True
                    elif res_cond is False:
                        if_chain_satisfied[curr_l_indent] = False
                        skip_block_indent = curr_l_indent
                        continue

                elif line_str.startswith("elif "):
                    if if_chain_satisfied.get(curr_l_indent, False):
                        skip_block_indent = curr_l_indent
                        continue
                    cond_part = line_str[5:].split(":", 1)[0].strip()
                    res_cond = RenpyASTAnalyzer.evaluate_condition_ast(cond_part, branch_state_env)
                    if res_cond is True:
                        if_chain_satisfied[curr_l_indent] = True
                    elif res_cond is False:
                        skip_block_indent = curr_l_indent
                        continue

                elif line_str.startswith("else:") or line_str.startswith("else :"):
                    if if_chain_satisfied.get(curr_l_indent, False):
                        skip_block_indent = curr_l_indent
                        continue

            # Durum izleme (branch_state_env mutasyon guncellemesi)
            if branch_state_env is not None:
                ast_l = RenpyASTAnalyzer.get_assignment_info(line_str)
                if ast_l.get("is_assign") and ast_l.get("target"):
                    t_name = ast_l["target"]
                    val = ast_l.get("value")
                    op = ast_l.get("op", "=")
                    if op == "=":
                        branch_state_env[t_name] = val
                    elif op in ("+=", "+") and isinstance(val, (int, float)):
                        curr = branch_state_env.get(t_name, 0.0)
                        if isinstance(curr, (int, float)):
                            branch_state_env[t_name] = curr + float(val)
                    elif op in ("-=", "-") and isinstance(val, (int, float)):
                        curr = branch_state_env.get(t_name, 0.0)
                        if isinstance(curr, (int, float)):
                            branch_state_env[t_name] = curr - float(val)

            sub_lines.append(l)
            if line_str.startswith(("show ", "scene ", "call screen ")):
                scene_count += 1
            if line_str == "return" and not call_stack:
                break

        if scene_count >= 2:
            score += 10.0
            pos_deltas.append(("EKSTRA SAHNE", 10.0))

        temp_choice = RenpyChoice("", 0, "", "", "", "", "")
        temp_choice.is_subscene = True
        self.inspect_code_lines(sub_lines, temp_choice)
        if (
            getattr(temp_choice, "is_conflicting_branches", False) or
            getattr(temp_choice, "dynamic_jump_unresolved", None) or
            getattr(temp_choice, "dynamic_func_unresolved", False) or
            bool(getattr(temp_choice, "dynamic_calls_unresolved", []))
        ):
            is_truncated = True

        score += temp_choice.score
        pos_deltas.extend(temp_choice.deltas_positive)
        neg_deltas.extend(temp_choice.deltas_negative)
        if getattr(temp_choice, "downstream_pos", None):
            pos_deltas.extend(temp_choice.downstream_pos)
        if getattr(temp_choice, "downstream_neg", None):
            neg_deltas.extend(temp_choice.downstream_neg)
        if temp_choice.is_death: is_death = True
        if temp_choice.is_survival: is_survival = True

        # H1 & H4: Recursive jump
        # Y8b fix: call için ayrı özyineleme bloğu kaldırıldı. inspect_code_lines
        # (4. adım) call hedefini zaten daha serbest koşullarla (taze visited,
        # stop_labels yok, depth=1) tarayıp sonuçları downstream_pos/neg'e ekliyor;
        # buradaki ekstra çağrı yalnızca aynı zinciri yeniden tarıyordu ve delta
        # döndürmediği sürece çalışmıyordu — yani bilgi kaybı yok, iş gürdüğü ve
        # döngülü zincirlerde tekrar çalışma riski vardı.
        # Y8a fix: branch_state_env özyinelemeye KOPYA ile verilir; aksi halde
        # alt dalın atamaları dış dict'i kirletip sonraki dalların koşul
        # budamasını (path-sensitive pruning) bozuyordu.
        if temp_choice.jump_target:
            if not (stop_labels and temp_choice.jump_target in stop_labels):
                sub_score, sub_pos, sub_neg, sub_death, sub_surv, sub_truncated = self.scan_downstream(
                    temp_choice.jump_target, depth + 1, visited.copy(), call_stack,
                    branch_state_env=(dict(branch_state_env) if branch_state_env is not None else None),
                    stop_labels=stop_labels
                )
                score += sub_score
                pos_deltas.extend(sub_pos)
                neg_deltas.extend(sub_neg)
                if sub_death: is_death = True
                if sub_surv: is_survival = True
                if sub_truncated: is_truncated = True

        # R6 follow_menu_hops v0.5: yakinsayan menu-hop ile tarama devam eder (opt-in).
        # Tum kardes seceneklerin attigi TEK ortak etikete dogru; dal ortalamasi riski yok.
        if _hop_deferred:
            try:
                h_score, h_pos, h_neg, h_death, h_surv, h_truncated = self.scan_downstream(
                    _hop_deferred, depth + 1, visited, call_stack,
                    branch_state_env=(dict(branch_state_env) if branch_state_env is not None else None),
                    stop_labels=stop_labels,
                    _hops_left=_hops_left - 1
                )
                score += h_score
                pos_deltas.extend(h_pos)
                neg_deltas.extend(h_neg)
                if h_death: is_death = True
                if h_surv: is_survival = True
                if h_truncated: is_truncated = True
            except Exception:
                pass

        if cache_key:
            if not hasattr(self, "downstream_memo"):
                self.downstream_memo = {}
            self.downstream_memo[cache_key] = (score, list(pos_deltas), list(neg_deltas), is_death, is_survival, is_truncated)

        if _memo_ctx_free:
            try:
                self.label_scan_memo[(jump_name, _stk_frozen)] = (score, list(pos_deltas), list(neg_deltas), is_death, is_survival, is_truncated)
            except Exception:
                pass

        return score, pos_deltas, neg_deltas, is_death, is_survival, is_truncated

    def format_hint(self, ch, is_positive=True, style="name_and_number"):
        """N1, N4, R7b, V1, V2, M1, M3: Tekil kacis, ham metin ve rozet uretici."""
        if style == "none":
            return ""

        arrow_prefix = "-> " if ch.is_gateway else ""
        deltas = ((ch.deltas_positive or []) + (ch.downstream_pos or [])) if is_positive else ((ch.deltas_negative or []) + (ch.downstream_neg or []))
        real_points = [(v, val) for v, val in deltas if is_real_point_metric(v)]

        cond_suffix = ""
        # 2. Kilitli Secenekler ve Kosul Ipucu (Locked Menu Choice Revealer)
        if getattr(ch, "condition", ""):
            cond_raw = ch.condition.strip()
            short_cond = (cond_raw[:27] + "...") if len(cond_raw) > 30 else cond_raw
            cond_suffix += f" [🔒 Şart: {short_cond}] (Koşullu: {short_cond})"

        # 5. Favori Karakter / Rota Odaklama (Static Analysis Focus Hint)
        focus_char = self.options.get("focus_char") or self.options.get("focus_character")
        if focus_char:
            focus_lower = str(focus_char).lower().strip()
            ch_text = getattr(ch, "text", "")
            if any(focus_lower in v.lower() for v, _ in deltas) or (ch_text and re.search(r'\b' + re.escape(focus_lower) + r'\b', ch_text, re.IGNORECASE)):
                cond_suffix = f" [Odak: {focus_char}]" + cond_suffix

        # R7b: Ic dallanma kosullari (if has_flowers: +5 else: -3)
        if getattr(ch, "conditional_branches", []):
            branch_notes = []
            for b in ch.conditional_branches:
                c_str = b.get("condition", "").strip()
                if len(c_str) > 20: c_str = c_str[:17] + "..."
                delta = b.get("score_delta", 0.0)
                if delta != 0:
                    branch_notes.append(f"{c_str}: {format_point_val(delta)}")
            if branch_notes:
                cond_suffix += f" ({', '.join(branch_notes[:2])})"
            if getattr(ch, "is_conflicting_branches", False):
                cond_suffix += " (?)"

        # M3, V1, V2: Cozulemeyen hedefler ve kesilen aramalar icin acik rozet
        if getattr(ch, "dynamic_jump_unresolved", None):
            cond_suffix += " (? Çözülemedi)"
        if getattr(ch, "downstream_truncated", False):
            cond_suffix += " (? Kesildi)"
        if getattr(ch, "has_contingent_inner", False):
            cond_suffix += " (? İç seçime bağlı)"
        # Q2 & Y4: Esik rozetleri (Secimden bagimsiz, Erisilemez veya Belirsiz)
        if getattr(ch, "threshold_satisfied_independent", False) or any("seçimden bağımsız" in str(u).lower() or "secimden bagimsiz" in str(u).lower() for u in getattr(ch, "unlocked_thresholds", [])):
            cond_suffix += " (? Eşik seçimden bağımsız zaten karşılanıyor)"
        elif getattr(ch, "is_unreachable_stat_only", False) or any("esige ulasilamiyor" in str(u).lower() or "erişilemez" in str(u).lower() for u in getattr(ch, "unlocked_thresholds", [])):
            cond_suffix += " (? Eşiğe ulaşılamıyor)"
        elif getattr(ch, "threshold_uncertain", False) or any("belirsiz" in str(u).lower() for u in getattr(ch, "unlocked_thresholds", [])):
            cond_suffix += " (? Eşik belirsiz)"
        # Q3: Fonksiyon rozeti (Yalnizca net puani bulunmayan seceneklerde gosterilir)
        if not real_points and (getattr(ch, "dynamic_func_unresolved", False) or len(getattr(ch, "dynamic_calls_unresolved", [])) > 0):
            cond_suffix += " (? Çözülemedi: fonksiyon)" 

        # Rule 4: Gelecekte/Kelebek rozetleri ipucunda gosterilmez
        pass

        if real_points:
            char_totals = {}
            char_order = []
            for var_name, val in real_points:
                char_name = clean_var_to_name(var_name)
                # M1: HAM birak, ara kacis yapma!
                if char_name not in char_totals:
                    char_totals[char_name] = 0.0
                    char_order.append(char_name)
                char_totals[char_name] += val

            # Karakter oncelikli siralama (Gercek karakterler depresyon/stres gibi statlardan once gosterilir)
            def _char_priority(cn):
                cn_low = cn.lower()
                if any(cn_low == k or cn_low in k for k in DYNAMIC_CHARACTERS):
                    return (0, cn)
                if any(cn_low == k or cn_low in k for k in KNOWN_CHARACTERS):
                    return (0, cn)
                if cn_low in ("dik", "chick"):
                    return (1, cn)
                if cn_low in ("can", "para", "altin", "guc", "zeka", "karizma", "enerji"):
                    return (2, cn)
                return (3, cn)

            char_order.sort(key=_char_priority)

            parts = []
            for char_name in char_order:
                total_val = char_totals[char_name]
                if total_val == 0:
                    continue
                num_str = format_point_val(total_val)
                if char_name:
                    parts.append(f"{arrow_prefix}{char_name} {num_str}" if style == "name_and_number" else f"{arrow_prefix}{char_name}")
                else:
                    parts.append(f"{arrow_prefix}{num_str}")

            if parts:
                return " (" + ", ".join(parts[:3]) + ")" + cond_suffix

        # Rule 4: İpucu Rozetlerini ({wt_hint}) Yapay Etiketlerden Temizle
        # deltas_positive ve deltas_negative içindeki uydurma metinler yerine somut sonuçlar:
        # (+1 Jill), (-1 Derek), (+DIK), (+CHICK), (Rota: Maya), (Eşya), (Özel Sahne), (💀 Ölüm/Kötü Son)
        if is_positive:
            if getattr(ch, "is_creampie", False):
                return " (Creampie)" + cond_suffix
            if getattr(ch, "future_life_saver", False):
                return " (Hayat Kurtarır)" + cond_suffix
            if getattr(ch, "is_purchase_or_item", False):
                return " (Eşya)" + cond_suffix
            if getattr(ch, "future_route_unlocker", False):
                r_name = getattr(ch, "unlocked_route_name", "")
                return (f" (Rota: {r_name})" if r_name else " (Rota)") + cond_suffix
            if getattr(ch, "future_scene_unlocker", False) or any(re.search(r'\b(?:scene|show)\s+(?:cg|event|hscene|anim|special|movie|gallery)_', l, re.IGNORECASE) for l in getattr(ch, "block_lines", [])):
                return " (Özel Sahne)" + cond_suffix
        else:
            if getattr(ch, "is_bribe_trap", False):
                return " [⚠️ İhanet / Rüşvet Tuzağı]" + cond_suffix
            if getattr(ch, "is_multi_route_breaker", False):
                return " [⚠️ Tekli Rota Kilidi: Diğer Rotaları Kapatır]" + cond_suffix
            if getattr(ch, "is_route_lock", False) or any(str(d[0]).startswith("ROTA KAPANIR") for d in (ch.deltas_negative or [])):
                r_name = getattr(ch, "route_locked_name", "")
                if not r_name:
                    for d in (ch.deltas_negative or []):
                        if str(d[0]).startswith("ROTA KAPANIR:"):
                            r_name = str(d[0]).split(":", 1)[1].strip()
                            break
                tag = f" (Rota Kapanır: {r_name})" if r_name else " (Rota Kapanır)"
                return tag + cond_suffix
            if ch.is_death or ch.is_downstream_death or getattr(ch, "future_death_risk", False):
                return " (💀 Ölüm/Kötü Son)" + cond_suffix

        return cond_suffix


    
    def index_interprocedural_functions(self):
        """Katman 1: Projedeki tum python bloklarini ve .py dosyalarini AST ile tarayip GLOBAL_FUNCTION_SUMMARIES uretir."""
        self.global_function_summaries.clear()
        self.global_instance_class_map.clear()
        GLOBAL_FUNCTION_SUMMARIES.clear()
        GLOBAL_INSTANCE_CLASS_MAP.clear()
        RenpyASTAnalyzer.GLOBAL_FUNCTION_SUMMARIES.clear()
        RenpyASTAnalyzer.GLOBAL_INSTANCE_CLASS_MAP.clear()

        re_py_start = re.compile(r'^\s*(?:init(?:\s+-\d+)?\s+)?python(?:\s+in\s+[a-zA-Z0-9_]+)?\s*:(?:\s*#.*)?$')
        for fpath in self.rpy_files:
            lines = self.get_file_lines(fpath)
            in_py = False
            py_indent = 0
            cur_block = []
            for l in lines:
                curr_indent = len(l) - len(l.lstrip())
                if in_py:
                    if l.strip() and curr_indent <= py_indent and not l.strip().startswith('#'):
                        code_txt = chr(10).join(cur_block)
                        s = RenpyASTAnalyzer.extract_function_summaries_from_source(code_txt, fpath)
                        self.global_function_summaries.update(s)
                        in_py = False
                        cur_block = []
                    else:
                        cur_block.append(l)
                if not in_py and re_py_start.match(l):
                    in_py = True
                    py_indent = curr_indent
                    cur_block = []

            if in_py and cur_block:
                code_txt = chr(10).join(cur_block)
                s = RenpyASTAnalyzer.extract_function_summaries_from_source(code_txt, fpath)
                self.global_function_summaries.update(s)

        # Ayrica proje dizinindeki .py dosyalarini tara
        p_dir = getattr(self, "target_dir", "") or getattr(self, "game_dir", "")
        if p_dir and os.path.exists(p_dir):
            for root, _, files in os.walk(p_dir):
                for fn in files:
                    if fn.endswith(".py"):
                        py_fp = os.path.join(root, fn)
                        try:
                            enc, _, _ = detect_file_encoding(py_fp)
                            with open(py_fp, "r", encoding=enc, errors="replace") as f_py:
                                code_txt = f_py.read()
                            s = RenpyASTAnalyzer.extract_function_summaries_from_source(code_txt, py_fp)
                            self.global_function_summaries.update(s)
                        except Exception:
                            pass

    def index_python_functions(self):
        """Q3: .rpy dosyalarindaki ve python bloklarindaki def tanimlarini AST ile ayristirarak puan fonksiyonlarini indeksler."""
        import textwrap
        self.point_functions.clear()
        for fp in self.rpy_files:
            lines = self.get_file_lines(fp)
            py_blocks = []
            in_py = False
            curr_lines = []
            for l in lines:
                if re.match(r'^\s*(?:init(?:\s+-\d+)?\s+)?python(?:\s+in\s+[a-zA-Z0-9_]+)?\s*:(?:\s*#.*)?$', l):
                    if in_py and curr_lines:
                        py_blocks.append(''.join(curr_lines))
                    in_py = True
                    curr_lines = []
                    continue
                if in_py:
                    if l.strip() and len(l) - len(l.lstrip()) == 0 and not l.strip().startswith('#'):
                        in_py = False
                        if curr_lines:
                            py_blocks.append(''.join(curr_lines))
                        curr_lines = []
                    else:
                        curr_lines.append(l)
            if in_py and curr_lines:
                py_blocks.append(''.join(curr_lines))

            for block in py_blocks:
                try:
                    dedented = textwrap.dedent(block)
                    tree = ast.parse(dedented, mode='exec')
                    for node in ast.walk(tree):
                        if isinstance(node, ast.FunctionDef):
                            self._register_ast_function(node, fp)
                except Exception:
                    pass

        # target_dir altindaki saf .py dosyalarini da tara
        if hasattr(self, 'target_dir') and self.target_dir and os.path.exists(self.target_dir):
            for root, dirs, files in os.walk(self.target_dir):
                for f in files:
                    if f.endswith('.py'):
                        py_path = os.path.join(root, f)
                        try:
                            with open(py_path, 'r', encoding='utf-8', errors='ignore') as pfp:
                                content = pfp.read()
                            tree = ast.parse(content, mode='exec')
                            for node in ast.walk(tree):
                                if isinstance(node, ast.FunctionDef):
                                    self._register_ast_function(node, py_path)
                        except Exception:
                            pass

    def _register_ast_function(self, node: ast.FunctionDef, fpath: str):
        func_name = node.name
        params = [a.arg for a in node.args.args]
        has_branches = any(isinstance(sub, (ast.If, ast.While, ast.For)) for sub in ast.walk(node))
        effects = []

        for stmt in node.body:
            if isinstance(stmt, ast.AugAssign) and isinstance(stmt.op, (ast.Add, ast.Sub)):
                target_str = RenpyASTAnalyzer._resolve_target(stmt.target)
                op = "+=" if isinstance(stmt.op, ast.Add) else "-="
                target_norm = normalize_var_name(target_str)
                
                # store.points[char] += pts
                if isinstance(stmt.target, ast.Subscript):
                    slice_node = stmt.target.slice
                    if hasattr(slice_node, 'value'):
                        slice_node = slice_node.value
                    if isinstance(slice_node, (ast.Name, ast.Constant)):
                        if isinstance(slice_node, ast.Name) and slice_node.id in params:
                            k_idx = params.index(slice_node.id)
                            if isinstance(stmt.value, ast.Name) and stmt.value.id in params:
                                v_idx = params.index(stmt.value.id)
                                effects.append({"type": "dict_subscript", "key_param_idx": k_idx, "val_param_idx": v_idx, "op": op})
                                continue

                if isinstance(stmt.value, ast.Name):
                    if stmt.value.id in params:
                        p_idx = params.index(stmt.value.id)
                        effects.append({"target": target_norm, "op": op, "type": "param_val", "param_idx": p_idx})
                elif isinstance(stmt.value, ast.Constant) and isinstance(stmt.value.value, (int, float)):
                    effects.append({"target": target_norm, "op": op, "type": "constant", "val": float(stmt.value.value)})

            elif isinstance(stmt, ast.Assign):
                if stmt.targets:
                    target_str = RenpyASTAnalyzer._resolve_target(stmt.targets[0])
                    target_norm = normalize_var_name(target_str)
                    if isinstance(stmt.value, ast.BinOp) and isinstance(stmt.value.op, (ast.Add, ast.Sub)):
                        left_name = RenpyASTAnalyzer._resolve_target(stmt.value.left)
                        if normalize_var_name(left_name) == target_norm:
                            op = "+=" if isinstance(stmt.value.op, ast.Add) else "-="
                            if isinstance(stmt.value.right, ast.Name) and stmt.value.right.id in params:
                                p_idx = params.index(stmt.value.right.id)
                                effects.append({"target": target_norm, "op": op, "type": "param_val", "param_idx": p_idx})
                            elif isinstance(stmt.value.right, ast.Constant) and isinstance(stmt.value.right.value, (int, float)):
                                effects.append({"target": target_norm, "op": op, "type": "constant", "val": float(stmt.value.right.value)})

        func_entry = {
            "name": func_name,
            "params": params,
            "effects": effects,
            "has_branches": has_branches,
            "file": fpath
        }
        self.point_functions[func_name] = func_entry
        fn_norm = normalize_var_name(func_name)
        if fn_norm:
            self.point_functions[fn_norm] = func_entry

    def resolve_point_function_call(self, line_str: str, choice) -> bool:
        """Q3: Secenek satiri icindeki fonksiyon cagrisini puan fonksiyonlari ile eslestirir."""
        stmt = RenpyASTAnalyzer.parse_statement(line_str)
        if not stmt or not stmt.body:
            return False
        first_stmt = stmt.body[0]
        if not (isinstance(first_stmt, ast.Expr) and isinstance(first_stmt.value, ast.Call)):
            return False
        call_node = first_stmt.value
        func_name = RenpyASTAnalyzer._resolve_target(call_node.func)
        func_norm = normalize_var_name(func_name)
        func_data = self.point_functions.get(func_norm) or self.point_functions.get(func_name)
        if not func_data:
            # Obje metot çağrıları: npc_victoria.add_love(2) veya victoria.add_points(1)
            if "." in func_name:
                obj_part, method_part = func_name.split(".", 1)
                method_low = method_part.lower()
                if any(k in method_low for k in ("add_love", "give_love", "add_points", "add_trust", "add_rel", "increase_love", "love_add", "add_aff")):
                    char_cand = clean_var_to_name(obj_part)
                    if char_cand:
                        target_var = f"{char_cand.lower()}_love"
                        if call_node.args:
                            val, _ = RenpyASTAnalyzer._resolve_value(call_node.args[0])
                            if isinstance(val, (int, float)):
                                self.apply_variable_delta_to_choice(choice, target_var, "+=", float(val), f"Metot: {func_name}")
                                return True
            return False

        if func_data.get("has_branches", False):
            return False

        effects = func_data.get("effects", [])
        if not effects:
            return False

        args_nodes = call_node.args
        arg_values = []
        for a in args_nodes:
            val, vtype = RenpyASTAnalyzer._resolve_value(a)
            if vtype == "name" and val not in ("True", "False"):
                # Degisken arguman
                return False
            arg_values.append(val)

        applied = False
        for eff in effects:
            eff_type = eff.get("type")
            op = eff.get("op", "+=")
            if eff_type == "param_val":
                p_idx = eff["param_idx"]
                if p_idx < len(arg_values) and isinstance(arg_values[p_idx], (int, float)):
                    f_val = float(arg_values[p_idx])
                    target_var = eff["target"]
                    self.apply_variable_delta_to_choice(choice, target_var, op, f_val, f"Fonksiyon: {func_norm}")
                    applied = True
            elif eff_type == "dict_subscript":
                k_idx = eff["key_param_idx"]
                v_idx = eff["val_param_idx"]
                if k_idx < len(arg_values) and v_idx < len(arg_values):
                    target_key = str(arg_values[k_idx]).strip('"\'')
                    if isinstance(arg_values[v_idx], (int, float)):
                        f_val = float(arg_values[v_idx])
                        self.apply_variable_delta_to_choice(choice, target_key, op, f_val, f"Fonksiyon: {func_norm}")
                        applied = True
            elif eff_type == "constant":
                f_val = eff["val"]
                target_var = eff["target"]
                self.apply_variable_delta_to_choice(choice, target_var, op, f_val, f"Fonksiyon: {func_norm}")
                applied = True

        return applied

    def apply_variable_delta_to_choice(self, choice, var_name, op, f_val, source_desc=""):
        """Degisken degisimini secenege ve esik analizine uygular."""
        var_norm = normalize_var_name(var_name)
        cat = "romance"
        lower_v = var_norm.lower()
        if any(k in lower_v for k in ("combat", "fight", "zombie", "enemy")): cat = "combat"
        elif any(k in lower_v for k in ("item", "inv", "gold", "money")): cat = "items"
        elif any(k in lower_v for k in ("hp", "health", "life", "surviv")): cat = "survival"

        # Efektif degisimi hesapla
        net_val = f_val if op in ("+=", "+") else -f_val
        if hasattr(self, "is_variable_inverted") and self.is_variable_inverted(var_norm):
            net_val = -net_val

        if net_val > 0:
            pos_mag = abs(net_val)
            choice.score += pos_mag
            choice.category_scores[cat] += pos_mag
            choice.deltas_positive.append((var_norm, pos_mag))
            choice.evidence_details.append(f"Kodla dogrulandi: {source_desc} -> {var_norm} (+{pos_mag})")
            
            # Esik kontrolu
            if var_norm in self.var_thresholds:
                init_val = self.initial_vars.get(var_norm, 0.0)
                if isinstance(init_val, (int, float)):
                    direct_val = init_val + pos_mag
                    has_dynamic = self.var_has_dynamic_addition.get(var_norm, False)
                    max_game_additions = self.max_var_additions.get(var_norm, pos_mag)
                    max_achievable = init_val + max_game_additions

                    for op_th, th_val, fpath_th, idx_th in self.var_thresholds[var_norm]:
                        abs_assign = self.find_absolute_assignment(var_norm, choice, fpath_th, idx_th)
                        if abs_assign is not None:
                            if abs_assign["is_conditional"]:
                                choice.threshold_uncertain = True
                                choice.unlocked_thresholds.append((
                                    f"{var_norm} {op_th} {th_val}",
                                    f"Eşik belirsiz / Esik belirsiz: koşullu mutlak atama [Gereken: {th_val}]"
                                ))
                                choice.evidence_details.append(f"Koşullu mutlak atama: {var_norm} -> Eşik belirsiz")
                            else:
                                abs_val = abs_assign["val"]
                                is_met = False
                                if op_th in ('>=', '>'):
                                    is_met = (abs_val >= th_val) if op_th == '>=' else (abs_val > th_val)
                                elif op_th == '==':
                                    is_met = (abs_val == th_val)
                                elif op_th in ('<=', '<'):
                                    is_met = (abs_val <= th_val) if op_th == '<=' else (abs_val < th_val)

                                if is_met:
                                    choice.threshold_satisfied_independent = True
                                    choice.unlocked_thresholds.append((
                                        f"{var_norm} {op_th} {th_val}",
                                        f"(? Eşik seçimden bağımsız zaten karşılanıyor) [Mutlak: {abs_val:.1f}, Gereken: {th_val}]"
                                    ))
                                    choice.evidence_details.append(f"Eşik seçimden bağımsız zaten karşılanıyor: {var_norm} = {abs_val:.1f} (Gereken: {th_val})")
                                else:
                                    choice.is_unreachable_stat_only = True
                                    choice.unlocked_thresholds.append((
                                        f"{var_norm} {op_th} {th_val}",
                                        f"Katkı / Katki (+{pos_mag:.1f}) [Gereken: {th_val}] - Erişilemez / Erisilemez: eşiğe ulaşılamıyor [Mutlak: {abs_val:.1f}, Gereken: {th_val}]"
                                    ))
                                    choice.evidence_details.append(f"Erişilemez: eşiğe ulaşılamıyor [Mutlak: {abs_val:.1f}, Gereken: {th_val}]")
                            continue

                        if op_th in ('>=', '>'):
                            if (direct_val >= th_val if op_th == '>=' else direct_val > th_val):
                                choice.unlocked_thresholds.append((f"{var_norm} {op_th} {th_val}", "Eşik sağlandı; sonucu ayrıca doğrulanmalı (ödül kanıtı değil)"))
                            elif has_dynamic:
                                choice.unlocked_thresholds.append((
                                    f"{var_norm} {op_th} {th_val}",
                                    f"Eşik belirsiz / Esik belirsiz: dinamik artış mevcut [Gereken: {th_val}]"
                                ))
                                choice.threshold_uncertain = True
                            elif max_achievable >= th_val:
                                choice.unlocked_thresholds.append((
                                    f"{var_norm} {op_th} {th_val}",
                                    f"Katkı / Katki (+{pos_mag:.1f}) [Gereken: {th_val}, bu secim {pos_mag:.1f} katki verir]"
                                ))
                            else:
                                # R5 Fix: '>=' 100 durumu '>=' 10'a tamamen dahildi; tekil koşula indirildi
                                if th_val >= 10 and max_achievable < th_val * 0.2:
                                    choice.unlocked_thresholds.append((
                                        f"{var_norm} {op_th} {th_val}",
                                        f"Katkı / Katki (+{pos_mag:.1f}) [Gereken: {th_val}, bu secim {pos_mag:.1f} katki verir] - Erişilemez / Erisilemez: eşiğe ulaşılamıyor [Gereken: {th_val}, Maks: {max_achievable:.1f}]"
                                    ))
                                    choice.is_unreachable_stat_only = True
                                    self._record_unique("unreachable_thresholds", {
                                        "file": choice.file_path, "line": choice.line_num + 1, "var": var_norm, "threshold": th_val, "max": max_achievable
                                    }, ("file", "line", "var", "threshold"))
                                else:
                                    choice.unlocked_thresholds.append((
                                        f"{var_norm} {op_th} {th_val}",
                                        f"Katkı / Katki (+{pos_mag:.1f}) [Gereken: {th_val}, bu secim {pos_mag:.1f} katki verir]"
                                    ))
        elif net_val < 0:
            # Bug 4: Sandbox enerji / stamina / AP harcamaları ceza olarak sayılmaz
            is_energy_resource = any(k in lower_v for k in (
                "energy", "stamina", "ap", "action_points", "mana", "mp", "fatigue", "hunger", "time", "enerji"
            ))
            if is_energy_resource:
                choice.evidence_details.append(f"Kaynak harcaması: {var_norm} (-{abs(net_val)})")
                return

            neg_mag = abs(net_val)
            choice.score -= neg_mag
            choice.category_scores[cat] -= neg_mag
            choice.deltas_negative.append((var_norm, -neg_mag))
            choice.evidence_details.append(f"Kodla dogrulandi: {source_desc} -> {var_norm} (-{neg_mag})")

    def find_absolute_assignment(self, v_norm: str, choice, fpath_th: str, idx_th: int):
        """
        Y4: Menü ile eşik (idx_th) arasındaki mutlak değer atamasını ($ love = 50, love = 0) tespit eder.
        """
        v_norm = normalize_var_name(v_norm)
        last_assign = None
        # 1. Aynı dosyada ise menü sonu ile eşik arasındaki satırları tara
        if choice and hasattr(choice, "menu") and choice.menu:
            menu_end = choice.menu.end_line_num
            ch_fpath = choice.file_path
            if ch_fpath == fpath_th and idx_th > menu_end:
                flines = self.get_file_lines(ch_fpath)
                for l_idx in range(menu_end, min(idx_th, len(flines))):
                    raw_l = flines[l_idx]
                    l_str = raw_l.strip()
                    if not l_str or l_str.startswith("#"):
                        continue
                    ast_info = RenpyASTAnalyzer.get_assignment_info(l_str)
                    if ast_info["is_assign"] and ast_info["target"]:
                        if normalize_var_name(ast_info["target"]) == v_norm and ast_info["op"] == "=":
                            if ast_info["val_type"] == "number" and isinstance(ast_info["value"], (int, float)):
                                is_cond = l_str.startswith("if ") or (" if " in l_str)
                                if not is_cond:
                                    indent_lvl = len(raw_l) - len(raw_l.lstrip())
                                    for up_i in range(l_idx - 1, menu_end - 1, -1):
                                        up_str = flines[up_i].strip()
                                        if not up_str or up_str.startswith("#"):
                                            continue
                                        up_indent = len(flines[up_i]) - len(flines[up_i].lstrip())
                                        if up_indent < indent_lvl:
                                            if up_str.startswith(("if ", "elif ", "else:")):
                                                is_cond = True
                                                break
                                            if up_str.startswith(("label ", "menu:")):
                                                break
                                last_assign = {
                                    "val": float(ast_info["value"]),
                                    "is_conditional": is_cond,
                                    "cond": l_str if is_cond else "",
                                    "line": l_idx
                                }
                if last_assign is not None:
                    return last_assign

        # 2. İndekslenmiş mutlak atamalardan ara
        if v_norm in self.var_absolute_assignments:
            candidates = []
            for item in self.var_absolute_assignments[v_norm]:
                if item["file"] == fpath_th and item["line"] < idx_th:
                    if choice and hasattr(choice, "menu") and choice.menu and choice.file_path == fpath_th:
                        if item["line"] <= choice.menu.end_line_num:
                            continue
                    candidates.append(item)
            if candidates:
                candidates.sort(key=lambda x: x["line"])
                return candidates[-1]

        return None

    _IRRELEVANT_PREFIXES = (
        "renpy.notify", "renpy.pause", "renpy.say", "renpy.show", "renpy.hide",
        "renpy.scene", "renpy.with_statement", "renpy.transition", "renpy.movie_cutscene",
        "renpy.music.", "renpy.sound.", "renpy.play", "renpy.stop", "renpy.save",
        "renpy.load", "renpy.take_screenshot", "renpy.restart_interaction",
        "renpy.checkpoint", "renpy.retain_after_load", "renpy.block_rollback",
        "renpy.full_restart", "gui.", "config.", "preferences.", "print", "len",
        "str", "int", "float", "bool", "round"
    )
    _irrelevant_cache = {}

    def is_irrelevant_call(self, func_name: str) -> bool:
        """Z1: Degisken veya oyun durumunu degistirmeyen ilgisiz Ren'Py/Python cagrilari.
        Not (R5): envanter/'esya' mutasyon cagrilari (append/add/remove vb.) burada 'irrelevant'
        isaretlenir; esya-kazanc bilgisi ayri metodlar (inspect_code_lines / apply_variable_delta
        esya dallari) tarafindan ele alir. Boylece ayni esya TIPLI durumu hem burada hem kural
        motorda iki kez sayilmaz; bu metodun adi tum mutasyonlar icin 'false' dondurmeyi gerekmez.
        """
        if not func_name:
            return True
        lower_f = func_name.lower().strip()
        cached = self._irrelevant_cache.get(lower_f)
        if cached is not None:
            return cached
        method_part = lower_f.split(".")[-1]
        is_inv_container = any(k in lower_f for k in ("inventory", "items", "bag", "pack", "stash", "storage"))
        if (is_inv_container and method_part in ("append", "add", "remove", "pop", "extend")) or method_part in ("give_item", "add_item"):
            self._irrelevant_cache[lower_f] = True
            return True
        res = any(lower_f.startswith(name) if name.endswith('.') else lower_f == name
                  for name in self._IRRELEVANT_PREFIXES)
        self._irrelevant_cache[lower_f] = res
        return res

    def check_call_affects_variable(self, func_name: str, line_str: str, var_name: str) -> tuple:
        """
        Z1: Cozulemeyen bir cagrinin bu degiskeni (var_name) etkileyip etkilemeyecegini belirler.
        Siki Kural: Dogrudan degisken adini, store'u veya bu nesne metodunu referans alan cagrilari baglar.
        Gevsek Kural: Projede govdesi bulunmayan saf kullanici fonksiyonlari Ren'Py'de store uzerinde calistigindan
                     tum aktif esik degiskenleri icin bilinmiyor/belirsiz sayilir.
        """
        if self.is_irrelevant_call(func_name):
            return False, "irrelevant"

        v_clean = var_name.lower().strip()
        lower_f = func_name.lower().strip()
        lower_line = line_str.lower()

        # 1. SIKI KURAL:
        # a) Fonksiyon veya metot adinda degisken adi geciyor mu? (orn: npc.add_love(), give_love_bonus())
        has_var_in_func = (v_clean in lower_f.split('.')[-1]) or (f"_{v_clean}" in lower_f) or (f"{v_clean}_" in lower_f)
        # b) Satir veya argumanlarda degisken adi geciyor mu? (orn: add_pts("love", 5))
        has_var_in_args = bool(re.search(r'\b' + re.escape(v_clean) + r'\b', lower_line))
        # c) 'store' veya 'renpy.store' erisimi var mi? (orn: store.update(), renpy.store.bonus())
        has_store = ("store." in lower_f) or ("renpy.store." in lower_f) or ("store." in lower_line)

        if has_var_in_func or has_var_in_args or has_store:
            return True, "strict"

        # 2. GEVSEK KURAL:
        # Tanimlanmamis, dahili/renpy disi saf bir kullanici fonksiyonu ($ give_bonus(), $ level_up())
        if not lower_f.startswith("renpy.") and not lower_f.startswith("gui.") and "." not in lower_f:
            return True, "relaxed"

        # renpy.* cagrisi ama alakasiz listesinde degilse (orn: renpy.call_in_new_context, renpy.run)
        if lower_f.startswith("renpy.") and lower_f not in ("renpy.jump", "renpy.call"):
            return True, "relaxed_renpy"

        return False, "none"

    def parse_lint_output(self, lint_out: str) -> list:
        return parse_lint_output(lint_out)

    def run_lint_baseline(self, log_callback=None):
        """Y2 & V1: Yama uygulanmadan önce tek seferlik temel çizgi (baseline) lint'ini çalıştırır."""
        if not self.options.get("verify_with_renpy_lint", False):
            return
        timeout = self.options.get("renpy_lint_timeout", 180)
        renpy_exe = self.options.get("renpy_executable")
        if log_callback:
            try: log_callback("[*] Y2: Yama öncesi temel çizgi (baseline) lint'i çalıştırılıyor...")
            except Exception: pass
        res = run_renpy_lint(self.game_dir, renpy_exe, timeout=timeout)
        if len(res) == 3:
            ok_lint, out, timed_out = res
        else:
            ok_lint, out = res
            timed_out = False

        self.baseline_lint_output = out
        parsed = self.parse_lint_output(out)
        self.baseline_lint_issues = parsed
        self.baseline_unattributed_errors = getattr(parsed, "unattributed_errors", [])

        # R5 Fix: baseline sonucu kullaniciya raporlanir (bkz. eski kod: sessiz calisiyordu,
        # baseline olayi log akisinda gorunmuyordu).
        if log_callback:
            try:
                n_issues = len(parsed) if parsed is not None else 0
                n_unatt = len(getattr(parsed, "unattributed_errors", []) or [])
                if timed_out:
                    log_callback("[!] Baseline lint zaman asimina ugradi; temel çizgi kaydi tam olmayabilir.")
                elif n_issues or n_unatt:
                    log_callback(f"[*] Baseline lint tamamlandi: temel çizgide {n_issues} dosya-spesifik ve {n_unatt} genel sorun mevcut (yalnizca YENILER raporlanacak).")
                else:
                    log_callback("[+] Baseline lint tamamlandi: temel çizgi temiz.")
            except Exception:
                pass

    def verify_project_lint(self, patched_files: list) -> LintVerificationResult:
        """
        Z3, Y1, Y2, Y3, V1: Tüm yamalanan dosyalar için tek seferde Ren'Py lint çalıştırır.
        - V1: Yalnızca yeni sorunlara göre karar verir; çıkış kodu 1 olsa bile yeni sorun yoksa yamayı korur.
        - V1: İstatistik/özet satırlarını ve satır kaymalarını tolere eder.
        - V1: Tutarsızlıkları (kod 1 / hata yok veya kod 0 / hata var) tespit edip raporlar.
        - V1: Dosyaya atfedilemeyen genel hata durumunda yalnızca yeni satırları neden olarak raporlar.
        """
        if not self.options.get("verify_with_renpy_lint", False):
            return LintVerificationResult(True)

        if not patched_files:
            return LintVerificationResult(True)

        timeout = self.options.get("renpy_lint_timeout", 180)
        file_count = len(self.rpy_files) if hasattr(self, "rpy_files") and self.rpy_files else len(patched_files)
        if file_count > 30 and timeout in (60, 180):
            adapted_timeout = max(timeout, min(360, 60 + file_count * 2))
            if adapted_timeout > timeout:
                timeout = adapted_timeout
                if self.log_callback:
                    self.log_callback(f"[*] Büyük proje tespit edildi ({file_count} script dosyası). Lint zaman aşımı {timeout} saniyeye uyarlandı.")

        renpy_exe = self.options.get("renpy_executable")
        res = run_renpy_lint(self.game_dir, renpy_exe, timeout=timeout)
        if len(res) == 3:
            ok_lint, lint_out, timed_out = res
        else:
            ok_lint, lint_out = res
            timed_out = False

        self.last_lint_output = lint_out

        if "bulunamadi" in lint_out.lower():
            if self.log_callback:
                self.log_callback("[!] BILGI / UYARI: Ren'Py calistirilabilir dosyasi bulunamadi. Lint atlandi; dahili AST ve sozluk dogrulamasi gecerli.")
            return LintVerificationResult(True)

        if timed_out:
            if self.log_callback:
                self.log_callback(f"[!] UYARI: Ren'Py lint zaman asimina ugradi ({timeout}s). Yama geri alinmadi, dahili AST/parantez dogrulamasi gecerli.")
            return LintVerificationResult(True)

        # Lint çıktısını satır satır ayrıştır (Y1 & V1)
        post_issues = self.parse_lint_output(lint_out)
        baseline_issues = getattr(self, "baseline_lint_issues", [])
        baseline_unatt = getattr(self, "baseline_unattributed_errors", [])

        # V1 (4): Çıkış kodu ile çıktı arasındaki tutarsızlıkları değerlendir
        has_real_error_kw = any(
            is_error_keyword_line(l)
            for l in lint_out.splitlines() if not is_lint_ignorable_line(l)
        )

        if not ok_lint and not has_real_error_kw and not post_issues and not post_issues.unattributed_errors:
            if self.log_callback:
                self.log_callback("[!] TUTARSIZLIK TESPİT EDİLDİ: Lint çıkış kodu 1 (başarısız) olmasına rağmen hata satırı bulunamadı.")
        elif ok_lint and has_real_error_kw:
            if self.log_callback:
                self.log_callback("[!] TUTARSIZLIK TESPİT EDİLDİ: Lint çıkış kodu 0 (başarılı) olmasına rağmen hata satırları içeriyor.")

        # V1 (1): Sadece YENİ dosya-spesifik sorunları ayıkla
        new_file_issues = []
        for pi in post_issues:
            is_old = any(pi.matches_baseline(bi) for bi in baseline_issues)
            if not is_old:
                new_file_issues.append(pi)

        # V1 (2): Sadece YENİ dosyaya atfedilemeyen genel hataları ayıkla
        def _norm_unatt(text):
            c = re.sub(r'\b\d+[\d,\.]*\b', '#NUM#', text.strip().lower())
            return " ".join(c.split())

        base_unatt_norm = {_norm_unatt(u) for u in baseline_unatt}
        new_unattributed_errors = [
            ue for ue in post_issues.unattributed_errors
            if _norm_unatt(ue) not in base_unatt_norm
        ]

        # V1 (1): Yeni sorun yoksa (ve temel çizgi varsa veya kod 0 ise) çıkış kodundan ve byte eşitliğinden bağımsız olarak yamayı KORU!
        has_baseline = getattr(self, "baseline_lint_output", None) is not None
        if not new_file_issues and not new_unattributed_errors and (has_baseline or ok_lint):
            if self.log_callback:
                if not ok_lint:
                    self.log_callback("[ℹ] V1: Lint çıkış kodu başarısız olsa da temel çizgidekiyle aynı sorun kümesi; yeni hata yok, yama korundu.")
                elif baseline_issues:
                    self.log_callback(f"[ℹ] Y2: Temel çizgide mevcut {len(baseline_issues)} lint uyarısı korundu; yama yeni hata üretmedi.")
                else:
                    self.log_callback("[+] Ren'Py lint projesi basariyla dogrulandi.")
            return LintVerificationResult(True)

        # Y1: Sorumlu dosyaları tam eşleşmeyle bul
        responsible_files = set()
        rollback_reasons = {}
        for ni in new_file_issues:
            for pf in patched_files:
                if is_same_renpy_file(ni.file_path, pf, self.game_dir):
                    responsible_files.add(pf)
                    rollback_reasons[pf] = ni.raw_line or ni.message

        # V1 (2): "Tüm dosyaları geri al" yedek davranışı
        # 1. Yeni atfedilemeyen sorun varken ve yeni dosya-spesifik sorun yokken devreye girer
        # 2. Veya temel çizgi çalıştırılmamışken ve lint başarısızken devreye girer
        if not responsible_files and (new_unattributed_errors or (not ok_lint and not has_baseline)):
            combined_reason = "\n".join(new_unattributed_errors) if new_unattributed_errors else lint_out.strip()
            for pf in patched_files:
                responsible_files.add(pf)
                rollback_reasons[pf] = combined_reason
            if self.log_callback:
                self.log_callback(f"[!] LINT HATASI: Ren'Py lint basarisiz.\nNeden:\n{combined_reason}")

        # Eğer yeni dosya-spesifik sorunlar var ama hiçbiri yamalanan dosyalara ait değilse (dış dosya)
        if not responsible_files:
            if self.log_callback:
                self.log_callback("[ℹ] V1: Yeni lint uyarısı yamalanan dosyalar dışında; yama korundu.")
            return LintVerificationResult(True)

        if self.log_callback and responsible_files and not new_unattributed_errors and not (not ok_lint and not has_baseline):
            self.log_callback(f"""[!] LINT HATASI: Ren'Py lint basarisiz.\nLint Ciktisi:\n{lint_out}""")

        rolled_back = []
        for rf in responsible_files:
            bak_path = rf + ".wtbak"
            if os.path.exists(bak_path):
                shutil.copy2(bak_path, rf)
                # R5 Fix: geri alinan dosyanin onbellegi tazelensin (eski icerik kullanilmasin)
                try: self.file_cache.pop(rf, None)
                except Exception: pass
                rolled_back.append(rf)
                # Y3: .rpyc tutarlılığı
                rpyc_p = rf + "c"
                rpyc_bak = rpyc_p + ".wtbak"
                if os.path.exists(rpyc_bak):
                    try: shutil.copy2(rpyc_bak, rpyc_p)
                    except Exception: pass
                elif os.path.exists(rpyc_p):
                    try: os.remove(rpyc_p)
                    except Exception: pass
                if self.log_callback:
                    self.log_callback(f"[!] Sorumlu dosya .wtbak yedeginden geri alindi: {os.path.basename(rf)} (Neden: {rollback_reasons.get(rf, 'Lint hatasi')})")

        self.last_rolled_back_files = rolled_back
        self.last_rollback_reasons = rollback_reasons
        return LintVerificationResult(False, rolled_back, rollback_reasons, new_file_issues)
    def analyze_file_menus(self, fpath):
        """H3, H6c, K3: .rpy dosyasindaki menu ve screen seceneklerini okur; Python blok ve string'lerini dislar."""
        lines = self.get_file_lines(fpath)
        if is_system_ui_screen(fpath, ""):
            return lines, []
        menus = []
        stack = []

        current_label = None
        current_screen = None
        current_screen_menu = None

        in_py_block = False
        py_block_indent = 0
        in_triple = None
        re_py_start = re.compile(r'^\s*(?:init(?:\s+-\d+)?\s+)?python(?:\s+in\s+[a-zA-Z0-9_]+)?\s*:(?:\s*#.*)?$')

        for line_num, line in enumerate(lines):
            curr_indent = len(line) - len(line.lstrip())
            line_clean = line.strip()

            if in_py_block:
                if line_clean and curr_indent <= py_block_indent and not line_clean.startswith("#") and in_triple is None:
                    in_py_block = False

            if not in_py_block and re_py_start.match(line):
                in_py_block = True
                py_block_indent = curr_indent

            i = 0
            while i < len(line):
                if in_triple:
                    if line[i:i+3] == in_triple:
                        in_triple = None
                        i += 3
                        continue
                    i += 1
                else:
                    if line[i:i+3] in ('"""', "'''"):
                        in_triple = line[i:i+3]
                        i += 3
                        continue
                    i += 1

            # Fix 1: Eğer stack doluysa (menü seçeneği içindeysek ve py_block_indent > stack[-1][0].indent ise),
            # python bloğu satırlarını atlama, seçeneğin block_lines listesine ekle!
            is_choice_py_block = in_py_block and stack and stack[-1][1] and py_block_indent > stack[-1][0].indent
            if (in_py_block and not is_choice_py_block) or in_triple:
                continue

            m_lbl = self.re_label.match(line)
            if m_lbl:
                current_label = m_lbl.group(1)

            m_scr = self.re_screen.match(line)
            if m_scr:
                current_screen = m_scr.group(1)
                if is_system_ui_screen(fpath, current_screen):
                    current_screen_menu = None
                    current_screen = None
                    continue
                current_screen_menu = RenpyMenu(fpath, line_num, curr_indent, is_screen=True, screen_name=current_screen)
                menus.append(current_screen_menu)
                continue

            if current_screen_menu:
                if curr_indent == 0 and line.strip() and not line.strip().startswith("#"):
                    current_screen_menu = None
                    current_screen = None
                else:
                    # Katman 6: Screen icinde timer tespiti
                    m_timer = re.search(r'\btimer\s+([0-9.]+)\s+action\s+(.*)', line, re.IGNORECASE)
                    if m_timer:
                        current_screen_menu.has_qte_timer = True
                        t_acts = RenpyASTAnalyzer.parse_screen_actions(m_timer.group(2).strip())
                        for ta in t_acts:
                            if ta.get("action") == "Jump":
                                current_screen_menu.qte_trap_target = ta.get("target")

                    # Katman 4: textbutton, imagebutton, hotspot eylemlerini AST ile coz
                    m_btn = self.re_textbutton.search(line)
                    m_imgbtn = re.search(r'\bimagebutton\b.*?\baction\s+(.*)', line, re.IGNORECASE) if not m_btn else None
                    m_hspot = re.search(r'\bhotspot\s*\([^)]+\)\s+action\s+(.*)', line, re.IGNORECASE) if not m_btn and not m_imgbtn else None

                    if m_btn or m_imgbtn or m_hspot:
                        if m_btn:
                            btn_quote = m_btn.group(2)
                            btn_text = m_btn.group(3)
                            btn_action = m_btn.group(4).strip()
                        elif m_imgbtn:
                            btn_quote = '"'
                            btn_text = "ImageButton"
                            btn_action = m_imgbtn.group(1).strip()
                        else:
                            btn_quote = '"'
                            btn_text = "Hotspot"
                            btn_action = m_hspot.group(1).strip()

                        choice_obj = RenpyChoice(fpath, line_num, "    ", btn_quote, btn_text, "", line)
                        choice_obj.menu = current_screen_menu

                        # Katman 4: parse_screen_actions
                        actions = RenpyASTAnalyzer.parse_screen_actions(btn_action)
                        if actions:
                            for act in actions:
                                act_type = act.get("action")
                                if act_type == "Jump":
                                    choice_obj.jump_target = act.get("target")
                                elif act_type == "Call":
                                    choice_obj.call_target = act.get("target")
                                elif act_type in ("SetVariable", "SetField", "SetDict"):
                                    tgt = act.get("target")
                                    v = act.get("val")
                                    if act.get("obj") == "persistent" or (tgt and str(tgt).startswith("persistent.")):
                                        continue
                                    if isinstance(v, bool):
                                        choice_obj.assigned_flags[tgt] = v
                                    elif act_type in ("SetField", "SetDict") and isinstance(v, (int, float)) and v > 0:
                                        choice_obj.block_lines.append(f"$ {tgt} += {v}")
                                    elif v is not None:
                                        choice_obj.block_lines.append(f"$ {tgt} = {v}")
                                elif act_type == "ToggleVariable":
                                    tgt = act.get("target")
                                    choice_obj.block_lines.append(f"$ {tgt} = not {tgt}")
                                elif act_type == "Function":
                                    fn = act.get("func")
                                    args_str = ", ".join(repr(a) for a in act.get("args", []))
                                    choice_obj.block_lines.append(f"$ {fn}({args_str})")
                        else:
                            # Fallback regex
                            m_ajump = re.search(r"Jump\(['\"]([a-zA-Z0-9_]+)['\"]\)", btn_action)
                            if m_ajump: choice_obj.jump_target = m_ajump.group(1)
                            m_acall = re.search(r"Call\(['\"]([a-zA-Z0-9_]+)['\"]\)", btn_action)
                            if m_acall: choice_obj.call_target = m_acall.group(1)
                            for m_set in re.finditer(r"SetVariable\(['\"]([a-zA-Z0-9_]+)['\"]\s*,\s*([^)]+)\)", btn_action):
                                sv_var = m_set.group(1)
                                sv_val_raw = m_set.group(2).strip().lower()
                                if sv_val_raw in ("true", "false"):
                                    choice_obj.assigned_flags[sv_var] = (sv_val_raw == "true")

                        current_screen_menu.choices.append(choice_obj)
                        continue

            while stack and line_clean and not line_clean.startswith("#") and curr_indent <= stack[-1][0].indent:
                stack[-1][0].end_line_num = line_num
                stack.pop()

            if re.match(r'^\s*menu\b', line):
                m_menu = self.re_menu.match(line)
                if not m_menu:
                    self.skipped_menus.append({
                        "file": fpath,
                        "line": line_num + 1,
                        "text": line.strip(),
                        "reason": "Taninmayan menu baslik soz dizimi"
                    })
                    if self.log_callback:
                        self.log_callback(f"[!] ATLANAN MENU: {fpath}:{line_num+1} - {line.strip()}")
                else:
                    m_name = m_menu.group(1)
                    m_args = m_menu.group(2)
                    m_obj = RenpyMenu(fpath, line_num, curr_indent, menu_name=m_name, menu_args=m_args)
                    m_obj.analyzer = self
                    m_obj.project_ctx = getattr(self, "project_ctx", None)
                    m_obj.enclosing_label = current_label
                    # Onceki konusmaciyi (preceding speaker) tespit et
                    preceding_speaker = None
                    for prev_idx in range(line_num - 1, max(0, line_num - 20), -1):
                        prev_l = lines[prev_idx].strip()
                        spk_m = re.match(r"^([a-zA-Z0-9_]+)\s+[\"']", prev_l)
                        if spk_m:
                            spk_raw = spk_m.group(1).lower()
                            if spk_raw in ("mc", "player", "narrator", "narr", "mct"):
                                continue
                            if spk_raw in DYNAMIC_CHARACTERS:
                                preceding_speaker = DYNAMIC_CHARACTERS[spk_raw]
                                break
                            if spk_raw in KNOWN_CHARACTERS:
                                preceding_speaker = spk_raw.capitalize()
                                break
                            if spk_raw in ("n", "nancy"): preceding_speaker = "Nancy"; break
                            if spk_raw in ("a", "annie"): preceding_speaker = "Annie"; break
                            if spk_raw in ("d", "dalia"): preceding_speaker = "Dalia"; break
                            if spk_raw in ("p", "penelope", "penny"): preceding_speaker = "Penelope"; break
                            if spk_raw in ("l", "luna"): preceding_speaker = "Luna"; break
                            if spk_raw in ("x", "alex"): preceding_speaker = "Alex"; break
                            break
                    m_obj.preceding_speaker = preceding_speaker
                    menus.append(m_obj)
                    if stack and stack[-1][1]:
                        parent_c = stack[-1][1]
                        parent_c.nested_menus.append(m_obj)
                        m_obj.parent_choice = parent_c
                    stack.append([m_obj, None, 0])
                    continue

            if stack:
                cur_m, cur_c, c_indent = stack[-1]
                m_choice = self.re_choice.match(line)
                if m_choice and (cur_c is None or curr_indent == c_indent):
                    indent = m_choice.group(1)
                    quote = m_choice.group(2)
                    text = m_choice.group(3)
                    cond = m_choice.group(4)

                    choice_obj = RenpyChoice(fpath, line_num, indent, quote, text, cond, line)
                    choice_obj.menu = cur_m
                    choice_obj.preceding_speaker = getattr(cur_m, "preceding_speaker", None)
                    cur_m.choices.append(choice_obj)
                    stack[-1][1] = choice_obj
                    stack[-1][2] = curr_indent
                elif cur_c:
                    cur_c.block_lines.append(line)
                elif cur_c is None:
                    # P1: Menu govdesindeki set, with veya caption satirlarini koru
                    s_line = line.strip()
                    if s_line.startswith("set "):
                        cur_m.set_statement = s_line
                    elif s_line.startswith("with "):
                        cur_m.with_statement = s_line
                    elif s_line.startswith(('"', "'")):
                        cur_m.caption = s_line

        while stack:
            stack[-1][0].end_line_num = len(lines)
            stack.pop()

        for menu in menus:
            # Katman 6: QTE/Timer tespiti ve puanlaması
            has_qte = getattr(menu, "has_qte_timer", False)
            trap_target = getattr(menu, "qte_trap_target", None)

            for ch in menu.choices:
                self.inspect_code_lines(ch.block_lines, ch)

                if has_qte and STUDIO_CONFIG.get("enable_qte_intelligence", True):
                    if trap_target and ch.jump_target == trap_target:
                        ch.is_combat_failure = True
                        ch.score += STUDIO_CONFIG["penalty_combat_failure"]
                        ch.category_scores["combat"] += STUDIO_CONFIG["penalty_combat_failure"]
                        ch.deltas_negative.append(("QTE TUZAK", STUDIO_CONFIG["penalty_combat_failure"]))
                        ch.evidence_details.append("QTE zaman aşımı tuzağına düşer")
                    else:
                        ch.is_combat_success = True
                        ch.is_combat_action = True
                        ch.score += STUDIO_CONFIG["bonus_combat_success"]
                        ch.category_scores["combat"] += STUDIO_CONFIG["bonus_combat_success"]
                        ch.deltas_positive.append(("QTE BASARISI", STUDIO_CONFIG["bonus_combat_success"]))
                        ch.evidence_details.append("QTE zamanlayıcısını yenen başarılı eylem")

                if ch.jump_target and menu.enclosing_label and ch.jump_target == menu.enclosing_label:
                    menu.is_looping_hub = True

                if getattr(ch, "dynamic_jump_unresolved", None):
                    self._record_unique("unresolved_targets", {
                        "file": fpath, "line": ch.line_num + 1, "text": ch.text, "expr": ch.dynamic_jump_unresolved
                    }, ("file", "line", "expr"))
                if getattr(ch, "downstream_truncated", False):
                    self._record_unique("truncated_scans", {
                        "file": fpath, "line": ch.line_num + 1, "text": ch.text
                    }, ("file", "line"))
                if getattr(ch, "is_conflicting_branches", False):
                    self._record_unique("conflicting_branches", {
                        "file": fpath, "line": ch.line_num + 1, "text": ch.text, "branches": ch.conditional_branches
                    }, ("file", "line", "text"))

        for menu in menus:
            for ch in menu.choices:
                for sub_m in ch.nested_menus:
                    if not sub_m.choices:
                        continue
                    sub_scores = [sc.score for sc in sub_m.choices]
                    min_inner = min(sub_scores)
                    max_inner = max(sub_scores)
                    ch.inner_potential_score += max_inner
                    ch.inner_min_score += min_inner

                    # Ortak garantili delta'lar
                    if len(sub_m.choices) > 1:
                        common_deltas = set(sub_m.choices[0].deltas_positive)
                        for other_sc in sub_m.choices[1:]:
                            common_deltas &= set(other_sc.deltas_positive)
                    else:
                        common_deltas = set(sub_m.choices[0].deltas_positive)

                    # Yalnizca TUM seceneklerde ortak olan garanti puan aktarilir
                    if min_inner > 0:
                        ch.score += min_inner
                        for var, val in common_deltas:
                            if (var, val) not in ch.deltas_positive:
                                ch.deltas_positive.append((var, val))
                        ch.evidence_details.append(f"Ic ice menuden garantili ortak kazanim aktarildi: +{min_inner}")

                    # Eger ic menude secenekler arasi puan farki varsa, bu kazanim ic secime baglidir
                    if max_inner > min_inner:
                        ch.has_contingent_inner = True
                        ch.contingent_inner_max = max(ch.contingent_inner_max, max_inner)
                        for sub_c in sub_m.choices:
                            if sub_c.score > min_inner:
                                ch.contingent_inner_choices.append((sub_c.text, sub_c.score))
                        ch.evidence_details.append(f"Ic ice menuden kosullu potansiyel (secime bagli): +{max_inner}")

            # Rule 2: Kardes seceneklerin ilk ortak etiketini (merge label / post-dominator) tespit et
            merge_labels = set()
            jump_choices = [c for c in menu.choices if c.jump_target]
            direct_jump_targets = {c.jump_target for c in jump_choices}
            # Bug 3: Eğer aynı menüde 2 veya daha fazla seçenek aynı etikete doğrudan zıplıyorsa, o etiket bir merge label'dır!
            target_counts = {}
            for c in jump_choices:
                target_counts[c.jump_target] = target_counts.get(c.jump_target, 0) + 1
            for tgt, cnt in target_counts.items():
                if cnt >= 2:
                    merge_labels.add(tgt)
            if len(jump_choices) >= 2 or (len(jump_choices) >= 1 and any(not c.jump_target for c in menu.choices)):
                reached_per_choice = []
                for c in menu.choices:
                    c_reached = set()
                    if c.jump_target and c.jump_target in self.labels:
                        # Secenegin kendi hedefinden sonraki downstream etiketler
                        q = [c.jump_target]
                        v_lbls = set()
                        while q and len(v_lbls) < 15:
                            curr_target = q.pop(0)
                            if curr_target in v_lbls or curr_target not in self.labels:
                                continue
                            v_lbls.add(curr_target)
                            if curr_target != c.jump_target:
                                c_reached.add(curr_target)
                            t_fpath, t_lidx = self.labels[curr_target]
                            t_lines = self.get_file_lines(t_fpath)
                            for tl in t_lines[t_lidx + 1 : t_lidx + 250]:
                                if self.re_label.match(tl) or self.re_menu.match(tl):
                                    break
                                mj = re.search(r'^\s*jump\s+([a-zA-Z0-9_]+)', tl)
                                if mj and not tl.strip().startswith('#'):
                                    nxt = mj.group(1)
                                    if nxt not in v_lbls:
                                        q.append(nxt)
                    elif not c.jump_target:
                        post_start = menu.end_line_num
                        limit_idx = min(post_start + 250, len(lines))
                        for idx in range(post_start, limit_idx):
                            tl = lines[idx]
                            ml = self.re_label.match(tl)
                            if ml:
                                # Kardes secenegin dogrudan atladigi etiket fallthrough merge sayilamaz
                                if ml.group(1) not in direct_jump_targets:
                                    c_reached.add(ml.group(1))
                                break
                            mj = re.search(r'^\s*jump\s+([a-zA-Z0-9_]+)', tl)
                            if mj and not tl.strip().startswith('#'):
                                if mj.group(1) not in direct_jump_targets:
                                    c_reached.add(mj.group(1))
                                break
                    if c_reached:
                        reached_per_choice.append(c_reached)
                if len(reached_per_choice) >= 2:
                    common = set.intersection(*reached_per_choice)
                    if common:
                        merge_labels.update(common)

            for ch in menu.choices:
                if ch.jump_target and self.options.get("deep_jump_scan", True) and not getattr(ch, "is_passive_skip", False):
                    # Bug 3: Eğer ch.jump_target kardeş seçeneklerin ortak hedefi veya merge label ise, durdur (kümeden çıkarma)!
                    if ch.jump_target in merge_labels:
                        choice_stop_labels = set(merge_labels)
                    else:
                        choice_stop_labels = merge_labels - {ch.jump_target}
                    ds_score, ds_pos, ds_neg, ds_death, ds_surv, ds_truncated = self.scan_downstream(
                        ch.jump_target,
                        branch_state_env=dict(ch.assigned_flags),
                        stop_labels=choice_stop_labels
                    )
                    ch.downstream_score = ds_score
                    ch.downstream_pos = ds_pos
                    ch.downstream_neg = ds_neg
                    ch.is_downstream_death = ds_death
                    ch.is_downstream_survival = ds_surv
                    ch.downstream_truncated = ds_truncated
                    if ds_pos and any(str(d[0]).startswith("ROTA:") for d in ch.deltas_positive):
                        for d in list(ch.deltas_positive):
                            if str(d[0]).startswith("ROTA:"):
                                r_char = str(d[0]).replace("ROTA:", "").strip().lower()
                                if any((r_char in str(pos_d[0]).lower() or r_char in clean_var_to_name(str(pos_d[0])).lower()) for pos_d in ds_pos):
                                    ch.deltas_positive.remove(d)
                                    ch.score -= d[1]
                                    ch.category_scores["romance"] = max(0.0, ch.category_scores.get("romance", 0.0) - d[1])

            sibling_jumps = {c.jump_target for c in menu.choices if c.jump_target}
            has_fallthrough = any(c.jump_target is None and c.call_target is None for c in menu.choices)
            if has_fallthrough and sibling_jumps:
                post_start = menu.end_line_num
                reached_in_fallthrough = set()
                limit_idx = min(post_start + 1500, len(lines))
                for idx in range(post_start, limit_idx):
                    l = lines[idx]
                    m_lbl = self.re_label.match(l)
                    if m_lbl: reached_in_fallthrough.add(m_lbl.group(1))
                    m_jmp = re.search(r'^\s*jump\s+([a-zA-Z0-9_]+)', l)
                    if m_jmp and not l.strip().startswith("#"):
                        reached_in_fallthrough.add(m_jmp.group(1))

                converged = sibling_jumps & reached_in_fallthrough
                if converged:
                    max_conv_ds = max(
                        (c.downstream_score for c in menu.choices if c.jump_target in converged),
                        default=0.0
                    )
                    for ch in menu.choices:
                        if ch.jump_target is None and ch.call_target is None:
                            # Rule 2 & Bug 3: Fall-through kardes seceneklerin downstream puanini kopyalayarak calamaz
                            ch.is_gateway = True

            post_start = menu.end_line_num
            post_lines = lines[post_start : post_start + 45]
            for ch in menu.choices:
                if not ch.jump_target and ch.assigned_flags:
                    bonus_lines = self._get_post_menu_matching_lines(post_lines, ch.assigned_flags)
                    if bonus_lines:
                        self.inspect_code_lines(bonus_lines, ch)

        existing_menu_keys = {(em.file_path, em.line_num) for em in self.menus}
        for m in menus:
            m.is_harem_game = self.is_harem_game
            m_key = (m.file_path, m.line_num)
            if m_key not in existing_menu_keys:
                self.menus.append(m)
                existing_menu_keys.add(m_key)
        # R6 Faz 2.8: Graph Solver v0.5 icin menu konum-lookup kaydi (satir konumundan menu bulunur)
        try:
            _abs_fp = os.path.abspath(fpath)
            for m in menus:
                self.menu_lookup[(_abs_fp, m.line_num)] = m
        except Exception:
            pass
        return lines, menus

    def patch_file(self, fpath, lines, menus):
        """H9, Katman 5, N1, N2, R9, M1, M2b, K1, K2 & M3: Guvenli kodlamali, sozluk dogrulamali ve geri almali yama motoru."""
        green_hex = self.options.get("green_color", "#2ECC71")
        red_hex = self.options.get("red_color", "#EF4444")
        show_hints = self.options.get("show_hints", True)
        hint_style = self.options.get("hint_style", "name_and_number")
        highlight_negative = self.options.get("highlight_negative", True)
        enable_cheat_menu = self.options.get("enable_cheat_menu", True)
        player_profile = self.options.get("player_profile", "ALL_CONTENT")
        highlight_neutral_badges = self.options.get("highlight_neutral_badges", True)

        # R6 Faz 1.2: patch_file, analiz turundeki parametrelerle evaluate_choices'u yeniden cagirir;
        # menu._evt_decision_cache ayni karar setini dondurgunden tekrar hesap olmaz (~2x hiz kazanir).
        # Kararlar secenek alanlarina baglidir ve bu yontem yama yazimi secenek alanlarını degistirmediginden
        # cache guvenlidir (yama yalnizca dosya satirlarini yazar).

        modified = False
        highlighted_best = 0
        highlighted_worst = 0
        neutral_cleaned = 0
        # R5 Fix: neutral cloak sayacı her çağrıda sifirlanir (kalinti deger kullanilmasin)
        self.last_patched_neutral = 0

        if self.options.get("read_only", False):
            if self.log_callback:
                self.log_callback("[!] GÜVENLİK ENGELİ: Salt okunur mod aktif, dosya değiştirilemez.")
            return 0, 0

        target_dir = getattr(self, "target_dir", None) or find_real_renpy_game_dir(self.game_dir)
        ensure_walkthrough_tags_installed(target_dir, log_callback=self.log_callback)

        bak_path = fpath + ".wtbak"
        if self.options.get("auto_backup", True):
            if not os.path.exists(bak_path):
                try:
                    shutil.copy2(fpath, bak_path)
                    bh, bs = compute_file_sha256(bak_path)
                    oh, osz = compute_file_sha256(fpath)
                    if bh != oh or bs != osz:
                        if os.path.exists(bak_path):
                            try: os.remove(bak_path)
                            except Exception: pass
                        if self.log_callback:
                            self.log_callback(f"[X] GÜVENLİK ENGELİ: Yedek doğrulanamadı ({fpath}). Dosya değiştirilmedi!")
                        return 0, 0
                except Exception as e:
                    if os.path.exists(bak_path):
                        try: os.remove(bak_path)
                        except Exception: pass
                    if self.log_callback:
                        self.log_callback(f"[X] GÜVENLİK ENGELİ: Yedek oluşturulamadı ({e}). Dosya değiştirilmedi!")
                    return 0, 0

        orig_lines_copy = list(lines)

        # R9, M2a & K2: Girdi dosyasi sozluk/parantez dogrulamasi
        is_orig_valid, orig_err = validate_renpy_syntax(lines)
        if not is_orig_valid and not self.options.get("allow_partial_patch", False):
            if self.log_callback:
                # R6 fix: dosya adi mesaja eklendi (hangisinin atlandigi gorunsun)
                self.log_callback(f"[!] HATA ({os.path.basename(fpath)}): Girdi dosyasi sozluk/parantez hatasi iceriyor ({orig_err}). Islem iptal edildi.")
            return 0, 0

        for menu in menus:
            decisions = menu.evaluate_choices(highlight_negative=highlight_negative, player_profile=player_profile)

            for ch, verdict in decisions.items():
                if not isinstance(ch, RenpyChoice):
                    continue
                clean_text = self.clean_existing_tags(ch.text)
                cond_part = f" if {ch.condition}" if ch.condition else ""

                # N2: Screen tabanli secim butonlarini yamala
                if getattr(menu, "is_screen", False):
                    line_idx = ch.line_num
                    if line_idx >= len(lines):
                        continue
                    orig_line = lines[line_idx]

                    has_scr_neutral = bool(
                        bool(getattr(ch, "condition", "")) or
                        getattr(ch, "dynamic_jump_unresolved", None) or
                        getattr(ch, "downstream_truncated", False) or
                        getattr(ch, "conditional_branches", []) or
                        getattr(ch, "is_conflicting_branches", False) or
                        getattr(ch, "has_contingent_inner", False) or
                        getattr(ch, "threshold_satisfied_independent", False) or
                        getattr(ch, "threshold_uncertain", False) or
                        getattr(ch, "is_unreachable_stat_only", False) or
                        getattr(ch, "dynamic_func_unresolved", False) or
                        len(getattr(ch, "dynamic_calls_unresolved", [])) > 0 or
                        any("katkı" in str(u).lower() or "katki" in str(u).lower() or "eşiğe ulaşılamıyor" in str(u).lower() or "erişilemez" in str(u).lower() or "belirsiz" in str(u).lower() for u in getattr(ch, "unlocked_thresholds", []))
                    )

                    if verdict == 'BEST':
                        hint_str = self.format_hint(ch, is_positive=True, style=hint_style) if show_hints else ""
                        esc_hint = escape_renpy_injected_text(hint_str, in_quote=ch.quote)
                        if enable_cheat_menu:
                            new_label = f"{{wt_best}}{clean_text}{{wt_hint}}{esc_hint}{{/wt_hint}}{{/wt_best}}" if esc_hint else f"{{wt_best}}{clean_text}{{/wt_best}}"
                        else:
                            new_label = f"{{color={green_hex}}}{clean_text}{{size=-4}}{esc_hint}{{/size}}{{/color}}" if esc_hint else f"{{color={green_hex}}}{clean_text}{{/color}}"
                    elif verdict == 'WORST':
                        hint_str = self.format_hint(ch, is_positive=False, style=hint_style) if show_hints else ""
                        esc_hint = escape_renpy_injected_text(hint_str, in_quote=ch.quote)
                        if enable_cheat_menu:
                            new_label = f"{{wt_worst}}{clean_text}{{wt_hint}}{esc_hint}{{/wt_hint}}{{/wt_worst}}" if esc_hint else f"{{wt_worst}}{clean_text}{{/wt_worst}}"
                        else:
                            new_label = f"{{color={red_hex}}}{clean_text}{{size=-4}}{esc_hint}{{/size}}{{/color}}" if esc_hint else f"{{color={red_hex}}}{clean_text}{{/color}}"
                    else:
                        # M3: Neutral screen butonu
                        if show_hints and highlight_neutral_badges and has_scr_neutral:
                            hint_str = self.format_hint(ch, is_positive=False, style=hint_style)
                            esc_hint = escape_renpy_injected_text(hint_str, in_quote=ch.quote)
                            new_label = f"{clean_text}{{wt_hint}}{esc_hint}{{/wt_hint}}" if enable_cheat_menu else f"{clean_text}{{size=-4}}{esc_hint}{{/size}}"
                        else:
                            new_label = clean_text

                    # N2: _(), _p(), kwargs ve quote korumali kesin ikame
                    m_btn = self.re_textbutton.search(orig_line)
                    if m_btn:
                        q = m_btn.group(2)
                        start_q = m_btn.start(2)
                        end_q = m_btn.start(2) + 1 + len(m_btn.group(3)) + 1
                        new_line = orig_line[:start_q] + f"{q}{new_label}{q}" + orig_line[end_q:]

                        # M2b: Screen buton satiri dogrulamasi
                        is_line_valid, line_err = validate_patched_choice_line(orig_line, new_line, clean_text, q, condition="", is_screen=True)
                        if not is_line_valid:
                            if self.log_callback:
                                self.log_callback(f"[!] YAMA REDDEDILDI: Screen buton satiri {line_idx+1} dogrulanamadi ({line_err}). Orijinal korundu.")
                            continue

                        if new_line != orig_line:
                            lines[line_idx] = new_line
                            modified = True
                            if verdict == 'BEST': highlighted_best += 1
                            elif verdict == 'WORST': highlighted_worst += 1
                    continue

                # Standart menu seceneklerini yamala
                q = ch.quote
                hint_str = ""
                if verdict == 'BEST':
                    if show_hints:
                        hint_str = self.format_hint(ch, is_positive=True, style=hint_style)
                    esc_hint = escape_renpy_injected_text(hint_str, in_quote=q)

                    if enable_cheat_menu:
                        new_text = f"{{wt_best}}{clean_text}{{wt_hint}}{esc_hint}{{/wt_hint}}{{/wt_best}}" if esc_hint else f"{{wt_best}}{clean_text}{{/wt_best}}"
                    else:
                        new_text = f"{{color={green_hex}}}{clean_text}{{size=-4}}{esc_hint}{{/size}}{{/color}}" if esc_hint else f"{{color={green_hex}}}{clean_text}{{/color}}"

                    new_line = f"{ch.indent}{q}{new_text}{q}{cond_part}:\n"
                    # M2b: Satir bazinda AST ve dize sonu dogrulamasi
                    is_line_valid, line_err = validate_patched_choice_line(orig_lines_copy[ch.line_num], new_line, clean_text, q, ch.condition, is_screen=False)
                    if not is_line_valid:
                        if self.log_callback:
                            self.log_callback(f"[!] YAMA REDDEDILDI: Satir {ch.line_num + 1} dogrulanamadi ({line_err}). Orijinal satir korundu.")
                        continue

                    if lines[ch.line_num] != new_line:
                        lines[ch.line_num] = new_line
                        modified = True
                        highlighted_best += 1

                elif verdict == 'WORST' and highlight_negative:
                    if show_hints:
                        hint_str = self.format_hint(ch, is_positive=False, style=hint_style)
                    esc_hint = escape_renpy_injected_text(hint_str, in_quote=q)

                    if enable_cheat_menu:
                        new_text = f"{{wt_worst}}{clean_text}{{wt_hint}}{esc_hint}{{/wt_hint}}{{/wt_worst}}" if esc_hint else f"{{wt_worst}}{clean_text}{{/wt_worst}}"
                    else:
                        new_text = f"{{color={red_hex}}}{clean_text}{{size=-4}}{esc_hint}{{/size}}{{/color}}" if esc_hint else f"{{color={red_hex}}}{clean_text}{{/color}}"

                    new_line = f"{ch.indent}{q}{new_text}{q}{cond_part}:\n"
                    # M2b: Satir bazinda AST ve dize sonu dogrulamasi
                    is_line_valid, line_err = validate_patched_choice_line(orig_lines_copy[ch.line_num], new_line, clean_text, q, ch.condition, is_screen=False)
                    if not is_line_valid:
                        if self.log_callback:
                            self.log_callback(f"[!] YAMA REDDEDILDI: Satir {ch.line_num + 1} dogrulanamadi ({line_err}). Orijinal satir korundu.")
                        continue

                    if lines[ch.line_num] != new_line:
                        lines[ch.line_num] = new_line
                        modified = True
                        highlighted_worst += 1

                else:
                    # M3: NEUTRAL secenek
                    has_neutral_info = bool(
                        bool(getattr(ch, "condition", "")) or
                        bool(ch.deltas_positive) or
                        bool(ch.deltas_negative) or
                        bool(getattr(ch, "downstream_pos", [])) or
                        bool(getattr(ch, "downstream_neg", [])) or
                        getattr(ch, "dynamic_jump_unresolved", None) or
                        getattr(ch, "downstream_truncated", False) or
                        getattr(ch, "conditional_branches", []) or
                        getattr(ch, "is_conflicting_branches", False) or
                        getattr(ch, "has_contingent_inner", False) or
                        getattr(ch, "threshold_satisfied_independent", False) or
                        getattr(ch, "threshold_uncertain", False) or
                        getattr(ch, "is_unreachable_stat_only", False) or
                        getattr(ch, "dynamic_func_unresolved", False) or
                        len(getattr(ch, "dynamic_calls_unresolved", [])) > 0 or
                        any("katkı" in str(u).lower() or "katki" in str(u).lower() or "eşiğe ulaşılamıyor" in str(u).lower() or "erişilemez" in str(u).lower() or "belirsiz" in str(u).lower() for u in getattr(ch, "unlocked_thresholds", []))
                    )

                    # D4 (b): Calisma zamani kancasi aktifse belirsiz seceneklerde wt_format_live_hint kullan
                    enable_hook_patch = self.options.get("enable_runtime_hook", False)
                    uncertain_var = None
                    uncertain_th = None
                    if enable_hook_patch and has_neutral_info:
                        for th_k, th_r in getattr(ch, "unlocked_thresholds", []):
                            if any(w in str(th_r).lower() for w in ("belirsiz", "dinamik", "koşullu", "kosullu")):
                                parts = str(th_k).split()
                                if len(parts) >= 3:
                                    uncertain_var = parts[0]
                                    try: uncertain_th = float(parts[2])
                                    except Exception: uncertain_th = parts[2]
                                    break
                        if not uncertain_var and getattr(ch, "point_changes", {}):
                            uncertain_var = next(iter(ch.point_changes.keys()))
                        if not uncertain_var and getattr(ch, "conditional_branches", []):
                            for cb in ch.conditional_branches:
                                cond = cb.get("condition", "")
                                parts = cond.split()
                                if len(parts) >= 3 and parts[1] in (">=", "<=", ">", "<", "=="):
                                    uncertain_var = parts[0]
                                    try: uncertain_th = float(parts[2])
                                    except Exception: uncertain_th = parts[2]
                                    break

                    if enable_hook_patch and uncertain_var:
                        if uncertain_th is not None:
                            new_text = f"[wt_format_live_hint('{clean_text}', '{uncertain_var}', {uncertain_th})]"
                        else:
                            new_text = f"[wt_format_live_hint('{clean_text}', '{uncertain_var}')]"
                    elif show_hints and highlight_neutral_badges and has_neutral_info:
                        is_pos_hint = bool(ch.deltas_positive or getattr(ch, "downstream_pos", []))
                        hint_str = self.format_hint(ch, is_positive=is_pos_hint, style=hint_style)
                        esc_hint = escape_renpy_injected_text(hint_str, in_quote=q)
                        if enable_cheat_menu:
                            new_text = f"{clean_text}{{wt_hint}}{esc_hint}{{/wt_hint}}" if esc_hint else clean_text
                        else:
                            new_text = f"{clean_text}{{size=-4}}{esc_hint}{{/size}}" if esc_hint else clean_text
                    else:
                        new_text = clean_text

                    new_line = f"{ch.indent}{q}{new_text}{q}{cond_part}:\n"
                    # M2b: Satir bazinda AST ve dize sonu dogrulamasi
                    is_line_valid, line_err = validate_patched_choice_line(orig_lines_copy[ch.line_num], new_line, clean_text, q, ch.condition, is_screen=False)
                    if not is_line_valid:
                        if self.log_callback:
                            self.log_callback(f"[!] YAMA REDDEDILDI: Satir {ch.line_num + 1} dogrulanamadi ({line_err}). Orijinal satir korundu.")
                        continue

                    if lines[ch.line_num] != new_line:
                        lines[ch.line_num] = new_line
                        modified = True
                        neutral_cleaned += 1

        if modified:
            # R9 & M2b: Yama sonrasi kesin soz dizimi ve butunluk dogrulamasi
            is_valid, err_msg = verify_patched_file_integrity(orig_lines_copy, lines)
            if not is_valid:
                if self.log_callback:
                    self.log_callback(f"[!] HATA: Yama sonrasi soz dizimi hatasi tespit edildi ({err_msg}). Dosya .wtbak yedeginden geri aliniyor.")
                if os.path.exists(bak_path):
                    shutil.copy2(bak_path, fpath)
                # R5 Fix: geri alinan dosyanin onbellegi tazelensin
                try: self.file_cache.pop(fpath, None)
                except Exception: pass
                return 0, 0

            # K1: Dosya karakter kodlamasi, CRLF/LF ve BOM durumunu tam koruyarak atomik yazim
            enc, nl, has_bom = self.file_encoding_info.get(fpath, detect_file_encoding(fpath))
            normalized_lines = []
            for l in lines:
                normalized_lines.append(l.rstrip("\r\n") + nl)

            import uuid
            tmp_fpath = fpath + f".tmp_{uuid.uuid4().hex}"
            try:
                with open(tmp_fpath, "w", encoding=enc, errors="surrogateescape", newline="") as f:
                    f.writelines(normalized_lines)
                if os.path.exists(tmp_fpath) and os.path.getsize(tmp_fpath) > 0:
                    os.replace(tmp_fpath, fpath)
                else:
                    if os.path.exists(tmp_fpath): os.remove(tmp_fpath)
                    if os.path.exists(bak_path): shutil.copy2(bak_path, fpath)
                    # R5 Fix: geri alinan dosyanin onbellegi tazelensin
                    try: self.file_cache.pop(fpath, None)
                    except Exception: pass
                    return 0, 0
            except Exception:
                if os.path.exists(tmp_fpath):
                    try: os.remove(tmp_fpath)
                    except Exception: pass
                if os.path.exists(bak_path): shutil.copy2(bak_path, fpath)
                # R5 Fix: geri alinan dosyanin onbellegi tazelensin
                try: self.file_cache.pop(fpath, None)
                except Exception: pass
                return 0, 0

            # Z3: Tekil dosya yamasinda eger toplu modda degilsek lint'i calistir
            if self.options.get("verify_with_renpy_lint", False):
                if not getattr(self, "_in_batch_patch", False):
                    lint_res = self.verify_project_lint([fpath])
                    if not lint_res or fpath in getattr(lint_res, "rolled_back", []):
                        return 0, 0

            if self.options.get("remove_rpyc", True):
                rpyc_path = fpath + "c"
                if os.path.exists(rpyc_path):
                    try:
                        bak_rpyc = rpyc_path + ".wtbak"
                        if not os.path.exists(bak_rpyc):
                            shutil.move(rpyc_path, bak_rpyc)
                        else:
                            os.remove(rpyc_path)
                    except Exception:
                        pass
            # R5 Fix: yalnizca 'neutral cloak' etiketi temizlenen dosyalar da sayilir
            # (analyze_and_patch bu sayaci modified_files listesine dahil etmek icin okur).
            if neutral_cleaned and modified:
                self.last_patched_neutral = neutral_cleaned

        return highlighted_best, highlighted_worst

    def clean_existing_tags(self, text):
        """H9: Yalnizca studio tarafindan eklenen etiketleri temizler; [name] ve (+500) KESINLIKLE KORUNUR."""
        cleaned = re.sub(r'\{wt_hint\}.*?\{/wt_hint\}', '', text, flags=re.DOTALL)
        cleaned = re.sub(r'\{size=[^}]+\}.*?\{/size\}', '', cleaned, flags=re.DOTALL)
        cleaned = re.sub(r'\{/?(?:wt_best|wt_worst|wt_hint|size)(?:=[^}]+)?\}', '', cleaned)
        cleaned = re.sub(r'\{/?color(?:=[^}]+)?\}', '', cleaned)
        return cleaned.strip()

    def discover_gallery_flags(self):
        """Oyun scriptlerinden galeri, replay, sahne ve son kilit değişkenlerini otomatik tespit eder."""
        found = set()
        patterns = [
            re.compile(r'persistent\.([a-zA-Z0-9_]+)\s*=\s*(?:True|False|[0-9]+|\[|\{)', re.IGNORECASE),
            re.compile(r'default\s+persistent\.([a-zA-Z0-9_]+)', re.IGNORECASE),
            re.compile(r'sensitive\s+persistent\.([a-zA-Z0-9_]+)', re.IGNORECASE),
            re.compile(r'if\s+(?:not\s+)?persistent\.([a-zA-Z0-9_]+)', re.IGNORECASE),
            re.compile(r'replays\.append\(\s*\[\s*persistent\.([a-zA-Z0-9_]+)', re.IGNORECASE)
        ]
        keywords = (
            'scene', 'replay', 'cg', 'gallery', 'unlock', 'seen',
            'photo', 'video', 'art', 'pic', 'bonus', 'special', 'anim', 'sex', 'kiss', 'date'
        )
        # Hikaye akisi, bolum atlama veya oyun durumunu bozan degiskenleri galeri kilitlerinden ayir
        progression_filter = (
            'chapter', 'route', 'quest', 'mission', 'progress', 'phase', 'dead',
            'kill', 'death', 'game_over', 'bad_end', 'stat_', 'level_', 'hp_', 'exp_',
            'gold_', 'money_', 'day_', 'hour_', 'flag_ch', 'story_'
        )
        exclude_prefixes = (
            'walkthrough_', 'wt_', '_seen_', 'volume_', 'text_cps', 'afm_time',
            'skip_unseen', 'music_volume', 'sfx_volume', 'voice_volume',
            'window_', 'save_', 'slot_', 'pref_', 'preference_'
        )
        exclude = {
            'walkthrough_enabled', 'wt_green_color', 'wt_red_color', 'wt_mode',
            'wt_show_hints', 'wt_menu_tab', '_chosen', '_preferences',
            '_file_page', '_default_fields', 'developer', 'console'
        }

        collection_containers = (
            'unlocks', 'entries', 'scenes_list', 'cgs_list', 'gallery_items',
            'gallery_dict', 'seen_set', 'replay_dict'
        )
        # M3 fix: galeri kilidi olmayan durum/sistem degiskenlerini ele (gercek vaka:
        # last_update_check, time_started, sexCounter, photosensitivity_mode vb.)
        junk_keywords = (
            'counter', 'cache', 'check', 'started', 'sensitivity', 'animations',
            'animation', 'hint', 'update', 'version', 'conditional', 'debug',
            'session', 'install', 'launch', 'timestamp', 'last_', '_at', 'temp'
        )

        target = getattr(self, "target_dir", None) or find_real_renpy_game_dir(self.game_dir)
        if not target or not os.path.isdir(target):
            return sorted(found)

        for root, dirs, files in os.walk(target):
            dirs[:] = [d for d in dirs if d.lower() not in IGNORED_DIRS]
            for f in files:
                if f.endswith('.rpy') and not f.startswith('zz_walkthrough'):
                    p = os.path.join(root, f)
                    try:
                        with open(p, 'r', encoding='utf-8', errors='ignore') as fp:
                            f_content = fp.read()
                            for pat in patterns:
                                for m in pat.finditer(f_content):
                                    var = m.group(1)
                                    vl = var.lower()
                                    is_collection = any(vl.endswith(ck) for ck in collection_containers) or vl in ('galleryunlocks', 'unlocked_scenes', 'gallery_entries')
                                    is_gallery_kw = any(kw in vl for kw in keywords)
                                    is_prog = any(pk in vl for pk in progression_filter) and not any(gk in vl for gk in ('gallery', 'cg', 'replay', 'photo', 'art', 'bonus', 'scene'))
                                    if var not in exclude and not any(vl.startswith(p) for p in exclude_prefixes) and is_gallery_kw and not is_prog and not is_collection and not any(jk in vl for jk in junk_keywords):
                                        found.add(var)
                    except Exception:
                        pass
        return sorted(found)

    def discover_game_currency(self):
        """
        Oyun scriptlerini tarayarak oyunun para birimini, değişken adını
        ve ekonomi ölçeğini (Eternum: 100/1000/10000, Being a DIK: 10/25/50/100 vb.) tespit eder.
        """
        curr_patterns = [
            re.compile(r'(?:default|\$)\s+([a-zA-Z0-9_]+)\s*=\s*([0-9]+(?:\.[0-9]+)?)', re.IGNORECASE),
            re.compile(r'(?:\$|\s)([a-zA-Z0-9_]+)\s*(\+=|-=)\s*([0-9]+(?:\.[0-9]+)?)', re.IGNORECASE),
            re.compile(r'(?:define)\s+(?:store\.)?([a-zA-Z0-9_]+)\s*=\s*([0-9]+(?:\.[0-9]+)?)', re.IGNORECASE)
        ]

        currency_specs = {
            'eternum': ('Eternum', [(-100, '-100'), (100, '+100'), (500, '+500'), (1000, '+1.000'), (5000, '+5.000')]),
            'money': ('Dolar', [(-10, '-10'), (10, '+10'), (25, '+25'), (50, '+50'), (100, '+100')]),
            'cash': ('Dolar', [(-10, '-10'), (10, '+10'), (25, '+25'), (50, '+50'), (100, '+100')]),
            'dollar': ('Dolar', [(-10, '-10'), (10, '+10'), (25, '+25'), (50, '+50'), (100, '+100')]),
            'dollars': ('Dolar', [(-10, '-10'), (10, '+10'), (25, '+25'), (50, '+50'), (100, '+100')]),
            'bucks': ('Dolar', [(-10, '-10'), (10, '+10'), (25, '+25'), (50, '+50'), (100, '+100')]),
            'gold': ('Altin', [(-50, '-50'), (50, '+50'), (100, '+100'), (500, '+500'), (1000, '+1.000')]),
            'coins': ('Altin', [(-50, '-50'), (50, '+50'), (100, '+100'), (500, '+500'), (1000, '+1.000')]),
            'coin': ('Altin', [(-50, '-50'), (50, '+50'), (100, '+100'), (500, '+500'), (1000, '+1.000')]),
            'silver': ('Gumus', [(-50, '-50'), (50, '+50'), (100, '+100'), (500, '+500'), (1000, '+1.000')]),
            'credits': ('Kredi', [(-50, '-50'), (50, '+50'), (100, '+100'), (500, '+500'), (1000, '+1.000')]),
            'credit': ('Kredi', [(-50, '-50'), (50, '+50'), (100, '+100'), (500, '+500'), (1000, '+1.000')]),
            'gems': ('Elmas', [(-10, '-10'), (10, '+10'), (50, '+50'), (100, '+100'), (500, '+500')]),
            'gem': ('Elmas', [(-10, '-10'), (10, '+10'), (50, '+50'), (100, '+100'), (500, '+500')]),
            'tokens': ('Jeton', [(-10, '-10'), (10, '+10'), (50, '+50'), (100, '+100'), (500, '+500')]),
            'token': ('Jeton', [(-10, '-10'), (10, '+10'), (50, '+50'), (100, '+100'), (500, '+500')]),
        }

        char_exclude = {'point', 'points', 'love', 'aff', 'rel', 'relation', 'favor', 'score', 'trust', 'stat', 'day', 'hour', 'min', 'limit', 'max', 'min', 'cap', 'spent'}

        discovered = {}

        target = getattr(self, "target_dir", None) or find_real_renpy_game_dir(self.game_dir)
        for root, dirs, files in os.walk(target):
            dirs[:] = [d for d in dirs if d.lower() not in IGNORED_DIRS]
            for f in files:
                if f.endswith('.rpy') and not f.startswith('zz_walkthrough'):
                    p = os.path.join(root, f)
                    try:
                        with open(p, 'r', encoding='utf-8', errors='ignore') as fp:
                            content = fp.read()
                            for pat in curr_patterns:
                                for m in pat.finditer(content):
                                    vname = m.group(1)
                                    v_lower = vname.lower()
                                    if any(exc in v_lower for exc in char_exclude):
                                        continue
                                    for k, (unit, steps) in currency_specs.items():
                                        if k == v_lower or v_lower.startswith(f'{k}_') or v_lower.endswith(f'_{k}'):
                                            discovered[vname] = (unit, steps)
                                            break
                    except Exception:
                        pass

        # Ayrıca klasör adında veya dosyalarında 'eternum' varsa
        is_eternum_game = any('eternum' in f.lower() for f in os.listdir(target)) or 'eternum' in target.lower()
        if is_eternum_game and 'eternum' not in discovered:
            discovered['eternum'] = currency_specs['eternum']

        has_currency = len(discovered) > 0
        if has_currency:
            priority_order = ['eternum', 'money', 'cash', 'gold', 'coins', 'credits', 'dollar', 'dollars']
            primary_var = None
            for p_key in priority_order:
                for d_var in discovered.keys():
                    if p_key in d_var.lower():
                        primary_var = d_var
                        break
                if primary_var:
                    break
            if not primary_var:
                primary_var = list(discovered.keys())[0]

            primary_unit, primary_steps = discovered[primary_var]
        else:
            primary_var = 'money'
            primary_unit = 'Para'
            primary_steps = [(-10, '-10'), (10, '+10'), (25, '+25'), (50, '+50'), (100, '+100')]

        confidence = 'AMBIGUOUS'
        if has_currency:
            if primary_var.lower() in ('eternum', 'money', 'cash', 'gold', 'coins', 'credits', 'dollar', 'dollars'):
                confidence = 'HIGH'
            else:
                confidence = 'MEDIUM'
        else:
            confidence = 'NONE'

        return {
            'has_currency': has_currency,
            'primary_var': primary_var,
            'primary_unit': primary_unit,
            'primary_steps': primary_steps,
            'all_discovered': discovered,
            'confidence': confidence
        }

    def export_both_report(self, output_path=None):
        """Return source-linked plans/proposals; reporting never patches a game."""
        import json
        if not getattr(self, '_both_detection_complete', False):
            self.detect_both_candidates()
        reader = BothScenePlanner(self)
        sources = {os.path.abspath(p): reader._file(p) for p in self.rpy_files}
        index = BothDependencyIndex(sources)
        menus = {(os.path.abspath(m.file_path), m.line_num + 1): m
                 for m in list(getattr(self, 'all_menus', [])) + list(self.menus)}
        entries = []
        for candidate in getattr(self, 'both_candidates', []):
            plan = candidate.scene_plan
            applied = getattr(candidate, 'applied', False)
            signatures = getattr(candidate, 'applied_sources', plan['sources']) if applied else plan['sources']
            fresh = all(compute_file_sha256(p) == sig for p, sig in signatures.items())
            entries.append({'file': candidate.file_path, 'line': candidate.menu.line_num + 1,
                            'status': ('applied' if applied else 'verified_candidate') if fresh else 'stale_requires_rescan',
                            'choices': [ch.text for ch in candidate.choices],
                            'changed_variables': plan['changed_variables'],
                            'dependencies': index.dependencies(plan['changed_variables']),
                            'condition_adaptations': plan['condition_adaptations'],
                            'verification': {**plan['verification'], 'source_basis': 'pre_patch_inputs',
                                             'current_source_matches_expected': fresh},
                            'automatic_write': False,
                            'eligible_for_automatic_apply': fresh and not applied,
                            'scope': 'private_both_branch_only',
                            'patch_preview': self._both_plan_preview(candidate),
                            'planned_source_hashes': {p: sig[0] for p, sig in plan['sources'].items()}})
        for skipped in getattr(self, 'both_skipped', []):
            menu = menus.get((os.path.abspath(skipped['file']), skipped['line']))
            variables = set()
            if menu:
                for choice in menu.choices:
                    # These are source candidates, never proof derived from heuristic scores.
                    variables.update(getattr(choice, 'assigned_flags', {}))
                    for line in choice.block_lines:
                        if line.strip().startswith('$'):
                            try:
                                tree = ast.parse(line.strip()[1:].strip())
                                variables.update(n.id for n in ast.walk(tree)
                                                 if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Store))
                                variables.update(_cs_dotted(n) for n in ast.walk(tree)
                                                 if isinstance(n, ast.Attribute) and isinstance(n.ctx, ast.Store) and _cs_dotted(n))
                            except SyntaxError:
                                pass
                    targets = {choice.jump_target, choice.call_target} - {None}
                    for row in index.rows:
                        if row['label'] in targets:
                            variables.update(row['writes'])
            dependencies = index.dependencies(variables)
            entries.append({**skipped, 'status': 'manual_review',
                            'candidate_variables': sorted(variables), 'dependencies': dependencies,
                            'proposal': {'mode': 'review_only', 'automatic_write': False,
                                         'required_proof': skipped['reason'],
                                         'source_conditions': [r for r in dependencies if r['kind'] == 'condition']}})
        entries.extend(getattr(self, 'both_existing', []))
        report = {'schema': 1, 'semantics': 'source_dependencies_not_inferred_romantic_routes',
                  'dependency_index_complete': index.complete, 'entries': entries,
                  'limitations': ['unsupported_python_screens_and_persistent_effects_need_review',
                                  'automatic_gate_adaptation_is_bounded_to_explicit_return',
                                  'ordinary_presentation_callbacks_assumed_state_free',
                                  'renpy_lint_and_runtime_not_claimed_by_static_verification']}
        if output_path:
            target = os.path.normcase(os.path.abspath(output_path))
            if target in {os.path.normcase(os.path.abspath(p)) for p in self.rpy_files} or str(output_path).lower().endswith(('.rpy', '.rpyc', '.rpa', '.py', '.wtbak')):
                raise BothPlanError('report_must_not_overwrite_game_source')
            with open(output_path, 'w', encoding='utf-8') as output:
                json.dump(report, output, ensure_ascii=False, indent=2)
        return report

    def _both_plan_preview(self, candidate):
        # Use the already verified source plan, even after the menu was patched.
        plan = candidate.scene_plan
        title = 'Mod: All' if len(candidate.choices) >= 3 else 'Mod: Both'
        guard = ' if ' + ' and '.join('(' + g + ')' for g in plan['guards']) if plan['guards'] else ''
        return '\n'.join(['"' + title + '"' + guard + ':'] + ['    ' + row for row in plan['body']])

    def detect_both_candidates(self, menus=None):
        """
        B-A & B-C: Birbirini dışlayan ve oyuncuyu ayrı içerikler arasında seçime zorlayan
        tüm menüleri analiz eder; en büyük köprülenebilir alt kümeyi ('Mod: Both' / 'Mod: All') listeler.
        """
        if menus is None:
            menus = getattr(self, "all_menus", [])
            if not menus:
                menus = []
                for fpath in self.rpy_files:
                    _, f_menus = self.analyze_file_menus(fpath)
                    menus.extend(f_menus)

        candidates = []
        self.both_skipped = []
        self.both_existing = []
        for menu in menus:
            if len(menu.choices) < 2:
                continue

            existing_texts = [c.text.lower() for c in menu.choices]
            # Menu objects may predate the insertion. Inspect current source too,
            # so a second scan reports an existing bridge rather than a failure.
            current = self.get_file_lines(menu.file_path)
            if menu.line_num < len(current) and self.re_menu.match(current[menu.line_num]):
                indent = len(current[menu.line_num]) - len(current[menu.line_num].lstrip())
                for line in current[menu.line_num + 1:]:
                    if line.strip() and not line.lstrip().startswith('#') and len(line) - len(line.lstrip()) <= indent:
                        break
                    match = self.re_choice.match(line)
                    if match:
                        existing_texts.append(match.group(3).lower())
            if any("mod: both" in t or "mod: all" in t for t in existing_texts):
                self.both_existing.append({'file': menu.file_path, 'line': menu.line_num + 1,
                                           'status': 'existing_both_not_modified',
                                           'verification': 'not_reverified_as_our_generated_plan'})
                continue
            if len(menu.choices) > 8:
                self.both_skipped.append({'file': menu.file_path, 'line': menu.line_num + 1,
                                          'reason': 'bridge_choice_budget_exceeded'})
                continue
            from itertools import combinations
            subset, plan, reason = [], None, 'no_compatible_scene_subset'
            for size in range(len(menu.choices), 1, -1):
                for group in combinations(menu.choices, size):
                    try:
                        plan = build_both_scene_plan(self, menu, list(group))
                        subset = list(group)
                        break
                    except (BothPlanError, OSError, ValueError, RecursionError) as exc:
                        reason = str(exc)
                if subset:
                    break
            if not subset:
                self.both_skipped.append({'file': menu.file_path, 'line': menu.line_num + 1,
                                          'reason': reason})
                continue

            ch_a = subset[0]
            ch_b = subset[1]
            char_a = clean_var_to_name(ch_a.deltas_positive[0][0]) if ch_a.deltas_positive else (ch_a.jump_target or "A")
            char_b = clean_var_to_name(ch_b.deltas_positive[0][0]) if ch_b.deltas_positive else (ch_b.jump_target or "B")

            cand = BothRouteCandidate(
                menu=menu,
                choice_a=ch_a,
                choice_b=ch_b,
                char_a=char_a,
                char_b=char_b,
                branch_a=ch_a.jump_target or "",
                branch_b=ch_b.jump_target or "",
                reason=f"Kaynak doğrulamalı ardışık sahneler ({len(subset)} seçenek; puanlar bir kez)",
                choices=subset,
                bridge_kind="all" if len(subset) >= 3 else "both"
            )
            cand.scene_plan = plan
            candidates.append(cand)

        self.both_candidates = candidates
        self._both_detection_complete = True
        return candidates

    def generate_both_patch(self, candidate):
        """Generate complete scenes, not merged rewards or edits to original labels."""
        choices = getattr(candidate, "choices", None) or [candidate.choice_a, candidate.choice_b]
        plan = build_both_scene_plan(self, candidate.menu, choices)
        indent = candidate.choice_a.indent
        body_indent = indent + "    "
        label_text = "Mod: All" if len(choices) >= 3 else "Mod: Both"
        style = self.options.get('hint_style', 'name_and_number')
        parts = []
        if self.options.get('show_hints', True) and style != 'none':
            for var, amount in sorted(plan['points'].items()):
                name, number = clean_var_to_name(var), format_point_val(amount)
                parts.append(number if style == 'number_only' else
                             f'{number} {name}' if style == 'number_and_name' else f'{name} {number}')
        hint = ' (' + ', '.join(parts) + ')' if parts else ''
        # Escape text once, at the Ren'Py quoted-string boundary.
        esc_hint = escape_renpy_injected_text(hint, '"')
        if self.options.get('enable_cheat_menu', True):
            caption = f'{{wt_best}}{label_text}'
            if esc_hint:
                caption += f'{{wt_hint}}{esc_hint}{{/wt_hint}}'
            caption += '{/wt_best}'
        else:
            caption = f'{{color=#2ECC71}}{label_text}'
            if esc_hint:
                caption += f'{{size=-4}}{esc_hint}{{/size}}'
            caption += '{/color}'
        guard = ' if ' + ' and '.join('(' + g + ')' for g in plan['guards']) if plan['guards'] else ''
        lines_code = [f'{indent}"{caption}"{guard}:',
                      f'{body_indent}# wt_scene_bridge:{candidate.candidate_id}']
        lines_code += [body_indent + line for line in plan['body']]
        return {'label_text': label_text, 'menu_choice_code': '\n'.join(lines_code),
                'bridge_code': '', 'candidate': candidate, 'scene_plan': plan}

    def _find_label_end_for_bridge(self, lines, fpath, a_label):
        """
        R5: 'Mod: Both' köprüsü için Dal A (a_label) etiketi gövdesini sonlandıran noktayı belirler.
        Döndürür: (insert_idx, indent_str) veya None.
        Öncelik:
        1. Gövde seviyesindeki ilk 'jump'/'return' ifadesinin ÖNCESİ (dalın doğal bitiş noktası),
        2. Gövdeyi bitiren sonraki üst-seviye bloğun (label/menu/...) ÖNCESİ (fall-through bitişi),
        3. Dosya sonuna ekleme (etiket dosya sonunda ise).
        Not: Ren'Py script yürütümü sıralıdır; etiket gövdesi bitince kontrol sonraki üst-seviye
        ifadeye akar, bu nedenle iki bitiş noktası da köprü için doğru araya giriş noktalarıdır.
        Köprü bloğu koşullu (flag_var) ve idempotent olduğundan, akış normal oyuncular için no-op'tur.
        """
        try:
            a_fpath, a_idx = self.labels[a_label]
        except Exception:
            return None
        try:
            if os.path.abspath(a_fpath) != os.path.abspath(fpath):
                return None
        except Exception:
            return None
        if not (0 <= a_idx < len(lines)):
            return None
        a_line = lines[a_idx]
        if not a_line.strip().startswith("label"):
            return None
        a_indent = len(a_line) - len(a_line.lstrip())

        # Gövde seviyesini belirle ve bitiş satırını bul
        body_indent = None
        end_idx = len(lines)
        for i in range(a_idx + 1, len(lines)):
            st = lines[i].strip()
            if not st or st.startswith("#"):
                continue
            ind = len(lines[i]) - len(lines[i].lstrip())
            if ind <= a_indent:
                end_idx = i
                break
            if body_indent is None:
                body_indent = ind

        # 1) Gövde seviyesindeki ilk jump/return: dal burada sonlanır
        for i in range(a_idx + 1, len(lines)):
            st = lines[i].strip()
            if not st or st.startswith("#"):
                continue
            ind = len(lines[i]) - len(lines[i].lstrip())
            if ind <= a_indent:
                break
            if ind == body_indent and (st.startswith("jump ") or st.startswith("return")):
                indent_str = lines[i][:len(lines[i]) - len(lines[i].lstrip())]
                return i, indent_str

        # 2) Sonraki üst-seviye bloğun önü (fall-through bitişi)
        if end_idx < len(lines):
            indent_str = lines[end_idx][:len(lines[end_idx]) - len(lines[end_idx].lstrip())]
            return end_idx, indent_str

        # 3) Etiket dosyanın sonuna kadar gidiyorsa dosya sonuna ekle (üst-seviye girinti)
        return len(lines), ""

    def apply_both_patch(self, candidate, log_callback=None):
        """Atomically insert full, verified scenes. Never patch shared label bodies."""
        def _log(msg):
            if log_callback:
                try:
                    log_callback(msg)
                except Exception:
                    pass
        if self.options.get("read_only", False):
            _log("[!] GÜVENLİK ENGELİ: Salt okunur mod aktif, Both yaması uygulanamaz.")
            return False
        fpath = candidate.file_path
        tmp_fpath = None
        try:
            patch_data = self.generate_both_patch(candidate)
            plan = patch_data['scene_plan']
            lines = plan['menu_lines']
            insertion = ['\n'] + [l + '\n' for l in patch_data['menu_choice_code'].splitlines()]
            pos = plan['menu_end']
            new_lines = lines[:pos] + insertion + lines[pos:]
            valid, reason = validate_renpy_syntax(new_lines)
            if not valid:
                raise BothPlanError('invalid_generated_syntax:' + str(reason))
            verify_both_generated_source(candidate, plan, new_lines)
            for source, signature in plan['sources'].items():
                if compute_file_sha256(source) != signature:
                    raise BothPlanError('source_changed_during_planning')
            bak_path = fpath + '.wtbak'
            if self.options.get('auto_backup', True) and not os.path.exists(bak_path):
                shutil.copy2(fpath, bak_path)
                if compute_file_sha256(bak_path) != compute_file_sha256(fpath):
                    raise BothPlanError('backup_verification_failed')
            enc, nl, has_bom = self.file_encoding_info.get(fpath, detect_file_encoding(fpath))
            normalized_lines = [l.rstrip("\r\n") + nl for l in new_lines]
            tmp_fpath = fpath + f'.tmp_{uuid.uuid4().hex}'
            with open(tmp_fpath, "w", encoding=enc, newline="", errors="surrogateescape") as f:
                f.writelines(normalized_lines)
            with open(tmp_fpath, 'r', encoding=enc, newline='', errors='surrogateescape') as f:
                if f.read() != ''.join(normalized_lines):
                    raise BothPlanError('write_verification_failed')
            # Recheck after backup/temp creation, immediately before replacing user source.
            if any(compute_file_sha256(p) != sig for p, sig in plan['sources'].items()):
                raise BothPlanError('source_changed_during_write')
            os.replace(tmp_fpath, fpath)
            candidate.scene_plan = plan
            candidate.applied = True
            encoded = ''.join(normalized_lines).encode(enc, errors='surrogateescape')
            candidate.applied_sources = {**plan['sources'], os.path.abspath(fpath):
                                         (hashlib.sha256(encoded).hexdigest(), len(encoded))}
            self.file_cache[fpath] = normalized_lines
            try:
                self._cache_file_meta(fpath)
            except Exception:
                self.file_cache.pop(fpath, None)
            self._cs_entry = None
            self._analysis_revision = getattr(self, '_analysis_revision', 0) + 1
            for label, (source, line) in list(self.labels.items()):
                if os.path.abspath(source) == os.path.abspath(fpath) and line >= pos:
                    self.labels[label] = (source, line + len(insertion))
            seen = set()
            for menu in list(getattr(self, 'all_menus', [])) + list(self.menus) + [candidate.menu]:
                if id(menu) in seen:
                    continue
                seen.add(id(menu))
                menu._evt_decision_cache = None
                if os.path.abspath(menu.file_path) == os.path.abspath(fpath):
                    if menu.line_num >= pos:
                        menu.line_num += len(insertion)
                    for ch in menu.choices:
                        if ch.line_num >= pos:
                            ch.line_num += len(insertion)
            _log(f"[+] {patch_data['label_text']}: {plan['scene_count']} sahne sırayla, puanlar bir kez: {candidate.file_basename}")
            return True
        except Exception as e:
            _log(f"[!] Both yaması güvenle atlandı: {e}")
            self.file_cache.pop(fpath, None)
            return False
        finally:
            if tmp_fpath and os.path.exists(tmp_fpath):
                try:
                    os.remove(tmp_fpath)
                except OSError:
                    pass

    def install_cheat_menu(self, log_callback=None):
        """
        zz_walkthrough_cheat_menu.rpy dosyasını 8 adımlı güvenli sırayla kurar:
        1. Hedef dizini doğrula.
        2. Hedef dosya çakışmalarını tespit et (Özel imza STUDIO_SIGNATURE kontrolü).
        3. Gerekli yedeği (.wtbak) oluştur. Var olan .wtbak'ı asla ezme, özetini doğrula.
        4. Hedef dosya yabancı/özelleştirilmiş ise veya yedekleme başarısızsa DURDUR ve uyar.
        5. Yeni içeriği benzersiz bir geçici dosyaya yaz (.tmp_<uuid>).
        6. Yazılan içeriği doğrula (boyut ve bütünlük).
        7. Güvenli ve atomik biçimde hedefe taşı (os.replace).
        8. Başarı teyit edildikten sonra bildirim yayınla.
        """
        def _log(msg):
            if log_callback:
                try: log_callback(msg)
                except Exception: pass

        if self.options.get("read_only", False):
            _log("[!] GÜVENLİK ENGELİ: Salt okunur mod aktif, hile menüsü kurulamaz.")
            return None

        # 1. Hedef dizini doğrula
        target = getattr(self, "target_dir", None) or find_real_renpy_game_dir(self.game_dir)
        if not target or not os.path.isdir(target):
            _log(f"[X] Hata: Hedef Ren'Py oyun klasörü doğrulanamadı: {target}")
            return None

        cheat_path = os.path.join(target, "zz_walkthrough_cheat_menu.rpy")
        green_hex = self.options.get("green_color", "#2ECC71")
        red_hex = self.options.get("red_color", "#EF4444")

        flags = self.discover_gallery_flags()
        flags_repr = repr(flags)
        curr_data = self.discover_game_currency()

        script_content = CHEAT_MENU_CODE_TEMPLATE.replace("__WT_GREEN_HEX__", green_hex).replace("__WT_RED_HEX__", red_hex).replace("__WT_DISCOVERED_GALLERY_FLAGS__", flags_repr)
        script_content = script_content.replace("__WT_DISCOVERED_CURRENCIES__", repr(curr_data['all_discovered']))
        script_content = script_content.replace("__WT_DYNAMIC_CHARACTERS__", repr(DYNAMIC_CHARACTERS))
        # R5 Fix: aktif sablon para arayuzunu wt_get_currency_info fonksiyonuyla hallettiği
        # icin __WT_GAME_HAS_CURRENCY__ / __WT_PRIMARY_* yer tutucuları mevcut şablonda yok.
        # Kosullu replace: yer tutucu gercekte bulunursa (gelecek şablon sürümleri) uygulansın;
        # aksi halde eski kod tanımsız yer tutucular üzerinde sessiz no-op yapıyor ve yanlış
        # güvenlik algısı yaratıyordu.
        _ph_replacements = (
            ("__WT_GAME_HAS_CURRENCY__", "True" if curr_data['has_currency'] else "False"),
            ("__WT_PRIMARY_CURRENCY_VAR__", curr_data['primary_var']),
            ("__WT_PRIMARY_CURRENCY_UNIT__", curr_data['primary_unit']),
            ("__WT_PRIMARY_CURRENCY_STEPS__", repr(curr_data['primary_steps'])),
        )
        for _ph, _ph_val in _ph_replacements:
            if _ph in script_content:
                script_content = script_content.replace(_ph, str(_ph_val))

        # 2 & 3 & 4. Hedef dosya çakışmalarını tespit et ve doğrulanmış yedek al
        if os.path.exists(cheat_path):
            if not is_file_owned_by_studio(cheat_path):
                _log("[X] GÜVENLİK ENGELİ: Hedef 'zz_walkthrough_cheat_menu.rpy' dosyası bu stüdyoya ait imza içermiyor (yabancı/özelleştirilmiş dosya)!")
                _log("[!] Kullanıcının özel dosyasının ezilmemesi için hile menüsü kurulumu durduruldu.")
                return None

            cheat_bak = cheat_path + ".wtbak"
            if not os.path.exists(cheat_bak):
                try:
                    shutil.copy2(cheat_path, cheat_bak)
                    bak_h, bak_sz = compute_file_sha256(cheat_bak)
                    orig_h, orig_sz = compute_file_sha256(cheat_path)
                    if bak_h != orig_h or bak_sz != orig_sz:
                        if os.path.exists(cheat_bak):
                            try: os.remove(cheat_bak)
                            except Exception: pass
                        _log("[X] Hata: Hile menüsü yedekleme bütünlük doğrulaması başarısız oldu. Kurulum durduruldu!")
                        return None
                    _log(f"[*] Var olan hile menüsü güvenle yedeklendi: {os.path.basename(cheat_bak)}")
                except Exception as e:
                    _log(f"[X] Hile menüsü yedeklenemedi ({e}). Kurulum durduruldu!")
                    return None
            else:
                _log(f"[*] Önceden oluşturulmuş hile menüsü yedeği (.wtbak) korundu: {os.path.basename(cheat_bak)}")

        unlock_custom_renpy_engine(self.game_dir, log_callback=log_callback)

        # 5. Yeni içeriği benzersiz bir geçici dosyaya yaz (.tmp_<uuid>)
        tmp_cheat = cheat_path + f".tmp_{uuid.uuid4().hex}"
        try:
            with open(tmp_cheat, "w", encoding="utf-8") as f:
                f.write(script_content)

            # 6. Yazılan içeriği doğrula
            if not os.path.exists(tmp_cheat) or os.path.getsize(tmp_cheat) == 0:
                _log("[X] Hata: Hile menüsü geçici dosyası boş veya yazılamadı!")
                if os.path.exists(tmp_cheat):
                    try: os.remove(tmp_cheat)
                    except Exception: pass
                return None

            # 7. Güvenli biçimde hedefe taşı (atomic replace)
            os.replace(tmp_cheat, cheat_path)

        except Exception as e:
            _log(f"[X] Hile menüsü yazma hatası: {e}")
            if os.path.exists(tmp_cheat):
                try: os.remove(tmp_cheat)
                except Exception: pass
            return None

        # 8. Başarıyı doğrula
        if not os.path.exists(cheat_path) or os.path.getsize(cheat_path) == 0:
            _log("[X] Hata: Hile menüsü hedef dosyası doğrulanamadı!")
            return None

        if self.options.get("remove_rpyc", True):
            rpyc_path = cheat_path + "c"
            if os.path.exists(rpyc_path):
                try:
                    os.remove(rpyc_path)
                except Exception:
                    pass

        # M7 fix: canli ipucu kancasi (runtime probe) istendiyse hile menusuyle
        # birlikte kurulur; boylece belirsiz esiklerde canli degerler gosterilir.
        if self.options.get("enable_runtime_hook", False):
            try:
                hook_path = self.get_runtime_hook_destination(None)
                self.generate_runtime_hook_script(hook_path)
                ok_h, h_msg = self.verify_runtime_hook(hook_path)
                _log(f"[*] Çalışma zamanı kancası kurulumu: {hook_path} ({h_msg})")
            except Exception as e:
                _log(f"[!] Runtime kanca kurulamadi (atlandi): {e}")

        if curr_data['has_currency']:
            _log(f"[💰] Oyun Para Birimi Tespit Edildi: {curr_data['primary_unit']} (${curr_data['primary_var']}) [Güven: {curr_data['confidence']}]")
        _log("[⚡] Hikâye Kontrol Merkezi (Hile Menüsü) başarıyla kuruldu!")
        return cheat_path

    def restore_backups(self, log_callback=None):
        """
        Orijinal dosyaları .wtbak yedeğinden SHA-256 ve boyut doğrulayarak geri yükler.
        Güvenlik kuralları:
        - Geri yükleme öncesinde yedeğin SHA-256 özetini ve boyutunu hesaplar.
        - Atomik replace ile hedefe aktarır ve hedef dosyanın özetini doğrular.
        - .wtbak yedeği SADECE hedef dosya başarıyla doğrulandıktan sonra silinir.
        - zz_walkthrough_cheat_menu.rpy SADECE bu stüdyoya aitse silinir, yabancı/özel dosyalar korunur.
        - .rpa.bak dosyaları güvenle korunur, hedef .rpa eksikse geri yüklenir.
        - renpy/ altındaki script.py.wtbak ve main.py.wtbak motor kilitleri de geri yüklenir.
        """
        def _log(msg):
            if log_callback:
                try: log_callback(msg)
                except Exception: pass

        restored_count = 0
        target = getattr(self, "target_dir", None) or find_real_renpy_game_dir(self.game_dir)
        if not target or not os.path.isdir(target):
            return 0

        target_abs = os.path.abspath(target)

        # 1. Hile Menüsü Geri Yükleme
        cheat_script = os.path.join(target, "zz_walkthrough_cheat_menu.rpy")
        cheat_bak = cheat_script + ".wtbak"
        cheat_rpyc = cheat_script + "c"

        if os.path.exists(cheat_bak):
            if safe_verified_restore_file(cheat_bak, cheat_script, target, log_callback=_log):
                if os.path.exists(cheat_rpyc):
                    try: os.remove(cheat_rpyc)
                    except Exception: pass
                restored_count += 1
                _log(f"[✓] Hile menüsü orijinal haline geri yüklendi: {os.path.basename(cheat_script)}")
        elif os.path.exists(cheat_script):
            if is_file_owned_by_studio(cheat_script):
                try:
                    os.remove(cheat_script)
                    if os.path.exists(cheat_rpyc):
                        os.remove(cheat_rpyc)
                    restored_count += 1
                    _log(f"[✓] Stüdyoya ait hile menüsü kaldırıldı: {os.path.basename(cheat_script)}")
                except Exception as e:
                    _log(f"[!] Hile menüsü kaldırılırken hata: {e}")
            else:
                _log(f"[!] DİKKAT: '{os.path.basename(cheat_script)}' dosyası stüdyo imzası içermiyor (kullanıcı/özel dosyası). KORUNDU ve silinmedi.")

        # 1b. Evrensel Metin Etiketleri Dosyasi Geri Yukleme / Temizleme
        tags_file = os.path.join(target, "00_walkthrough_tags.rpy")
        tags_rpyc = tags_file + "c"
        if os.path.exists(tags_file):
            try:
                os.remove(tags_file)
                if os.path.exists(tags_rpyc):
                    os.remove(tags_rpyc)
                _log(f"[*] Stüdyoya ait metin etiketleri dosyası kaldırıldı: {os.path.basename(tags_file)}")
            except Exception as e:
                _log(f"[!] Metin etiketleri kaldırılırken hata: {e}")

        # 2. Oyun klasöründeki .wtbak yedeklerini tara ve geri yükle
        for root, dirs, files in os.walk(target):
            dirs[:] = [d for d in dirs if d.lower() not in IGNORED_DIRS]
            if not is_safe_subpath(root, target):
                continue

            for f in files:
                if f.endswith(".rpy.wtbak"):
                    full_bak = os.path.join(root, f)
                    original_rpy = full_bak[:-6]
                    if safe_verified_restore_file(full_bak, original_rpy, target, log_callback=_log):
                        restored_count += 1
                        _log(f"[✓] Geri yüklendi: {os.path.basename(original_rpy)}")

                    rpyc = original_rpy + "c"
                    rpyc_bak = rpyc + ".wtbak"
                    if os.path.exists(rpyc_bak):
                        safe_verified_restore_file(rpyc_bak, rpyc, target, log_callback=_log)
                    elif os.path.exists(rpyc):
                        try: os.remove(rpyc)
                        except Exception: pass

                elif f.endswith(".rpa.bak"):
                    full_bak = os.path.join(root, f)
                    orig_rpa = full_bak[:-4]
                    if not os.path.exists(orig_rpa):
                        if safe_verified_restore_file(full_bak, orig_rpa, target, log_callback=_log):
                            restored_count += 1
                            _log(f"[✓] RPA arşivi geri yüklendi: {os.path.basename(orig_rpa)}")
                    else:
                        _log(f"[*] Var olan RPA arşivi korundu, .rpa.bak güvenle saklandı: {f}")

        # 3. renpy/ motor klasöründeki kilit açma yedeklerini geri yükle
        renpy_candidates = [
            os.path.join(self.game_dir, "renpy"),
            os.path.join(target, "..", "renpy")
        ]
        for r_dir in renpy_candidates:
            r_dir_abs = os.path.abspath(r_dir)
            if os.path.isdir(r_dir_abs):
                for eng_file in ["script.py", "main.py"]:
                    eng_bak = os.path.join(r_dir_abs, eng_file + ".wtbak")
                    eng_orig = os.path.join(r_dir_abs, eng_file)
                    if os.path.exists(eng_bak):
                        if safe_verified_restore_file(eng_bak, eng_orig, os.path.dirname(r_dir_abs), log_callback=_log):
                            restored_count += 1
                            _log(f"[✓] Ren'Py motor dosyası geri yüklendi: {eng_file}")

        return restored_count


    def _resolve_bridge_target_file(self, rel_path):
        """R6 Faz 2.10: wt_bridges.json icindeki dosya yolunu gercek konuma cozer.
        Yol yorumlama sirasi:
        1) Mutlak yol ise oldugu gibi,
        2) 'game/script.rpy' biciminde ise proje koku (game/ ust dizini) uzerinden,
        3) 'scripts/e3s11.rpy' biciminde ise dogrudan game/ klasoru uzerinden,
        4) target_dir uzerinden (target_dir game/ degilse uyum icin),
        bulunuyorsa gercek konumu dondurur; yoksa en olasi aday döner."""
        rel = str(rel_path).replace("\\", "/").lstrip("/")
        # Mutlak yol: dogrudan kullan
        cand_abs = os.path.normpath(rel)
        if os.path.isabs(rel) and os.path.exists(cand_abs):
            return cand_abs

        tgt = getattr(self, "target_dir", None) or find_real_renpy_game_dir(self.game_dir)
        # tgt genellikle '.../game' klasorudur; proje koku ust dizinidir.
        try:
            game_dir_n = os.path.normpath(tgt)
            is_game_dir = os.path.basename(game_dir_n).lower() == "game"
        except Exception:
            game_dir_n = tgt
            is_game_dir = False
        project_root = os.path.dirname(game_dir_n) if is_game_dir else os.path.normpath(tgt)

        bases = [
            os.path.join(project_root, rel),
            os.path.join(game_dir_n, rel),
            os.path.join(tgt, rel),
        ]
        for b in bases:
            cand = os.path.normpath(b)
            if os.path.exists(cand):
                return cand
        return os.path.normpath(bases[0])

    def apply_config_bridges(self, log_callback=None):
        """R6 Faz 2.10: wt_bridges.json veri-tabanlı köprü uygulayıcı.
        Sema:
        {
          "bridges": [
            {
              "file": "scripts/e3s11.rpy",
              "idempotent_marker": "Mod: Both",
              "insert_after": [{"anchor": "jump e3s11choiceJess", "lines": ["    label wt_bridge_a:", "        jump other"]}],
              "insert_before": [{"anchor": "stop music fadeout 2", "lines": ["..."]}]
            }
          ]
        }
        Guvenlik: her köprü dosyası .wtbak yedeklenir; 'anchor' metninin dosyada TAM BİR
        kere geçmesi şart koşulur, idempotent marker ile tekrar uygulama engellenir,
        söz dizimi doğrulanır ve atomik olarak yazılır."""
        def _log(msg):
            if log_callback:
                try: log_callback(msg)
                except Exception: pass

        cfg_path = self._resolve_bridge_target_file("wt_bridges.json")
        if cfg_path and os.path.exists(cfg_path):
            pass
        else:
            tgt = getattr(self, "target_dir", None) or find_real_renpy_game_dir(self.game_dir)
            cfg_path = os.path.join(tgt, "wt_bridges.json")
            if not os.path.exists(cfg_path):
                return 0
        try:
            import json
            with open(cfg_path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except Exception as e:
            _log(f"[X] wt_bridges.json okunamadi: {e}")
            return 0
        rules = data.get("bridges", []) if isinstance(data, dict) else []
        if not isinstance(rules, list):
            rules = []
        applied = 0
        for rule in rules:
            try:
                if not isinstance(rule, dict) or not rule.get("file"):
                    continue
                fpath = self._resolve_bridge_target_file(rule["file"])
                if not os.path.exists(fpath):
                    _log(f"[!] wt_bridges: dosya bulunamadi ({rule['file']}) — atlandi")
                    continue
                lines = list(self.get_file_lines(fpath))
                content = "".join(lines)
                marker = rule.get("idempotent_marker")
                if marker and str(marker) in content:
                    continue  # zaten uygulanmiş
                insertions = []
                ok_rule = True
                for mode_key in ("insert_after", "insert_before"):
                    for ins in (rule.get(mode_key) or []):
                        anchor = str(ins.get("anchor", ""))
                        ins_lines = ins.get("lines") or []
                        if not anchor or not ins_lines:
                            ok_rule = False
                            break
                        try: oc_content = content.count(anchor)
                        except Exception: oc_content = 0
                        if oc_content != 1:
                            _log(f"[!] wt_bridges: çapa bulunamadı veya benzersiz değil ({rule['file']}): '{anchor[:40]}' — kural atlandı")
                            ok_rule = False
                            break
                        idx = content.find(anchor)
                        ins_idx = 0
                        for i_cnt, c_cnt in enumerate(content[:idx]):
                            if c_cnt == "\n": ins_idx += 1
                        line_after = content.find("\n", idx)
                        if mode_key == "insert_after":
                            ins_idx = ins_idx if line_after == -1 else ins_idx + 1
                        nl_text = "".join(l if l.endswith("\n") else l + "\n" for l in [str(x) for x in ins_lines])
                        insertions.append((ins_idx, nl_text))
                    if not ok_rule:
                        break
                if not ok_rule or not insertions:
                    continue
                new_lines = list(lines)
                for ins_idx, ins_text in sorted(insertions, key=lambda t: t[0], reverse=True):
                    new_lines.insert(ins_idx, ins_text)
                is_valid, err_msg = validate_renpy_syntax(new_lines)
                if not is_valid:
                    _log(f"[X] wt_bridges: soz dizimi hata ({err_msg}) — '{rule['file']}' yok sayildi")
                    continue
                enc, nl, has_bom = self.file_encoding_info.get(fpath) or detect_file_encoding(fpath)
                self.file_encoding_info[fpath] = (enc, nl, has_bom)
                # R6: .wtbak yedeği + atomik yazim (safe_write_with_backup yoluyla)
                normalized = [l.rstrip("\r\n") + nl for l in new_lines]
                if not safe_write_with_backup(fpath, "".join(normalized), log_callback=log_callback):
                    _log(f"[X] wt_bridges: yazim basarisiz ({rule['file']})")
                    continue
                try: self.file_cache[fpath] = normalized; self._cache_file_meta(fpath)
                except Exception: pass
                applied += 1
                _log(f"[+] wt_bridges: köprü uygulandı: {rule['file']}")
            except Exception as e:
                _log(f"[!] wt_bridges kural hatası: {e}")
        return applied

    def apply_both_routes(self, log_callback=None):
        """
        Oyundaki iki farkli rotayi/kiyafeti birlestiren 'Mod: Both' seceneklerini ve
        kopruleri guvenle enjekte eder (Ripples ve benzeri oyunlar icin).
        """
        def _log(msg):
            if log_callback:
                try: log_callback(msg)
                except Exception: pass

        if self.options.get("read_only", False):
            _log("[!] GÜVENLİK ENGELİ: Salt okunur mod aktif, Both rotaları uygulanamaz.")
            return False

        scripts_dir = os.path.join(self.game_dir, "game", "scripts")
        if not os.path.exists(scripts_dir):
            scripts_dir = os.path.join(self.game_dir, "game")

        # R6 Faz 2.10: veri-tabanlı kullanıcı köprüleri (wt_bridges.json) — legacy'den once uygulanır
        try:
            self.apply_config_bridges(log_callback=_log)
        except Exception as e:
            _log(f"[!] wt_bridges.json uygulanamadi (atlandi): {e}")

        # 1. B-F: Veri odaklı oyun profillerini (Ripples vb.) öncelikli uygula
        # Legacy profiles bypass the source planner; require explicit opt-in.
        if self.options.get("legacy_bridges", False) and RipplesGameProfile.is_applicable(scripts_dir):
            RipplesGameProfile.apply(scripts_dir, log_cb=_log)

        # 2. Genel menü adaylarını tespit et ve uygula
        cands = self.detect_both_candidates()
        for skipped in getattr(self, 'both_skipped', [])[:10]:
            _log(f"[!] Both atlandı: {os.path.basename(skipped['file'])}:{skipped['line']} ({skipped['reason']})")
        cands = sorted(cands, key=lambda c: (c.file_path, -c.line_num))
        applied = 0
        for cand in cands:
            try:
                if self.apply_both_patch(cand, log_callback=_log):
                    applied += 1
            except Exception as e:
                _log(f"[!] Both yaması adayı atlandı ({getattr(cand, 'candidate_id', 'unknown')}): {e}")
        return applied > 0

    # R6 Faz 2.7: genel stat sozcukleri — alias akrabaliginda tek basina gruplama belirteci
    # olamaz ('love_score' & 'money_score' gibi farkli karakterlerin ortak 'score' sozcugu
    # yanlis gruplama yapar; bu sozcukler ortak belirteç olarak sayiĝetmez).
    _GENERIC_STAT_TOKENS = {
        "points", "point", "score", "favor", "love", "trust", "aff", "affection",
        "stat", "stat2", "bonus", "money", "cash", "gold", "credits", "progress",
        "value", "var", "val", "total", "count", "level", "xp", "exp", "counter",
        "amount", "balance", "rating", "meter", "bar",
    }

    def filter_cfg_unreachable(self, unreachable):
        """R6 Faz 1.5g: CFG'in 'erisilemez' dedigi etiketler arasindan yanlis-pozitifleri ayiklar.
        Betikteki herhangi bir 'jump <label>' / 'call <label>' referansi (menu govdesindeki
        if/else dallarindakiler dahil) olan etiket erisilebilir kabul edilir; boylece CFG'in
        kacirdigi kod-ici dallardan karar kapısına yanlış bilgi akmaz."""
        try:
            referenced = set()
            for fpath in list(getattr(self, "rpy_files", []) or []):
                for line in self.get_file_lines(fpath):
                    m = re.match(r'\s*(?:jump|call)\s+([A-Za-z_][A-Za-z0-9_]*)', line)
                    if m:
                        referenced.add(m.group(1))
            return {u for u in (unreachable or set()) if u not in referenced}
        except Exception:
            return set(unreachable or set())

    def build_alias_map(self, log_callback=None):
        """R6 Faz 2.7: Degisken takma adi grafigi uretir.
        Kural (muhafazakar): ayni secimin kazanims listesinde birlikte artan ve isimsel akrabaligi
        olan (biri digerini iceriyor VEYA son '_parcasi' ayni) degiskenler ayni karakter grubuna koyulur.
        Gruplandirma sonuclari _finalize'daki hedef-karakter puanlamasinda kullanilir."""
        def _log(msg):
            if log_callback:
                try: log_callback(msg)
                except Exception: pass
        try:
            from collections import Counter
            cooccur = Counter()
            for menu in getattr(self, "all_menus", []):
                for ch in getattr(menu, "choices", []):
                    uniq = {clean_identifier(str(v)).lower() for v, _ in list(getattr(ch, "deltas_positive", [])) if v}
                    uniq = {u for u in uniq if u and len(u) >= 3}
                    vars_list = sorted(uniq)
                    for i in range(len(vars_list)):
                        for j in range(i + 1, len(vars_list)):
                            a, b = vars_list[i], vars_list[j]
                            # R6 iyilestirme: klasik alias bicimlerini yakalayan akrabalik kurallari:
                            # 1) icerme: 'luna' & 'luna_points' benzeri
                            # 2) ayni son parca: 'love_luna' & 'trust_luna'
                            # 3) ortak belirtec: 'love_luna' & 'luna_points' icin gizli ortak
                            #    'luna' belirteci; genel stat sozcukleri (points/score/favor...)
                            #    ortak belirtec olarak sayilmaz.
                            shared_tokens = set(a.split("_")) & set(b.split("_"))
                            shared_tokens = {t for t in shared_tokens if len(t) >= 3 and t not in self._GENERIC_STAT_TOKENS}
                            is_kindred = (
                                (a in b)
                                or (b in a)
                                or (a.split("_")[-1] == b.split("_")[-1] and len(a.split("_")[-1]) >= 3)
                                or bool(shared_tokens)
                            )
                            if is_kindred:
                                cooccur[tuple((a, b))] += 1
            min_cc = STUDIO_CONFIG.get("min_alias_cooccur", 2)
            alias_group = {}

            # Union-find
            parent = {}
            def _find(x):
                while parent.get(x, x) != x:
                    parent[x] = parent.get(parent[x], parent[x])
                    x = parent[x]
                return x
            def _union(a, b):
                parent.setdefault(a, a); parent.setdefault(b, b)
                ra, rb = _find(a), _find(b)
                if ra != rb:
                    parent[rb] = ra

            for (a, b), cnt in cooccur.items():
                if cnt >= min_cc:
                    _union(a, b)

            groups = {}
            for v in list(parent.keys()):
                groups.setdefault(_find(v), set()).add(v)
            for g_members in groups.values():
                gm = sorted(g_members)
                canonical = gm[0]
                for v in gm:
                    alias_group[v] = sorted(g_members)
            self.alias_group = alias_group
            if alias_group and log_callback:
                try: log_callback(f"[*] Alias grafiği: {len(alias_group)} değişken gruplandırıldı.")
                except Exception: pass
            return alias_group
        except Exception as e:
            self.alias_group = {}
            _log(f"[!] Alias grafiği kurulamadı (atlandı): {e}")
            return {}

    # --- R6 Faz 2.9: Runtime probe geri besleme ---
    def _runtime_observations_path(self):
        target = getattr(self, "target_dir", None) or find_real_renpy_game_dir(self.game_dir)
        return os.path.join(target, "wt_probe_observations.json")

    def load_runtime_observations(self, log_callback=None):
        """R6 Faz 2.9: Oyun icine entegre probe (Shift+W overlay) uretigi gozlem kaydini okur.
        Seması:
            {"version": 1, "vars": {"love": {"min": x, "max": y, "samples": n}},
             "labels": ["label_a", ...]}
        Dosya yoksa False doner; analiz davranisi degismez."""
        if not STUDIO_CONFIG.get("enable_runtime_feedback", True):
            return False
        path = self._runtime_observations_path()
        if not os.path.exists(path):
            return False
        try:
            import json
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if not isinstance(data, dict):
                return False
            self.runtime_observations = data
            if log_callback:
                try: log_callback(f"[⚡] Runtime probe gözlem kaydı okundu: {path} ({len(data.get('vars', {}))} değişken)")
                except Exception: pass
            return True
        except Exception as e:
            if log_callback:
                try: log_callback(f"[!] Runtime probe kaydi okunamadi (atlandi): {e}")
                except Exception: pass
            return False

    def apply_runtime_observations(self, log_callback=None):
        """R6 Faz 2.9: Gozlemlenen degerleri kararlara uygular:
        1) dynamic_jump_unresolved -> probe'un gordugu tekil etiketle cozulur,
        2) esik belirsizlikleri -> probe'un gordugu max degerle kesinlestirilir.
        Sadece analiz sonucu iyilestirir; hicbir mevcut kaniti silemez."""
        if not self.runtime_observations:
            return 0
        # Y5 fix: gozlemler secenek durumunu (jump eslemleri, esik kesinlestirme)
        # degistirebilir; analiz revizyonunu artir ki menu karar cache'i
        # (evaluate_choices / _evt_decision_cache) bayat sonucu geri veremesin.
        try:
            self._analysis_revision = getattr(self, "_analysis_revision", 0) + 1
        except Exception:
            pass
        resolved = 0
        obs_vars = self.runtime_observations.get("vars", {}) or {}
        for menu in getattr(self, "all_menus", []):
            for ch in list(getattr(menu, "choices", [])):
                # 1) Dinamik jump cozumu
                dj_expr = getattr(ch, "dynamic_jump_unresolved", None)
                if dj_expr:
                    try:
                        obs_jumps = self.runtime_observations.get("jumps", {}) or {}
                        # Dogrudan anahtar eslesen: ifadenin tam metni veya kimligi
                        labels_pool = []
                        key_candidates = [str(dj_expr).strip(), clean_identifier(str(dj_expr)).lower()]
                        for kc in key_candidates:
                            seen = obs_jumps.get(kc)
                            if isinstance(seen, list):
                                labels_pool.extend(seen)
                        # R6 v0.5b: ifade beloken belirtec tabanli cozum —
                        # 'target + \"_path\"' gibi ifadelerde 'target' degiskeninin tek
                        # gozlenen degeri gecerli bir etiket ise akis oraya yakinsar.
                        try:
                            _tokens = re.findall(r"[A-Za-z_][A-Za-z0-9_]*", str(dj_expr))
                        except Exception:
                            _tokens = []
                        for _tok in _tokens:
                            if _tok.lower() in ("expression", "renpy", "jump", "call"):
                                continue
                            seen = obs_jumps.get(_tok)
                            if isinstance(seen, list):
                                labels_pool.extend(seen)
                        labels_seen = list(dict.fromkeys(labels_pool))  # sirayi koruyarak benzersizleştir
                        if len(labels_seen) == 1 and labels_seen[0] in self.labels:
                            ch.jump_target = labels_seen[0]
                            ch.dynamic_jump_unresolved = None
                            ch.evidence_details.append(f"Runtime probe ile çözüldü: dinamik hedef '{labels_seen[0]}'")
                            ch.evidence_chain.append("RUNTIME_PROBE_RESOLVED")
                            resolved += 1
                            if getattr(ch, "downstream_truncated", False):
                                try:
                                    c_score, c_pos, c_neg, c_death, c_surv, c_truncated = self.scan_downstream(
                                        ch.jump_target, depth=1)
                                    ch.downstream_score = c_score
                                    ch.downstream_pos = c_pos
                                    ch.downstream_neg = c_neg
                                    ch.is_downstream_death = c_death
                                    ch.is_downstream_survival = c_surv
                                    ch.downstream_truncated = c_truncated
                                    ch.score += c_score
                                except Exception:
                                    pass
                    except Exception:
                        pass
                # 2) Esik kesinlestirme
                try:
                    if getattr(ch, "threshold_uncertain", False) and obs_vars:
                        for u_label, u_desc in list(getattr(ch, "unlocked_thresholds", [])):
                            parts = str(u_label).split()
                            if len(parts) >= 3:
                                v_norm = parts[0]
                                try: th_val = float(parts[2])
                                except Exception:
                                    continue
                                ent = obs_vars.get(v_norm)
                                if isinstance(ent, dict) and isinstance(ent.get("max"), (int, float)):
                                    obs_max = float(ent["max"])
                                    if obs_max >= th_val:
                                        ch.threshold_uncertain = False
                                        ch.evidence_details.append(
                                            f"Runtime probe: '{v_norm}' oyun icerisinde {obs_max:g} seviyesine ulasti (esik {th_val:g}).")
                                        ch.evidence_chain.append("RUNTIME_PROBE_THRESHOLD_MET")
                                        resolved += 1
                    pass
                except Exception:
                    pass
        if resolved and log_callback:
            try: log_callback(f"[⚡] Runtime probe ile {resolved} belirsizlik çözüldü.")
            except Exception: pass
        return resolved

    # --- R6 Faz 3.11: Karar-gereklendirme raporu ---
    def export_decisions_report(self, output_path=None):
        """R6 Faz 3.11: analyze sırasında kaydedilen karar+gerekçe kaydını JSON'a yazar.
        Her YEŞİL/KIRMIZI secimin neden o renk oldugu (kural + kanıt zinciri) listelenir."""
        target = getattr(self, "target_dir", None) or find_real_renpy_game_dir(self.game_dir)
        if output_path is None:
            output_path = os.path.join(target, "wt_decisions_report.json")
        try:
            import json
            payload = {
                "generated": datetime.now().isoformat(timespec="seconds"),
                "menu_count": len(self.decision_log),
                "menus": self.decision_log,
            }
            with open(output_path, "w", encoding="utf-8") as f:
                json.dump(payload, f, ensure_ascii=False, indent=2)
            return output_path
        except Exception as e:
            if self.log_callback:
                try: self.log_callback(f"[!] Karar raporu yazılamadı: {e}")
                except Exception: pass
            return None

    def build_control_flow_graph(self):
        """
        G2: label, menu, choice, call, return ve jump dugumlerini baglayan tam CFG insa eder.
        Call-return yiginini modelleyerek ulasilabilir sonlari ve secim yollarini uretir.
        """
        if not self.menus:
            for f in self.rpy_files:
                self.analyze_file_menus(f)
        self.cfg = RenpyCFG(self)
        self.cfg.build_graph()
        return self.cfg

    def clean_backups(self, log_callback=None, dry_run=False):
        """R6: '.wtbak' yedek dosyalarini temizler; orijinal dosyalara dokunmaz.
        Guvenlik: yalnizca karsiligindaki orijinal dosya HALEN VAR olan yedekleri siler;
        orijinali kaybolmus yedek, geri yükleme icin son kopya oldugundan dokunulmaz."""
        def _log(msg):
            if log_callback:
                try: log_callback(msg)
                except Exception: pass
        removed = 0
        base = getattr(self, "game_dir", None)
        if not base or not os.path.isdir(base):
            _log("[!] .wtbak temizligi: oyun klasoru bulunamadi.")
            return 0
        for root, _dirs, files in os.walk(base):
            for fn in files:
                if not fn.endswith(".wtbak"):
                    continue
                full = os.path.join(root, fn)
                try:
                    _orig_path = os.path.join(root, fn[:-len(".wtbak")])
                    if not os.path.exists(_orig_path):
                        continue  # orijinal yok = tek kopya; silme
                    if dry_run:
                        removed += 1
                        continue
                    os.remove(full)
                    removed += 1
                    if removed <= 30:
                        _log(f"    silinen yedek: {full}")
                except Exception as e:
                    _log(f"[!] .wtbak silinemedi ({full}): {e}")
        if removed:
            _log(f"[*] .wtbak temizligi tamamlandi: {removed} dosya.")
        return removed

    def export_cfg_json(self, output_path=None):
        """G2: CFG analiz ciktisini JSON formatinda disa aktarir."""
        if not self.cfg:
            self.build_control_flow_graph()
        return self.cfg.export_cfg_json(output_path)

    def format_cfg_report_text(self):
        """G2: Insan okunur CFG, Sonlar ve Rota Kilitleri Raporunu metin olarak uretir."""
        if not self.cfg:
            self.build_control_flow_graph()
        return self.cfg.format_cfg_report_text()

    # ==================================================================================
    # G5: KANIT ZINCIRI VE KAPSAMLI RAPORLAMA METOTLARI
    # ==================================================================================
    def export_analysis_report(self, output_path=None):
        """
        G5, C4: Her secenek icin karar gerekcesi, kural adi, guven skoru, rozet metni,
        belirsizlik nedenleri ve CFG son analizini iceren tam JSON analiz raporunu uretir.
        """
        if not getattr(self, "menus", []):
            for f in self.rpy_files:
                self.analyze_file_menus(f)
        menus_data = []
        total_choices = 0
        decisions_count = {"BEST": 0, "WORST": 0, "NEUTRAL": 0}

        for m in getattr(self, "menus", []):
            c_list = []
            for c in m.choices:
                total_choices += 1
                v = str(Decision(getattr(c, "verdict", "NEUTRAL")))
                legacy_verdict = {'GREEN': 'BEST', 'RED': 'WORST', 'NONE': 'NEUTRAL'}[v]
                decisions_count[legacy_verdict] += 1
                c_list.append({
                    "text": c.clean_text,
                    "line": c.line_num + 1,
                    "verdict": v,
                    "decision_rule": getattr(c, "decision_rule", "RULE_DEFAULT_NEUTRAL"),
                    "decision_verified": bool(getattr(c, "decision_verified", False)),
                    "confidence_score": getattr(c, "confidence_score", 0.0),
                    "evidence_level": getattr(c, "evidence_level", "AMBIGUOUS"),
                    "badge_text": self.format_hint(c, is_positive=(v == "GREEN")),
                    "evidence_chain": getattr(c, "evidence_chain", []),
                    "evidence_details": getattr(c, "evidence_details", []),
                    "uncertainty_reasons": getattr(c, "uncertainty_reasons", []),
                    "unresolved_ast_expressions": getattr(c, "unresolved_ast_expressions", [])
                })
            menus_data.append({
                "file": m.file_path,
                "line": m.line_num + 1,
                "is_screen": m.is_screen,
                "context_coverage": getattr(m, 'context_coverage', {}),
                "choices": c_list
            })

        # C4: CFG analizini de rapora dahil et
        cfg_report_data = {}
        try:
            if not getattr(self, "cfg", None):
                self.build_control_flow_graph()
            cfg_report_data = self.cfg.export_cfg_json()
        except Exception:
            cfg_report_data = {}

        report = {
            "analysis_policy": {
                "verification_scope": "bounded_source_model_not_all_game_routes",
                "contract_enforcement": self.options.get('contract_enforcement', True),
                "narrative_is_terminal_proof": False,
                "condition_satisfaction_is_reward": False,
                "complete_incoming_coverage_required": True,
                "state_join": "equal_scalar_or_unknown_no_path_sampling",
                "memo_state": "future_dependencies_and_actual_caller_continuation",
                "unverified_colors": "neutral_when_contract_enforcement_enabled",
                "code_evidence_is_not_verdict_confidence": True,
            },
            "summary": {
                "total_menus": len(getattr(self, "menus", [])),
                "total_choices": total_choices,
                "decisions": decisions_count,
                "unreachable_thresholds": len(getattr(self, "unreachable_thresholds", [])),
                "uncertain_thresholds": len(getattr(self, "uncertain_thresholds", [])),
                "ast_parse_errors": len(getattr(self, "ast_parse_errors", [])),
                "last_rolled_back_files": getattr(self, "last_rolled_back_files", [])
            },
            "simulation": _cs_diagnostics(self),
            "unreachable_thresholds": getattr(self, "unreachable_thresholds", []),
            "uncertain_thresholds": getattr(self, "uncertain_thresholds", []),
            "ast_parse_errors": getattr(self, "ast_parse_errors", []),
            "menus": menus_data,
            "cfg": cfg_report_data
        }
        report['both'] = self.export_both_report()

        if output_path:
            try:
                if str(output_path).lower().endswith(".txt"):
                    text_summary = self.generate_human_readable_summary()
                    cfg_text = self.format_cfg_report_text()
                    full_text = text_summary + "\n\n" + cfg_text
                    with open(output_path, "w", encoding="utf-8") as f:
                        f.write(full_text)
                else:
                    import json
                    with open(output_path, "w", encoding="utf-8") as f:
                        json.dump(report, f, ensure_ascii=False, indent=2)
            except Exception:
                pass
        return report

    def generate_human_readable_summary(self):
        """
        G5: En riskli 20 secenek, cozulemeyen hedefler, erisilemez esikler ve
        yama geri almalarini ozetleyen insan okunur rapor uretir.
        """
        lines = []
        lines.append("=" * 80)
        lines.append("           REN'PY WALKTHROUGH STUDIO - KAPSAMLI ANALIZ VE KANIT RAPORU           ")
        lines.append("=" * 80)

        # 1. En Riskli 20 Secenek
        risky_choices = []
        for m in getattr(self, "menus", []):
            for c in m.choices:
                if c.is_death or getattr(c, "future_death_risk", False) or c.is_downstream_death or c.score < -10:
                    risky_choices.append((m.file_path, c.line_num + 1, c.clean_text, c.death_reason or "Olum/Kotu Son"))

        lines.append("1. EN RISKLI VE TEHLIKELI SECENEKLER (ILK 20):")
        lines.append("-" * 80)
        if risky_choices:
            for item in risky_choices[:20]:
                lines.append(f"- {os.path.basename(item[0])}:{item[1]} -> \"{item[2]}\" (Neden: {item[3]})")
        else:
            lines.append("  (Projeden olumcul bir risk secenegi tespit edilmedi)")
        lines.append("")

        # 2. Cozulemeyen Hedefler ve Dinamik Cagrilar
        lines.append("2. COZULEMEYEN DINAMIK HEDEFLER VE DIS CAGRI LAR:")
        lines.append("-" * 80)
        unresolved = []
        for m in getattr(self, "menus", []):
            for c in m.choices:
                if getattr(c, "dynamic_jump_unresolved", None):
                    unresolved.append(f"Jump: {c.dynamic_jump_unresolved} ({os.path.basename(m.file_path)}:{c.line_num+1})")
                for fn in getattr(c, "dynamic_calls_unresolved", []):
                    unresolved.append(f"Fonksiyon: {fn} ({os.path.basename(m.file_path)}:{c.line_num+1})")
        if unresolved:
            for u in sorted(set(unresolved))[:20]:
                lines.append(f"- {u}")
        else:
            lines.append("  (Tum jump ve cagri hedefleri basariyla cozuldu)")
        lines.append("")

        # 3. Erisilemez Esikler
        lines.append("3. ERISILEMEZ ESIK DEGISKENLERI:")
        lines.append("-" * 80)
        unreach = getattr(self, "unreachable_thresholds", [])
        if unreach:
            for item in unreach[:15]:
                lines.append(f"- Degisken '{item.get('var')}' -> Gereken: {item.get('threshold')}, Maksimum Achievable: {item.get('max', item.get('mutlak', 0.0))}")
        else:
            lines.append("  (Erisilemez esik tespit edilmedi)")
        lines.append("")

        # 4. Geri Alinan Yamalar
        lines.append("4. LINT HATASI NEDENIYLE GERI ALINAN DOSYALAR:")
        lines.append("-" * 80)
        rolled_back = getattr(self, "last_rolled_back_files", [])
        reasons = getattr(self, "last_rollback_reasons", {})
        if rolled_back:
            for rf in rolled_back:
                lines.append(f"- {os.path.basename(rf)}: {reasons.get(rf, 'Lint hatasi')}")
        else:
            lines.append("  (Hicbir yama geri alinmadi; tum dosyalar temiz dogrulandi)")

        return chr(10).join(lines)

    # ==================================================================================
    # G6: CALISMA ZAMANI KANCASI (RUNTIME HOOK) URETECI VE ANALIZI
    # ==================================================================================
    def get_runtime_hook_destination(self, output_path=None):
        """
        D4 (a): Calisma zamani kancasi dosya hedefini belirler.
        Eger proje klasorunde 'game' alt klasoru varsa dosyayi game/ icine,
        yoksa dogrudan proje klasorune yazar.
        """
        fname = os.path.basename(output_path) if output_path else "00_wt_runtime_probe.rpy"
        if not fname:
            fname = "00_wt_runtime_probe.rpy"

        if output_path and os.path.isabs(output_path) and os.path.dirname(output_path):
            dir_part = os.path.dirname(output_path)
            if os.path.abspath(dir_part) == os.path.abspath(self.game_dir):
                game_sub = os.path.join(self.game_dir, "game")
                if os.path.isdir(game_sub):
                    return os.path.join(game_sub, fname)
            return output_path

        game_sub = os.path.join(self.game_dir, "game")
        if os.path.isdir(game_sub):
            return os.path.join(game_sub, fname)
        return os.path.join(self.game_dir, fname)

    def generate_runtime_hook_script(self, output_path=None):
        """
        G6, C5, D4: Guvenli Calisma Zamani Kancasi (Runtime Live Probe) Betigi Ureteci.
        - D4 (a): game/ alt dizini varsa oraya yazar.
        - D4 (c): config.overlay_screens listesine 'choice_probe_overlay' ekler.
        - D4 (e): Tek 'w' (K_w) tusu oyun kisayollariyla cakismamasi icin yalnizca Shift+W (shift_K_w) baglar.
        - D4 (b): wt_format_live_hint ile belirsiz seceneklerde canli deger gosterir.
        """
        output_path = self.get_runtime_hook_destination(output_path)
        hook_lines = [
            "# -*- coding: utf-8 -*-",
            "# Ren'Py Walkthrough Studio - Guvenli Calisma Zamani Kancasi (Runtime Live Probe)",
            "# Bu dosya statik analizin belirsiz dedigi durumlarda (dinamik artislar, rastgele sayilar)",
            "# oyuncuya canli store degiskenlerini guvenle sunar.",
            "",
            "init -999 python:",
            "    # 1. Kayit ve Rollback Guvenligi: renpy.store salt okunur taranir.",
            "    def wt_get_live_variable_value(var_name, default=None):",
            "        try:",
            "            if not hasattr(renpy.store, var_name):",
            "                return default",
            "            return getattr(renpy.store, var_name, default)",
            "        except Exception:",
            "            return default",
            "",
            "    # 2. Tip Guvenli Karsilastirici (TypeError onleyici):",
            "    def wt_safe_compare(val, threshold, op='>='):",
            "        try:",
            "            if val is None or threshold is None:",
            "                return None",
            "            f_val = float(val)",
            "            f_thresh = float(threshold)",
            "            if op == '>=':",
            "                return f_val >= f_thresh",
            "            elif op == '<=':",
            "                return f_val <= f_thresh",
            "            elif op == '>':",
            "                return f_val > f_thresh",
            "            elif op == '<':",
            "                return f_val < f_thresh",
            "            elif op == '==':",
            "                return f_val == f_thresh",
            "            return False",
            "        except (ValueError, TypeError):",
            "            try:",
            "                return str(val) == str(threshold)",
            "            except Exception:",
            "                return False",
            "",
            "    # 3. Canli Ipucu Bicimlendirici: [[Yeterli]] / [[Yetersiz]] / [[Bilinmiyor]] kacisi",
            "    def wt_format_live_hint(caption, var_name, required_threshold=None):",
            "        val = wt_get_live_variable_value(var_name, default=None)",
            "        if val is None:",
            "            status = \"{color=#FFAA00}[[Bilinmiyor]]{/color}\"",
            "            if required_threshold is not None:",
            "                return \"%s {size=-4}(Canlı: %s=?, Eşik: %s %s){/size}\" % (caption, var_name, required_threshold, status)",
            "            return \"%s {size=-4}(Canlı: %s=? %s){/size}\" % (caption, var_name, status)",
            "",
            "        if required_threshold is not None:",
            "            cmp_res = wt_safe_compare(val, required_threshold, '>=')",
            "            if cmp_res is True:",
            "                status = \"{color=#00FF00}[[Yeterli]]{/color}\"",
            "            elif cmp_res is False:",
            "                status = \"{color=#FF5555}[[Yetersiz]]{/color}\"",
            "            else:",
            "                status = \"{color=#FFAA00}[[Bilinmiyor]]{/color}\"",
            "            return \"%s {size=-4}(Canlı: %s=%s, Eşik: %s %s){/size}\" % (caption, var_name, val, required_threshold, status)",
            "        return \"%s {size=-4}(Canlı: %s=%s){/size}\" % (caption, var_name, val)",
            "",
            "    # 4. Gelistirici modu veya Shift+W ile acilip kapanabilen overlay",
            "    wt_overlay_visible = getattr(renpy.config, 'developer', False)",
            "    def wt_toggle_overlay():",
            "        global wt_overlay_visible",
            "        wt_overlay_visible = not wt_overlay_visible",
            "        renpy.restart_interaction()",
            "",
            "    # D4 (c): Overlay ekranini config.overlay_screens listesine ekle",
            "    if 'choice_probe_overlay' not in getattr(config, 'overlay_screens', []):",
            "        try:",
            "            config.overlay_screens.append('choice_probe_overlay')",
            "        except Exception:",
            "            pass",
            "",
            "    # D4 (e): Shift+W kisayolunu bagla (Tek 'w' tusu oyun diyalog ve skip kontrolleriyle cakismamasi icin guvenli Shift+W)",
            "    try:",
            "        renpy.config.keymap['wt_toggle_overlay'] = ['shift_K_w']",
            "    except Exception:",
            "        pass",
            "",
            "    # R6 Faz 2.9: Gozlem kaydi — Shift+W ile overlay acildiginda anlik deger + label yazar.",
            "    wt_obs_watched = ['love', 'romance', 'money', 'gold', 'cash', 'credits', 'charm', 'trust', 'points', 'potions']",
            "    wt_obs_path = None",
            "    def wt_obs_snapshot():",
            "        try:",
            "            import json, os",
            "            try:",
            "                _cur = renpy.game.context().current",
            "            except Exception:",
            "                _cur = ''",
            "            _vals = {}",
            "            for _v in wt_obs_watched:",
            "                _vv = wt_get_live_variable_value(_v, default=None)",
            "                if _vv is not None:",
            "                    _vals[_v] = _vv",
            "            global wt_obs_path",
            "            if not wt_obs_path:",
            "                wt_obs_path = os.path.join(config.basedir, 'wt_probe_observations.json')",
            "            _path = wt_obs_path",
            "            _data = {'vars': {}, 'labels': [], 'jumps': {}}",
            "            try:",
            "                with open(_path, 'r', encoding='utf-8') as _f: _data = json.load(_f)",
            "                if not isinstance(_data, dict): _data = {'vars': {}, 'labels': [], 'jumps': {}}",
            "            except Exception:",
            "                _data = {'vars': {}, 'labels': [], 'jumps': {}}",
            "            for _v, _vv in _vals.items():",
            "                if isinstance(_vv, (int, float, bool)) and not isinstance(_vv, bool):",
            "                    _ent = _data['vars'].setdefault(_v, {'min': _vv, 'max': _vv, 'samples': 0})",
            "                    try:",
            "                        _ent['min'] = min(float(_ent.get('min', _vv)), float(_vv))",
            "                        _ent['max'] = max(float(_ent.get('max', _vv)), float(_vv))",
            "                        _ent['samples'] = int(_ent.get('samples', 0)) + 1",
            "                    except Exception:",
            "                        pass",
            "            if _cur and _cur not in _data['labels']:",
            "                _data['labels'].append(_cur)",
            "            # R6 v0.5b: dinamik jump ifadelerinin cozumunde kullanilmak uzere",
            "            # store'daki metin tipindeki degisken degerleri 'jumps' altina yazilir.",
            "            # Semantik: {'jumps': {degisken_adi: [gorulen_degerler...]}}",
            "            _jumps = _data.setdefault('jumps', {})",
            "            try:",
            "                for _k, _v in list(vars(renpy.store).items()):",
            "                    if not isinstance(_k, str) or _k.startswith('_'):",
            "                        continue",
            "                    try:",
            "                        _is_id = _k.isidentifier()",
            "                    except Exception:",
            "                        _is_id = False",
            "                    if not _is_id:",
            "                        continue",
            "                    if isinstance(_v, str) and _v and len(_v) < 80:",
            "                        _lst = _jumps.setdefault(_k, [])",
            "                        if _v not in _lst:",
            "                            _lst.append(_v)",
            "                        if len(_lst) > 8:",
            "                            del _lst[:-8]",
            "            except Exception:",
            "                pass",
            "            try:",
            "                _data['version'] = 1",
            "                with open(_path, 'w', encoding='utf-8') as _f: json.dump(_data, _f)",
            "            except Exception:",
            "                pass",
            "        except Exception:",
            "            pass",
            "",
            "# Canli Probing Ekrani (Shift+W kisayolu veya developer modunda aktif)",
            "screen choice_probe_overlay():",
            "    zorder 100",
            "    if getattr(renpy.store, 'wt_overlay_visible', getattr(renpy.config, 'developer', False)):",
            "        frame:",
            "            xalign 0.99",
            "            yalign 0.01",
            "            background '#000000AA'",
            "            padding (8, 4)",
            "            has vbox",
            "            text 'Walkthrough Mod: Canli Analiz Aktif (Shift+W)' size 13 color '#00FFCC'",
            "        timer 2.0 repeat True action Function(wt_obs_snapshot)",
            "    key 'shift_K_w' action Function(wt_toggle_overlay)",
            ""
        ]
        script = chr(10).join(hook_lines)
        if output_path:
            try:
                os.makedirs(os.path.dirname(output_path), exist_ok=True)
                with open(output_path, "w", encoding="utf-8") as f:
                    f.write(script)
            except Exception:
                pass
        return script

    def verify_runtime_hook(self, hook_path=None, hook_content=None):
        """
        C5, D4: Uretilen runtime hook betiginin gecerli Python ve Ren'Py
        sozdizimine uygun oldugunu dogrular (AST parse, enterpolasyon kacislari, overlay screens).
        Mümkünse Ren'Py lint calistirir, motor yoksa dogrulanamayan kismi acikca bildirir.
        """
        if hook_content is None:
            if hook_path and os.path.exists(hook_path):
                with open(hook_path, "r", encoding="utf-8") as f:
                    hook_content = f.read()
            else:
                hook_content = self.generate_runtime_hook_script()

        # 1. init python blogunun AST sozdizimi dogrulamasi
        py_lines = []
        in_python_block = False
        for line in hook_content.splitlines():
            s = line.strip()
            if s.startswith("init") and "python:" in s:
                in_python_block = True
                continue
            elif in_python_block:
                if s.startswith("screen ") or s.startswith("label "):
                    in_python_block = False
                    continue
                if line.startswith("    ") or line.startswith("\t"):
                    py_lines.append(line[4:] if line.startswith("    ") else line[1:])
                elif not s:
                    py_lines.append("")
                else:
                    in_python_block = False
                    continue

        try:
            import ast
            ast.parse("\n".join(py_lines))
        except SyntaxError as e:
            return False, f"Python sozdizimi hatasi: {e}"

        # 2. Metin etiketlerinde enterpolasyon kacis kontrolu: [[Yeterli]] olmali, tek [Yeterli] olmamali
        import re
        if re.search(r'(?<!\[)\[(Yeterli|Yetersiz|Bilinmiyor)\](?!\])', hook_content):
            return False, "Ren'Py metin enterpolasyonu kacisi eksik: [[...]] kullanilmali"

        # 3. D4 (c): config.overlay_screens kontrolu
        if "config.overlay_screens.append" not in hook_content or "choice_probe_overlay" not in hook_content:
            return False, "choice_probe_overlay ekrani config.overlay_screens listesine eklenmemis"

        # 4. D4 (e): Tek 'w' tusu baglantisinin olmadigini dogrula (guvenli Shift+W kontrolu)
        if re.search(r'\[\s*["\']K_w["\']\s*\]|,\s*["\']K_w["\']', hook_content):
            return False, "Guvenlik uyarisi: Tek 'w' (K_w) tusu oyun kisayollariyla cakisabilir; yalnizca Shift+W kullanilmali"

        # 5. D4 (d): Ren'Py motoru varsa lint ile dogrula, yoksa durumu raporla
        renpy_exe = self.options.get("renpy_executable")
        if renpy_exe and os.path.exists(renpy_exe):
            try:
                import subprocess
                res = subprocess.run([renpy_exe, self.game_dir, "lint"], capture_output=True, text=True, timeout=30)
                if res.returncode == 0:
                    return True, "Python soz dizimi, overlay ve Ren'Py lint ile basariyla dogrulandi"
                else:
                    return False, f"Ren'Py lint hatasi: {res.stdout[:200]}"
            except Exception as e:
                return True, f"Python bloklari ve kacislar dogrulandi; Ren'Py lint calistirilamadi ({e})"

        return True, "Python bloklari, kacislar ve overlay basariyla dogrulandi (Harici Ren'Py motoru olmadigindan motor duzeyinde lint dogrulanamadi)"

    def _walkthrough_source_state(self):
        state = {}
        for path in self.rpy_files:
            st = os.stat(path)
            state[path] = (st.st_mtime_ns, st.st_size)
        return state

    def _check_walkthrough_sources(self, expected):
        for path, signature in expected.items():
            st = os.stat(path)
            if (st.st_mtime_ns, st.st_size) != signature:
                raise RuntimeError('Kaynak analizden sonra değişti; yeniden tarayın: ' + path)

    def _record_walkthrough_write(self, expected, path):
        st = os.stat(path)
        expected[path] = (st.st_mtime_ns, st.st_size)

    def _prepare_walkthrough_profile(self, lines, menus, highlight_negative):
        profile = self.options.get('player_profile', 'ALL_CONTENT')
        if profile == 'ALL_CONTENT' or self.options.get('read_only', False):
            return
        # An invalid input is rejected before patch_file evaluates the selected
        # profile. Do not change even its diagnostic verdict by warming it early.
        if not self.options.get('allow_partial_patch', False) and not validate_renpy_syntax(lines)[0]:
            return
        for menu in menus:
            menu.evaluate_choices(highlight_negative=highlight_negative, player_profile=profile)

    def analyze_and_patch(self, log_callback=None):
        """
        Tum dosyalari tarar, etiketleri indeksler, menuleri analiz eder,
        secimleri renklendirir ve hile menusunu entegre eder.
        Hem CLI hem de arayuzsuz otomasyonlar icin tek adimda tam analiz ve yama saglar.
        """
        def _log(msg):
            if log_callback:
                try: log_callback(msg)
                except Exception: pass

        auto_repair_decompiled_scripts(self.game_dir, log_callback=_log)
        rpy_c, rpyc_c, rpa_c = self.scan_files(auto_extract=True, log_callback=_log)
        if rpy_c == 0:
            _log("[X] Islenebilecek .rpy dosyasi bulunamadi!")
            return {"total_files": 0, "patched_menus": 0, "modified_files": 0}

        if self.options.get("deep_jump_scan", True) and not self.labels:
            _log("[*] Hikaye etiketleri (Labels) taraniyor...")
            self.index_labels(log_callback=_log)

        # R6 Faz 1.1/2.7/1.5/2.9: Iki asamali boru hattı.
        # Asama A: tum dosyalar bir kez analiz edilir (menus + deltas toplanır),
        # ardından proje-baglam (_consumed vars), alias grafigi, CFG ve runtime
        # gozlemleri aktifleşir. Asama B: yama turu eski akıştıyle calisir.
        highlight_negative = self.options.get("highlight_negative", True)
        source_state = self._walkthrough_source_state()
        collected = []  # (fpath, lines, menus)
        self.all_menus = []
        try:
            for fpath in self.rpy_files:
                pts_lines, menus = self.analyze_file_menus(fpath)
                if not menus:
                    continue
                collected.append((fpath, pts_lines, menus))
                self.all_menus.extend(menus)
        finally:
            # menus zaten self.menus'a analyze_file_menus icinden eklenmistir

            # R6 Faz 1.1: proje-baglam (project_ctx) bir kez uret ve tum menulere bagla
            try:
                _cv = self.get_all_consumed_variables()
                self.project_ctx = {"consumed_vars": _cv}
                for _m_all in self.all_menus:
                    _m_all.project_ctx = self.project_ctx
            except Exception as e:
                _log(f"[!] project_ctx uretilemedi (atlandi): {e}")

            # R6 Faz 2.7: alias grafigi
            try:
                self.build_alias_map(log_callback=_log)
            except Exception as e:
                _log(f"[!] Alias grafigi kurulamadi (atlandi): {e}")

            # R6 Faz 1.5: CFG kararlara baglanir (hata halinde sessizce atlanir)
            if self.options.get("enable_cfg_verdicts", True):
                try:
                    cfg = self.build_control_flow_graph()
                    if getattr(cfg, "analysis_truncated", False):
                        _log("[!] CFG analizi sure/adim butcesine carpti — erisilemez-etiket "
                             "kapisi bos birakildi (eski davranis ile devam ediliyor).")
                    try:
                        unl = cfg.get_unreachable_labels()
                        # R6 Faz 1.5g: kod-ici jump/call referansina sahip etiketler
                        # erisilemez sayilmaz (CFG'in menu icindeki if/else dallarini
                        # iskalamasina karsi koruma).
                        self.cfg_unreachable_labels = self.filter_cfg_unreachable(
                            set(unl) if isinstance(unl, (set, list, tuple)) else set()
                        )
                    except Exception:
                        self.cfg_unreachable_labels = set()
                    try:
                        pnr = cfg.get_points_of_no_return()
                        if isinstance(pnr, (set, list, tuple)):
                            self.cfg_points_of_no_return = set(pnr)
                    except Exception:
                        pass
                    try:
                        mel = cfg.get_mutually_exclusive_routes()
                        if isinstance(mel, (list, tuple)):
                            self.cfg_mutually_exclusive = list(mel)
                    except Exception:
                        pass
                    if (self.cfg_unreachable_labels or self.cfg_points_of_no_return) and log_callback:
                        _log(f"[*] CFG dogrulamasi: {len(self.cfg_unreachable_labels)} erisilemez etiket, "
                             f"{len(self.cfg_points_of_no_return)} geri-donulemez secim noktasi.")
                except Exception as e:
                    self.cfg = None
                    self.cfg_unreachable_labels = set()
                    _log(f"[!] CFG analizi atlandi: {e}")

            # R6 Faz 2.9: runtime probe geri beslemesi (dosya varsa)
            try:
                if self.load_runtime_observations(log_callback=_log):
                    self.apply_runtime_observations(log_callback=_log)
            except Exception as e:
                _log(f"[!] Runtime geri besleme uygulanamadi (atlandi): {e}")

        total_menus = 0
        total_choices = 0
        total_best = 0
        total_worst = 0
        total_neutral = 0
        modified_files = 0

        # Y2: Eger lint aciksa, yamadan ONCE tek seferde temel cizgi (baseline) lint'ini calistir
        self.baseline_lint_output = ""
        self.baseline_lint_issues = []
        if self.options.get("verify_with_renpy_lint", False):
            self.run_lint_baseline(log_callback=_log)

        patched_files_list = []
        file_patch_stats = {}
        prepared_files = []
        self._in_batch_patch = True
        try:
            # R6: Asama B — yama turu. Dosyalar Asama A'da bir kez analiz edildi;
            # burada artık yeniden analiz yok (karar cache + collected listesi ile hızlanır).
            for fpath, lines, menus in collected:
                fname = os.path.basename(fpath)
                if not menus:
                    continue

                total_menus += len(menus)
                file_best = 0
                file_worst = 0
                file_neutral = 0

                for menu in menus:
                    total_choices += len(menu.choices)
                    decisions = menu.evaluate_choices(highlight_negative=highlight_negative)
                    # Y6 fix: '__BOTH__' köprü pseudo-girdisi (str anahtar) sayaçlara girmez.
                    for c_key, verdict in decisions.items():
                        if isinstance(c_key, str):
                            continue
                        if verdict == 'BEST': file_best += 1
                        elif verdict == 'WORST': file_worst += 1
                        else: file_neutral += 1

                total_best += file_best
                total_worst += file_worst
                total_neutral += file_neutral

                if file_best > 0 or file_worst > 0 or file_neutral > 0:
                    self._prepare_walkthrough_profile(lines, menus, highlight_negative)
                prepared_files.append((fpath, lines, menus, file_best, file_worst, file_neutral))

            self._check_walkthrough_sources(source_state)
            for fpath, lines, menus, file_best, file_worst, file_neutral in prepared_files:
                fname = os.path.basename(fpath)
                if file_best > 0 or file_worst > 0 or file_neutral > 0:
                    self._check_walkthrough_sources(source_state)
                    p_best, p_worst = self.patch_file(fpath, lines, menus)
                    self._record_walkthrough_write(source_state, fpath)
                    # R5 Fix: yalnizca 'neutral cloak' etiketleri eklenen dosyalar da sayilir;
                    # eski durumda tamamen neutral olan dosyalar modified_files'a girmiyordu.
                    p_neutral = int(getattr(self, "last_patched_neutral", 0) or 0)
                    if p_best > 0 or p_worst > 0 or p_neutral > 0:
                        modified_files += 1
                        patched_files_list.append(fpath)
                        file_patch_stats[fpath] = {
                            "best": p_best,
                            "worst": p_worst,
                            "neutral": p_neutral,
                            "menus": len(menus),
                            "choices": sum(len(m.choices) for m in menus)
                        }
                        _log(f"  [⚡ Modlandi] {fname}: {p_best} yesil, {p_worst} kirmizi" + (f", {p_neutral} belirsiz" if p_neutral else ""))
        finally:
            self._in_batch_patch = False

        # Z3 & Y1, Y2, Y3: Proje duzeyinde tek seferde Ren'Py lint dogrulamasi
        rolled_back_files = []
        rollback_reasons = {}
        if self.options.get("verify_with_renpy_lint", False) and patched_files_list:
            _log("[*] Z3: Proje duzeyinde Ren'Py lint dogrulamasi calistiriliyor...")
            lint_res = self.verify_project_lint(patched_files_list)
            if not lint_res and lint_res.rolled_back:
                rolled_back_files = lint_res.rolled_back
                rollback_reasons = lint_res.reasons
                for rf in rolled_back_files:
                    if rf in patched_files_list:
                        patched_files_list.remove(rf)
                    st = file_patch_stats.get(rf, {})
                    modified_files -= 1
                    total_best -= st.get("best", 0)
                    total_worst -= st.get("worst", 0)
                    total_neutral -= st.get("neutral", 0)
                    total_menus -= st.get("menus", 0)
                    total_choices -= st.get("choices", 0)
                _log(f"[!] LINT GERİ ALMA RAPORU: {len(rolled_back_files)} dosya lint hatası nedeniyle geri alındı.")
                for rf in rolled_back_files:
                    _log(f"    • {os.path.basename(rf)}: {rollback_reasons.get(rf, 'Lint hatası')}")

        if self.options.get("enable_both_route", False):
            try:
                self.apply_both_routes(log_callback=_log)
            except Exception as e:
                _log(f"[!] Both rotaları uygulanırken hata oluştu (atlandı): {e}")

        target_dir = getattr(self, "target_dir", None) or find_real_renpy_game_dir(self.game_dir)
        ensure_walkthrough_tags_installed(target_dir, log_callback=_log)
        if self.options.get("enable_cheat_menu", True):
            self.install_cheat_menu(log_callback=_log)

        if self.options.get("remove_rpyc", True):
            compile_renpy_game(self.game_dir, self.options.get("renpy_executable"), log_callback=_log)

        # R5 Fix: rapor 'patched' metrikleri gercekten yamalanan dosyalardan hesaplanir;
        # eski durumda taranan AMA yamalanmayan menuler de 'patched_menus' olarak sayiliyordu.
        patched_menus_final = sum(int(st.get("menus", 0)) for st in file_patch_stats.values())
        patched_choices_final = sum(int(st.get("choices", 0)) for st in file_patch_stats.values())

        # R6 Faz 3.11: rapor flag'i aciksa karar-gereklendirme raporunu da yaz
        if self.options.get("export_report", False):
            try:
                rep_path = self.export_decisions_report()
                if rep_path:
                    _log(f"[📋] Karar-gereklendirme raporu yazildi: {rep_path}")
            except Exception as e:
                _log(f"[!] Karar raporu yazilamadi (atlandi): {e}")

        return {
            "total_files": len(self.rpy_files),
            "modified_files": modified_files,
            "patched_menus": patched_menus_final,
            "patched_choices": patched_choices_final,
            "total_choices": total_choices,
            "total_best": total_best,
            "total_worst": total_worst,
            "total_neutral": total_neutral,
            "rolled_back_files": rolled_back_files,
            "rollback_reasons": rollback_reasons
        }

